window.setupSidebar = setupSidebar;
window.getLastVisitedPage = getLastVisitedPage;
window.NAV_STUDENT = NAV_STUDENT;
window.NAV_ADMIN = NAV_ADMIN;
window.ADMIN_ONLY_NAV_IDS = ADMIN_ONLY_NAV_IDS;


