// a real cross-file consumer, not just ones reachable from onclick markup.
// See PHASE7_WINDOW_EXPORT_AUDIT.md.
window.updateTopbar = updateTopbar;
window.restoreSidebarState = restoreSidebarState;


/* ---- ./modules/shared/button-loading.js ---- */
/* ═══════════════════════════════════════════════════════════════════════════════
   EduQuest — button-loading.js
   Load anywhere after base.css (styles come from #eq-btn-loading-styles below,
   injected once at parse time — no separate stylesheet dependency, so this
   module works even on pages/screens that load before base.css finishes).

   PROBLEM THIS SOLVES: any button that triggers an async round-trip (login,
   logout, claiming a reward, submitting a form, etc.) used to just sit there
   doing nothing between click and result. Nothing told the user their click
   registered, so a slow network made it look broken and invited a
   frustrated second/third click — which, for non-idempotent actions like
   "claim reward" or "submit", can double-fire the request.

   Exports:
     eqButtonLoading(btn, isLoading, opts)   — low-level toggle
     eqWithButtonLoading(btn, label, fn)     — wraps an async fn, always
                                                restores the button after
                                                (success OR error)

   USAGE (reusable anywhere a button kicks off an async action):
     async function claimReward(btn){
       await eqWithButtonLoading(btn, 'Claiming…', async () => {
         const result = await LootService.claim(...);
         if (!result.ok) throw new Error(result.error);
         // ...handle success (toast, UI update, etc.)...
       });
     }
     <button onclick="claimReward(this)">Claim</button>

   Or the two-step form if you need more control over the try/catch:
     eqButtonLoading(btn, true, { label: 'Saving…' });
     try { await save(); } finally { eqButtonLoading(btn, false); }
   ═══════════════════════════════════════════════════════════════════════════════ */

(function (window, document) {
  'use strict';

  // Injected once — reuses the @keyframes spin already defined in base.css
  // for every other spinner in the app (registration submit, etc.), so this
  // stays visually consistent with existing loading states rather than
  // introducing a second spin animation.
  if (!document.getElementById('eq-btn-loading-styles')) {
    var style = document.createElement('style');
    style.id = 'eq-btn-loading-styles';
    style.textContent =
      '.eq-btn-spinner{font-size:16px;vertical-align:middle;animation:spin 1s linear infinite;margin-right:6px}' +
      '.eq-btn-loading{opacity:.85;cursor:not-allowed !important;pointer-events:none}';
    document.head.appendChild(style);
  }

  /**
   * eqButtonLoading(btn, isLoading, opts)
   * Toggles a button between its normal state and a disabled spinner+label
   * state. Saves the button's exact original innerHTML the first time it
   * goes into loading state, and restores it byte-for-byte when turned off
   * — so callers never need to know/repeat the button's original markup.
   *
   * @param {HTMLButtonElement} btn
   * @param {boolean} isLoading
   * @param {Object} [opts]
   * @param {string} [opts.label='Loading…'] — text shown next to the spinner
   */
  function eqButtonLoading(btn, isLoading, opts) {
    if (!btn) return;
    opts = opts || {};

    if (isLoading) {
      if (btn.dataset.eqLoading === '1') return; // already loading — don't clobber saved original
      btn.dataset.eqLoading = '1';
      btn.dataset.eqOrigHtml = btn.innerHTML;
      // Lock the button's current rendered width before swapping content,
      // so "Enter Quest →" → spinner+"Signing in…" doesn't reflow/shrink
      // the button (and, on the login form, doesn't shift the card layout).
      btn.style.minWidth = btn.offsetWidth + 'px';
      btn.disabled = true;
      btn.classList.add('eq-btn-loading');
      var label = opts.label || 'Loading…';
      btn.innerHTML = '<span class="material-symbols-outlined eq-btn-spinner">progress_activity</span>' + label;
    } else {
      if (btn.dataset.eqLoading !== '1') return; // never entered loading state — nothing to restore
      btn.innerHTML = btn.dataset.eqOrigHtml;
      btn.disabled = false;
      btn.classList.remove('eq-btn-loading');
      btn.style.minWidth = '';
      delete btn.dataset.eqLoading;
      delete btn.dataset.eqOrigHtml;
    }
  }
  window.eqButtonLoading = eqButtonLoading;

  /**
   * eqWithButtonLoading(btn, label, fn) → Promise<any>
   * Puts btn into its loading state, runs fn() (sync or async), and ALWAYS
   * restores the button afterward via finally — whether fn() resolves,
   * rejects, or throws. Re-throws/returns exactly what fn() would have, so
   * callers can keep their existing success/error branching unchanged; this
   * only adds the loading-state bookkeeping around it.
   *
   * @param {HTMLButtonElement} btn
   * @param {string} label
   * @param {Function} fn — () => Promise<any> | any
   */
  async function eqWithButtonLoading(btn, label, fn) {
    eqButtonLoading(btn, true, { label: label });
    try {
      return await fn();
    } finally {
      eqButtonLoading(btn, false);
    }
  }
  window.eqWithButtonLoading = eqWithButtonLoading;

})(window, document);


/* ---- ./modules/shared/notification-service.js ---- */
// ═══════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/shared/notification-service.js
//  PHASE 67 — STUDENT NOTIFICATION SYSTEM
//
//  STUDENT-ONLY, on purpose (see the topbar wiring in index.html/topbar.js —
//  the bell is hidden entirely for currentRole 'admin'/'teacher'). Nothing
//  here is registered or rendered for staff sessions.
//
//  DESIGN — why notifications are SYNTHESIZED, not written at the source:
//    The events a student cares about (quiz/campaign/boss/achievement/mail
//    rewards, admin point grants, store purchases) are already written to
//    DB.pointLog and DB.orders by six-plus different call sites across the
//    codebase (recitation/logger.js, campaign_engine.js, combat-settings.js,
//    ach_engine.js, mail-engine.js, student-manager.js, index.html's
//    finishQuiz(), shop_store.js's cartCheckout()) — several of which run
//    from a TEACHER's session, not the student's own. Teaching every one of
//    those call sites to also insert into `notifications` would mean half
//    of them need permission to write a *different student's* row, which
//    reopens exactly the kind of RLS carve-out (is_staff_for_section, etc.)
//    that's caused most of the 42501 bugs in this project's history.
//
//    Instead, this service reads point_log/orders — which the affected
//    student's own client already pulls and can already see under existing
//    RLS — and turns any row it hasn't notified about yet into a
//    `notifications` row, written by that student's own session. Simple
//    "student_id = auth.uid()" RLS the whole way (see
//    supabase/phase67_notifications.sql), no exceptions needed.
//
//    Practical effect: a notification appears the moment the affected
//    student's client is running and pulls fresh data — instantly if they're
//    online when it happens (the existing postgres_changes subscription on
//    point_log/orders triggers a pull, which triggers this), or the next
//    time they log in otherwise.
//
//  BOOTSTRAP — first time this ships for a given student, DB.notifications
//    is empty and DB.pointLog might have months of history already in it.
//    Backfilling all of it as unread would flood the bell for a feature that
//    was never there before. So: the very first synthesize() call for a
//    student (tracked via a local "bootstrapped" flag, see NOTIF_BOOT_KEY)
//    imports a capped, already-READ backfill (history is there if they open
//    the bell, nothing pings them for it) and every call after that treats
//    genuinely new rows normally (unread, toast-worthy).
//
//  Exports: window.eqTimeAgo(iso), window.NotificationService
//  DEPENDENCIES: DB/loadDB/saveDB/currentUser/currentRole (globals), uid()
//    (utils.js), toast() (dom.js), navTo() (nav.js). Must load AFTER
//    db-schema.js (DB.notifications default) and BEFORE topbar.js calls
//    NotificationService.refresh() from updateTopbar().
// ═══════════════════════════════════════════════════════════════════════════

// ── Shared relative-time formatter ──────────────────────────────────────────
// Used by the notification panel AND the dashboard's Overall Activity feed
// (index.html renderStudentDashboard()) so neither one ever freezes on a
// stored string the way DB.pointLog[].when used to (see FIXES doc for
// Phase 67 — the old bug was literally storing the word "Just now" forever).
// Always compute from a real ISO timestamp at render time instead.
window.eqTimeAgo = function (iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  const now = new Date();
  const diffMs = now - d;
  if (diffMs < 0 || diffMs < 60000) return 'Just now';
  if (diffMs < 3600000) return Math.floor(diffMs / 60000) + 'm ago';
  if (diffMs < 86400000) return Math.floor(diffMs / 3600000) + 'h ago';
  // Calendar-day comparison (not a raw 24h/48h bucket) so "Yesterday" means
  // yesterday even if it was only 3 hours ago by clock time.
  const dayStart = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  const nowStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const dayDiff = Math.round((nowStart - dayStart) / 86400000);
  if (dayDiff === 1) return 'Yesterday';
  if (dayDiff > 1 && dayDiff < 7) return dayDiff + 'd ago';
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
};

(function () {
  const NOTIF_BOOT_KEY_PREFIX = 'eq_notif_bootstrapped_';
  const BOOT_POINTLOG_CAP = 30; // capped one-time backfill, see header comment
  const BOOT_ORDERS_CAP   = 10;
  const LOCAL_NOTIF_CAP   = 200; // trims local array growth; server keeps full history

  let _panelOpen = false;

  // ── Classification: DB.pointLog[].what (free text) → notification content ─
  // pointLog entries are written by 7 different call sites with their own
  // free-text `what` strings (see header comment). This is a best-effort
  // keyword/regex match, not a structured field — if a future call site's
  // wording doesn't match any pattern here it just falls through to the
  // generic "Points Awarded/Deducted" bucket, which is always a safe default.
  //
  // IMPORTANT — title/body here are deliberately NOT the same text the
  // dashboard's Overall Activity feed shows. Overall Activity is a terse,
  // ledger-style history (it displays entry.what verbatim, e.g. "Quest:
  // Algebra Basics (86%)"); a notification is a one-off alert, so it gets a
  // friendlier, reworded sentence built from the same underlying data
  // ("Quest Completed! You scored 86% on 'Algebra Basics' and earned 15
  // XP."). Only the icon is intentionally shared between the two — that's
  // just consistent iconography, not duplicated wording.
  function _classifyPointLog(entry) {
    const what = entry.what || '';
    const pts  = typeof entry.pts === 'number' ? entry.pts : 0;
    let m;

    if ((m = /^Quest:\s*(.+?)\s*\((\d+)%\)\s*$/.exec(what))) {
      return {
        type: 'quiz', icon: '⚔️', action: 's-quizzes',
        title: 'Quest Completed!',
        body: `You scored ${m[2]}% on "${m[1]}"${pts ? ` and earned ${pts} XP` : ''}.`,
      };
    }
    if ((m = /^Stage:\s*(.+)$/.exec(what))) {
      return {
        type: 'campaign', icon: '🗺️', action: 's-quizzes',
        title: 'Campaign Stage Cleared!',
        body: `You cleared "${m[1]}"${pts ? ` and earned ${pts} XP` : ''}.`,
      };
    }
    if ((m = /Boss Raid:\s*"([^"]+)"/.exec(what))) {
      return {
        type: 'boss', icon: '👹', action: 's-world-boss',
        title: 'Boss Defeated!',
        body: `Your party brought down ${m[1]}. Victory rewards are waiting in your inventory.`,
      };
    }
    if ((m = /Achievement Claimed:\s*(.+)$/.exec(what))) {
      return {
        type: 'achievement', icon: '🏅', action: 's-badges',
        title: 'Achievement Unlocked!',
        body: `You claimed the reward for "${m[1]}".`,
      };
    }
    if ((m = /Mail Reward:\s*(.+)$/.exec(what))) {
      return {
        type: 'mail_reward', icon: '📬', action: 's-mail',
        title: 'Mail Reward Claimed!',
        body: `You picked up a reward attached to "${m[1]}".`,
      };
    }
    if (/^Recitation/.test(what)) {
      return {
        type: 'points', icon: '🎤', action: 's-dashboard',
        title: pts >= 0 ? 'Recitation Points' : 'Recitation Deduction',
        body: pts >= 0
          ? `Your teacher awarded you ${pts} points for reciting in class.`
          : `${Math.abs(pts)} points were deducted for recitation.`,
      };
    }
    if (/^Attendance/.test(what)) {
      return {
        type: 'points', icon: '📅', action: 's-dashboard',
        title: 'Attendance Logged',
        body: `Your attendance was just recorded${pts ? ` (+${pts} pts)` : ''}.`,
      };
    }
    if (pts < 0) {
      return {
        type: 'points', icon: '⚠️', action: 's-dashboard',
        title: 'Points Deducted',
        body: `Your teacher deducted ${Math.abs(pts)} points. Tap to see your recent activity.`,
      };
    }
    return {
      type: 'points', icon: '⭐', action: 's-dashboard',
      title: 'Points Awarded',
      body: `Your teacher awarded you ${pts} points. Tap to see your recent activity.`,
    };
  }

  // Exposed globally — index.html's renderStudentDashboard() Overall Activity
  // feed reuses this for its icon ONLY (c.icon), never c.title/c.body, so the
  // two surfaces stay visually consistent without repeating the same wording.
  window.eqClassifyActivity = _classifyPointLog;

  // [Phase 3 migration] reads go through AppStore.getSlice() instead of the
  // live `DB` global — see modules/core/state-manager.js. getSlice() clones
  // only the requested sub-tree, so what these functions get back is always
  // a snapshot, never a reference into AppStore's internal _state. That's
  // deliberate: it's what forces every write in this file to go back through
  // AppStore.updateState() instead of mutating a found object in place (the
  // old DB.notifications.find() pattern used to work only because DB was a
  // live shared reference — see markRead/markAllRead/openRow below for
  // where that mattered).
  function _existingSourceIds(sid, notifications) {
    const set = new Set();
    (notifications || []).forEach(n => { if (n.studentId === sid && n.sourceId) set.add(n.sourceId); });
    return set;
  }

  // ── Core synthesis pass ───────────────────────────────────────────────────
  // Returns the array of genuinely-new (non-bootstrap) notifications created
  // this call, so refresh() knows whether a toast is warranted.
  function synthesize() {
    if (currentRole !== 'student' || !currentUser || typeof AppStore === 'undefined') return [];
    const sid = currentUser.id;

    let isBootstrap = false;
    const bootKey = NOTIF_BOOT_KEY_PREFIX + sid;
    try { isBootstrap = !localStorage.getItem(bootKey); } catch (e) { /* storage unavailable — treat as non-bootstrap, safest default */ }

    const notifications = AppStore.getSlice(s => s.notifications) || [];
    const existing = _existingSourceIds(sid, notifications);
    const created = [];

    let plRows = (AppStore.getSlice(s => s.pointLog) || []).filter(p => p.studentId === sid && p.id && !existing.has(p.id));
    if (isBootstrap) plRows = plRows.slice(0, BOOT_POINTLOG_CAP);
    plRows.forEach(p => {
      const c = _classifyPointLog(p);
      created.push({
        id: 'ntf_' + uid(), studentId: sid, type: c.type, icon: c.icon, title: c.title,
        body: c.body, action: c.action, pts: typeof p.pts === 'number' ? p.pts : null,
        sourceId: p.id, read: isBootstrap,
        createdAt: p.createdAt || new Date().toISOString(),
      });
    });

    let ordRows = (AppStore.getSlice(s => s.orders) || []).filter(o => o.studentId === sid && o.orderId && !existing.has(o.orderId));
    if (isBootstrap) ordRows = ordRows.slice(0, BOOT_ORDERS_CAP);
    ordRows.forEach(o => {
      created.push({
        id: 'ntf_' + uid(), studentId: sid, type: 'store', icon: o.emoji || '🛍️',
        // Distinct from the dashboard's "Purchased {itemName}" ledger line —
        // this is the alert version, phrased as a receipt/confirmation.
        title: 'Purchase Confirmed',
        body: `Your order for "${o.itemName}" (${o.cost || 0} pts) was placed. Visit the Armory to claim it.`,
        action: 's-inventory',
        pts: -(o.cost || 0), sourceId: o.orderId, read: isBootstrap,
        createdAt: o.createdAt || new Date().toISOString(),
      });
    });

    if (created.length) {
      AppStore.updateState(draft => {
        if (!Array.isArray(draft.notifications)) draft.notifications = [];
        draft.notifications = created.concat(draft.notifications)
          .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
          .slice(0, LOCAL_NOTIF_CAP);
      }, { type: 'notifications:synthesized', payload: { studentId: sid, count: created.length } });
    }
    if (isBootstrap) {
      try { localStorage.setItem(bootKey, '1'); } catch (e) { /* non-fatal — worst case, re-backfills (still capped) next load */ }
      return []; // bootstrap backfill never toasts
    }
    return created;
  }

  function _myNotifs() {
    if (currentRole !== 'student' || !currentUser) return [];
    return (AppStore.getSlice(s => s.notifications) || [])
      .filter(n => n.studentId === currentUser.id)
      .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  }

  function _unreadCount() {
    return _myNotifs().filter(n => !n.read).length;
  }

  // ── Badge ──────────────────────────────────────────────────────────────────
  function _renderBadge() {
    const wrap  = document.getElementById('notif-wrap');
    const badge = document.getElementById('notif-badge');
    if (!wrap || !badge) return;
    if (currentRole !== 'student') { wrap.style.display = 'none'; return; }
    wrap.style.display = '';
    const n = _unreadCount();
    if (n > 0) {
      badge.style.display = 'block';
      badge.textContent = n > 99 ? '99+' : String(n);
    } else {
      badge.style.display = 'none';
    }
  }

  // ── Dropdown panel ─────────────────────────────────────────────────────────
  function _rowHtml(n) {
    const pts = n.pts;
    const ptsHtml = (typeof pts === 'number' && pts !== 0)
      ? `<div class="notif-row-pts" style="color:${pts > 0 ? '#4edea3' : '#ffb4ab'}">${pts > 0 ? '+' : ''}${pts}</div>`
      : '';
    return `
    <div class="notif-row ${n.read ? '' : 'unread'}" onclick="NotificationService.openRow('${n.id}')">
      <div class="notif-row-icon">${n.icon || '🔔'}</div>
      <div class="notif-row-body">
        <div class="notif-row-title">${_esc(n.title)}</div>
        <div class="notif-row-sub">${_esc(n.body || '')}</div>
        <div class="notif-row-when">${window.eqTimeAgo(n.createdAt)}</div>
      </div>
      ${ptsHtml}
      ${n.read ? '' : '<div class="notif-row-dot"></div>'}
    </div>`;
  }

  function _renderPanel() {
    const panel = document.getElementById('notif-panel');
    if (!panel) return;
    const notifs = _myNotifs().slice(0, 40);
    const unread = notifs.filter(n => !n.read).length;
    panel.innerHTML = `
      <div class="notif-panel-head">
        <h3>Notifications</h3>
        ${unread > 0 ? `<button class="notif-mark-all" onclick="NotificationService.markAllRead()">Mark all read</button>` : ''}
      </div>
      ${notifs.length
        ? notifs.map(_rowHtml).join('')
        : `<div class="notif-empty"><span class="emoji">🔔</span>No notifications yet.<br>Quests, rewards, and purchases will show up here.</div>`}
    `;
  }

  // ── Public API ──────────────────────────────────────────────────────────────
  window.NotificationService = {
    // Called from updateTopbar() (topbar.js) after every state refresh — the
    // one central hook already fired app-wide whenever DB changes.
    refresh: function () {
      const fresh = synthesize();
      _renderBadge();
      if (_panelOpen) _renderPanel();
      if (fresh.length === 1) {
        toast(`${fresh[0].icon || '🔔'} ${fresh[0].title}`, '#d0bcff');
      } else if (fresh.length > 1) {
        toast(`🔔 You have ${fresh.length} new updates`, '#d0bcff');
      }
    },

    toggle: function () {
      const panel = document.getElementById('notif-panel');
      if (!panel) return;
      _panelOpen = !_panelOpen;
      if (_panelOpen) {
        _renderPanel();
        panel.style.display = 'block';
      } else {
        panel.style.display = 'none';
      }
    },

    close: function () {
      const panel = document.getElementById('notif-panel');
      if (!panel) return;
      _panelOpen = false;
      panel.style.display = 'none';
    },

    markRead: function (id) {
      // Look up first (read-only, cloned) so we only pay for an updateState
      // call — and its persist + subscriber notify — when something is
      // actually changing, same as the old "if (n && !n.read)" gate.
      const existing = (AppStore.getSlice(s => s.notifications) || []).find(x => x.id === id);
      if (existing && !existing.read) {
        AppStore.updateState(draft => {
          const n = (draft.notifications || []).find(x => x.id === id);
          if (n) n.read = true;
        }, { type: 'notifications:read', payload: { id } });
      }
      _renderBadge();
      if (_panelOpen) _renderPanel();
    },

    markAllRead: function () {
      const sid = currentUser && currentUser.id;
      const hasUnread = _myNotifs().some(n => !n.read);
      if (hasUnread) {
        AppStore.updateState(draft => {
          (draft.notifications || [])
            .filter(n => n.studentId === sid)
            .forEach(n => { n.read = true; });
        }, { type: 'notifications:all-read', payload: { studentId: sid } });
      }
      _renderBadge();
      if (_panelOpen) _renderPanel();
    },

    // Click on a row: mark read, close the panel, and navigate to wherever
    // that notification is about (Quest Board, Armory Inventory, etc).
    openRow: function (id) {
      const n = (AppStore.getSlice(s => s.notifications) || []).find(x => x.id === id);
      if (!n) return;
      if (!n.read) {
        AppStore.updateState(draft => {
          const target = (draft.notifications || []).find(x => x.id === id);
          if (target) target.read = true;
        }, { type: 'notifications:read', payload: { id } });
      }
      this.close();
      _renderBadge();
      // n.action came from the pre-update snapshot, but action is never
      // mutated by the read-flag update above, so it's still accurate.
      if (n.action && typeof navTo === 'function') navTo(n.action);
    },
  };

  // Close the dropdown on an outside click (capture phase so it still
  // closes even if the click target itself gets removed/re-rendered).
  document.addEventListener('click', function (e) {
    if (!_panelOpen) return;
    const panel = document.getElementById('notif-panel');
    const wrap  = document.getElementById('notif-wrap');
    if (!panel || !wrap) return;
    if (wrap.contains(e.target)) return; // bell button itself toggles separately
    if (!panel.contains(e.target)) NotificationService.close();
  }, true);
})();

console.log('[EduQuest] shared/notification-service.js loaded — NotificationService registered.');


/* ---- ./auth.js ---- */
// ─────────────────────────────────────────────────────────────────────────────
// SHARED AUTH — Login, logout, session initialization
//
// Exports: selectRole(), doLogin(), doLogout(), bootApp()
//
// DEPENDENCIES:
//   - DB, currentUser, currentRole, selectedLoginRole (globals / core/app-state)
//   - loadDB(), saveDB() (core/db-service via legacy bridge)
//   - updateTopbar(), setupSidebar() (ui/topbar, shared/nav)
//   - renderAdminDashboard(), renderStudentDashboard() (ui/dashboard)
//   - showPage() (shared/nav)
//   - WBC, wbmStopSpawnLoop(), wbcUpdateTopbarWidget() (world-boss — global)
//   - getStageProgress() (campaign — global)
//   - quizTimer (quiz — global)
//
// PHASE 1 EXTRACTION NOTE:
//   bootApp() is monkey-patched by at least 4 other modules in the monolith:
//   WBSN (summon notify), title cleanup, DSM, and achievement system.
//   All patches are preserved in the monolith. This extracted version contains
//   the base bootApp() only. Patches will be replaced with explicit init() calls
//   in Phase 5 (Replace Monkey-Patches).
// ─────────────────────────────────────────────────────────────────────────────

// selectRole() is kept as a harmless no-op for backward compatibility — the
// login screen no longer has separate Student/Teacher buttons (removed per
// design update: login is now a single normal form, role is resolved from
// profiles.role after auth, same as it already was under the hood).
function selectRole(role){
  selectedLoginRole=role;
}
// doLogin() is now ASYNC — it calls Supabase Auth over the network instead of
// checking DB.students/DB.admin locally. Callers (the login button's onclick)
// don't need to change: an onclick handler is allowed to fire an async
// function and not await it. Nothing downstream reads currentUser/currentRole
// until bootApp() runs, and bootApp() is only ever called from inside here,
// after the real session + profile are both confirmed — so there's no race.
//
// AUTH MIGRATION NOTE: students/admins now log in with EMAIL + password via
// real Supabase Auth (supabase.auth.signInWithPassword), not a local DB
// lookup. profiles.id is the Supabase Auth UUID (auth.uid()), so once signed
// in we fetch the caller's own profiles row (allowed by
// profiles_select_all_authenticated) to populate currentUser/currentRole —
// role comes from profiles.role, not from which login button was clicked.
// selectedLoginRole is kept only as a cosmetic hint for the demo-text box;
// it no longer gates which account type can log in.
async function doLogin(){
  const email=document.getElementById('login-user').value.trim().toLowerCase();
  const p=document.getElementById('login-pass').value.trim();
  const err=document.getElementById('login-err');
  const pendingErr=document.getElementById('login-pending-err');
  const btn=document.getElementById('login-submit-btn');
  err.style.display='none';
  pendingErr.style.display='none';

  if (!email || !p) {
    err.innerHTML='❌ Please enter your email and password.';
    err.style.display='block';
    return;
  }

  // BUGFIX (confusing "dead" login button): signInWithPassword() + the
  // profile fetch below are a real network round-trip with nothing else on
  // screen changing in the meantime, which read as the button doing
  // nothing and invited people to click it repeatedly. eqButtonLoading()
  // (modules/shared/button-loading.js) swaps the button to a disabled
  // spinner+label immediately and restores it via the `finally` below on
  // EVERY exit path — success, invalid credentials, pending registration,
  // deactivated account, or an unexpected error — so a fast double-click
  // can't fire two concurrent sign-in attempts either.
  if (typeof eqButtonLoading === 'function') eqButtonLoading(btn, true, { label: 'Signing in…' });
  try {

  const client = (typeof DBService !== 'undefined') ? DBService.getAuthClient() : null;
  if (!client) {
    err.innerHTML='⏳ Still connecting, please try again in a moment.';
    err.style.display='block';
    return;
  }

  const { data: authData, error: authError } = await client.auth.signInWithPassword({
    email: email, password: p,
  });

  if (authError) {
    // Supabase returns a generic "Invalid login credentials" for both
    // wrong-password and unknown-email, by design (so a login form can't be
    // used to discover which emails are registered). We surface that as-is,
    // then separately check registration status for a more specific
    // pending/rejected message, same as before — but via the
    // check_registration_status() RPC now rather than the local
    // DB.registrations cache, since that cache is only ever populated with
    // an unauthenticated visitor's OWN row under the tightened RLS policy
    // added in wave2_registration_security_fixes.sql, not everyone's.
    if (typeof RegistrationService !== 'undefined') {
      const statusResult = await RegistrationService.checkStatus(email);
      if (statusResult.ok && statusResult.found) {
        if (statusResult.status === 'pending') { pendingErr.style.display='block'; document.getElementById('login-pass').value=''; return; }
        if (statusResult.status === 'rejected') { err.innerHTML='❌ Your registration was not approved. Contact your teacher.'; err.style.display='block'; document.getElementById('login-pass').value=''; return; }
      }
    }
    err.innerHTML='❌ Incorrect email or password.';
    err.style.display='block';
    document.getElementById('login-pass').value='';
    return;
  }

  // Auth succeeded — fetch this user's own profile row to determine role.
  const uid = authData.user.id;
  const { data: profile, error: profileError } = await client
    .from('profiles')
    .select('*')
    .eq('id', uid)
    .single();

  if (profileError || !profile) {
    // AUTH MIGRATION NOTE: registration now creates the real Auth account
    // up front (see registrations.js doRegister() / RegistrationService),
    // so signInWithPassword() above can succeed for a still-pending student
    // — there's a real, working account, just no `profiles` row yet because
    // an admin hasn't approved it. That's expected, not an error state, so
    // check registration status before falling back to the generic message
    // (which now only fires for the genuinely unexpected case: a Supabase
    // Auth account with no matching registration record at all).
    let handled = false;
    if (typeof RegistrationService !== 'undefined') {
      const statusResult = await RegistrationService.checkStatus(email);
      if (statusResult.ok && statusResult.found) {
        if (statusResult.status === 'pending') { pendingErr.style.display='block'; handled = true; }
        else if (statusResult.status === 'rejected') { err.innerHTML='❌ Your registration was not approved. Contact your teacher.'; err.style.display='block'; handled = true; }
      }
    }
    if (!handled) {
      err.innerHTML='❌ Signed in, but no profile was found for this account. Contact your teacher.';
      err.style.display='block';
    }
    document.getElementById('login-pass').value='';
    await client.auth.signOut();
    return;
  }

  // ROLE SPLIT (ISOLATION_ROLES_PLAN.md §11/§12 step 5, chunk A3): a
  // deactivated admin/teacher account (profile.is_active === false) already
  // loses every RLS-gated read/write and RPC the moment
  // phase36_deactivate_reactivate.sql's helper-function update lands
  // server-side — this is belt-and-suspenders client-side UX so a
  // deactivated teacher sees a clear message instead of a session that
  // silently can't do anything. Students have no is_active column semantics
  // defined yet (only admin/teacher accounts can be deactivated via
  // deactivate_teacher_account()), so this only ever fires for staff.
  if (profile.is_active === false) {
    err.innerHTML='❌ This account has been deactivated. Contact your school\'s admin.';
    err.style.display='block';
    document.getElementById('login-pass').value='';
    await client.auth.signOut();
    return;
  }

  // AUTH MIGRATION — SHAPE BRIDGE: every other module in the app (topbar.js,
  // dashboard.js, etc.) was written against the OLD DB.students[i]/DB.admin
  // shape: { name, init, color, xp, coins, level, tier, attendance, quizAvg,
  // firstName, lastName, displayName, email, profilePic, ... }. The real
  // `profiles` table uses different column names (display_name, first_name,
  // attendance_pct, profile_pic_url, snake_case throughout). Rather than
  // hunt down and edit every downstream read of currentUser.* across the
  // codebase, we normalize ONCE here, right after fetching the profile, so
  // currentUser keeps the exact shape every other file already expects.
  // If you add new profiles columns that other modules need, map them here
  // too rather than reading profile.* directly elsewhere.
  currentUser = {
    id: profile.id,
    name: profile.display_name,
    displayName: profile.display_name,
    firstName: profile.first_name,
    lastName: profile.last_name,
    init: profile.init,
    color: profile.color,
    xp: profile.xp,
    coins: profile.coins,
    level: profile.level,
    tier: profile.tier,
    attendance: profile.attendance_pct,
    quizAvg: profile.quiz_avg,
    profilePic: profile.profile_pic_url,
    classId: profile.class_id,
    role: profile.role,
    email: authData.user.email,
    joinDate: profile.join_date,
    // BUGFIX (renderStudentQuizzes crash — "Cannot read properties of
    // undefined (reading 'length')" at index.html renderStudentQuizzes):
    // this shape-bridge object was missing completedQuizzes entirely, unlike
    // the DB.students[] shape (db-service.js's refreshFromRemote()) which
    // always defaults it to []. Every render function that reads
    // currentUser.completedQuizzes (Quest Board's streak stat, the profile
    // stats strip, the dashboard's pending-quiz filter) assumes it's always
    // at least an array, so a real-Supabase-login currentUser without this
    // field threw the instant a student opened the Quest Board. DB.students
    // is already hydrated (AppStore.ready resolves before the login screen
    // even shows), so reuse that row's completedQuizzes if present instead
    // of just defaulting to [] here, so an in-progress session's quiz
    // history isn't dropped.
    completedQuizzes: (typeof DB !== 'undefined' && DB.students
      ? (DB.students.find(s => s.id === profile.id) || {}).completedQuizzes
      : null) || [],
  };
  // AUTH FIX (post-Phase 33 — ISOLATION_ROLES_PLAN.md §12 step 4 follow-up):
  // this used to collapse anything that wasn't 'admin' straight to 'student',
  // which meant a real teacher account (role='teacher', once the relabel in
  // §1 lands) would be logged in AS a student — wrong dashboard, wrong nav,
  // wrong topbar. profiles.role only ever has three values ('admin',
  // 'teacher', 'student'); pass the first two through as-is and only default
  // to 'student' for anything else. Every existing `currentRole==='student'`/
  // `!== 'student'` check elsewhere in the app (world-boss, mail, shop,
  // titles, achievements, etc.) already works unchanged either way, since
  // 'teacher' is just as not-student as 'admin' was. The only call sites that
  // ever singled out 'admin' specifically were auth.js's own bootApp() and
  // nav.js's setupSidebar() (both updated alongside this) plus
  // world-boss/loot-rain.js's admin-panel check — see those files' comments.
  currentRole = (profile.role === 'admin' || profile.role === 'teacher') ? profile.role : 'student';

  // BUGFIX (see REPORT_cross_account_data_and_template_row.md, Part 5, and
  // REPORT_empty_data_until_admin_login.md): DB (the in-memory cache
  // everything else in the app reads) was still whatever initRemote()
  // pulled at PAGE LOAD time — under whatever session existed then (a
  // previous account's, or no session at all). signInWithPassword() above
  // only changes which account can write / which rows RLS allows on the
  // NEXT query; it does nothing to a cache that was already populated
  // before this login happened. That's what let a teacher account render a
  // previous session's (e.g. admin's, or another teacher's) full roster
  // after switching accounts without a full page reload in between. Await
  // a fresh, correctly-scoped pull under THIS session before bootApp()
  // renders anything.
  // refreshAfterAuthChange() calls AppStore.syncFromLegacy() internally,
  // which already re-clones into window.DB and notifies subscribers — no
  // separate DB reassignment needed here.
  if (typeof DBService !== 'undefined' && typeof DBService.refreshAfterAuthChange === 'function') {
    await DBService.refreshAfterAuthChange();
  }

  // Now that a real Supabase Auth session exists, kick off a fresh,
  // authenticated fetch of classroom_layouts/seats/seat_assignments right
  // away rather than waiting for whichever classroom page happens to mount
  // first. See classroom_index.js's _bootstrapClassroomData() — this is the
  // "auth.js doLogin()" call site its own comments already refer to.
  if (typeof window.refreshClassroomData === 'function') {
    window.refreshClassroomData().catch(function (e) {
      console.warn('[auth] post-login classroom data refresh failed:', e);
    });
  }

  // BUGFIX (section names showing as raw IDs): class_sections is fetched
  // once by sections_index.js's _bootstrapSectionData(), triggered by
  // AppStore.ready — which normally fires before the user has logged in.
  // That unauthenticated fetch comes back empty under RLS, so
  // state.classSections stayed [] for the rest of the session unless the
  // user happened to visit Section Maker/Registrations (the only other
  // callers of window.refreshSectionData()) first. Every screen that
  // renders a section's display name (Live Monitor, Quiz Builder,
  // Achievements, Titles, Campaign Map, Classroom Builder, My Section,
  // Analytics, the kiosk) goes through getClassLabel(), which silently
  // falls back to the raw id when classSections has no match — hence
  // teachers/students sometimes seeing "Grade 10 – Rizal" and sometimes
  // just seeing the section's UUID. Same fix as refreshClassroomData
  // above: force a fresh, authenticated re-fetch right after login.
  if (typeof window.refreshSectionData === 'function') {
    window.refreshSectionData().catch(function (e) {
      console.warn('[auth] post-login section data refresh failed:', e);
    });
  }

  bootApp();

  } finally {
    if (typeof eqButtonLoading === 'function') eqButtonLoading(btn, false);
  }
}
// restoreSession() — BUGFIX (refresh logs the user out): Supabase Auth
// already persists its access/refresh token in localStorage
// (persistSession:true in DBService's client config, see db-service.js),
// and DBService.initRemote() already checks client.auth.getSession() to
// decide whether to pull fresh data on page load. But NOTHING previously
// used that saved session to actually restore the LOGGED-IN UI: currentUser
// and currentRole are plain in-memory variables (see app-state.js), so a
// hard refresh reset them to null every time and the login screen showed
// again — even though the Supabase session itself was still valid and
// initRemote() had already pulled this user's data.
//
// This mirrors doLogin()'s post-auth steps (fetch own profile row, map it
// to the currentUser shape bridge, resolve currentRole, then bootApp())
// but starting from an existing session instead of a fresh
// signInWithPassword() call. Called once from index.html inside the
// AppStore.ready.then(...) bootstrap, after DB/AppStore hydration — by the
// time getSession()'s network round trip resolves, every later <script>
// tag (campaign, world-boss, etc.) has already executed, so functions like
// getStageProgress()/wbcUpdateTopbarWidget() that bootApp() depends on are
// safely defined.
// showLoginScreen() — pairs with #boot-loading in index.html (BUGFIX: login
// screen flash on refresh). Hides the boot spinner and reveals the login
// form. login-screen's CSS rule (#login-screen{display:flex;...} in
// base.css) is normally what shows it — it now starts with an inline
// display:none in the HTML that outranks that, so this restores 'flex'
// explicitly rather than just clearing the inline style, to avoid depending
// on CSS cascade order.
function showLoginScreen(){
  const boot = document.getElementById('boot-loading');
  if (boot) boot.style.display = 'none';
  const login = document.getElementById('login-screen');
  if (login) login.style.display = 'flex';
}
async function restoreSession(){
  const client = (typeof DBService !== 'undefined') ? DBService.getAuthClient() : null;
  if (!client) { showLoginScreen(); return; }

  try {
    const { data: sessionData } = await client.auth.getSession();
    if (!sessionData || !sessionData.session) { showLoginScreen(); return; } // no saved session — normal logged-out state

    const authUser = sessionData.session.user;
    const { data: profile, error: profileError } = await client
      .from('profiles')
      .select('*')
      .eq('id', authUser.id)
      .single();

    // Same edge cases doLogin() guards against: a still-pending registration
    // (real Auth account, no profiles row yet) or a deactivated staff
    // account. On refresh there's no login form to show an error in, so we
    // just sign out quietly and leave the person on the login screen —
    // they'll get the normal doLogin() error messaging if they try again.
    if (profileError || !profile || profile.is_active === false) {
      console.warn('[auth] restoreSession: session present but profile missing/inactive; signing out.', profileError);
      await client.auth.signOut();
      showLoginScreen();
      return;
    }

    currentUser = {
      id: profile.id,
      name: profile.display_name,
      displayName: profile.display_name,
      firstName: profile.first_name,
      lastName: profile.last_name,
      init: profile.init,
      color: profile.color,
      xp: profile.xp,
      coins: profile.coins,
      level: profile.level,
      tier: profile.tier,
      attendance: profile.attendance_pct,
      quizAvg: profile.quiz_avg,
      profilePic: profile.profile_pic_url,
      classId: profile.class_id,
      role: profile.role,
      email: authUser.email,
      joinDate: profile.join_date,
      completedQuizzes: (typeof DB !== 'undefined' && DB.students
        ? (DB.students.find(s => s.id === profile.id) || {}).completedQuizzes
        : null) || [],
    };
    currentRole = (profile.role === 'admin' || profile.role === 'teacher') ? profile.role : 'student';

    // DB was already hydrated correctly-scoped by initRemote() (it only
    // pulls when a saved session exists), so no extra refreshAfterAuthChange()
    // pull is needed here — just render. bootApp() hides #boot-loading itself.
    //
    // BUGFIX (section names showing as raw IDs on refresh): unlike DB,
    // class_sections is NOT part of initRemote()'s pull — it's fetched
    // separately by sections_index.js's _bootstrapSectionData(), fired once
    // from AppStore.ready. On a hard refresh that fetch can race the
    // Supabase client's own session restore and lose, leaving
    // state.classSections empty and every getClassLabel() call falling back
    // to the raw id. Force a fresh, now-authenticated re-fetch here too —
    // same fix as doLogin() above.
    if (typeof window.refreshSectionData === 'function') {
      window.refreshSectionData().catch(function (e) {
        console.warn('[auth] restoreSession section data refresh failed:', e);
      });
    }

    bootApp();
  } catch (e) {
    console.warn('[auth] restoreSession failed; leaving user on login screen:', e);
    showLoginScreen();
  }
}
// doLogout() is now ASYNC for the same reason doLogin() is: ending a real
// Supabase Auth session is a network call (client.auth.signOut()). Without
// this, the Supabase client would keep its access token in localStorage and
// silently re-authenticate the same user on next page load, even after
// clicking "Logout" — signOut() explicitly revokes/clears that session.
async function doLogout(){
  // Cleanup 5: closeProfile absorbed from index.html monkey patch (doLogout → closeProfile → _origLogout)
  if(typeof closeProfile==='function')closeProfile();
  const logoutBtn=document.getElementById('sidebar-logout-btn');
  // Same "button looks dead" problem as doLogin() — client.auth.signOut()
  // is a network call. finally-reset at the end (not left for bootApp() to
  // clean up, since logging out doesn't go through bootApp()) so the
  // sidebar button is back to normal the next time this account — or the
  // next one signed into this browser — logs in and out again.
  if (typeof eqButtonLoading === 'function') eqButtonLoading(logoutBtn, true, { label: 'Signing out…' });
  try {
  // BUGFIX (42501 RLS errors — "new row violates row-level security policy"
  // — for orders/inventory/quiz_history/etc. surviving even the flush
  // below): the boss-combat refresh loop, minion spawn loop, presence
  // heartbeat, quiz timer, and the Supabase realtime channels can all
  // independently dirty AppStore state (a boss-combat tick can log a quiz
  // answer or loot drop; a realtime event on orders/inventory/quiz_history
  // re-triggers a pull-then-push cycle — see DBService.teardownRealtime()).
  // These used to be stopped only at the very END of doLogout(), AFTER
  // signOut() had already run — so any one of them ticking during the
  // flush below could queue a brand-new upload the flush never sees, which
  // then fires post-signOut and 42501s. Stopping every one of them FIRST,
  // before flushing anything, closes that gap instead of just narrowing it.
  WBC.joined=false;WBC.bossIdx=-1;WBC.qIdx=0;WBC.answered=[];WBC.comboCount=0;
  WBC.battleStartTime=0;WBC.cooldownActive=false;
  if(WBC.refreshInterval){clearInterval(WBC.refreshInterval);WBC.refreshInterval=null;}
  if(WBC.cooldownTimeout){clearTimeout(WBC.cooldownTimeout);WBC.cooldownTimeout=null;}
  // Stop minion timers
  wbmStopSpawnLoop();
  // System Health presence heartbeat (ADMIN_SYSTEM_HEALTH.md Phase 2):
  // paired with the startPresenceHeartbeat() call in bootApp() below, same
  // start/stop lifecycle pairing as WBC.refreshInterval just above.
  if (typeof SystemHealthService !== 'undefined') SystemHealthService.stopPresenceHeartbeat();
  if (typeof shStopCountsRefresh === 'function') shStopCountsRefresh();
  if(quizTimer)clearInterval(quizTimer);
  if (typeof DBService !== 'undefined' && typeof DBService.teardownRealtime === 'function') {
    DBService.teardownRealtime();
  }

  // Now that nothing can re-dirty state, flush whatever's already pending
  // — a change made just before clicking Logout can still be sitting in
  // AppStore's 300ms persist debounce and/or DBService's 400ms upload
  // debounce. Flushing here, BEFORE signOut(), guarantees any pending
  // write reaches the server (or fails loudly) while the session is still
  // valid, instead of racing teardown. No-op if nothing was pending.
  if (typeof AppStore !== 'undefined' && typeof AppStore.flushNow === 'function') {
    AppStore.flushNow(); // synchronous: flushes the 300ms persist debounce, which itself queues a fresh upload if the state was dirty
  }
  if (typeof DBService !== 'undefined' && typeof DBService.flushPendingUpload === 'function') {
    await DBService.flushPendingUpload(); // flushes that upload (whether just (re)queued above, or already pending) before we tear the session down
  }
  const client = (typeof DBService !== 'undefined') ? DBService.getAuthClient() : null;
  if (client) { try { await client.auth.signOut(); } catch (e) { console.warn('[auth] signOut failed:', e); } }
  // BUGFIX: without this, switching accounts on the same browser (e.g.
  // testing as Teacher A then Teacher B, or after an ownership transfer
  // moves a teacher's content elsewhere) left the PREVIOUS account's cached
  // shop_products/boss_events/etc. sitting in localStorage. The next login's
  // first bulk push would then try to upsert rows still stamped with the
  // old owner_teacher_id/class_id, which correctly fails RLS server-side —
  // seen as "[DBService] remote sync failed" for shop_products/boss_events.
  // Clearing here forces the next login to hydrate fresh from Supabase
  // instead of trusting a stale local mirror.
  if (typeof DBService !== 'undefined' && typeof DBService.remove === 'function') {
    try { DBService.remove(); } catch (e) { console.warn('[auth] local cache clear failed:', e); }
  }
  // Same "don't leak the previous account's state into the next login on
  // this browser" reasoning as DBService.remove() above — a stale "resume
  // last page" or (far more importantly) a stale kiosk-lock flag has no
  // business surviving past an explicit, authenticated logout.
  try { localStorage.removeItem('eq_last_page'); } catch (e) {}
  if (typeof _enrollPersistLock === 'function') { try { _enrollPersistLock(false); } catch (e) {} }
  currentUser=null;currentRole=null;
  document.getElementById('main-app').style.display='none';
  document.getElementById('login-screen').style.display='flex';
  document.getElementById('login-user').value='';document.getElementById('login-pass').value='';
  document.getElementById('login-err').style.display='none';
  document.getElementById('stage-map-btn').style.display='none';
  activeWorld=0;
  } finally {
    if (typeof eqButtonLoading === 'function') eqButtonLoading(logoutBtn, false);
  }
}
function bootApp(){
  // Cleanup 5: profInitAll absorbed from index.html monkey patch (bootApp → profInitAll → _origBoot → refreshAllAvatars)
  if(typeof profInitAll==='function')profInitAll();
  // BUGFIX (login screen flash on refresh): #boot-loading is the true
  // default state now (see index.html), covering both a fresh doLogin()
  // and a restoreSession() on page refresh — harmless no-op if it's
  // already hidden (e.g. manual login, where it was hidden by
  // showLoginScreen() back when restoreSession() found no session).
  const boot = document.getElementById('boot-loading');
  if(boot) boot.style.display='none';
  document.getElementById('login-screen').style.display='none';
  document.getElementById('main-app').style.display='block';
  updateTopbar();setupSidebar();
  // System Health presence heartbeat (ADMIN_SYSTEM_HEALTH.md Phase 2): starts
  // on every bootApp() call — both a fresh doLogin() and a restoreSession()
  // on refresh — and is idempotent (no-ops if already running), since
  // bootApp() itself runs from both call sites. Stopped in doLogout() above.
  if (typeof SystemHealthService !== 'undefined') SystemHealthService.startPresenceHeartbeat();
  if(typeof restoreSidebarState==='function')restoreSidebarState();

  // SECURITY FIX: a browser refresh used to always fall through to the
  // dashboard branch below — which, for a device left in Card Enrollment's
  // Self-Service kiosk Lock Mode, meant reloading was a one-tap escape
  // hatch onto the full admin/teacher shell (sidebar, every other page,
  // all reachable again). This persisted flag takes priority over
  // everything else in this function: if it's set, re-enter the locked
  // kiosk screen directly and skip the dashboard/last-page logic below
  // entirely. See enrollment-hub.js's _enrollRestoreLockedKioskOnBoot().
  const kioskLockedOnDisk = (currentRole==='admin'||currentRole==='teacher') &&
    typeof _enrollHasPersistedLock==='function' && _enrollHasPersistedLock();

  if (kioskLockedOnDisk && typeof _enrollRestoreLockedKioskOnBoot==='function') {
    _enrollRestoreLockedKioskOnBoot();
  } else {
    // BUGFIX: a reload otherwise always discarded whatever page you were
    // actually on and bounced you back to the dashboard. Resume the last
    // page visited (persisted by navTo() — see nav.js) when there's a
    // usable one for this session's role; fall back to the dashboard
    // exactly as before when there isn't (fresh login, nothing saved yet,
    // or the saved id belonged to a different role).
    const lastPage = (typeof getLastVisitedPage === 'function') ? getLastVisitedPage(currentRole) : null;
    const dashId = (currentRole==='admin'||currentRole==='teacher') ? 'a-dashboard' : 's-dashboard';
    if (lastPage && lastPage !== dashId && typeof navTo === 'function') {
      navTo(lastPage);
    } else if(currentRole==='admin'||currentRole==='teacher'){renderAdminDashboard();showPage('a-dashboard');}
    else{renderStudentDashboard();showPage('s-dashboard');}
  }
  // Show stage map button for students — unless an admin has hidden,
  // locked, disabled, or "coming soon"-ed it via Navigation Manager >
  // Student Nav (DSM_STUDENT_DEFAULTS' s-stagemap-btn widget row; see
  // dsm-manager.js's dsmGetWidgetConfig()).
  const btn = document.getElementById('stage-map-btn');
  if(btn){
    const cfg = (typeof dsmGetWidgetConfig==='function')
      ? dsmGetWidgetConfig('s-stagemap-btn')
      : { visible:true, locked:false, disabled:false, status:'active', lockMsg:'' };
    const gated = cfg.locked || cfg.disabled || cfg.status==='coming_soon';
    if(currentRole==='student' && cfg.visible){
      btn.style.display = 'flex';
      btn.disabled = gated;
      btn.style.opacity = gated ? '0.5' : '';
      btn.style.pointerEvents = gated ? 'none' : '';
      btn.style.cursor = gated ? 'not-allowed' : '';
      btn.title = gated ? (cfg.lockMsg || (cfg.status==='coming_soon' ? 'Coming Soon' : 'Locked')) : 'Quest Map';
    } else {
      btn.style.display = 'none';
    }
  }
  // Show notif dot if student has active stage
  if(currentRole==='student'){
    const prog = getStageProgress(currentUser);
    const dot = document.getElementById('stage-notif');
    if(dot) dot.style.display = prog.activeStageId ? 'flex' : 'none';
  }
  // Show boss topbar widget if active boss
  wbcUpdateTopbarWidget();
  // Reset WBC join state on new login
  WBC.joined=false; WBC.bossIdx=-1; WBC.qIdx=0; WBC.comboCount=0; WBC.cooldownActive=false;
  if(WBC.refreshInterval){clearInterval(WBC.refreshInterval);WBC.refreshInterval=null;}
  if(typeof refreshAllAvatars==='function')refreshAllAvatars();

  // Event-Driven Communication phase (roadmap Phase 4) — replaces the 7
  // files that used to monkey-patch window.bootApp. Uses AppStore.emit()
  // rather than updateState(): bootApp() never mutates DB.* itself (it's
  // pure UI/navigation orchestration), and it's the single highest-
  // frequency call in the app (every login, every refresh) — running it
  // through updateState()'s clone/persist pipeline for a change that never
  // happened would be pure waste. See state-manager.js's emit() comment.
  AppStore.emit({ type: 'session:booted', payload: { role: currentRole, userId: currentUser ? currentUser.id : null } });
}

// ── Phase 7 (2026-08-10, session 2): explicit window export ──
// These were previously implicit globals (bare top-level function
// declarations, exposed to window only via classic-script behavior).
// Made explicit ahead of any real module/bundle scoping change —
// see PHASE7_IMPLICIT_GLOBALS.md.
window.doLogin = doLogin;
window.doLogout = doLogout;

// ── Phase 7 (2026-08-10, session 7): explicit window exports ──
// These were previously implicit globals (bare top-level declarations,
// reachable to other files only via classic-script auto-attach-to-window
// behavior). Made explicit ahead of any real bundle/module scoping change
// — found by build/audit-window-exports.js, which checks every symbol with
// a real cross-file consumer, not just ones reachable from onclick markup.
// See PHASE7_WINDOW_EXPORT_AUDIT.md.
window.restoreSession = restoreSession;


/* ---- ./recovery.js ---- */
// ─────────────────────────────────────────────────────────────────────────────
// PASSWORD RECOVERY — "Set new password" screen
// (ISOLATION_ROLES_PLAN.md §11 "Account & access management", §12 step 5,
//  chunk A4 — see modules/admin/teacher-directory.js's "Send Reset Email"
//  button / teacher-directory-service.js's sendPasswordReset() for the
//  admin-side trigger.)
//
// FLOW
//   1. Admin clicks "Send Reset Email" on a Teacher Directory row →
//      DBService.sendPasswordResetEmail(email, redirectTo) calls Supabase's
//      resetPasswordForEmail(), with redirectTo pointing back at THIS app's
//      own origin+path (window.location.origin + window.location.pathname —
//      no fixed production URL is configured yet, so this has to be
//      dynamic; if a fixed URL is added to Supabase's redirect allow-list
//      later, this can be hardcoded instead).
//   2. The teacher/admin opens the email and clicks the link. Supabase
//      redirects back to that URL with recovery tokens attached. The
//      Supabase client is created with its default detectSessionInUrl:true
//      (see db-service.js _getClient()), so it silently parses those tokens
//      and exchanges them for a real (recovery-scoped) session the moment
//      the client is created on this fresh page load — no manual
//      location.hash/location.search parsing needed anywhere in this file.
//   3. That exchange fires a PASSWORD_RECOVERY event via onAuthStateChange.
//      This file listens for exactly that event and swaps in the "Set new
//      password" screen below instead of whatever screen would otherwise
//      show first (normally the login screen).
//   4. Because it's a real session, client.auth.updateUser({ password })
//      works directly against it — no separate "verify OTP/token" step.
//   5. On success: sign out (so the person logs back in fresh with the new
//      password, same posture as any other credential change) and return to
//      the normal login screen with a success toast.
//
// SCOPE NOTE: this screen has no role awareness — it just completes
// whatever recovery session Supabase resolved from the URL. Chunk A4 only
// adds the ADMIN-SIDE TRIGGER button to the Teacher Directory (per the
// build-order decision: directory-triggered resets only, no self-service
// "Forgot password?" link on the login screen yet). Any Supabase Auth
// account that receives a reset email — by whatever means — completes it
// through this same screen; that's fine since resetPasswordForEmail() is
// what generates the token in the first place.
// ─────────────────────────────────────────────────────────────────────────────

window.showRecoveryScreen = function () {
  const loginScreen = document.getElementById('login-screen');
  const regScreen = document.getElementById('reg-screen');
  if (loginScreen) loginScreen.style.display = 'none';
  if (regScreen) regScreen.classList.remove('open');

  document.getElementById('recovery-card-content').innerHTML = `
    <div style="text-align:center;margin-bottom:24px">
      <div style="font-family:var(--fh);font-size:28px;font-weight:900">EDUQUEST</div>
      <div style="color:var(--text-muted);font-size:13px;margin-top:4px">🔑 Set a new password</div>
    </div>

    <div class="form-group">
      <label class="form-label">
        New Password <span style="color:var(--text-muted);font-size:11px">(min 8 characters, letters + numbers)</span>
      </label>
      <div style="position:relative">
        <input type="password" id="rec-pass" placeholder="••••••••" autocomplete="new-password"
               style="width:100%;padding-right:40px" oninput="recCheckValidation()">
        ${regPasswordToggleBtn('rec-pass')}
      </div>
      <div id="rec-pass-msg" class="reg-validation-msg"></div>
    </div>

    <div class="form-group">
      <label class="form-label">Confirm New Password</label>
      <div style="position:relative">
        <input type="password" id="rec-pass-confirm" placeholder="••••••••" autocomplete="new-password"
               style="width:100%;padding-right:40px" oninput="recCheckValidation()"
               onkeydown="if(event.key==='Enter')doSetNewPassword()">
        ${regPasswordToggleBtn('rec-pass-confirm')}
      </div>
      <div id="rec-pass-confirm-msg" class="reg-validation-msg"></div>
    </div>

    <div id="rec-err" style="color:#ffb4ab;font-size:13px;margin-bottom:10px;display:none"></div>

    <button class="btn btn-primary btn-block" id="rec-submit-btn" style="padding:13px;font-size:15px" onclick="doSetNewPassword()">
      Set New Password →
    </button>
  `;

  // Own copy of the screen shell + validation-message styles, deliberately
  // NOT relying on registrations.js's showRegScreen() having run first (it
  // injects the same-named .reg-validation-msg classes, but only the first
  // time someone opens the registration screen — a recovery-link visit is
  // very likely the FIRST thing to happen on a fresh page load, so this
  // can't assume that's already there).
  if (!document.getElementById('recovery-screen-styles')) {
    const style = document.createElement('style');
    style.id = 'recovery-screen-styles';
    style.textContent = `
      #recovery-screen {
        display: none; position: fixed; inset: 0; z-index: 999;
        background: var(--surface, #1a1a2e);
        overflow-y: auto; padding: 24px 16px;
        justify-content: center; align-items: flex-start;
      }
      #recovery-screen.open { display: flex; }
      .reg-validation-msg { font-size: 11px; min-height: 16px; margin-top: 3px; }
      .reg-validation-msg.ok  { color: #4edea3; }
      .reg-validation-msg.err { color: #ffb4ab; }
    `;
    document.head.appendChild(style);
  }

  document.getElementById('recovery-screen').classList.add('open');
  setTimeout(function () { const f = document.getElementById('rec-pass'); if (f) f.focus(); }, 50);
};

function recCheckValidation() {
  const passEl = document.getElementById('rec-pass');
  const confirmEl = document.getElementById('rec-pass-confirm');
  if (!passEl || !confirmEl) return;
  const pass = passEl.value;
  const confirmVal = confirmEl.value;
  const passMsg = document.getElementById('rec-pass-msg');
  const confirmMsg = document.getElementById('rec-pass-confirm-msg');

  if (!pass) {
    passMsg.textContent = ''; passMsg.className = 'reg-validation-msg';
  } else {
    const v = regValidatePassword(pass);
    passMsg.textContent = v.ok ? '✓ Looks good' : v.msg;
    passMsg.className = 'reg-validation-msg ' + (v.ok ? 'ok' : 'err');
  }

  if (!confirmVal) {
    confirmMsg.textContent = ''; confirmMsg.className = 'reg-validation-msg';
  } else {
    const match = confirmVal === pass;
    confirmMsg.textContent = match ? '✓ Passwords match' : 'Passwords do not match.';
    confirmMsg.className = 'reg-validation-msg ' + (match ? 'ok' : 'err');
  }
}

window.doSetNewPassword = async function () {
  const pass = document.getElementById('rec-pass').value;
  const confirmVal = document.getElementById('rec-pass-confirm').value;
  const err = document.getElementById('rec-err');
  err.style.display = 'none';

  const v = regValidatePassword(pass);
  if (!v.ok) { err.textContent = '❌ ' + v.msg; err.style.display = 'block'; return; }
  if (pass !== confirmVal) { err.textContent = '❌ Passwords do not match.'; err.style.display = 'block'; return; }

  const client = (typeof DBService !== 'undefined') ? DBService.getAuthClient() : null;
  if (!client) {
    err.textContent = '⏳ Still connecting, please try again in a moment.';
    err.style.display = 'block';
    return;
  }

  const btn = document.getElementById('rec-submit-btn');
  const originalLabel = btn.textContent;
  btn.disabled = true; btn.textContent = 'Saving…';

  const { error } = await client.auth.updateUser({ password: pass });

  btn.disabled = false; btn.textContent = originalLabel;

  if (error) {
    // Expired/already-used links land here — updateUser() fails against a
    // session that never got established or has since gone stale.
    err.textContent = '❌ ' + (error.message || 'Could not update your password. The reset link may have expired — ask your admin to send a new one.');
    err.style.display = 'block';
    return;
  }

  // Sign out of the recovery session so the person logs back in fresh with
  // the new password, same posture as any other credential change (see
  // doLogout()'s comment in auth.js for why signOut() itself is async).
  try { await client.auth.signOut(); } catch (e) { console.warn('[recovery] post-reset signOut failed:', e); }

  document.getElementById('recovery-screen').classList.remove('open');
  const loginScreen = document.getElementById('login-screen');
  if (loginScreen) loginScreen.style.display = 'flex';
  if (typeof toast === 'function') toast('✅ Password updated. Log in with your new password.');
};

// ── LISTEN FOR THE RECOVERY REDIRECT ────────────────────────────────────────
// Registered once, at script-load time — this runs on EVERY page load, not
// just ones that came from a reset email, so it has to be a no-op the rest
// of the time (and it is: PASSWORD_RECOVERY only ever fires when the client
// actually parsed recovery tokens out of the URL). Calling getAuthClient()
// here is what triggers the Supabase client's first creation on a fresh
// page load coming straight from a recovery link — same lazy singleton
// db-service.js's _getClient() would hand back to whatever else asked for
// it a few script-tags later regardless.
(function () {
  const client = (typeof DBService !== 'undefined') ? DBService.getAuthClient() : null;
  if (!client) return;
  client.auth.onAuthStateChange(function (event) {
    if (event === 'PASSWORD_RECOVERY') {
      window.showRecoveryScreen();
    }
  });
})();

// ── Phase 7 (2026-08-10, session 2): explicit window export ──
// These were previously implicit globals (bare top-level function
// declarations, exposed to window only via classic-script behavior).
// Made explicit ahead of any real module/bundle scoping change —
// see PHASE7_IMPLICIT_GLOBALS.md.
window.recCheckValidation = recCheckValidation;


