/* ---- ./modules/admin/sections-service.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/admin/sections-service.js
//  Service Layer for Phase 4 Section Maker.
//
//  REPOSITORY PATTERN CONTRACT — same rule as AttendanceService
//  (see modules/attendance/attendance-service.js header):
//    UI modules (sections.js, registrations.js, the kiosk/Live Monitor/
//    seating-builder class selectors) NEVER call Supabase and NEVER mutate
//    AppStore state directly for anything in this file's domain. They call
//    SectionService.<method>(...). SectionService is the ONLY thing that:
//      a) calls DBService.rpc() for class_sections writes, and
//      b) calls AppStore.updateState() to reflect those writes into the
//         single source of truth.
//
//  STATE SHAPE (slice populated by sections_index.js → AppStore):
//    draft.classSections  [{ id, gradeLevel, sectionName, adviserId, archived,
//                             createdAt, updatedAt }]
//
//  See Section_Maker_Feature_Spec.md §2–§5 for the design this implements.
// ═══════════════════════════════════════════════════════════════════════════════

window.SectionService = (function () {
  'use strict';

  function _rowFromRpcResult(data) {
    return {
      id: data.id,
      gradeLevel: data.grade_level,
      sectionName: data.section_name,
      adviserId: data.adviser_id || null,
      archived: !!data.archived,
      createdAt: data.created_at,
      updatedAt: data.updated_at,
    };
  }

  function _upsertIntoDraft(draft, row) {
    if (!Array.isArray(draft.classSections)) draft.classSections = [];
    const idx = draft.classSections.findIndex(s => s.id === row.id);
    if (idx >= 0) draft.classSections[idx] = row;
    else draft.classSections.push(row);
  }

  /**
   * createSection(gradeLevel, sectionName, opts) → Promise<{ok, error?, section?}>
   * opts: { adviserId?, schedule?, dayOverrides? }
   * opts.schedule (optional; BUGFIX report §3): { openTime, startTime,
   * lateCutoff, closeTime } — 'HH:MM' or 'HH:MM:SS' strings. When provided,
   * create_class_section() creates the DEFAULT (dayOfWeek 0) attendance_schedules
   * row in the same transaction, so the section can take attendance the
   * moment it's created instead of needing a second trip to the kiosk's
   * settings screen. Omit it to create a schedule-less section exactly as
   * before (still editable later via AttendanceService.upsertSchedule()).
   * opts.dayOverrides (Phase 54, optional): [{ dayOfWeek, openTime,
   * startTime, lateCutoff, closeTime, dayOff? }, ...] — per-weekday
   * exceptions to the default above (e.g. a shorter Friday). dayOff: true
   * (Phase 55) marks that weekday as having no class at all instead of
   * custom times — openTime/startTime/lateCutoff/closeTime are still
   * required (sent as '00:00' placeholders) but are ignored server-side
   * once dayOff is set. Only meaningful alongside opts.schedule, since a
   * section needs a section id before any override row can reference it:
   * each is applied as its own upsert_attendance_schedule call right after
   * create_class_section() returns, sequentially so a failure partway
   * through still leaves earlier days saved.
   */
  async function createSection(gradeLevel, sectionName, opts) {
    opts = opts || {};
    const grade = String(gradeLevel || '').trim();
    const name = String(sectionName || '').trim();
    if (!grade) return { ok: false, error: 'Grade level is required.' };
    if (!name) return { ok: false, error: 'Section name is required.' };

    const sched = opts.schedule || {};
    const hasSchedule = !!(sched.openTime && sched.startTime && sched.lateCutoff && sched.closeTime);
    const dayOverrides = hasSchedule ? (opts.dayOverrides || []) : []; // no default = no overrides to hang off it

    const rpcParams = {
      p_grade_level: grade, p_section_name: name, p_adviser_id: opts.adviserId || null,
    };
    if (hasSchedule) {
      rpcParams.p_open_time = sched.openTime;
      rpcParams.p_start_time = sched.startTime;
      rpcParams.p_late_cutoff = sched.lateCutoff;
      rpcParams.p_close_time = sched.closeTime;
    }

    const { data, error } = await DBService.rpc('create_class_section', rpcParams);
    if (error) {
      console.error('[SectionService] createSection failed:', error);
      return { ok: false, error: error.message || 'Could not create section.' };
    }

    const row = _rowFromRpcResult(data);

    // Day overrides need the section id create_class_section() just
    // returned, so they're applied as follow-up calls to the same RPC
    // Section Maker's edit modal uses (upsert_attendance_schedule) —
    // sequential, not parallel, so a mid-week failure doesn't race with
    // its neighbors and is easy to reason about in the returned errors list.
    const dayOverrideErrors = [];
    for (const ov of dayOverrides) {
      const { error: ovError } = await DBService.rpc('upsert_attendance_schedule', {
        p_class_id: row.id, p_open_time: ov.openTime, p_start_time: ov.startTime,
        p_late_cutoff: ov.lateCutoff, p_close_time: ov.closeTime, p_day_of_week: ov.dayOfWeek,
        p_day_off: !!ov.dayOff,
      });
      if (ovError) {
        console.error('[SectionService] createSection day-override failed:', ov.dayOfWeek, ovError);
        dayOverrideErrors.push(ov.dayOfWeek);
      }
    }

    AppStore.updateState(draft => {
      _upsertIntoDraft(draft, row);
      // The RPC also wrote the default attendance_schedules row server-side
      // when a schedule was supplied — mirror it into the draft so the
      // kiosk/Live Monitor don't need a realtime round-trip to see the new
      // section is usable.
      if (!Array.isArray(draft.attendanceSchedules)) draft.attendanceSchedules = [];
      if (hasSchedule) {
        const idx = draft.attendanceSchedules.findIndex(s => s.classId === row.id && (s.dayOfWeek || 0) === 0);
        const schedRow = {
          id: null, classId: row.id, dayOfWeek: 0, openTime: sched.openTime, startTime: sched.startTime,
          lateCutoff: sched.lateCutoff, closeTime: sched.closeTime, active: true,
        };
        if (idx >= 0) draft.attendanceSchedules[idx] = schedRow;
        else draft.attendanceSchedules.push(schedRow);
      }
      // Mirror whichever day overrides actually succeeded above.
      dayOverrides
        .filter(ov => !dayOverrideErrors.includes(ov.dayOfWeek))
        .forEach(ov => {
          const idx = draft.attendanceSchedules.findIndex(s => s.classId === row.id && (s.dayOfWeek || 0) === ov.dayOfWeek);
          const schedRow = {
            id: null, classId: row.id, dayOfWeek: ov.dayOfWeek, dayOff: !!ov.dayOff, openTime: ov.openTime, startTime: ov.startTime,
            lateCutoff: ov.lateCutoff, closeTime: ov.closeTime, active: true,
          };
          if (idx >= 0) draft.attendanceSchedules[idx] = schedRow;
          else draft.attendanceSchedules.push(schedRow);
        });
    }, { type: 'sections:created', payload: { sectionId: row.id, scheduled: hasSchedule, dayOverrideCount: dayOverrides.length - dayOverrideErrors.length } });

    if (dayOverrideErrors.length) {
      return {
        ok: true, section: row,
        error: `Section created, but ${dayOverrideErrors.length} day override${dayOverrideErrors.length === 1 ? '' : 's'} failed to save — edit the section to retry.`,
      };
    }
    return { ok: true, section: row };
  }

  /**
   * updateSection(sectionId, patch) → Promise<{ok, error?, section?}>
   * patch: { gradeLevel?, sectionName?, adviserId?, clearAdviser? }
   * Renaming/re-grading relabels the existing row — id never changes (§5).
   */
  async function updateSection(sectionId, patch) {
    patch = patch || {};
    if (!sectionId) return { ok: false, error: 'sectionId is required.' };

    const { data, error } = await DBService.rpc('update_class_section', {
      p_section_id: sectionId,
      p_grade_level: patch.gradeLevel || null,
      p_section_name: patch.sectionName || null,
      p_adviser_id: patch.adviserId || null,
      p_clear_adviser: !!patch.clearAdviser,
    });
    if (error) {
      console.error('[SectionService] updateSection failed:', error);
      return { ok: false, error: error.message || 'Could not update section.' };
    }

    const row = _rowFromRpcResult(data);
    AppStore.updateState(draft => {
      _upsertIntoDraft(draft, row);
    }, { type: 'sections:updated', payload: { sectionId: row.id } });

    return { ok: true, section: row };
  }

  /**
   * archiveSection(sectionId) → Promise<{ok, error?, section?}>
   * Soft-delete only — a section with students/schedule/seating/attendance
   * history attached is never hard-deleted (§5).
   */
  async function archiveSection(sectionId) {
    if (!sectionId) return { ok: false, error: 'sectionId is required.' };

    const { data, error } = await DBService.rpc('archive_class_section', { p_section_id: sectionId });
    if (error) {
      console.error('[SectionService] archiveSection failed:', error);
      return { ok: false, error: error.message || 'Could not archive section.' };
    }

    const row = _rowFromRpcResult(data);
    AppStore.updateState(draft => {
      _upsertIntoDraft(draft, row);
    }, { type: 'sections:archived', payload: { sectionId: row.id } });

    return { ok: true, section: row };
  }

  /**
   * unarchiveSection(sectionId) → Promise<{ok, error?, section?}>
   */
  async function unarchiveSection(sectionId) {
    if (!sectionId) return { ok: false, error: 'sectionId is required.' };

    const { data, error } = await DBService.rpc('unarchive_class_section', { p_section_id: sectionId });
    if (error) {
      console.error('[SectionService] unarchiveSection failed:', error);
      return { ok: false, error: error.message || 'Could not restore section.' };
    }

    const row = _rowFromRpcResult(data);
    AppStore.updateState(draft => {
      _upsertIntoDraft(draft, row);
    }, { type: 'sections:unarchived', payload: { sectionId: row.id } });

    return { ok: true, section: row };
  }

  /**
   * reassignAdviser(sectionId, newAdviserId, opts) → Promise<{ok, error?, section?}>
   * opts: { clearAdviser? } — mid-year coverage change for ONE section,
   * independent of full offboarding (see ownership-service.js for that).
   * Backed by reassign_section_adviser() (Phase 42) rather than
   * updateSection() above — same authorization, but scoped to just the
   * adviser column and its own audit_log entry, since "who covers this
   * section" is a distinct action from "edit this section's name/grade".
   */
  async function reassignAdviser(sectionId, newAdviserId, opts) {
    opts = opts || {};
    if (!sectionId) return { ok: false, error: 'sectionId is required.' };
    if (!opts.clearAdviser && !newAdviserId) return { ok: false, error: 'Choose a new adviser, or clear the current one.' };

    const { data, error } = await DBService.rpc('reassign_section_adviser', {
      p_section_id: sectionId,
      p_new_adviser_id: opts.clearAdviser ? null : newAdviserId,
      p_clear_adviser: !!opts.clearAdviser,
    });
    if (error) {
      console.error('[SectionService] reassignAdviser failed:', error);
      return { ok: false, error: error.message || 'Could not reassign this section.' };
    }

    const row = _rowFromRpcResult(data);
    AppStore.updateState(draft => {
      _upsertIntoDraft(draft, row);
    }, { type: 'sections:adviser-reassigned', payload: { sectionId: row.id } });

    return { ok: true, section: row };
  }

  /**
   * listSections({ includeArchived }) → Array
   * Synchronous read straight off AppStore — classSections is kept current
   * by sections_index.js's bootstrap + realtime subscription, same pattern
   * as classroomLayouts.
   */
  function listSections(opts) {
    opts = opts || {};
    const all = AppStore.getSlice(s => s.classSections) || [];
    return opts.includeArchived ? all : all.filter(s => !s.archived);
  }

  /**
   * getSection(sectionId) → Object|null
   */
  function getSection(sectionId) {
    const all = AppStore.getSlice(s => s.classSections) || [];
    return all.find(s => s.id === sectionId) || null;
  }

  return {
    createSection,
    updateSection,
    archiveSection,
    unarchiveSection,
    reassignAdviser,
    listSections,
    getSection,
  };
}());

// ═══════════════════════════════════════════════════════════════════════════════
//  Shared class-list helpers — used by every screen that used to derive its
//  class dropdown from `Array.from(new Set(students.map(s => s.classId)))`:
//  the kiosk (att_scanner_rfid.js), Live Monitor (live_monitor.js), and the
//  seating layout builder (classroom_builder.js). See §6 of the spec.
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * getActiveClassIds(state) → string[]
 * Returns every non-archived class_sections id, sorted by grade then name.
 * Falls back to the old "derive from whichever students happen to exist"
 * behavior ONLY when no sections have been created yet, so a fresh
 * deployment (or one that hasn't run Section Maker yet) never shows an
 * empty dropdown.
 */
window.getActiveClassIds = function (state) {
  state = state || (window.AppStore ? AppStore.getState() : {});
  const sections = (state.classSections || []).filter(s => !s.archived);

  if (sections.length) {
    return sections
      .slice()
      .sort((a, b) => {
        const g = String(a.gradeLevel).localeCompare(String(b.gradeLevel), undefined, { numeric: true });
        if (g !== 0) return g;
        return String(a.sectionName).localeCompare(String(b.sectionName));
      })
      .map(s => s.id);
  }

  // No sections created yet — same derive-from-students fallback every
  // selector used before Section Maker existed.
  return Array.from(new Set((state.students || []).map(s => s.classId || 'default-class'))).sort();
};

/**
 * getClassLabel(classId, state) → string
 * Human-readable label for a classId in dropdowns — "Grade 10 – Rizal" when
 * it resolves to a real section, otherwise the raw classId string (covers
 * pre-Section-Maker ad-hoc classIds and the backfill's unreviewed rows).
 */
window.getClassLabel = function (classId, state) {
  state = state || (window.AppStore ? AppStore.getState() : {});
  const section = (state.classSections || []).find(s => s.id === classId);
  if (section) return 'Grade ' + section.gradeLevel + ' – ' + section.sectionName;
  return classId;
};

/**
 * getMySectionsLabel(state) → string
 * Phase 33 (ISOLATION_ROLES_PLAN.md §12 step 4) — Command Center and
 * Analytics both used to hardcode "Grade 8-A" in their header regardless of
 * which account was logged in. This replaces that with the caller's ACTUAL
 * owned section(s): every non-archived class_sections row whose adviserId
 * is the current user. A section with no adviser yet, or an account that
 * owns none (today's single `role='admin'` account, or the future real
 * `admin` oversight role once the relabel lands), falls back to
 * "All Sections" rather than a misleading single hardcoded grade.
 */
window.getMySectionsLabel = function (state) {
  state = state || (window.AppStore ? AppStore.getState() : {});
  const uid = (typeof currentUser !== 'undefined' && currentUser) ? currentUser.id : null;
  const mine = (state.classSections || [])
    .filter(s => !s.archived && uid && s.adviserId === uid)
    .sort((a, b) => String(a.gradeLevel).localeCompare(String(b.gradeLevel), undefined, { numeric: true })
      || String(a.sectionName).localeCompare(String(b.sectionName)));
  if (!mine.length) return 'All Sections';
  return mine.map(s => 'Grade ' + s.gradeLevel + ' – ' + s.sectionName).join(', ');
};

console.log('[EduQuest] admin/sections-service.js loaded — SectionService registered.');


/* ---- ./modules/admin/sections.js ---- */
// ══════════════════════════════════════════════════════
//  modules/admin/sections.js
//  Section Maker — admin page for creating/editing/archiving class_sections.
//  Implements Section_Maker_Feature_Spec.md §3, §5, §8 (build order steps 3 & 8).
//
//  DB table: public.class_sections (via SectionService, never called directly)
//  AppStore slice: draft.classSections
//    [{ id, gradeLevel, sectionName, adviserId, archived, createdAt, updatedAt }]
//
//  This page is the canonical place sections are created — before this
//  page existed, a "class" only appeared once a student happened to have
//  that classId string on their profile (see spec §1). Every other screen
//  that lists classes (kiosk, Live Monitor, seating builder, the
//  registration form) reads from the same classSections slice via
//  window.getActiveClassIds() / window.getClassLabel() (sections-service.js).
//
//  CHUNK D — adviser picker + standalone reassignment (ISOLATION_ROLES_PLAN.md
//  Chunk D, see supabase/phase42_ownership_lifecycle.sql):
//    - The create/edit modal's adviser <select> used to offer only
//      state.admin or "Unassigned" (this app had exactly one account when
//      it was written). Now that a real multi-teacher roster exists
//      (Chunk A), it's sourced from TeacherDirectoryService.getDirectory()
//      instead — admin-only, since that RPC is is_admin()-gated. A teacher
//      editing their own section still sees the field, but as read-only
//      text, not a picker.
//    - "🔁 Reassign" is a new quick action, separate from "✏️ Edit" — a
//      mid-year coverage change ("who covers this section starting
//      today") shouldn't require opening the full edit form and touching
//      grade/name. Backed by SectionService.reassignAdviser(), which logs
//      its own audit_log entry (see phase42). Admin-only, same reasoning
//      as the picker above.
//
//  PHASE 49 — auto-own on create + roster viewer (see
//  supabase/phase49_section_maker_fix.sql):
//    - Section creation was also fixed at the SQL layer (Phase 39 had left
//      a stray duplicate overload of create_class_section() that made
//      every create call ambiguous — see that migration's header). As
//      part of the same fix, create_class_section() now forces
//      adviser_id = the calling teacher on the server, so a teacher never
//      again ends up owning nothing after creating a section. The adviser
//      field below just reflects that for teachers instead of offering a
//      picker they can't use.
//    - "👥 View Roster" is a new quick action: a big, dedicated view of
//      every student in a section, with profile picture, level, and
//      attendance at a glance — see _secOpenRosterModal().
//
//  PHASE 54 — WEEKLY ATTENDANCE SCHEDULE (see
//  supabase/phase54_weekly_attendance_schedule.sql):
//    - attendance_schedules used to be exactly one row per section, so a
//      section that ran shorter hours on, say, Friday had no way to
//      represent that — command-center.js even carried a DATA GAP comment
//      about it. The schedule block in the create/edit modal is now a full
//      weekly editor: one DEFAULT (whole-week) set of times, plus optional
//      per-day overrides for Monday–Sunday. A day left unticked always
//      follows the default automatically, including days added later.
//    - Backed by dayOfWeek on attendance_schedules (0 = default, 1..7 =
//      ISO weekday override) and get_effective_attendance_schedule()
//      server-side, which process_attendance_scan(), the kiosk countdown,
//      and Command Center all now resolve against instead of assuming
//      there's only ever one row per class_id.
//    - The modal grew from 'sm' to 'lg' to fit this — see
//      _secOpenCreateModal()/_secOpenEditModal().
// ══════════════════════════════════════════════════════

const GRADE_LEVELS = ['7', '8', '9', '10', '11', '12'];

// Phase 54 — weekly attendance schedule. ISO weekday numbering (1=Monday..
// 7=Sunday), matching Postgres' extract(isodow from date) so the client and
// get_effective_attendance_schedule() never disagree about which day is
// which. dayOfWeek 0 (not listed here) is the separate "default/whole-week"
// row — see _secScheduleFieldsHTML().
const SEC_DAY_DEFS = [
  { dow: 1, short: 'Mon', full: 'Monday' },
  { dow: 2, short: 'Tue', full: 'Tuesday' },
  { dow: 3, short: 'Wed', full: 'Wednesday' },
  { dow: 4, short: 'Thu', full: 'Thursday' },
  { dow: 5, short: 'Fri', full: 'Friday' },
  { dow: 6, short: 'Sat', full: 'Saturday' },
  { dow: 7, short: 'Sun', full: 'Sunday' },
];

let _secMounted = false;
let _secGradeFilter = 'all';
let _secShowArchived = false;
let _secSearch = '';

// Lazy-loaded, admin-only teacher roster for the adviser picker/reassign
// modal — fetched once per Section Maker mount, not on every render.
let _secTeacherDir = null;
let _secTeacherDirLoading = false;

async function _secEnsureTeacherDir() {
  if (currentRole !== 'admin') return [];
  if (_secTeacherDir || _secTeacherDirLoading) return _secTeacherDir || [];
  _secTeacherDirLoading = true;
  try {
    const res = await TeacherDirectoryService.getDirectory();
    _secTeacherDir = res.ok ? res.teachers.filter(t => t.isActive !== false) : [];
  } catch (e) {
    console.warn('[SectionMaker] Could not load teacher directory for adviser picker:', e);
    _secTeacherDir = [];
  } finally {
    _secTeacherDirLoading = false;
  }
  return _secTeacherDir;
}

// ── MAIN RENDER ─────────────────────────────────────────

window.renderSectionMaker = function () {
  _secMounted = true;
  _secTeacherDir = null; // re-fetch on every mount — roster may have changed

  document.getElementById('a-sections').innerHTML = `
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:24px;flex-wrap:wrap;gap:12px">
    <div>
      <div style="font-family:var(--fh);font-size:26px;font-weight:900">🏫 Section Maker</div>
      <div style="color:var(--text-muted);font-size:13px;margin-top:4px" id="sec-header-sub"></div>
    </div>
    <button class="btn btn-primary" onclick="_secOpenCreateModal()">＋ New Section</button>
  </div>

  <div id="sec-stats" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin-bottom:20px"></div>

  <div class="sec-filter-bar">
    <select id="sec-grade-filter" onchange="_secGradeFilter=this.value;_secRenderList()">
      <option value="all">All Grades</option>
      ${GRADE_LEVELS.map(g => `<option value="${g}">Grade ${g}</option>`).join('')}
    </select>
    <label class="sec-archived-toggle">
      <input type="checkbox" id="sec-show-archived" onchange="_secShowArchived=this.checked;_secRenderList()">
      Show archived
    </label>
    <input class="reg-search-input" type="text" placeholder="Search section name…" value="${_secSearch}"
           oninput="_secSearch=this.value;_secRenderList()">
  </div>

  <div id="sec-list"></div>`;

  _secRenderList();

  AppStore.subscribe('section-maker', function (state, event) {
    if (!_secMounted) return;
    if (!event || event.type === 'state:updated' || event.type.indexOf('sections:') === 0 || event.type === 'state:remote-sync') {
      _secRenderList();
    }
  });

  if (typeof window.refreshSectionData === 'function') {
    window.refreshSectionData().catch(function (e) {
      console.warn('[SectionMaker] mount-time section data refresh failed:', e);
    });
  }
};

window.unmountSectionMaker = function () {
  _secMounted = false;
  AppStore.unsubscribe('section-maker');
};

// ── LIST RENDER ─────────────────────────────────────────

window._secRenderList = function () {
  if (!_secMounted) return;
  const state = AppStore.getState();
  const all = state.classSections || [];
  const active = all.filter(s => !s.archived);
  const archived = all.filter(s => s.archived);
  const gradesCovered = new Set(active.map(s => s.gradeLevel)).size;

  const subEl = document.getElementById('sec-header-sub');
  if (subEl) subEl.textContent = `${currentRole === 'admin' ? 'Every section, school-wide · ' : 'Your sections · '}${active.length} active section${active.length === 1 ? '' : 's'} · ${archived.length} archived`;

  const statsEl = document.getElementById('sec-stats');
  if (statsEl) {
    statsEl.innerHTML = `
      <div class="glass-card" style="padding:14px;text-align:center;margin-bottom:0">
        <div style="font-family:var(--fh);font-size:26px;font-weight:900;color:var(--primary)">${active.length}</div>
        <div style="font-size:10px;color:var(--text-muted);font-weight:700;letter-spacing:.08em;text-transform:uppercase">Active</div>
      </div>
      <div class="glass-card" style="padding:14px;text-align:center;margin-bottom:0">
        <div style="font-family:var(--fh);font-size:26px;font-weight:900;color:var(--secondary)">${gradesCovered}</div>
        <div style="font-size:10px;color:var(--text-muted);font-weight:700;letter-spacing:.08em;text-transform:uppercase">Grades Covered</div>
      </div>
      <div class="glass-card" style="padding:14px;text-align:center;margin-bottom:0">
        <div style="font-family:var(--fh);font-size:26px;font-weight:900;color:#ffb95f">${archived.length}</div>
        <div style="font-size:10px;color:var(--text-muted);font-weight:700;letter-spacing:.08em;text-transform:uppercase">Archived</div>
      </div>`;
  }

  const listEl = document.getElementById('sec-list');
  if (listEl) listEl.innerHTML = _secRenderListHTML(all);
};

function _secStudentCount(state, sectionId) {
  return (state.students || []).filter(s => (s.classId || 'default-class') === sectionId).length;
}

function _secRenderListHTML(all) {
  const state = AppStore.getState();
  let list = _secShowArchived ? all : all.filter(s => !s.archived);
  if (_secGradeFilter !== 'all') list = list.filter(s => s.gradeLevel === _secGradeFilter);
  const q = (_secSearch || '').trim().toLowerCase();
  if (q) list = list.filter(s => s.sectionName.toLowerCase().includes(q));

  if (!list.length) {
    return `<div style="text-align:center;padding:64px;background:rgba(35,31,56,.7);border:1px solid var(--border);border-radius:16px">
      <div style="font-size:48px;margin-bottom:12px">🏫</div>
      <div style="font-family:var(--fh);font-size:17px;font-weight:800;margin-bottom:6px">No sections found</div>
      <div style="color:var(--text-muted);font-size:13px">${all.length === 0 ? 'Create your first section to get started — the kiosk, Live Monitor, and seating builder will pick it up automatically.' : 'Try a different filter or search term.'}</div>
    </div>`;
  }

  // Group by grade level for readability.
  const byGrade = {};
  list.forEach(s => {
    if (!byGrade[s.gradeLevel]) byGrade[s.gradeLevel] = [];
    byGrade[s.gradeLevel].push(s);
  });
  const grades = Object.keys(byGrade).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  return grades.map(g => `
    <div style="margin-bottom:20px">
      <div style="font-family:var(--fh);font-size:13px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted);margin-bottom:8px">Grade ${_esc(g)}</div>
      <div class="sec-grid">
        ${byGrade[g]
          .sort((a, b) => a.sectionName.localeCompare(b.sectionName))
          .map(s => _secCardHTML(s, state))
          .join('')}
      </div>
    </div>`).join('');
}

function _secCardHTML(s, state) {
  const count = _secStudentCount(state, s.id);
  const adviserName = _secAdviserName(s.adviserId, state);
  const defaultSched = _secGetSchedule(s.id, state);
  const dayOverrideRows = Object.values(_secGetDayOverrides(s.id, state));
  const dayOffCount = dayOverrideRows.filter(r => r.dayOff).length;
  const overrideCount = dayOverrideRows.length - dayOffCount;
  const t = v => (v ? String(v).slice(0, 5) : '');
  return `<div class="sec-card ${s.archived ? 'sec-card-archived' : ''}">
    <div class="sec-card-top">
      <div class="sec-card-name">${_esc(s.sectionName)}</div>
      ${s.archived ? `<span class="badge-pill bp-muted">Archived</span>` : `<span class="badge-pill bp-primary">Active</span>`}
    </div>
    <div class="sec-card-meta">
      <span>👥 ${count} student${count === 1 ? '' : 's'}</span>
      <span>👤 ${adviserName ? _esc(adviserName) : 'No adviser assigned'}</span>
      ${defaultSched
        ? `<span title="Default — applies every day unless overridden">⏰ ${t(defaultSched.openTime)}–${t(defaultSched.closeTime)}${overrideCount ? ` <span style="color:var(--primary)">· 🗓 ${overrideCount} custom day${overrideCount === 1 ? '' : 's'}</span>` : ''}${dayOffCount ? ` <span style="color:#ff8a8a">· 🚫 ${dayOffCount} day${dayOffCount === 1 ? '' : 's'} off</span>` : ''}</span>`
        : `<span style="color:var(--text-muted)">⏰ No attendance schedule set</span>`}
    </div>
    <div class="sec-card-id" title="This is the classId value stored on students, schedules, seating layouts, and attendance logs.">id: ${_esc(s.id)}</div>
    <div class="sec-card-actions">
      <button class="btn btn-ghost btn-xs" onclick="_secOpenRosterModal('${s.id}')">👥 Roster</button>
      <button class="btn btn-ghost btn-xs" onclick="_secOpenEditModal('${s.id}')">✏️ Edit</button>
      ${(!s.archived && currentRole === 'admin')
        ? `<button class="btn btn-ghost btn-xs" onclick="_secOpenReassignModal('${s.id}')">🔁 Reassign</button>` : ''}
      ${s.archived
        ? `<button class="btn btn-ghost btn-xs" onclick="_secUnarchive('${s.id}')">↩ Restore</button>`
        : `<button class="btn btn-danger btn-xs" onclick="_secConfirmArchive('${s.id}', ${count})">🗄 Archive</button>`}
    </div>
  </div>`;
}

function _secAdviserName(adviserId, state) {
  if (!adviserId) return null;
  if (state.admin && state.admin.id === adviserId) return state.admin.name;
  const s = (state.students || []).find(st => st.id === adviserId);
  return s ? s.name : adviserId;
}

// ── CREATE / EDIT MODAL ─────────────────────────────────

window._secOpenCreateModal = async function () {
  await _secEnsureTeacherDir();
  showModal(_secModalHTML(null), 'lg');
};

window._secOpenEditModal = async function (sectionId) {
  const state = AppStore.getState();
  const section = (state.classSections || []).find(s => s.id === sectionId);
  if (!section) { toast('❌ Section not found.', '#ffb4ab'); return; }
  await _secEnsureTeacherDir();
  showModal(_secModalHTML(section), 'lg');
};

function _secAdviserFieldHTML(section) {
  // Admin: real picker, sourced from the teacher directory (Chunk D — see
  // header). Teacher editing their own section: read-only, since handing a
  // section to a SPECIFIC other teacher is treated as an admin action here.
  if (currentRole !== 'admin') {
    // Creating: there's nothing to pick — create_class_section() (Phase 49)
    // always assigns a teacher-created section to the creator server-side,
    // so just say so instead of offering a field with nothing to do.
    if (!section) {
      return `<div class="form-group">
        <label class="form-label">Adviser</label>
        <div style="font-size:13px;padding:8px 0;color:var(--text-muted)">👤 This section will be created under your name.</div>
      </div>`;
    }
    const state = AppStore.getState();
    const label = _secAdviserName(section.adviserId, state);
    return `<div class="form-group">
      <label class="form-label">Adviser</label>
      <div style="font-size:13px;padding:8px 0;color:var(--text-muted)">${label ? _esc(label) : '— Unassigned —'} <span style="font-size:11px">(ask an admin to reassign)</span></div>
    </div>`;
  }

  const roster = _secTeacherDir || [];
  const adviserOptions = [
    `<option value="">— Unassigned —</option>`,
    ...roster.map(t => `<option value="${_esc(t.id)}" ${section && section.adviserId === t.id ? 'selected' : ''}>${_esc(t.displayName || t.email || t.id)}${t.role === 'admin' ? ' (Admin)' : ''}</option>`),
  ].join('');

  return `<div class="form-group">
    <label class="form-label">Adviser <span style="color:var(--text-muted);font-size:11px">(optional)</span></label>
    <select id="sec-form-adviser" style="width:100%">${adviserOptions}</select>
  </div>`;
}

function _secModalHTML(section) {
  const isEdit = !!section;

  return `
  <div style="font-family:var(--fh);font-size:18px;font-weight:900;margin-bottom:16px">${isEdit ? '✏️ Edit Section' : '＋ New Section'}</div>

  ${isEdit ? `<div style="font-size:11px;color:var(--text-muted);margin-bottom:14px">
    Renaming or changing the grade relabels this section — it does not create a new one.
    Its underlying id (<code>${_esc(section.id)}</code>) stays the same, so attendance, schedule,
    and seating history stay linked.
  </div>` : ''}

  <div class="form-group">
    <label class="form-label">Grade Level</label>
    <select id="sec-form-grade" style="width:100%">
      <option value="">— Select —</option>
      ${GRADE_LEVELS.map(g => `<option value="${g}" ${section && section.gradeLevel === g ? 'selected' : ''}>Grade ${g}</option>`).join('')}
    </select>
  </div>

  <div class="form-group">
    <label class="form-label">Section Name</label>
    <input type="text" id="sec-form-name" placeholder="e.g. Rizal" autocomplete="off" style="width:100%"
           value="${section ? _esc(section.sectionName) : ''}">
  </div>

  ${_secAdviserFieldHTML(section)}

  ${_secScheduleFieldsHTML(section)}

  <div id="sec-form-err" style="color:#ffb4ab;font-size:13px;margin-bottom:10px;display:none"></div>

  <div style="display:flex;gap:8px">
    <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button>
    <button class="btn btn-primary" style="flex:1" onclick="_secSubmitForm(${isEdit ? `'${section.id}'` : 'null'})">${isEdit ? 'Save Changes' : 'Create Section'}</button>
  </div>`;
}

/**
 * _secGetSchedule(sectionId, state) → default schedule row | null
 * Reads the section's DEFAULT (dayOfWeek 0, "whole week") attendance_schedules
 * row straight off AppStore (draft.attendanceSchedules, kept current the
 * same way draft.classSections is — see sections-service.js /
 * attendance-service.js). A section can have up to 8 rows now (Phase 54) —
 * this always resolves the one that applies unless a specific day overrides it.
 */
function _secGetSchedule(sectionId, state) {
  if (!sectionId) return null;
  state = state || AppStore.getState();
  return (state.attendanceSchedules || []).find(s => s.classId === sectionId && (s.dayOfWeek || 0) === 0) || null;
}

/**
 * _secGetDayOverrides(sectionId, state) → { [dayOfWeek]: scheduleRow }
 * Every day-specific (dayOfWeek 1..7) row currently on file for this
 * section, keyed by dayOfWeek for O(1) lookup while rendering the weekly
 * grid below.
 */
function _secGetDayOverrides(sectionId, state) {
  if (!sectionId) return {};
  state = state || AppStore.getState();
  const map = {};
  (state.attendanceSchedules || []).forEach(s => {
    if (s.classId === sectionId && s.dayOfWeek) map[s.dayOfWeek] = s;
  });
  return map;
}

/**
 * _secScheduleFieldsHTML(section) — shared by create AND edit.
 * Create: optional, off by default (same as before). Edit: if the section
 * already has a default schedule, the checkbox starts CHECKED and the
 * fields are prefilled with its current times.
 *
 * PHASE 54 — WEEKLY SCHEDULE: below the default (whole-week) times sits a
 * Monday–Sunday grid. Each day starts collapsed to "Same as default" — tick
 * a day to give it its own Opens/Start/Late cutoff/Closes times (e.g. a
 * shorter Friday, a later Wednesday flag ceremony). Unticking a day that
 * previously had an override reverts it back to the default on Save — it
 * does not need separate confirmation, same as every other field in this
 * form.
 */
function _secScheduleFieldsHTML(section) {
  const existing = section ? _secGetSchedule(section.id) : null;
  const hasExisting = !!existing;
  const overrides = section ? _secGetDayOverrides(section.id) : {};
  // 'HH:MM:SS' from the DB → the <input type=time> wants 'HH:MM'.
  const t = v => (v ? String(v).slice(0, 5) : '');
  const DEFAULTS = { openTime: '07:00', startTime: '07:30', lateCutoff: '07:45', closeTime: '08:30' };
  const defVals = {
    openTime: t(existing?.openTime) || DEFAULTS.openTime,
    startTime: t(existing?.startTime) || DEFAULTS.startTime,
    lateCutoff: t(existing?.lateCutoff) || DEFAULTS.lateCutoff,
    closeTime: t(existing?.closeTime) || DEFAULTS.closeTime,
  };

  return `
  <div class="form-group" style="border-top:1px solid var(--border);padding-top:14px;margin-top:4px">
    <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;font-weight:600">
      <input type="checkbox" id="sec-form-sched-toggle" ${hasExisting ? 'checked' : ''} onchange="_secToggleScheduleFields(this.checked)">
      ${hasExisting ? 'Attendance schedule' : 'Set attendance schedule now'}
    </label>
    <div style="font-size:11px;color:var(--text-muted);margin-top:4px">
      ${hasExisting
        ? 'Edit the times below freely, then Save Changes — updates apply immediately.'
        : 'Optional — you can also set this later, including from here after the section exists.'}
    </div>
  </div>

  <div id="sec-form-sched-fields" style="display:${hasExisting ? 'block' : 'none'};margin-bottom:14px">

    <div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:var(--text-muted);margin-bottom:8px">
      📅 Default — applies every day of the week
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px">
      <div><label class="form-label">Opens</label><input type="time" id="sec-form-sched-open" value="${defVals.openTime}" style="width:100%" onchange="_secSyncDefaultIntoUnoverriddenDays()"></div>
      <div><label class="form-label">Start (On Time from)</label><input type="time" id="sec-form-sched-start" value="${defVals.startTime}" style="width:100%" onchange="_secSyncDefaultIntoUnoverriddenDays()"></div>
      <div><label class="form-label">Late cutoff</label><input type="time" id="sec-form-sched-late" value="${defVals.lateCutoff}" style="width:100%" onchange="_secSyncDefaultIntoUnoverriddenDays()"></div>
      <div><label class="form-label">Closes</label><input type="time" id="sec-form-sched-close" value="${defVals.closeTime}" style="width:100%" onchange="_secSyncDefaultIntoUnoverriddenDays()"></div>
    </div>

    <div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:var(--text-muted);margin-bottom:2px">
      🗓 Per-day overrides
    </div>
    <div style="font-size:11px;color:var(--text-muted);margin-bottom:10px">
      Optional — only tick a day if it genuinely runs different hours. Every day left unticked follows the default above automatically, including days added later.
    </div>

    <div id="sec-form-sched-days" style="display:flex;flex-direction:column;gap:6px">
      ${SEC_DAY_DEFS.map(d => _secDayOverrideRowHTML(d, overrides[d.dow], defVals)).join('')}
    </div>
  </div>`;
}

function _secDayOverrideRowHTML(day, overrideRow, defVals) {
  const t = v => (v ? String(v).slice(0, 5) : '');
  const hasOverride = !!overrideRow;
  const isDayOff = hasOverride && !!overrideRow.dayOff;
  // A day-off row still carries the DB's placeholder 00:00 times (see
  // AttendanceService.setDayOff) — never show those in the time fields, so
  // ticking "different schedule" afterward seeds from the real default
  // instead of a wall of midnight values.
  const hasCustomTimes = hasOverride && !isDayOff;
  const v = hasCustomTimes
    ? { openTime: t(overrideRow.openTime), startTime: t(overrideRow.startTime), lateCutoff: t(overrideRow.lateCutoff), closeTime: t(overrideRow.closeTime) }
    : defVals;

  return `
  <div class="sec-sched-day-row ${isDayOff ? 'sec-sched-day-row-off' : ''}" data-dow="${day.dow}">
    <div class="sec-sched-day-toprow">
      <label class="sec-sched-day-toggle">
        <input type="checkbox" id="sec-form-sched-day-enable-${day.dow}" ${hasCustomTimes ? 'checked' : ''} ${isDayOff ? 'disabled' : ''}
               onchange="_secToggleDayOverride(${day.dow}, this.checked)">
        <span class="sec-sched-day-name">${day.full}</span>
        <span class="sec-sched-day-hint" id="sec-form-sched-day-hint-${day.dow}" style="display:${(hasCustomTimes || isDayOff) ? 'none' : 'inline'}">Same as default</span>
      </label>
      <label class="sec-sched-day-toggle sec-sched-day-off-toggle">
        <input type="checkbox" id="sec-form-sched-day-off-${day.dow}" ${isDayOff ? 'checked' : ''}
               onchange="_secToggleDayOff(${day.dow}, this.checked)">
        🚫 No class this day
      </label>
    </div>
    <div id="sec-form-sched-day-fields-${day.dow}" class="sec-sched-day-fields" style="display:${hasCustomTimes ? 'grid' : 'none'}">
      <div><label class="form-label">Opens</label><input type="time" id="sec-form-sched-day-${day.dow}-open" value="${v.openTime}" style="width:100%"></div>
      <div><label class="form-label">Start</label><input type="time" id="sec-form-sched-day-${day.dow}-start" value="${v.startTime}" style="width:100%"></div>
      <div><label class="form-label">Late</label><input type="time" id="sec-form-sched-day-${day.dow}-late" value="${v.lateCutoff}" style="width:100%"></div>
      <div><label class="form-label">Closes</label><input type="time" id="sec-form-sched-day-${day.dow}-close" value="${v.closeTime}" style="width:100%"></div>
    </div>
    <div id="sec-form-sched-day-off-note-${day.dow}" class="sec-sched-day-off-note" style="display:${isDayOff ? 'block' : 'none'}">No attendance schedule — this section simply has no class on ${day.full.toLowerCase()}s.</div>
  </div>`;
}

window._secToggleScheduleFields = function (checked) {
  const el = document.getElementById('sec-form-sched-fields');
  if (el) el.style.display = checked ? 'block' : 'none';
};

/**
 * _secToggleDayOverride(dow, checked) — a day's "different schedule" tick.
 * Turning it ON reveals that day's own four time fields, seeded with
 * whatever the default currently shows (so the teacher is nudging numbers,
 * not typing a fresh schedule from scratch). Turning it OFF just hides the
 * fields again — _secSubmitForm() reads the checkbox state directly, so an
 * unticked day is dropped/cleared on Save regardless of what's still in
 * its (hidden) inputs.
 */
window._secToggleDayOverride = function (dow, checked) {
  const fieldsEl = document.getElementById(`sec-form-sched-day-fields-${dow}`);
  const hintEl = document.getElementById(`sec-form-sched-day-hint-${dow}`);
  if (fieldsEl) fieldsEl.style.display = checked ? 'grid' : 'none';
  if (hintEl) hintEl.style.display = checked ? 'none' : 'inline';

  if (checked) {
    // Mutually exclusive with "No class this day" — a day either follows
    // its own times or has none at all, never both.
    const dayOffEl = document.getElementById(`sec-form-sched-day-off-${dow}`);
    if (dayOffEl && dayOffEl.checked) {
      dayOffEl.checked = false;
      _secToggleDayOff(dow, false);
    }

    const openEl = document.getElementById(`sec-form-sched-day-${dow}-open`);
    // Only seed from the default if this day's fields are still at their
    // initial render value AND empty/untouched — cheapest safe signal is
    // "was this ever toggled on before with a real override present", which
    // we don't track, so just seed every time the field is currently blank.
    if (openEl && !openEl.value) {
      _secCopyDefaultIntoDayFields(dow);
    }
  }
};

/**
 * _secToggleDayOff(dow, checked) — a day's "No class this day" tick.
 * Marks the weekday as having no attendance schedule at all (Phase 55
 * day-off), distinct from "different schedule" (which still runs class,
 * just at different times). Mutually exclusive with the "different
 * schedule" checkbox on the same row — ticking one turns the other off
 * and disables it, since a day off has no times to fill in.
 * _secSubmitForm() reads this checkbox directly, same pattern as the
 * "different schedule" one.
 */
window._secToggleDayOff = function (dow, checked) {
  const enableEl = document.getElementById(`sec-form-sched-day-enable-${dow}`);
  const fieldsEl = document.getElementById(`sec-form-sched-day-fields-${dow}`);
  const hintEl = document.getElementById(`sec-form-sched-day-hint-${dow}`);
  const noteEl = document.getElementById(`sec-form-sched-day-off-note-${dow}`);
  const rowEl = document.querySelector(`.sec-sched-day-row[data-dow="${dow}"]`);

  if (checked) {
    // Turning "No class" on means this day has no times — collapse and
    // lock the "different schedule" side so the two can't disagree.
    if (enableEl && enableEl.checked) {
      enableEl.checked = false;
      _secToggleDayOverride(dow, false);
    }
    if (enableEl) enableEl.disabled = true;
    if (fieldsEl) fieldsEl.style.display = 'none';
    if (hintEl) hintEl.style.display = 'none';
  } else if (enableEl) {
    enableEl.disabled = false;
    if (hintEl) hintEl.style.display = enableEl.checked ? 'none' : 'inline';
  }

  if (noteEl) noteEl.style.display = checked ? 'block' : 'none';
  if (rowEl) rowEl.classList.toggle('sec-sched-day-row-off', checked);
};

function _secCopyDefaultIntoDayFields(dow) {
  const map = { open: 'sec-form-sched-open', start: 'sec-form-sched-start', late: 'sec-form-sched-late', close: 'sec-form-sched-close' };
  Object.keys(map).forEach(k => {
    const src = document.getElementById(map[k]);
    const dst = document.getElementById(`sec-form-sched-day-${dow}-${k}`);
    if (src && dst) dst.value = src.value;
  });
}

/**
 * _secSyncDefaultIntoUnoverriddenDays() — fires on every default time-field
 * change. Any day whose override checkbox is OFF is, by definition, "same
 * as default" — so its (hidden) fields are kept in lockstep with the
 * default as it's edited, purely so that ticking the day open afterward
 * shows the CURRENT default rather than a stale one from page-load.
 */
window._secSyncDefaultIntoUnoverriddenDays = function () {
  SEC_DAY_DEFS.forEach(d => {
    const enableEl = document.getElementById(`sec-form-sched-day-enable-${d.dow}`);
    if (enableEl && !enableEl.checked) _secCopyDefaultIntoDayFields(d.dow);
  });
};

window._secSubmitForm = async function (sectionId) {
  const grade = document.getElementById('sec-form-grade')?.value || '';
  const name = document.getElementById('sec-form-name')?.value.trim() || '';
  // The adviser <select> only exists in admin mode (_secAdviserFieldHTML) —
  // a teacher editing their own section has no adviser control at all, so
  // adviserTouched stays false and the existing adviser is left alone.
  const adviserEl = document.getElementById('sec-form-adviser');
  const adviserTouched = !!adviserEl;
  const adviserId = adviserEl ? (adviserEl.value || null) : null;
  const errEl = document.getElementById('sec-form-err');

  if (!grade) { _secShowFormErr('Please select a grade level.'); return; }
  if (!name) { _secShowFormErr('Section name is required.'); return; }
  if (errEl) errEl.style.display = 'none';

  // Schedule fields are shown (and read) on BOTH create and edit — see
  // _secScheduleFieldsHTML(). Unchecked = "don't touch the schedule right
  // now" either way; it does not delete an existing default.
  const schedToggle = document.getElementById('sec-form-sched-toggle');
  let schedule = null;
  const dayOverrides = [];      // days to upsert: [{ dayOfWeek, openTime, startTime, lateCutoff, closeTime }]
  const dayOverridesToClear = []; // days to revert to default: [dayOfWeek]

  if (schedToggle && schedToggle.checked) {
    const openTime = document.getElementById('sec-form-sched-open')?.value;
    const startTime = document.getElementById('sec-form-sched-start')?.value;
    const lateCutoff = document.getElementById('sec-form-sched-late')?.value;
    const closeTime = document.getElementById('sec-form-sched-close')?.value;
    if (!openTime || !startTime || !lateCutoff || !closeTime) {
      _secShowFormErr('Please fill in all four default schedule times, or uncheck the attendance schedule.');
      return;
    }
    if (!(openTime <= startTime && startTime <= lateCutoff && lateCutoff <= closeTime)) {
      _secShowFormErr('Default schedule times must be in order: Opens ≤ Start ≤ Late cutoff ≤ Closes.');
      return;
    }
    schedule = { openTime, startTime, lateCutoff, closeTime };

    // Existing overrides (edit mode only — a brand-new section has none
    // yet) tell us which "now unticked" days actually need a clear call
    // rather than just being days that were never overridden in the first
    // place.
    const existingOverrides = sectionId ? _secGetDayOverrides(sectionId) : {};

    for (const d of SEC_DAY_DEFS) {
      const enableEl = document.getElementById(`sec-form-sched-day-enable-${d.dow}`);
      const dayOffEl = document.getElementById(`sec-form-sched-day-off-${d.dow}`);
      const isChecked = !!(enableEl && enableEl.checked);
      const isDayOff = !!(dayOffEl && dayOffEl.checked);

      if (isDayOff) {
        // No times to validate — day-off rows store placeholder 00:00s
        // server-side (see AttendanceService.setDayOff) and every reader
        // treats dayOff:true as "no attendance today" regardless of them.
        dayOverrides.push({ dayOfWeek: d.dow, dayOff: true, openTime: '00:00', startTime: '00:00', lateCutoff: '00:00', closeTime: '00:00' });
      } else if (isChecked) {
        const dOpen = document.getElementById(`sec-form-sched-day-${d.dow}-open`)?.value;
        const dStart = document.getElementById(`sec-form-sched-day-${d.dow}-start`)?.value;
        const dLate = document.getElementById(`sec-form-sched-day-${d.dow}-late`)?.value;
        const dClose = document.getElementById(`sec-form-sched-day-${d.dow}-close`)?.value;
        if (!dOpen || !dStart || !dLate || !dClose) {
          _secShowFormErr(`Please fill in all four times for ${d.full}, or untick its "different schedule" box.`);
          return;
        }
        if (!(dOpen <= dStart && dStart <= dLate && dLate <= dClose)) {
          _secShowFormErr(`${d.full}'s schedule times must be in order: Opens ≤ Start ≤ Late cutoff ≤ Closes.`);
          return;
        }
        dayOverrides.push({ dayOfWeek: d.dow, dayOff: false, openTime: dOpen, startTime: dStart, lateCutoff: dLate, closeTime: dClose });
      } else if (existingOverrides[d.dow]) {
        dayOverridesToClear.push(d.dow);
      }
    }
  }

  const result = sectionId
    ? await SectionService.updateSection(sectionId, adviserTouched
        ? { gradeLevel: grade, sectionName: name, adviserId, clearAdviser: !adviserId }
        : { gradeLevel: grade, sectionName: name })
    : await SectionService.createSection(grade, name, { adviserId, schedule, dayOverrides });

  if (!result.ok) { _secShowFormErr(result.error || 'Something went wrong.'); return; }

  // Create already folds the default schedule AND every day override into
  // SectionService.createSection()'s own sequence (see sections-service.js).
  // Edit doesn't — update_class_section() never touches attendance_schedules
  // — so save the default + each override/clear as explicit follow-up
  // steps here. If the section save succeeded but one of these fails, the
  // user still keeps their name/grade/adviser changes; only that one
  // schedule write needs a retry.
  const schedErrors = [];
  if (sectionId && schedule) {
    const defResult = await AttendanceService.upsertSchedule(sectionId, schedule, 0);
    if (!defResult.ok) schedErrors.push(defResult.error || 'default schedule');

    for (const ov of dayOverrides) {
      const r = await AttendanceService.upsertSchedule(sectionId, ov, ov.dayOfWeek, ov.dayOff);
      if (!r.ok) schedErrors.push(`${SEC_DAY_DEFS.find(d => d.dow === ov.dayOfWeek)?.full || ov.dayOfWeek} — ${r.error || 'failed to save'}`);
    }
    for (const dow of dayOverridesToClear) {
      const r = await AttendanceService.clearScheduleOverride(sectionId, dow);
      if (!r.ok) schedErrors.push(`${SEC_DAY_DEFS.find(d => d.dow === dow)?.full || dow} — ${r.error || 'failed to clear'}`);
    }
  }

  closeModalForce();
  if (schedErrors.length) {
    toast(`⚠️ Section updated, but the schedule had ${schedErrors.length} issue${schedErrors.length === 1 ? '' : 's'}: ${schedErrors[0]}`, '#ffb95f');
  } else if (!sectionId && result.error) {
    // createSection() returns ok:true with an error string attached when
    // the section itself was created fine but one or more day overrides
    // failed to save (see sections-service.js) — the user shouldn't lose
    // the whole create over that, just be told to go fix the overrides.
    toast(`⚠️ ${result.error}`, '#ffb95f');
  } else {
    const overrideCount = dayOverrides.length;
    const schedNote = schedule ? ` — schedule saved${overrideCount ? ` (${overrideCount} day override${overrideCount === 1 ? '' : 's'})` : ''}.` : '.';
    toast(sectionId ? `✅ Section updated${schedNote}` : `✅ "${name}" created${schedule ? ` with an attendance schedule${overrideCount ? ` (${overrideCount} day override${overrideCount === 1 ? '' : 's'})` : ''}` : ''}.`);
  }
  _secRenderList();
};

function _secShowFormErr(msg) {
  const errEl = document.getElementById('sec-form-err');
  if (errEl) { errEl.textContent = '❌ ' + msg; errEl.style.display = 'block'; }
}

// ── ARCHIVE / RESTORE ───────────────────────────────────

window._secConfirmArchive = function (sectionId, studentCount) {
  const state = AppStore.getState();
  const section = (state.classSections || []).find(s => s.id === sectionId);
  if (!section) return;

  showModal(`
    <div style="font-family:var(--fh);font-size:18px;font-weight:900;margin-bottom:12px">🗄 Archive "${_esc(section.sectionName)}"?</div>
    <div style="font-size:13px;color:var(--text-muted);margin-bottom:16px;line-height:1.5">
      This hides it from the kiosk, Live Monitor, seating builder, and the registration form.
      ${studentCount > 0 ? `<strong style="color:#ffb95f">${studentCount} student${studentCount === 1 ? ' is' : 's are'} currently in this section</strong> — their records, attendance, and seating history are kept exactly as-is; they just won't appear as an option for new enrollments until this section is restored.` : 'It has no students currently assigned.'}
      Nothing is deleted — you can restore it anytime.
    </div>
    <div style="display:flex;gap:8px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button>
      <button class="btn btn-danger" style="flex:1" onclick="_secArchive('${sectionId}')">Archive Section</button>
    </div>`, 'sm');
};

window._secArchive = async function (sectionId) {
  const result = await SectionService.archiveSection(sectionId);
  closeModalForce();
  if (!result.ok) { toast('❌ ' + (result.error || 'Could not archive section.'), '#ffb4ab'); return; }
  toast('✅ Section archived.');
  _secRenderList();
};

window._secUnarchive = async function (sectionId) {
  const result = await SectionService.unarchiveSection(sectionId);
  if (!result.ok) { toast('❌ ' + (result.error || 'Could not restore section.'), '#ffb4ab'); return; }
  toast('✅ Section restored.');
  _secRenderList();
};

// ── REASSIGN ADVISER (Chunk D — standalone, mid-year coverage change) ──
// Deliberately separate from the edit modal above: a single-purpose action
// for "who covers this section starting now", with its own audit_log entry
// (reassign_section_adviser(), Phase 42) — see the file header for why this
// isn't folded into _secOpenEditModal.

window._secOpenReassignModal = async function (sectionId) {
  const state = AppStore.getState();
  const section = (state.classSections || []).find(s => s.id === sectionId);
  if (!section) { toast('❌ Section not found.', '#ffb4ab'); return; }
  await _secEnsureTeacherDir();

  const roster = (_secTeacherDir || []).filter(t => t.id !== section.adviserId);
  const currentLabel = section.adviserId ? _secAdviserName(section.adviserId, state) : '— Unassigned —';
  const options = [
    `<option value="">— Unassigned —</option>`,
    ...roster.map(t => `<option value="${_esc(t.id)}">${_esc(t.displayName || t.email || t.id)}${t.role === 'admin' ? ' (Admin)' : ''}</option>`),
  ].join('');

  showModal(`
    <div style="font-family:var(--fh);font-size:18px;font-weight:900;margin-bottom:6px">🔁 Reassign Adviser</div>
    <div style="font-size:13px;color:var(--text-muted);margin-bottom:16px">
      Grade ${_esc(section.gradeLevel)} – ${_esc(section.sectionName)}<br>
      Currently: <strong>${_esc(currentLabel)}</strong>
    </div>
    <div class="form-group">
      <label class="form-label">New Adviser</label>
      <select id="sec-reassign-select" style="width:100%">${options}</select>
    </div>
    <div style="font-size:11px;color:var(--text-muted);margin-bottom:14px">
      This changes only who covers this section. It does not move any of the
      previous adviser's content — see the Teacher Directory's "Transfer
      Ownership" action for that.
    </div>
    <div id="sec-reassign-err" style="color:#ffb4ab;font-size:13px;margin-bottom:10px;display:none"></div>
    <div style="display:flex;gap:8px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button>
      <button class="btn btn-primary" style="flex:1" onclick="_secSubmitReassign('${sectionId}')">Reassign</button>
    </div>`, 'sm');
};

// ── ROSTER VIEWER (Phase 49) ────────────────────────────────────────────
// A big, dedicated view of everyone in a section — the section cards above
// only ever showed a headcount. Opens in the 'xl' modal size (see
// styles/base.css) so a full class fits comfortably in a photo grid instead
// of a cramped list.

let _secRosterSearch = '';

window._secOpenRosterModal = function (sectionId) {
  const state = AppStore.getState();
  const section = (state.classSections || []).find(s => s.id === sectionId);
  if (!section) { toast('❌ Section not found.', '#ffb4ab'); return; }

  _secRosterSearch = '';
  showModal(_secRosterModalHTML(section, state), 'xl');
};

function _secRosterModalHTML(section, state) {
  const adviserName = _secAdviserName(section.adviserId, state);
  const roster = (state.students || []).filter(s => (s.classId || 'default-class') === section.id);

  return `
  <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:4px">
    <div>
      <div style="font-family:var(--fh);font-size:20px;font-weight:900">👥 Grade ${_esc(section.gradeLevel)} – ${_esc(section.sectionName)}</div>
      <div style="color:var(--text-muted);font-size:13px;margin-top:2px">
        ${roster.length} student${roster.length === 1 ? '' : 's'} · Adviser: ${adviserName ? _esc(adviserName) : 'Unassigned'}
      </div>
    </div>
    <button class="btn btn-ghost btn-xs" onclick="closeModalForce()">✕ Close</button>
  </div>

  <input class="reg-search-input" type="text" placeholder="Search students…" value="${_esc(_secRosterSearch)}"
         style="width:100%;margin:14px 0" oninput="_secRosterSearch=this.value;_secRerenderRoster('${section.id}')">

  <div id="sec-roster-grid">${_secRosterGridHTML(roster)}</div>`;
}

window._secRerenderRoster = function (sectionId) {
  const state = AppStore.getState();
  const roster = (state.students || []).filter(s => (s.classId || 'default-class') === sectionId);
  const gridEl = document.getElementById('sec-roster-grid');
  if (gridEl) gridEl.innerHTML = _secRosterGridHTML(roster);
};

function _secRosterGridHTML(roster) {
  const q = (_secRosterSearch || '').trim().toLowerCase();
  const list = q ? roster.filter(s => (s.name || '').toLowerCase().includes(q)) : roster;

  if (!list.length) {
    return `<div style="text-align:center;padding:56px 20px;color:var(--text-muted)">
      <div style="font-size:40px;margin-bottom:10px">🧑‍🎓</div>
      ${roster.length ? 'No students match that search.' : 'No students are enrolled in this section yet.'}
    </div>`;
  }

  return `<div class="sec-roster-grid">
    ${list
      .slice()
      .sort((a, b) => (a.name || '').localeCompare(b.name || ''))
      .map(_secRosterCardHTML)
      .join('')}
  </div>`;
}

function _secRosterCardHTML(s) {
  const color = _cssColor(s.color);
  const init = s.init || (s.name || '?').charAt(0).toUpperCase();
  const portraitHtml = s.profilePic
    ? `<div class="sec-roster-portrait" style="background:${color}22;border-color:${color}55">
         <img src="${_esc(s.profilePic)}" alt="${_esc(s.name || '')}" onerror="this.parentElement.style.color='${color}';this.parentElement.innerHTML='<span class=&quot;sec-roster-portrait-init&quot;>${_esc(init)}</span>'">
       </div>`
    : `<div class="sec-roster-portrait" style="background:${color}22;color:${color};border-color:${color}55">
         <span class="sec-roster-portrait-init">${_esc(init)}</span>
       </div>`;

  const level = (s.level !== undefined && s.level !== null) ? s.level : null;
  const attendance = (s.attendance !== undefined && s.attendance !== null) ? s.attendance : null;

  return `<div class="sec-roster-card">
    ${portraitHtml}
    <div class="sec-roster-name">${_esc(s.name || s.displayName || s.id)}</div>
    <div class="sec-roster-stats">
      ${level !== null ? `<span class="badge-pill bp-primary" title="Level">Lv. ${_esc(String(level))}</span>` : ''}
      ${s.tier ? `<span class="badge-pill" style="background:${color}22;color:${color};border:1px solid ${color}44">${_esc(s.tier)}</span>` : ''}
      ${attendance !== null ? `<span class="badge-pill bp-muted" title="Attendance rate">📋 ${_esc(String(attendance))}%</span>` : ''}
    </div>
  </div>`;
}

window._secSubmitReassign = async function (sectionId) {
  const select = document.getElementById('sec-reassign-select');
  const newAdviserId = select ? (select.value || null) : null;

  const result = await SectionService.reassignAdviser(sectionId, newAdviserId, { clearAdviser: !newAdviserId });
  if (!result.ok) {
    const errEl = document.getElementById('sec-reassign-err');
    if (errEl) { errEl.textContent = '❌ ' + (result.error || 'Could not reassign this section.'); errEl.style.display = 'block'; }
    return;
  }

  closeModalForce();
  toast('✅ Adviser reassigned.');
  _secRenderList();
};


/* ---- ./modules/admin/sections_index.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/admin/sections_index.js
//  Phase 4: Load-order guard + AppStore bootstrap for class_sections.
//
//  RESPONSIBILITY (mirrors modules/seat-arrangement/classroom_index.js):
//    1. Verify that SectionService and renderSectionMaker were registered
//       successfully by the preceding <script> tags.
//    2. Expose window.renderSectionMaker() / window.unmountSectionMaker()
//       that nav.js/navTo() calls.
//    3. Bootstrap AppStore with class_sections from Supabase as soon as
//       AppStore.ready resolves — so the first navTo('a-sections'), and
//       every screen that reads getActiveClassIds()/getClassLabel(), finds
//       data already in state.
//
//  LOAD ORDER (enforced by <script src> sequence in index.html):
//    1. modules/core/state-manager.js       (AppStore)
//    2. db-service.js                       (DBService, Supabase client)
//    3. modules/admin/sections-service.js   (SectionService, getActiveClassIds)
//    4. modules/admin/sections.js           (renderSectionMaker, etc.)
//    5. THIS FILE                           (bootstrap + guard)
//
//  WHY NOT IN DBService._pullCacheFromSupabase()
//    Same reasoning as classroom_layouts: that function populates the
//    legacy DB blob's pre-existing shape, and class_sections has no legacy
//    shape — it lives exclusively in the new AppStore slice. The table is
//    small (dozens of rows for a whole school), so a parallel fetch outside
//    the big pull is fine.
// ═══════════════════════════════════════════════════════════════════════════════

;(function () {
  'use strict';

  // ── 1. Load-order verification ────────────────────────────────────────────

  const REQUIRED_FUNCTIONS = [
    ['SectionService',        typeof window.SectionService === 'object'],
    ['getActiveClassIds',     typeof window.getActiveClassIds === 'function'],
    ['getClassLabel',         typeof window.getClassLabel === 'function'],
    ['renderSectionMaker',    typeof window.renderSectionMaker === 'function'],
    ['unmountSectionMaker',   typeof window.unmountSectionMaker === 'function'],
  ];

  const failed = REQUIRED_FUNCTIONS.filter(([, ok]) => !ok).map(([name]) => name);
  if (failed.length) {
    console.error('[EduQuest] sections_index.js — MISSING exports:', failed,
      '— Check that sections-service.js and sections.js loaded first.');
  } else {
    console.log('[EduQuest] sections_index.js — All exports verified ✅');
  }

  window.__SECTIONS_MODULE_VERSION__ = '1.0.0';

  // ── 2. Supabase data bootstrap ────────────────────────────────────────────
  //
  // Same STALE-RESPONSE GUARD as classroom_index.js's _bootstrapClassroomData
  // — _bootstrapSectionData() is called from multiple uncoordinated places
  // (pre-login AppStore.ready, every Section Maker mount, every realtime
  // event), so a sequence number discards any response that's been
  // superseded by a newer request before it can apply stale data.
  let _bootstrapSeq = 0;

  async function _bootstrapSectionData() {
    const mySeq = ++_bootstrapSeq;

    const client = (typeof DBService !== 'undefined' && typeof DBService.getAuthClient === 'function')
      ? DBService.getAuthClient()
      : (window.supabase || null);

    if (!client) {
      console.info('[SectionsIndex] No Supabase client — class_sections not fetched (offline mode).');
      return;
    }

    try {
      const res = await client.from('class_sections').select('*').order('grade_level', { ascending: true });
      if (res.error) throw res.error;

      if (mySeq !== _bootstrapSeq) {
        console.info('[SectionsIndex] Discarding stale class_sections fetch (superseded by a newer request).');
        return;
      }

      const sections = (res.data || []).map(row => ({
        id:          row.id,
        gradeLevel:  row.grade_level,
        sectionName: row.section_name,
        adviserId:   row.adviser_id || null,
        archived:    !!row.archived,
        createdAt:   row.created_at,
        updatedAt:   row.updated_at,
      }));

      AppStore.updateState(draft => {
        draft.classSections = sections;
      }, { type: 'sections:bootstrapped', payload: { count: sections.length } });

      console.log(`[SectionsIndex] Bootstrapped — ${sections.length} sections.`);
    } catch (err) {
      console.warn('[SectionsIndex] Bootstrap fetch failed (non-fatal):', err.message || err);
    }
  }

  // Exposed publicly so page-mount code (renderSectionMaker, plus the
  // registration form and every class-selector screen) can trigger a fresh
  // fetch on every visit — same "PRE-LOGIN BOOTSTRAP RACE" reasoning as
  // classroom_index.js's window.refreshClassroomData.
  window.refreshSectionData = _bootstrapSectionData;

  // ── 3. Realtime subscription for class_sections ───────────────────────────

  let _sectionsRealtimeChannel = null;
  let _realtimeRefreshTimer    = null;

  function _scheduleSectionsRefresh() {
    if (_realtimeRefreshTimer) clearTimeout(_realtimeRefreshTimer);
    _realtimeRefreshTimer = setTimeout(_bootstrapSectionData, 400);
  }

  function _setupSectionsRealtime() {
    const client = (typeof DBService !== 'undefined' && typeof DBService.getAuthClient === 'function')
      ? DBService.getAuthClient()
      : null;
    if (!client || typeof client.channel !== 'function') {
      console.info('[SectionsIndex] Realtime not available — skipping channel setup.');
      return;
    }

    _sectionsRealtimeChannel = client
      .channel('eduquest-sections-sync')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'class_sections' }, _scheduleSectionsRefresh)
      .subscribe(status => {
        if (status === 'SUBSCRIBED') {
          console.log('[SectionsIndex] Realtime channel subscribed ✅');
        }
      });
  }

  // ── 4. Wire into AppStore.ready ───────────────────────────────────────────

  if (window.AppStore && typeof AppStore.ready !== 'undefined') {
    AppStore.ready.then(function () {
      _bootstrapSectionData()
        .then(_setupSectionsRealtime)
        .catch(function (err) {
          console.warn('[SectionsIndex] Startup error (non-fatal):', err && err.message || err);
        });
    });
  } else {
    document.addEventListener('DOMContentLoaded', function () {
      if (window.AppStore && AppStore.ready) {
        AppStore.ready.then(function () {
          _bootstrapSectionData()
            .then(_setupSectionsRealtime)
            .catch(function (err) {
              console.warn('[SectionsIndex] Startup error (non-fatal):', err && err.message || err);
            });
        });
      }
    });
  }

  // ── 5. Expose teardown for the realtime channel ───────────────────────────

  window._sectionsIndexTeardown = function () {
    if (_sectionsRealtimeChannel) {
      _sectionsRealtimeChannel.unsubscribe();
      _sectionsRealtimeChannel = null;
    }
    if (_realtimeRefreshTimer) {
      clearTimeout(_realtimeRefreshTimer);
      _realtimeRefreshTimer = null;
    }
  };

}());

console.log('[EduQuest] sections_index.js loaded — Phase 4 sections bootstrap registered.');


/* ---- ./modules/attendance/attendance-service.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/attendance/attendance-service.js
//  Service Layer for Phase 1 RFID/NFC Attendance.
//
//  REPOSITORY PATTERN CONTRACT — read this before touching this file:
//    UI modules (att_scanner_rfid.js, att_editor.js, etc.) NEVER call
//    Supabase and NEVER mutate `DB`/AppStore state directly for anything in
//    this file's domain. They call AttendanceService.<method>(...).
//    AttendanceService is the ONLY thing in the codebase that:
//      a) calls DBService.rpc() for attendance_logs / rfid_cards /
//         attendance_schedules writes, and
//      b) calls AppStore.updateState() to reflect those writes into the
//         single source of truth.
//    AttendanceService never touches `window.supabase` or `client.from(...)`
//    directly — that boundary belongs to db-service.js alone. If you find
//    yourself wanting to import a Supabase client here, the right move is
//    to add a narrower DBService method instead, not to reach around this
//    file.
//
//  STATE SHAPE (slices populated by db-service.js → AppStore):
//    draft.rfidCards            [{ id, tagId, studentId, isActive, assignedAt, revokedAt }]
//    draft.attendanceSchedules  [{ id, classId, dayOfWeek, openTime, startTime, lateCutoff,
//                                   closeTime, active }]
//      dayOfWeek (Phase 54): 0 = default/whole-week row, 1..7 = ISO-weekday
//      (Mon..Sun) override — up to 8 rows per classId now, not exactly 1.
//      Use AttendanceService.getEffectiveSchedule(classId) to resolve
//      "which one applies today" instead of a raw .find(classId===...).
//    draft.attendanceLogs       [{ id, studentId, classId, logDate, status, scannedAt,
//                                   entryMethod, rfidTag, recordedBy, notes }]
//    draft.students[i].classId  (added in Phase 1; defaults to 'default-class')
//
//  OPTIMISTIC UPDATE STRATEGY
//    Every write below follows the same three-beat rhythm:
//      1. Call the authoritative RPC (DBService.rpc) and AWAIT it — RPCs are
//         the only place the Early/On Time/Late/Absent decision and the
//         one-row-per-student-per-day invariant are actually enforced, so
//         we cannot "optimistically" invent a result before the network
//         responds without risking it being wrong.
//      2. The instant the RPC resolves, apply ITS authoritative result into
//         AppStore.updateState() ourselves — this is what makes the UI feel
//         instant: we do NOT wait for the realtime echo (db-service.js's
//         `attendance_logs`/`rfid_cards` postgres_changes listener) to
//         update local state; we apply it the moment we have it.
//      3. The realtime listener in db-service.js is a backstop for OTHER
//         tabs/devices (and a safety net for our own tab if step 2 ever
//         disagrees with what eventually lands server-side) — it's not the
//         primary update path, just eventual-consistency insurance.
//    This is "optimistic" in the sense that the *local UI* never blocks on
//    a second round-trip after the RPC — not in the sense of guessing the
//    result before asking the server. For a 200-person line of students
//    tapping a badge at the door, guessing wrong and rolling back would be
//    worse than the RPC's normal latency.
// ═══════════════════════════════════════════════════════════════════════════════

window.AttendanceService = (function () {
  'use strict';

  /**
   * Upsert one attendance_logs row into draft.attendanceLogs (by id if
   * present, else by the student+class+day natural key) — shared by every
   * method below that needs to reflect an RPC's returned `log` object.
   */
  function _upsertLogIntoDraft(draft, log) {
    if (!log) return;
    if (!Array.isArray(draft.attendanceLogs)) draft.attendanceLogs = [];
    const idx = draft.attendanceLogs.findIndex(l =>
      (log.id && l.id === log.id) ||
      (l.studentId === log.studentId && l.classId === log.classId && l.logDate === log.logDate)
    );
    const row = {
      id: log.id, studentId: log.student_id || log.studentId,
      classId: log.class_id || log.classId, logDate: log.log_date || log.logDate,
      status: log.status, scannedAt: log.scanned_at || log.scannedAt,
      entryMethod: log.entry_method || log.entryMethod,
      rfidTag: log.rfid_tag ?? log.rfidTag ?? null,
      recordedBy: log.recorded_by ?? log.recordedBy ?? null,
      notes: log.notes ?? null,
    };
    if (idx >= 0) draft.attendanceLogs[idx] = row;
    else draft.attendanceLogs.unshift(row);
  }

  /**
   * assignCard(studentId, rfidTag) → Promise<{ok, error?, card?}>
   * Registers a card to a student, replacing any prior card on either side
   * of the binding (old card → inactive; tag's previous owner, if any →
   * inactive). See assign_rfid_card() in phase1_rfid_attendance.sql for the
   * actual atomicity guarantee — this method just calls it and reflects the
   * result.
   */
  async function assignCard(studentId, rfidTag) {
    const tagId = String(rfidTag || '').trim();
    if (!studentId || !tagId) {
      return { ok: false, error: 'Student and card tag are both required.' };
    }

    const { data, error } = await DBService.rpc('assign_rfid_card', {
      p_student_id: studentId, p_tag_id: tagId,
    });
    if (error) {
      console.error('[AttendanceService] assignCard failed:', error);
      return { ok: false, error: error.message || 'Could not assign card.' };
    }

    AppStore.updateState(draft => {
      if (!Array.isArray(draft.rfidCards)) draft.rfidCards = [];
      // Mirror exactly what the RPC did server-side: deactivate this
      // student's old card and this tag's old owner, then add the new row.
      draft.rfidCards.forEach(c => {
        if ((c.studentId === studentId || c.tagId === tagId) && c.isActive && c.id !== data.id) {
          c.isActive = false;
          c.revokedAt = new Date().toISOString();
        }
      });
      const idx = draft.rfidCards.findIndex(c => c.id === data.id);
      const row = {
        id: data.id, tagId: data.tag_id, studentId: data.student_id,
        isActive: data.is_active, assignedAt: data.assigned_at, revokedAt: data.revoked_at,
      };
      if (idx >= 0) draft.rfidCards[idx] = row; else draft.rfidCards.unshift(row);
    }, { type: 'attendance:card-assigned', payload: { studentId, tagId } });

    return { ok: true, card: data };
  }

  /**
   * assignStudentToClass(studentId, classId) → Promise<{ok, error?}>
   * Roster assignment — needed before closeAttendanceSession() can sweep a
   * class, since the sweep matches on profiles.class_id.
   */
  async function assignStudentToClass(studentId, classId) {
    if (!studentId || !classId) return { ok: false, error: 'Student and class are both required.' };

    const { error } = await DBService.rpc('set_student_class', {
      p_student_id: studentId, p_class_id: classId,
    });
    if (error) {
      console.error('[AttendanceService] assignStudentToClass failed:', error);
      return { ok: false, error: error.message || 'Could not update class assignment.' };
    }

    AppStore.updateState(draft => {
      const s = (draft.students || []).find(st => st.id === studentId);
      if (s) s.classId = classId;
    }, { type: 'attendance:student-class-changed', payload: { studentId, classId } });

    return { ok: true };
  }

  /**
   * upsertSchedule(classId, { openTime, startTime, lateCutoff, closeTime }, dayOfWeek?, dayOff?) → Promise<{ok, error?, schedule?}>
   * Times are 'HH:MM' or 'HH:MM:SS' strings (Postgres `time` accepts both).
   * dayOfWeek (Phase 54): 0 (default, applies every day unless overridden —
   * this is also the implicit value when omitted, so every pre-Phase-54
   * call site keeps writing the whole-week row exactly as before) or 1..7
   * (ISO weekday override, 1=Monday..7=Sunday).
   * dayOff (Phase 55): true marks that weekday as having NO class at all —
   * only valid alongside a real dayOfWeek (1..7), never the default. Prefer
   * setDayOff() below for that case; this still accepts it directly for
   * symmetry with the RPC.
   */
  async function upsertSchedule(classId, times, dayOfWeek, dayOff) {
    const { openTime, startTime, lateCutoff, closeTime } = times || {};
    const dow = (dayOfWeek === undefined || dayOfWeek === null) ? 0 : dayOfWeek;
    const isDayOff = !!dayOff;
    if (!classId || !openTime || !startTime || !lateCutoff || !closeTime) {
      return { ok: false, error: 'classId, openTime, startTime, lateCutoff, and closeTime are all required.' };
    }

    const { data, error } = await DBService.rpc('upsert_attendance_schedule', {
      p_class_id: classId, p_open_time: openTime, p_start_time: startTime,
      p_late_cutoff: lateCutoff, p_close_time: closeTime, p_day_of_week: dow, p_day_off: isDayOff,
    });
    if (error) {
      console.error('[AttendanceService] upsertSchedule failed:', error);
      return { ok: false, error: error.message || 'Could not save schedule.' };
    }

    AppStore.updateState(draft => {
      if (!Array.isArray(draft.attendanceSchedules)) draft.attendanceSchedules = [];
      const idx = draft.attendanceSchedules.findIndex(s => s.classId === classId && (s.dayOfWeek || 0) === dow);
      const row = {
        id: data.id, classId: data.class_id, dayOfWeek: data.day_of_week ?? dow, dayOff: !!data.day_off,
        openTime: data.open_time, startTime: data.start_time, lateCutoff: data.late_cutoff,
        closeTime: data.close_time, active: data.active,
      };
      if (idx >= 0) draft.attendanceSchedules[idx] = row; else draft.attendanceSchedules.push(row);
    }, { type: 'attendance:schedule-updated', payload: { classId, dayOfWeek: dow, dayOff: isDayOff } });

    return { ok: true, schedule: data };
  }

  /**
   * setDayOff(classId, dayOfWeek) → Promise<{ok, error?, schedule?}>
   * Marks one weekday (1..7) as "no class at all" — distinct from simply
   * not overriding it (which inherits the default schedule instead). The
   * stored times are a placeholder (00:00 all the way through); nothing
   * reads them once dayOff is true.
   */
  async function setDayOff(classId, dayOfWeek) {
    if (!dayOfWeek || dayOfWeek < 1 || dayOfWeek > 7) {
      return { ok: false, error: 'dayOfWeek must be between 1 (Monday) and 7 (Sunday).' };
    }
    return upsertSchedule(classId, { openTime: '00:00', startTime: '00:00', lateCutoff: '00:00', closeTime: '00:00' }, dayOfWeek, true);
  }

  /**
   * clearScheduleOverride(classId, dayOfWeek) → Promise<{ok, error?, removed?}>
   * Deletes ONE day's override row (dayOfWeek 1..7 only — the default row
   * at 0 isn't a valid target) so that day falls back to the default
   * schedule again. Section Maker calls this when a teacher turns a day's
   * "different schedule" toggle back off.
   */
  async function clearScheduleOverride(classId, dayOfWeek) {
    if (!classId) return { ok: false, error: 'classId is required.' };
    if (!dayOfWeek || dayOfWeek < 1 || dayOfWeek > 7) {
      return { ok: false, error: 'dayOfWeek must be between 1 (Monday) and 7 (Sunday).' };
    }

    const { data, error } = await DBService.rpc('clear_attendance_schedule_override', {
      p_class_id: classId, p_day_of_week: dayOfWeek,
    });
    if (error) {
      console.error('[AttendanceService] clearScheduleOverride failed:', error);
      return { ok: false, error: error.message || 'Could not clear that day\'s override.' };
    }

    AppStore.updateState(draft => {
      draft.attendanceSchedules = (draft.attendanceSchedules || [])
        .filter(s => !(s.classId === classId && (s.dayOfWeek || 0) === dayOfWeek));
    }, { type: 'attendance:schedule-override-cleared', payload: { classId, dayOfWeek } });

    return { ok: true, removed: !!data };
  }

  /**
   * getEffectiveSchedule(classId, opts) → schedule row | null
   * "Which window applies on this date" — that weekday's override row if
   * one exists and is active, else the default (dayOfWeek 0) row. Client-
   * side mirror of get_effective_attendance_schedule() (Phase 54) so the
   * kiosk countdown / Command Center don't need a round trip just to answer
   * a question the draft already has everything needed for.
   * opts: { date? } — a JS Date, defaults to right now (Asia/Manila).
   */
  function getEffectiveSchedule(classId, opts) {
    opts = opts || {};
    if (!classId) return null;
    const all = AppStore.getSlice(s => s.attendanceSchedules) || [];
    const mine = all.filter(s => s.classId === classId && s.active !== false);
    if (!mine.length) return null;

    const d = opts.date || new Date();
    // ISO weekday in Asia/Manila (1=Monday..7=Sunday), matching Postgres'
    // extract(isodow from date) used server-side.
    const manilaDowLabel = d.toLocaleDateString('en-US', { timeZone: 'Asia/Manila', weekday: 'short' });
    const isoDow = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 }[manilaDowLabel] || 1;

    const override = mine.find(s => (s.dayOfWeek || 0) === isoDow);
    if (override) return override;
    return mine.find(s => (s.dayOfWeek || 0) === 0) || null;
  }

  /**
   * processScan(rfidTag, classId) → Promise<ScanResult>
   * The hot path called from the scanner UI on every badge tap. See the
   * file header for the optimistic-update rhythm. Returns a discriminated
   * result the UI renders directly — it never has to re-derive status text.
   *
   * ScanResult:
   *   { ok: true,  alreadyRecorded: boolean, studentId, status, studentName }
   *   { ok: false, error: 'unknown_card'|'no_schedule'|'not_open'|'closed'|string, message }
   */
  async function processScan(rfidTag, classId) {
    const tagId = String(rfidTag || '').trim();
    if (!tagId) return { ok: false, error: 'empty_scan', message: 'No card data received.' };
    if (!classId) return { ok: false, error: 'no_class', message: 'No class selected for this scanner.' };

    const { data, error } = await DBService.rpc('process_attendance_scan', {
      p_tag_id: tagId, p_class_id: classId,
    });

    if (error) {
      console.error('[AttendanceService] processScan RPC failed:', error);
      return { ok: false, error: 'network', message: error.message || 'Scan failed — try again.' };
    }
    if (!data || data.ok === false) {
      return { ok: false, error: (data && data.error) || 'unknown', message: (data && data.message) || 'Scan rejected.' };
    }

    AppStore.updateState(draft => {
      _upsertLogIntoDraft(draft, data.log);
      // BUGFIX (report §1): same recompute as overrideAttendance()/
      // closeAttendanceSession() — keeps the RFID hot path consistent so a
      // scanned student's attendance % updates immediately too, not just
      // manual overrides.
      const student = (draft.students || []).find(s => s.id === data.student_id);
      if (student) {
        recalcStudentStats(student, { attendanceLogs: draft.attendanceLogs });
        // FIX (Pending Fixes Report §3): persist the freshly-recomputed
        // attendance_pct via its own column-scoped RPC instead of letting it
        // ride the next debounced whole-roster bulk push — see utils.js.
        syncStudentDerivedStatsToServer(student.id, student.attendance, student.quizAvg);
      }
    }, { type: 'attendance:scan-recorded', payload: { studentId: data.student_id, status: data.status, alreadyRecorded: !!data.already_recorded } });

    const student = AppStore.getStudent(data.student_id);
    return {
      ok: true,
      alreadyRecorded: !!data.already_recorded,
      studentId: data.student_id,
      status: data.status,
      studentName: student ? (student.name || student.displayName) : data.student_id,
    };
  }

  /**
   * overrideAttendance(studentId, classId, status, opts) → Promise<{ok, error?, removed?, log?}>
   * status: 'Present' | 'Early' | 'On Time' | 'Late' | 'Absent' | 'Excused' | 'Remove'
   * ('Edit' isn't a distinct status — call this again with the corrected
   * status; the RPC upserts in place.)
   * opts: { logDate?: 'YYYY-MM-DD', notes?: string }
   */
  async function overrideAttendance(studentId, classId, status, opts) {
    opts = opts || {};
    if (!studentId || !classId || !status) {
      return { ok: false, error: 'studentId, classId, and status are all required.' };
    }
    const recordedBy = (typeof currentUser !== 'undefined' && currentUser) ? currentUser.id : null;

    // NOTE: p_log_date must be OMITTED (not sent as null) when the caller
    // doesn't specify a date. The SQL function declares
    // `p_log_date date DEFAULT CURRENT_DATE`, but Postgres only applies a
    // parameter default when the argument is absent — PostgREST passing an
    // explicit `null` overrides that default and inserts a literal NULL,
    // which violates attendance_logs' NOT NULL constraint on log_date.
    const rpcParams = {
      p_student_id: studentId, p_class_id: classId, p_status: status,
      p_recorded_by: recordedBy, p_notes: opts.notes || null,
    };
    if (opts.logDate) rpcParams.p_log_date = opts.logDate;

    const { data, error } = await DBService.rpc('override_attendance', rpcParams);
    if (error) {
      console.error('[AttendanceService] overrideAttendance failed:', error);
      return { ok: false, error: error.message || 'Could not save override.' };
    }
    if (data && data.ok === false) {
      return { ok: false, error: data.message || 'Override rejected.' };
    }

    AppStore.updateState(draft => {
      if (data.removed) {
        // BUGFIX: was new Date().toISOString().slice(0,10) (UTC date) — see
        // utils.js isoDate() for why that's 8 hours off from Manila time.
        const logDate = opts.logDate || isoDate();
        draft.attendanceLogs = (draft.attendanceLogs || []).filter(l =>
          !(l.studentId === studentId && l.classId === classId && l.logDate === logDate)
        );
      } else {
        _upsertLogIntoDraft(draft, data.log);
      }
      // BUGFIX (report §1): recalcStudentStats() already knows how to derive
      // attendance % live from draft.attendanceLogs — it just was never
      // called after an override, so the Manual Override panel saved a real
      // log row but the student's displayed attendance total never moved.
      // Recompute it here, against the draft's just-updated logs, so the
      // change is reflected immediately (and persisted on the next sync).
      const student = (draft.students || []).find(s => s.id === studentId);
      if (student) {
        recalcStudentStats(student, { attendanceLogs: draft.attendanceLogs });
        // FIX (Pending Fixes Report §3): see processScan() above.
        syncStudentDerivedStatsToServer(student.id, student.attendance, student.quizAvg);
      }
    }, { type: 'attendance:override', payload: { studentId, classId, status } });

    return data.removed ? { ok: true, removed: true } : { ok: true, log: data.log };
  }

  /**
   * closeAttendanceSession(classId, logDate?) → Promise<{ok, error?, absencesRecorded?}>
   * Sweeps every student in `classId` (profiles.class_id) with no log row
   * yet for the day and marks them Absent. Optimistically reflects the
   * sweep into local state immediately using the roster AppStore already
   * has — the realtime listener will true this up to the exact server
   * rows within ~400ms, same backstop as everywhere else in this file.
   */
  async function closeAttendanceSession(classId, logDate) {
    if (!classId) return { ok: false, error: 'classId is required.' };
    // BUGFIX: was new Date().toISOString().slice(0,10) (UTC date) — see
    // utils.js isoDate() for why that's 8 hours off from Manila time.
    const day = logDate || isoDate();

    const { data, error } = await DBService.rpc('close_attendance_session', {
      p_class_id: classId, p_log_date: day,
    });
    if (error) {
      console.error('[AttendanceService] closeAttendanceSession failed:', error);
      return { ok: false, error: error.message || 'Could not close session.' };
    }

    AppStore.updateState(draft => {
      if (!Array.isArray(draft.attendanceLogs)) draft.attendanceLogs = [];
      const already = new Set(
        draft.attendanceLogs
          .filter(l => l.classId === classId && l.logDate === day)
          .map(l => l.studentId)
      );
      const sweptStudentIds = [];
      (draft.students || [])
        .filter(s => (s.classId || 'default-class') === classId && !already.has(s.id))
        .forEach(s => {
          draft.attendanceLogs.unshift({
            id: null, studentId: s.id, classId, logDate: day, status: 'Absent',
            scannedAt: new Date().toISOString(), entryMethod: 'Manual',
            rfidTag: null, recordedBy: null, notes: null,
          });
          sweptStudentIds.push(s.id);
        });
      // BUGFIX (report §1): recompute the swept students' attendance % now
      // that they each have a fresh Absent row — see the matching note in
      // overrideAttendance() above.
      sweptStudentIds.forEach(id => {
        const student = (draft.students || []).find(s => s.id === id);
        if (student) {
          recalcStudentStats(student, { attendanceLogs: draft.attendanceLogs });
          // FIX (Pending Fixes Report §3): see processScan() above.
          syncStudentDerivedStatsToServer(student.id, student.attendance, student.quizAvg);
        }
      });
    }, { type: 'attendance:session-closed', payload: { classId, logDate: day, absencesRecorded: data.absences_recorded } });

    return { ok: true, absencesRecorded: data.absences_recorded };
  }

  return {
    assignCard,
    assignStudentToClass,
    upsertSchedule,
    clearScheduleOverride,
    getEffectiveSchedule,
    processScan,
    overrideAttendance,
    closeAttendanceSession,
  };
}());

console.log('[EduQuest] attendance/attendance-service.js loaded — AttendanceService registered.');


/* ---- ./modules/attendance/att_scanner_rfid.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/attendance/att_scanner_rfid.js
//  Owns renderRfidScanner() / unmountRfidScanner() — the Phase 1 replacement
//  for the manual-only renderScanner() in att_scanner.js.
//
//  PHASE 4 — KIOSK REFACTOR
//    This screen ("Device 1") is now a headless, distraction-free full-screen
//    kiosk: no sidebar, no topbar, no admin chrome. It's a 2-column layout —
//    an 80% "Student Spotlight" (huge profile card on scan) and a 20%
//    "Recent Activity Log" (last 10 scans). Everything administrative that
//    used to live on this page (Manual Override, Schedule, Close Session,
//    Assign-Card mode) still works exactly as before — it just moved:
//      - Manual Override → now lives in the LiveClassroomMonitor sidebar
//        (modules/seat-arrangement/live_monitor.js), Device 2's screen,
//        per the Phase 4 spec. Same AttendanceService.overrideAttendance()
//        call underneath, just a different UI host.
//      - Schedule / Close Session / Assign-Card mode → tucked behind the
//        small ⚙️ settings icon in the kiosk's top-right corner, so the
//        main screen stays clean but nothing was deleted.
//
//  INTEGRATION (the only two edits needed outside this file):
//    nav.js, navTo():
//      else if(id==='a-scanner')renderScanner();
//      → else if(id==='a-scanner')renderRfidScanner();
//
//      Add a teardown line next to the existing _adminStoreInterval cleanup
//      at the top of navTo(), same pattern:
//        if(id!=='a-scanner') unmountRfidScanner();
//
//    index.html / load order: this file loads AFTER attendance-service.js,
//    state-manager.js, and db-service.js (same position att_scanner.js
//    occupies today).
//
//  HARDWARE MODEL
//    The RFID/NFC reader is a USB-HID keyboard emulator: it "types" the tag
//    ID into whatever has focus, character by character, then sends Enter.
//    Rather than a document-wide keydown listener (which would hijack
//    keystrokes from every other input on the page, including admin search
//    boxes elsewhere in the app), this screen keeps a single dedicated,
//    visually-hidden <input> focused at all times while mounted, and reads
//    from THAT input specifically. Two finalize triggers, so it works
//    whether or not your specific reader model sends an Enter keystroke:
//      1. Enter keydown on the capture input (the common case).
//      2. A 120ms inactivity timer after the last keystroke (fallback for
//         readers that don't emit a terminator).
//
//  OPTIMISTIC / REALTIME REACTIVITY
//    This module never mutates DB/AppStore itself — every action goes
//    through AttendanceService, which applies the authoritative RPC result
//    to AppStore the instant it resolves (see attendance-service.js header).
//    This module's job is purely:
//      - capture the scan and hand it to AttendanceService.processScan()
//      - subscribe to AppStore so the recent-activity log re-renders the
//        moment that update (or a realtime echo from another device)
//        lands — no polling, no manual refresh button needed.
//    This subscription is Supabase Realtime's job downstream (untouched
//    here) — this module only reacts to AppStore, never talks to Supabase
//    directly.
// ═══════════════════════════════════════════════════════════════════════════════

let _rfidFocusInterval = null;
let _rfidScanBuffer = '';
let _rfidInactivityTimer = null;
let _rfidScannerMounted = false;
let _rfidScanMode = 'attendance';   // 'attendance' | 'assign'
let _rfidAssignTargetStudentId = null;
let _rfidSelectedClassId = 'default-class';
let _rfidClockInterval = null;
let _rfidScheduleTimerInterval = null;
// Phone-as-NFC-reader (Web NFC / NDEFReader) — an additive second capture
// source that sits next to the USB-HID keyboard-emulator capture below.
// Both feed the exact same _rfidFinalizeScan(tagId) pipeline, so nothing
// about AttendanceService, the spotlight, or the activity log needs to
// know or care which physical reader produced the tag ID. Android Chrome
// only (see _rfidWebNfcSupported()) — the toggle button simply doesn't
// render on browsers/devices without NDEFReader, so the USB flow is
// completely unaffected everywhere else.
let _rfidWebNfcActive = false;
let _rfidWebNfcAbortController = null;
// Fullscreen/kiosk toggle (opt-in) — same pattern live_monitor.js uses for
// its own lm-kiosk-mode: defaults to a normal embedded page (sidebar +
// topbar visible) and only fills the screen once the teacher explicitly
// clicks the ⛶ Fullscreen button. Forced back to false on unmount so a
// left-open kiosk session never leaks into the next page.
let _rfidKioskMode = false;

/**
 * renderRfidScanner() → void  [window.renderRfidScanner]
 * Mounts the full-screen attendance kiosk into #a-scanner.
 */
window.renderRfidScanner = function () {
  _rfidScannerMounted = true;
  _rfidSelectedClassId = _rfidSelectedClassId || 'default-class';

  // Headless kiosk mode is now OPT-IN — see window._rfidToggleKioskMode()
  // below. Every mount starts embedded (sidebar + topbar visible); the
  // teacher explicitly clicks ⛶ Fullscreen to fill the screen for
  // scanning/projecting, same as live_monitor.js's lm-kiosk-mode.
  _rfidKioskMode = false;
  document.body.classList.remove('rfid-kiosk-mode');

  // Phase 4: read from Section Maker's canonical list (shows every section,
  // not just ones with an already-enrolled student) — falls back to the old
  // derive-from-students behavior automatically if no sections exist yet.
  // See modules/admin/sections-service.js.
  const state = (typeof AppStore !== 'undefined') ? AppStore.getState() : {};
  const classIds = window.getActiveClassIds ? window.getActiveClassIds(state) : Array.from(new Set((state.students || []).map(s => s.classId || 'default-class'))).sort();
  if (!classIds.includes(_rfidSelectedClassId)) _rfidSelectedClassId = classIds[0] || 'default-class';

  document.getElementById('a-scanner').innerHTML = `
    <div class="kiosk-page">
      <input id="rfid-capture-input" autocomplete="off" inputmode="none"
             style="position:absolute;opacity:0;pointer-events:none;width:1px;height:1px" />

      <div class="kiosk-status-eyebrow" id="kiosk-status-eyebrow"></div>
      <div class="kiosk-clock-corner" id="kiosk-clock-corner"></div>

      <div class="kiosk-topstrip">
        <select id="rfid-class-select" class="kiosk-class-select" onchange="_rfidOnClassChange(this.value)">
          ${classIds.map(c => `<option value="${_esc(c)}" ${c === _rfidSelectedClassId ? 'selected' : ''}>${_esc(_rfidClassOptionLabel(c, state))}</option>`).join('')}
        </select>
        <button class="kiosk-fullscreen-btn${_rfidKioskMode ? ' active' : ''}" id="rfid-fullscreen-btn"
          onclick="_rfidToggleKioskMode()"
          title="${_rfidKioskMode ? 'Exit fullscreen' : 'Fill the screen for scanning/kiosk display'}">
          ${_rfidKioskMode ? '⤢ Exit' : '⛶ Fullscreen'}
        </button>
        <button class="kiosk-icon-btn" title="Settings — schedule, assign card, close session" onclick="_rfidOpenSettings()">⚙️</button>
        ${_rfidWebNfcSupported() ? `
        <button class="kiosk-icon-btn${_rfidWebNfcActive ? ' active' : ''}" id="rfid-webnfc-btn"
          title="${_rfidWebNfcActive ? 'Stop using this phone as an NFC reader' : 'Use this phone as an NFC reader — tap to arm, then hold cards to the back of the phone'}"
          onclick="_rfidToggleWebNfc()">
          ${_rfidWebNfcActive ? '📱 NFC On' : '📱 Use Phone as Reader'}
        </button>` : ''}
        <!-- BUGFIX (report §4): true fullscreen hides the whole app shell
             (topbar + sidebar) so students scanning cards don't see admin
             nav, but nothing was left in its place to get back out — the
             only way out was the browser Back button. This calls the same
             navTo() every other nav link uses, which already tears down
             kiosk mode via unmountRfidScanner() in nav.js. Only shown while
             actually fullscreen — the sidebar already covers this otherwise. -->
        ${_rfidKioskMode ? `<button class="kiosk-icon-btn" id="rfid-exit-kiosk-btn" title="Exit kiosk — back to admin dashboard" onclick="navTo('a-dashboard')">⏻</button>` : ''}
      </div>

      <div class="kiosk-columns">
        <div class="kiosk-spotlight" id="kiosk-spotlight"></div>

        <div class="kiosk-activity">
          <div class="kiosk-activity-header">Recent Activity</div>
          <div class="kiosk-schedule-timer" id="kiosk-schedule-timer"></div>
          <div class="kiosk-roster-stats" id="kiosk-roster-stats"></div>
          <div class="kiosk-activity-summary" id="kiosk-activity-summary"></div>
          <div class="kiosk-activity-list" id="kiosk-activity-list"></div>
        </div>
      </div>
    </div>`;

  _rfidRenderSpotlight('idle');
  _rfidRenderActivity();
  _rfidUpdateStatusEyebrow();
  _rfidStartCapture();
  _rfidStartClock();
  _rfidStartScheduleTimer();

  AppStore.subscribe('rfid-scanner', function (state, event) {
    if (!_rfidScannerMounted) return;
    // Cheap targeted re-render — only the activity log (and dropdown label
    // text), never the whole page (which would steal focus from the capture
    // input mid-scan).
    if (!event || event.type === 'state:updated' || event.type.indexOf('attendance:') === 0 || event.type === 'state:remote-sync') {
      _rfidRenderActivity();
      _rfidRefreshClassSelectCounts();
      _rfidUpdateStatusEyebrow();
    }
  });
};

/**
 * _rfidUpdateStatusEyebrow() → void
 * Fills the top-left "Section A · Scanning" status tag (design v2) — reads
 * the same class label + schedule-state helpers the rest of this page
 * already uses (getClassLabel, AttendanceService.getEffectiveSchedule via
 * _rfidScheduleFor), so this is purely a display of existing state, not a
 * new data source. Session state maps to: Scanning (open), Late window
 * (past lateCutoff, before close), or Closed (past close/no schedule).
 */
function _rfidUpdateStatusEyebrow() {
  const el = document.getElementById('kiosk-status-eyebrow');
  if (!el) return;
  const state = (typeof AppStore !== 'undefined') ? AppStore.getState() : {};
  const label = window.getClassLabel ? window.getClassLabel(_rfidSelectedClassId, state) : _rfidSelectedClassId;
  const info = _rfidNextScheduleMilestone(_rfidSelectedClassId);
  const statusText = info.tone === 'closed' ? 'Closed' : info.tone === 'late' ? 'Late window' : 'Scanning';
  el.innerHTML = `<span class="dot"></span><span>${_esc(label)} · ${_esc(statusText)}</span>`;
}

/**
 * _rfidClassOptionLabel(classId, state) → string  (Investigation Report §4)
 * "Section A (12/24)" — scanned-today / enrolled — instead of just the bare
 * section name, so the dropdown itself answers "how's this section doing"
 * without opening anything else.
 */
function _rfidClassOptionLabel(classId, state) {
  const label = window.getClassLabel ? window.getClassLabel(classId, state) : classId;
  const enrolled = (state.students || []).filter(s => (s.classId || 'default-class') === classId).length;
  const today = _rfidTodayISO();
  const scannedToday = (state.attendanceLogs || []).filter(l => l.classId === classId && l.logDate === today).length;
  return `${label} (${scannedToday}/${enrolled})`;
}

/**
 * _rfidRefreshClassSelectCounts() → void
 * Updates each <option>'s label text in place (never rebuilds the <select>
 * itself) so the enrolled/scanned-today counts stay live as scans come in
 * — called from the AppStore subscription alongside _rfidRenderActivity().
 */
function _rfidRefreshClassSelectCounts() {
  const select = document.getElementById('rfid-class-select');
  if (!select) return;
  const state = AppStore.getState();
  Array.from(select.options).forEach(opt => {
    opt.textContent = _rfidClassOptionLabel(opt.value, state);
  });
}

/**
 * unmountRfidScanner() → void  [window.unmountRfidScanner]
 * Call when navigating away from #a-scanner — stops the focus-stealing
 * interval, unsubscribes from AppStore, and restores the app shell.
 * See nav.js integration note above.
 */
window.unmountRfidScanner = function () {
  _rfidScannerMounted = false;
  if (_rfidFocusInterval) { clearInterval(_rfidFocusInterval); _rfidFocusInterval = null; }
  if (_rfidInactivityTimer) { clearTimeout(_rfidInactivityTimer); _rfidInactivityTimer = null; }
  if (_rfidClockInterval) { clearInterval(_rfidClockInterval); _rfidClockInterval = null; }
  if (_rfidScheduleTimerInterval) { clearInterval(_rfidScheduleTimerInterval); _rfidScheduleTimerInterval = null; }
  if (_rfidWebNfcAbortController) { _rfidWebNfcAbortController.abort(); _rfidWebNfcAbortController = null; }
  _rfidWebNfcActive = false;
  clearTimeout(window._rfidSpotlightResetTimer);
  _rfidKioskMode = false;
  document.body.classList.remove('rfid-kiosk-mode');
  AppStore.unsubscribe('rfid-scanner');
};

/**
 * _rfidToggleKioskMode() → void  [window._rfidToggleKioskMode]
 * Flips the scanner between its default embedded view (sidebar + topbar
 * visible) and true fullscreen (both hidden, page fills the viewport) —
 * same body-class mechanism live_monitor.js uses for its own Fullscreen
 * button. Only the topstrip needs to change (button label/state, plus the
 * ⏻ exit-to-dashboard button appearing/disappearing) — everything else
 * (capture input, clock, activity feed, AppStore subscription) is
 * untouched, so scanning isn't interrupted by toggling this mid-session.
 */
window._rfidToggleKioskMode = function () {
  _rfidKioskMode = !_rfidKioskMode;
  document.body.classList.toggle('rfid-kiosk-mode', _rfidKioskMode);

  const btn = document.getElementById('rfid-fullscreen-btn');
  if (btn) {
    btn.classList.toggle('active', _rfidKioskMode);
    btn.title = _rfidKioskMode ? 'Exit fullscreen' : 'Fill the screen for scanning/kiosk display';
    btn.textContent = _rfidKioskMode ? '⤢ Exit' : '⛶ Fullscreen';
  }

  const topstrip = document.querySelector('.kiosk-topstrip');
  let exitBtn = document.getElementById('rfid-exit-kiosk-btn');
  if (_rfidKioskMode && !exitBtn && topstrip) {
    exitBtn = document.createElement('button');
    exitBtn.id = 'rfid-exit-kiosk-btn';
    exitBtn.className = 'kiosk-icon-btn';
    exitBtn.title = 'Exit kiosk — back to admin dashboard';
    exitBtn.textContent = '⏻';
    exitBtn.onclick = function () { navTo('a-dashboard'); };
    topstrip.appendChild(exitBtn);
  } else if (!_rfidKioskMode && exitBtn) {
    exitBtn.remove();
  }
};

// ── Capture plumbing ────────────────────────────────────────────────────────

// ── Live clock (Task 4 — gives the otherwise-empty top-left corner a job,
//    and makes the kiosk feel "alive" during idle stretches between scans) ──

function _rfidTickClock() {
  const el = document.getElementById('kiosk-clock-corner');
  if (!el) return;
  const now = new Date();
  const time = now.toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' });
  const date = now.toLocaleDateString('en-PH', { weekday: 'short', month: 'short', day: 'numeric' });
  const blinkTime = _esc(time).replace(':', '<span class="kiosk-clock-blink">:</span>');
  el.innerHTML = `<div class="kiosk-clock-time">${blinkTime}</div><div class="kiosk-clock-date">${_esc(date)}</div>`;
}

function _rfidStartClock() {
  if (_rfidClockInterval) clearInterval(_rfidClockInterval);
  _rfidTickClock();
  _rfidClockInterval = setInterval(_rfidTickClock, 1000 * 15);
}

// ── Schedule countdown (one chip, not three) ────────────────────────────────
// A teacher only ever cares about whichever milestone is coming up next, so
// instead of showing "opens/late/closes" as three separate timers this picks
// the single next one and switches automatically as the day progresses:
//   before openTime   → "Opens in"
//   openTime→lateCutoff → "Late in"     (counting down to when scans start
//                                        being marked Late)
//   lateCutoff→closeTime → "Closes in"  (counting down to auto-close, which
//                                        marks remaining students Absent)
//   after closeTime   → "Session closed"
function _rfidScheduleFor(classId) {
  // Phase 54: a section can have a whole-week default PLUS per-day
  // overrides — resolve TODAY's actual window instead of grabbing whatever
  // single row used to be the only one.
  const sched = (typeof AttendanceService !== 'undefined' && AttendanceService.getEffectiveSchedule)
    ? AttendanceService.getEffectiveSchedule(classId)
    : AppStore.getSlice(s => (s.attendanceSchedules || []).find(x => x.classId === classId && (x.dayOfWeek || 0) === 0));
  return sched || { openTime: '07:00', startTime: '07:30', lateCutoff: '07:45', closeTime: '08:30' };
}

function _rfidTimeStrToDate(hhmm, base) {
  const parts = (hhmm || '00:00').split(':').map(Number);
  const d = new Date(base);
  d.setHours(parts[0] || 0, parts[1] || 0, 0, 0);
  return d;
}

function _rfidNextScheduleMilestone(classId) {
  const sched = _rfidScheduleFor(classId);
  const now = new Date();
  const open = _rfidTimeStrToDate(sched.openTime, now);
  const late = _rfidTimeStrToDate(sched.lateCutoff, now);
  const close = _rfidTimeStrToDate(sched.closeTime, now);

  if (now < open) return { label: 'Opens in', target: open, tone: 'open' };
  if (now < late) return { label: 'Late in', target: late, tone: 'late' };
  if (now < close) return { label: 'Closes in', target: close, tone: 'close' };
  return { label: 'Session closed', target: null, tone: 'closed' };
}

function _rfidFormatCountdown(ms) {
  const totalSec = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  return h > 0
    ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
    : `${m}:${String(s).padStart(2, '0')}`;
}

function _rfidTickScheduleTimer() {
  _rfidUpdateStatusEyebrow();
  const el = document.getElementById('kiosk-schedule-timer');
  if (!el) return;
  const info = _rfidNextScheduleMilestone(_rfidSelectedClassId);
  if (!info.target) {
    el.innerHTML = `<div class="kiosk-timer-chip kiosk-timer-closed"><span class="kiosk-timer-label">🔒 Session closed</span></div>`;
    return;
  }
  const remaining = _rfidFormatCountdown(info.target - new Date());
  const icons = { open: '🚪', late: '⏰', close: '🔒' };
  el.innerHTML = `
    <div class="kiosk-timer-chip kiosk-timer-${info.tone}">
      <span class="kiosk-timer-icon">${icons[info.tone] || '⏱'}</span>
      <span class="kiosk-timer-label">${_esc(info.label)}</span>
      <span class="kiosk-timer-value">${_esc(remaining)}</span>
    </div>`;
}

function _rfidStartScheduleTimer() {
  if (_rfidScheduleTimerInterval) clearInterval(_rfidScheduleTimerInterval);
  _rfidTickScheduleTimer();
  _rfidScheduleTimerInterval = setInterval(_rfidTickScheduleTimer, 1000);
}

function _rfidStartCapture() {
  const input = document.getElementById('rfid-capture-input');
  if (!input) return;

  input.value = '';
  _rfidScanBuffer = '';
  input.focus();

  // Defensive refocus: clicking a button on this screen, or a modal opening
  // elsewhere (e.g. the ⚙️ Settings modal), can steal focus from the
  // capture input. Re-grab it continuously while mounted, but never while
  // the user is deliberately typing into a real text field (schedule
  // times, the assign-card picker, etc.) or while a select/dropdown is open.
  if (_rfidFocusInterval) clearInterval(_rfidFocusInterval);
  _rfidFocusInterval = setInterval(function () {
    if (!_rfidScannerMounted) return;
    const active = document.activeElement;
    const isRealInput = active && active !== input &&
      (active.tagName === 'INPUT' || active.tagName === 'SELECT' || active.tagName === 'TEXTAREA');
    if (!isRealInput && document.getElementById('rfid-capture-input')) {
      document.getElementById('rfid-capture-input').focus();
    }
  }, 600);

  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      _rfidFinalizeScan(input.value);
      return;
    }
    // Reset the inactivity finalize-timer on every keystroke.
    if (_rfidInactivityTimer) clearTimeout(_rfidInactivityTimer);
    _rfidInactivityTimer = setTimeout(function () {
      if (input.value) _rfidFinalizeScan(input.value);
    }, 120);
  });
}

// ── Phone-as-NFC-reader (Web NFC) ───────────────────────────────────────────
// Entirely additive to the USB-HID capture above: it never touches
// _rfidScanBuffer, the hidden #rfid-capture-input, or the focus-stealing
// interval. It only ever calls the same _rfidFinalizeScan(tagId) that the
// keyboard-emulator path calls, so AttendanceService.processScan() and
// everything downstream (spotlight, activity log, realtime) is identical
// no matter which physical reader produced the tag.

function _rfidWebNfcSupported() {
  return typeof window !== 'undefined' && 'NDEFReader' in window;
}

window._rfidToggleWebNfc = function () {
  if (_rfidWebNfcActive) {
    _rfidStopWebNfcCapture();
  } else {
    _rfidStartWebNfcCapture();
  }
};

async function _rfidStartWebNfcCapture() {
  if (!_rfidWebNfcSupported()) return;
  try {
    _rfidWebNfcAbortController = new AbortController();
    const ndef = new NDEFReader();
    // Must be called from a user gesture (the button's onclick) — this is
    // a browser security requirement, not something we can work around.
    await ndef.scan({ signal: _rfidWebNfcAbortController.signal });

    _rfidWebNfcActive = true;
    _rfidRefreshWebNfcButton();
    toast('📱 Phone NFC reader armed — hold cards to the back of the phone', '#4edea3');

    ndef.onreading = (event) => {
      if (!_rfidScannerMounted) return;
      // event.serialNumber is the tag/card UID (e.g. "04:a2:3f:9c:1b:80"),
      // in the phone's native hex format — different on the wire from what
      // the USB reader types, but _rfidFinalizeScan() normalizes both into
      // one canonical id (see _rfidNormalizeTagId() above), so a card
      // assigned via either reader is recognized by both.
      const tagId = event.serialNumber;
      if (tagId) _rfidFinalizeScan(tagId);
    };

    ndef.onreadingerror = () => {
      toast('⚠️ Could not read that tag — try again', '#ffd166');
    };
  } catch (err) {
    _rfidWebNfcActive = false;
    _rfidWebNfcAbortController = null;
    _rfidRefreshWebNfcButton();
    toast('Could not start phone NFC: ' + (err && err.message ? err.message : err), '#ffb4ab');
  }
}

function _rfidStopWebNfcCapture() {
  if (_rfidWebNfcAbortController) {
    _rfidWebNfcAbortController.abort();
    _rfidWebNfcAbortController = null;
  }
  _rfidWebNfcActive = false;
  _rfidRefreshWebNfcButton();
}

function _rfidRefreshWebNfcButton() {
  const btn = document.getElementById('rfid-webnfc-btn');
  if (!btn) return;
  btn.classList.toggle('active', _rfidWebNfcActive);
  btn.textContent = _rfidWebNfcActive ? '📱 NFC On' : '📱 Use Phone as Reader';
  btn.title = _rfidWebNfcActive
    ? 'Stop using this phone as an NFC reader'
    : 'Use this phone as an NFC reader — tap to arm, then hold cards to the back of the phone';
}

/**
 * _rfidNormalizeTagId(raw) → string
 * Makes a phone (Web NFC) scan and a USB (keyboard-wedge) scan of the SAME
 * physical card produce the SAME tag_id, so either reader can be assigned
 * once and then used interchangeably for that card.
 *
 * Confirmed against this project's actual USB reader with a real card:
 *   phone (Web NFC serialNumber): "27:21:7c:33"   (hex, card's native byte order)
 *   USB reader (keyboard-wedge):  "0863772967"    (decimal, REVERSED byte
 *                                                   order, zero-padded to
 *                                                   10 digits)
 *   27:21:7c:33 reversed -> 33:7c:21:27 -> hex 337C2127 -> decimal 863772967
 *   -> zero-padded -> 0863772967  ✓ matches exactly.
 *
 * The USB decimal format is treated as canonical (not the phone's hex)
 * because every card assigned before this fix is already stored that way —
 * so this needs no data migration, and only phone reads get converted.
 * A plain digit string (already-USB-format input) is untouched and passes
 * straight through, so the existing USB-only flow is byte-for-byte
 * unaffected. Only 4-byte UIDs (colon/dash-separated hex, exactly 4 bytes —
 * the common MIFARE Classic case, and the one verified above) get the
 * fixed 10-digit zero-pad; longer UIDs are still converted to decimal but
 * not force-padded, since there's no confirmed USB sample for that case.
 */
function _rfidNormalizeTagId(raw) {
  const s = String(raw || '').trim();
  if (!s) return '';
  if (/^[0-9a-fA-F]{2}([:\-][0-9a-fA-F]{2})+$/.test(s)) {
    const hexBytes = s.split(/[:\-]/);
    const reversedHex = hexBytes.slice().reverse().join('');
    try {
      const asDecimal = BigInt('0x' + reversedHex).toString();
      return hexBytes.length === 4 ? asDecimal.padStart(10, '0') : asDecimal;
    } catch (e) {
      return s.replace(/[:\-]/g, '').toUpperCase(); // fallback if BigInt parsing ever fails
    }
  }
  return s; // already USB/decimal format (or an unrecognized shape) — unchanged
}

function _rfidFinalizeScan(rawValue) {
  const input = document.getElementById('rfid-capture-input');
  const tagId = _rfidNormalizeTagId(rawValue);
  if (input) input.value = '';
  if (_rfidInactivityTimer) { clearTimeout(_rfidInactivityTimer); _rfidInactivityTimer = null; }
  if (!tagId) return;

  if (_rfidScanMode === 'assign') {
    _rfidHandleAssignScan(tagId);
  } else {
    _rfidHandleAttendanceScan(tagId);
  }
}

async function _rfidHandleAttendanceScan(tagId) {
  _rfidRenderSpotlight('loading', { text: 'Checking card…' });
  const result = await AttendanceService.processScan(tagId, _rfidSelectedClassId);

  if (!result.ok) {
    // BUGFIX (Investigation Report §4): "the attendance window closed for
    // the day" isn't a mistake the way "unknown card" is — it's an expected
    // end-of-period state. It used to render through the same 🚫 error
    // look as everything else; now it gets its own calmer 'closed' mode.
    if (result.error === 'closed') {
      _rfidRenderSpotlight('closed', { message: result.message });
      return;
    }
    const messages = {
      unknown_card:  'Unknown card — not registered to any student.',
      no_schedule:   'No schedule configured for this class.',
      not_open:      'Attendance has not opened yet.',
      wrong_section: result.message || 'This student is enrolled in a different section and cannot be scanned here.',
    };
    _rfidRenderSpotlight('error', {
      message: messages[result.error] || result.message || 'Scan failed.',
      rawTag: result.error === 'unknown_card' ? tagId : null,
    });
    return;
  }

  const student = AppStore.getStudent(result.studentId);
  _rfidRenderSpotlight('profile', {
    student, status: result.status,
    alreadyRecorded: result.alreadyRecorded, fallbackName: result.studentName,
  });
  // _rfidRenderActivity() is also triggered by the AppStore subscription
  // once AttendanceService applies the result — no need to call it here
  // directly, but doing so keeps the log snappy on this device specifically
  // rather than waiting on the realtime round-trip.
  _rfidRenderActivity();
}

async function _rfidHandleAssignScan(tagId) {
  if (!_rfidAssignTargetStudentId) {
    _rfidRenderSpotlight('message', { icon: '⚠️', text: 'Pick a student in Settings before scanning.', color: '#ffd166' });
    return;
  }
  _rfidRenderSpotlight('loading', { text: 'Assigning card…' });
  const result = await AttendanceService.assignCard(_rfidAssignTargetStudentId, tagId);
  if (!result.ok) {
    _rfidRenderSpotlight('message', { icon: '❌', text: result.error || 'Could not assign card.', color: '#ffb4ab', rawTag: tagId });
    return;
  }
  const student = AppStore.getStudent(_rfidAssignTargetStudentId);
  _rfidRenderSpotlight('message', { icon: '🪪', text: `Card assigned to ${student ? student.name : _rfidAssignTargetStudentId}.`, color: '#4edea3', rawTag: tagId });
}

// ── Student Spotlight (Task 1, left column — 80%) ───────────────────────────

function _rfidSpotlightIdleHtml() {
  if (_rfidScanMode === 'assign') {
    const target = _rfidAssignTargetStudentId ? AppStore.getStudent(_rfidAssignTargetStudentId) : null;
    return `
      <div class="kiosk-spotlight-idle">
        <div class="kiosk-spotlight-idle-icon">🪪</div>
        <div class="kiosk-spotlight-idle-text">Ready to assign a card</div>
        <div class="kiosk-spotlight-idle-sub">${target ? `Tap a card for ${_esc(target.name)}` : 'Pick a student in Settings first'}</div>
      </div>`;
  }
  return `
    <div class="kiosk-spotlight-idle">
      <div class="kiosk-spotlight-idle-icon">📶</div>
      <div class="kiosk-spotlight-idle-text">Waiting for a card…</div>
      <div class="kiosk-spotlight-idle-sub">Class: ${_esc(_rfidSelectedClassId)}</div>
    </div>`;
}

function _rfidWelcomeMessage(name, status, streak, alreadyRecorded) {
  const firstName = _esc(String(name || 'Student').trim().split(/\s+/)[0]);
  if (alreadyRecorded) return `You're already logged in for today, ${firstName}. See you in class!`;
  if (status === 'Late') return `You're logged in, ${firstName} — try to beat the bell tomorrow!`;
  if (streak && streak.current >= 3) return `Welcome back, ${firstName}! That's a ${streak.current}-day streak — keep up the great work!`;
  if (status === 'Early') return `Welcome back, ${firstName}! Great to see you here early!`;
  return `Welcome back, ${firstName}! Keep up the great work!`;
}

// Level/XP progress — mirrors the exact formula topbar.js's updateTopbar()
// uses for the sidebar XP bar (xpNext=(level+1)*1000), so the number shown
// here always agrees with what the student sees in their own sidebar.
function _rfidLevelProgress(student) {
  if (!student) return null;
  const lvl = student.level || 0;
  const xp = student.xp || 0;
  const xpNext = (lvl + 1) * 1000;
  const pct = Math.min(100, Math.round((xp / xpNext) * 100));
  return { lvl, xp, xpNext, pct };
}

// Class rank by XP — same sort AttendanceService/hall-of-fame.js already
// uses for the leaderboard podium, scoped to this student's own section.
// Returns null when there's no meaningful ranking to show (solo section).
function _rfidClassRank(student) {
  if (!student) return null;
  const classmates = AppStore.getSlice(s => (s.students || []).filter(
    x => (x.classId || 'default-class') === (student.classId || 'default-class')
  )) || [];
  if (classmates.length < 2) return null;
  const sorted = classmates.slice().sort((a, b) => (b.xp || 0) - (a.xp || 0));
  const idx = sorted.findIndex(s => s.id === student.id);
  return idx === -1 ? null : { rank: idx + 1, of: sorted.length };
}

function _rfidProfileCardHtml(student, status, alreadyRecorded, fallbackName) {
  const icons  = { 'Early': '🌅', 'On Time': '✅', 'Late': '⏰' };
  const colors = { 'Early': '#7fd8ff', 'On Time': '#4edea3', 'Late': '#ffd166' };
  const badgeColor = colors[status] || '#4edea3';
  const name = student ? (student.name || student.displayName) : fallbackName;
  const initials = (student && student.init) || String(name || '?').trim().slice(0, 2).toUpperCase();
  const avatarColor = _cssColor(student && student.color);
  const pct = student ? Math.round(Number(student.attendance) || 0) : null;
  const pctColor = pct === null ? 'var(--text-muted)' : pct >= 90 ? '#4edea3' : pct >= 75 ? '#ffd166' : '#ffb4ab';

  // Attendance streak (Investigation Report §4) — shares the exact same
  // normalization + math as the student's own Progress page via the utils.js
  // helpers, rather than a second copy of this logic living here.
  const streak = student ? computeAttendanceStreak(getStudentAttendanceRecords(student.id)) : null;

  // Too-many-absences warning (Investigation Report §4): no threshold existed
  // anywhere in the app before. Reuses the same 75% line the progress ring
  // color already draws, so a teacher sees one consistent cutoff everywhere
  // instead of two different thresholds meaning slightly different things.
  const showAbsenceWarning = pct !== null && pct < 75;

  // Circular progress ring drawn with a conic-gradient — no SVG needed, and
  // it scales/recolors purely through CSS custom properties set inline.
  const ringDeg = pct !== null ? Math.round((pct / 100) * 360) : 0;

  const lvlInfo = _rfidLevelProgress(student);
  const rankInfo = _rfidClassRank(student);
  // Equipped title — reuses the same tsGetEquippedTitle()/tsBuildBadgeHTML()
  // pair the sidebar and dashboard use (modules/titles/), so the kiosk shows
  // the exact same badge a student sees everywhere else. Guarded with
  // typeof since modules/titles/*.js loads after this file (see index.html).
  const equippedTitle = student && typeof tsGetEquippedTitle === 'function' ? tsGetEquippedTitle(student.id) : null;
  const hasStatsPanel = (student && student.coins != null) || rankInfo;

  return `
    <div class="kiosk-dashboard">
      <div class="kiosk-welcome-banner">
        <div class="kiosk-welcome-icon">${!alreadyRecorded ? '✅' : '👋'}</div>
        <div class="kiosk-welcome-copy">
          <div class="kiosk-welcome-kicker">${!alreadyRecorded ? 'Scan Successful' : 'Already Checked In'}</div>
          <div class="kiosk-welcome-text">${_rfidWelcomeMessage(name, status, streak, alreadyRecorded)}</div>
        </div>
      </div>

      <div class="kiosk-dashboard-grid${pct === null ? ' kiosk-dashboard-grid-single' : ''}">
        <div class="kiosk-panel kiosk-identity-panel">
          ${student && student.profilePic
            ? `<img class="kiosk-profile-avatar" src="${_esc(student.profilePic)}" alt="" />`
            : `<div class="kiosk-profile-avatar" style="background:${avatarColor}22;color:${avatarColor};border-color:${avatarColor}44">${_esc(initials)}</div>`
          }
          <div class="kiosk-identity-info">
            <div class="kiosk-profile-name">${_esc(name || 'Student')}</div>
            <div class="kiosk-name-accent"></div>
            ${student ? `<div class="kiosk-profile-section">Section: ${_esc(typeof getClassLabel === 'function' ? getClassLabel(student.classId) : student.classId)}</div>` : ''}
            <div>
              <div class="kiosk-status-badge" style="background:${badgeColor}22;color:${badgeColor};border:2px solid ${badgeColor}55">
                ${icons[status] || '✅'} ${_esc(status)}${alreadyRecorded ? ' · already logged today' : ''}
              </div>
              ${streak && streak.current > 0 ? `<div class="kiosk-streak-pill">🔥 ${streak.current}-day streak</div>` : ''}
            </div>
            ${lvlInfo ? `
            <div class="kiosk-level-block">
              <div class="kiosk-level-label"><span>Level ${lvlInfo.lvl}</span><span>${lvlInfo.xp.toLocaleString()} / ${lvlInfo.xpNext.toLocaleString()} XP</span></div>
              <div class="kiosk-level-track"><div class="kiosk-level-fill" style="width:${lvlInfo.pct}%"></div></div>
              ${equippedTitle ? `<div class="kiosk-equipped-title"><div class="kiosk-equipped-label">Equipped Title</div>${tsBuildBadgeHTML(equippedTitle, { noParticles: true })}</div>` : ''}
            </div>` : ''}
          </div>
        </div>

        ${pct !== null ? `
        <div class="kiosk-panel kiosk-attendance-panel" style="--ring-color:${pctColor}">
          <div class="kiosk-ring" style="--ring-deg:${ringDeg}deg;--ring-color:${pctColor}">
            <div class="kiosk-ring-inner">
              <div class="kiosk-ring-pct">${pct}<span>%</span></div>
              <div class="kiosk-ring-label">Cumulative<br>Attendance</div>
            </div>
          </div>
          ${showAbsenceWarning ? `<div class="kiosk-absence-warning">⚠️ Below 75% — worth checking in with this student.</div>` : ''}
        </div>` : ''}

        ${pct !== null && hasStatsPanel ? `
        <div class="kiosk-panel kiosk-stats-panel">
          ${student && student.coins != null ? `
          <div class="kiosk-stat-chip kiosk-stat-chip-coins">
            <div class="kiosk-stat-label">Coins</div>
            <div class="kiosk-stat-value">🪙 ${Number(student.coins || 0).toLocaleString()}</div>
          </div>` : ''}
          ${rankInfo ? `
          <div class="kiosk-stat-chip kiosk-stat-chip-rank">
            <div class="kiosk-stat-label">Class Rank</div>
            <div class="kiosk-stat-value">#${rankInfo.rank} <span>of ${rankInfo.of}</span></div>
          </div>` : ''}
        </div>` : ''}
      </div>
    </div>`;
}

/**
 * _rfidRenderSpotlight(mode, data) — the single entry point for everything
 * shown in the left "Student Spotlight" column.
 *   mode: 'idle' | 'loading' | 'message' | 'error' | 'profile'
 * Auto-returns to 'idle' after a beat (except 'idle'/'loading' themselves)
 * so the kiosk is always ready for the next student in line.
 */
function _rfidRenderSpotlight(mode, data) {
  const el = document.getElementById('kiosk-spotlight');
  if (!el) return;
  data = data || {};
  clearTimeout(window._rfidSpotlightResetTimer);

  if (mode === 'idle') {
    el.innerHTML = _rfidSpotlightIdleHtml();
    return;
  }
  if (mode === 'loading') {
    el.innerHTML = `
      <div class="kiosk-spotlight-idle">
        <div class="kiosk-spotlight-idle-icon">⏳</div>
        <div class="kiosk-spotlight-idle-text">${_esc(data.text || 'Checking card…')}</div>
      </div>`;
    return;
  }
  if (mode === 'message') {
    el.innerHTML = `
      <div class="kiosk-spotlight-idle">
        <div class="kiosk-spotlight-idle-icon">${_esc(data.icon || 'ℹ️')}</div>
        <div class="kiosk-spotlight-idle-text" style="color:${data.color || 'inherit'}">${_esc(data.text || '')}</div>
        ${data.rawTag ? `<div class="kiosk-spotlight-raw-tag">Raw ID read: <code>${_esc(data.rawTag)}</code></div>` : ''}
      </div>`;
    window._rfidSpotlightResetTimer = setTimeout(function () { _rfidRenderSpotlight('idle'); }, 5200);
    return;
  }
  if (mode === 'error') {
    el.innerHTML = `
      <div class="kiosk-spotlight-error">
        <div class="kiosk-spotlight-error-icon">🚫</div>
        <div class="kiosk-spotlight-error-text">${_esc(data.message || 'Scan failed.')}</div>
        ${data.rawTag ? `<div class="kiosk-spotlight-raw-tag">Raw ID read: <code>${_esc(data.rawTag)}</code></div>` : ''}
      </div>`;
    window._rfidSpotlightResetTimer = setTimeout(function () { _rfidRenderSpotlight('idle'); }, 3200);
    return;
  }
  if (mode === 'closed') {
    // Distinct from 'error' (Investigation Report §4) — a closed window is
    // an expected end-of-period state, not a scan gone wrong, so it gets a
    // calmer icon/color and a direct pointer to where to still record it.
    el.innerHTML = `
      <div class="kiosk-spotlight-closed">
        <div class="kiosk-spotlight-closed-icon">🔒</div>
        <div class="kiosk-spotlight-closed-text">Attendance Window Closed</div>
        <div class="kiosk-spotlight-closed-sub">${_esc(data.message || 'Use the Manual Override on the Live Classroom Monitor instead.')}</div>
      </div>`;
    window._rfidSpotlightResetTimer = setTimeout(function () { _rfidRenderSpotlight('idle'); }, 3200);
    return;
  }
  if (mode === 'profile') {
    el.innerHTML = _rfidProfileCardHtml(data.student, data.status, data.alreadyRecorded, data.fallbackName);
    window._rfidSpotlightResetTimer = setTimeout(function () { _rfidRenderSpotlight('idle'); }, 5000);
    return;
  }
}

// ── Recent Activity Log (Task 1, right column — 20%) ────────────────────────

// BUGFIX: this used to be new Date().toISOString().slice(0,10) — the UTC
// date, not the Manila date, same class of bug already fixed elsewhere for
// the 8am-instead-of-midnight rollover (FIXES_APPLIED.md §2). Now shares
// utils.js's isoDate() so "today" means the same thing everywhere.
function _rfidTodayISO() {
  return isoDate();
}

function _rfidRenderActivity() {
  const statsEl = document.getElementById('kiosk-roster-stats');
  const summaryEl = document.getElementById('kiosk-activity-summary');
  const listEl = document.getElementById('kiosk-activity-list');
  if (!summaryEl || !listEl) return;

  const today = _rfidTodayISO();
  const students = AppStore.getSlice(s => s.students) || [];
  const todaysLogs = AppStore.getSlice(s => (s.attendanceLogs || []).filter(
    l => l.classId === _rfidSelectedClassId && l.logDate === today
  ));

  const by = { 'Early': 0, 'On Time': 0, 'Late': 0, 'Absent': 0, 'Excused': 0 };
  todaysLogs.forEach(l => { if (by[l.status] !== undefined) by[l.status]++; });
  const colors = { 'Early': '#7fd8ff', 'On Time': '#4edea3', 'Late': '#ffd166', 'Absent': '#ffb4ab', 'Excused': '#c4b5fd' };

  // Roster snapshot — the four numbers a teacher glances at first when the
  // kiosk is idle: how many are enrolled, how many are in (on time or
  // early), how many came in late, and how many the kiosk hasn't seen yet
  // today. "Not Checked In" mirrors the "already logged in" phrasing the
  // spotlight card already uses, instead of the more clinical "not yet
  // scanned".
  if (statsEl) {
    const enrolledCount = students.filter(s => (s.classId || 'default-class') === _rfidSelectedClassId).length;
    const presentCount = by['Early'] + by['On Time'];
    const lateCount = by['Late'];
    const loggedCount = todaysLogs.length;
    const notCheckedInCount = Math.max(0, enrolledCount - loggedCount);

    statsEl.innerHTML = `
      <div class="kiosk-roster-stat">
        <div class="kiosk-roster-stat-value">${enrolledCount}</div>
        <div class="kiosk-roster-stat-label">Total</div>
      </div>
      <div class="kiosk-roster-stat kiosk-roster-stat-present">
        <div class="kiosk-roster-stat-value">${presentCount}</div>
        <div class="kiosk-roster-stat-label">Present</div>
      </div>
      <div class="kiosk-roster-stat kiosk-roster-stat-late">
        <div class="kiosk-roster-stat-value">${lateCount}</div>
        <div class="kiosk-roster-stat-label">Late</div>
      </div>
      <div class="kiosk-roster-stat kiosk-roster-stat-pending">
        <div class="kiosk-roster-stat-value">${notCheckedInCount}</div>
        <div class="kiosk-roster-stat-label">Not Checked In</div>
      </div>`;
  }

  // Compact one-line summary — the full stat grid the old layout had would
  // crowd the spec'd 80/20 split, so this keeps the same information
  // available at a glance without competing with the activity list.
  summaryEl.innerHTML = ['Early', 'On Time', 'Late', 'Absent', 'Excused']
    .filter(k => by[k] > 0)
    .map(k => `<span style="color:${colors[k]};font-weight:800">${by[k]}</span> ${_esc(k)}`)
    .join(' <span style="opacity:.35">·</span> ') || 'No scans yet today';

  const last10 = todaysLogs.slice()
    .sort((a, b) => new Date(b.scannedAt) - new Date(a.scannedAt))
    .slice(0, 10);

  listEl.innerHTML = last10.length ? last10.map(l => {
    const student = students.find(s => s.id === l.studentId);
    const name = student ? (student.name || student.displayName) : l.studentId;
    const initials = (student && student.init) || String(name || '?').trim().slice(0, 2).toUpperCase();
    const avatarColor = _cssColor(student && student.color);
    const color = colors[l.status] || 'var(--text-muted)';
    return `
      <div class="kiosk-activity-item">
        ${student && student.profilePic
          ? `<img class="kiosk-activity-avatar" src="${_esc(student.profilePic)}" alt="" />`
          : `<div class="kiosk-activity-avatar" style="background:${avatarColor}22;color:${avatarColor}">${_esc(initials)}</div>`
        }
        <div class="kiosk-activity-main">
          <div class="kiosk-activity-name">${_esc(name)}</div>
          <div class="kiosk-activity-meta" style="color:${color}">${_esc(l.status)}${l.entryMethod === 'Manual' ? ' · manual' : ''}</div>
        </div>
        <div class="kiosk-activity-time">${_esc(new Date(l.scannedAt).toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' }))}</div>
      </div>`;
  }).join('') : `<div class="kiosk-activity-empty">No scans yet today</div>`;
}

// ── Mode / class switching ──────────────────────────────────────────────────

window._rfidSetMode = function (mode) {
  _rfidScanMode = mode;
  _rfidAssignTargetStudentId = null;
  window.renderRfidScanner();
  // Settings modal stays open across mode switches so the teacher can flip
  // between Attendance/Assign and immediately see the updated picker.
  if (document.getElementById('rfid-settings-panel')) window._rfidOpenSettings();
};
window._rfidOpenAssignPicker = function () {
  const students = AppStore.getSlice(s => s.students) || [];
  _rfidAssignTargetStudentId = students[0] ? students[0].id : null;
  _rfidSetMode('assign');
};
window._rfidOnClassChange = function (classId) {
  _rfidSelectedClassId = classId;
  window.renderRfidScanner();
};

// ── ⚙️ Settings (Task 1: everything administrative, tucked out of the way) ──
// Assign-Card mode, Schedule, and Close Session all still work exactly as
// they did before the kiosk refactor — they're just one tap away instead of
// permanently on-screen, keeping the main kiosk view distraction-free.
// (Manual Override moved out entirely — see the file header.)

window._rfidOpenSettings = function () {
  const students = AppStore.getSlice(s => s.students) || [];
  showModal(`
    <h3 style="margin-bottom:4px">⚙️ Kiosk Settings</h3>
    <div id="rfid-settings-panel" style="color:var(--text-muted);font-size:12px;margin-bottom:18px">Class: ${_esc(window.getClassLabel ? window.getClassLabel(_rfidSelectedClassId, AppStore.getState()) : _rfidSelectedClassId)}</div>

    <div style="margin-bottom:20px">
      <label class="form-label">Scan Mode</label>
      <div style="display:flex;gap:10px;margin-top:8px">
        <button class="btn ${_rfidScanMode === 'attendance' ? 'btn-primary' : ''}" onclick="_rfidSetMode('attendance')">📡 Attendance Mode</button>
        <button class="btn ${_rfidScanMode === 'assign' ? 'btn-primary' : ''}" onclick="_rfidOpenAssignPicker()">🪪 Assign Card</button>
      </div>
      ${_rfidScanMode === 'assign' ? `
      <div style="margin-top:12px;background:rgba(255,255,255,.03);border-radius:10px;padding:12px;border:1px solid var(--border)">
        <div style="font-size:11px;color:var(--text-muted);font-weight:700;margin-bottom:8px;letter-spacing:.06em">ASSIGNING NEXT SCANNED CARD TO</div>
        <select id="rfid-assign-student" style="width:100%" onchange="_rfidAssignTargetStudentId=this.value">
          ${students.map(s => `<option value="${s.id}" ${s.id === _rfidAssignTargetStudentId ? 'selected' : ''}>${_esc(s.name)}</option>`).join('')}
        </select>
      </div>` : ''}
    </div>

    <div style="margin-bottom:20px">
      <label class="form-label">⏰ Default Schedule — ${_esc(window.getClassLabel ? window.getClassLabel(_rfidSelectedClassId, AppStore.getState()) : _rfidSelectedClassId)}</label>
      <div style="margin-top:8px">${_rfidRenderScheduleForm()}</div>
      <div style="margin-top:6px;font-size:11px;color:var(--text-muted)">
        This is the whole-week default. Per-day overrides (e.g. a shorter Friday) and
        every other section setting live in
        <a style="color:var(--primary);font-weight:700;cursor:pointer;text-decoration:none" onclick="closeModalForce();navTo('a-sections')">Section Maker →</a>
      </div>
    </div>

    <div style="border-top:1px solid var(--border);padding-top:16px;display:flex;justify-content:space-between;align-items:center">
      <button class="btn btn-danger" onclick="_rfidCloseSession()">🔒 Close Session</button>
      <button class="btn" onclick="closeModalForce()">Done</button>
    </div>
  `, 'md');
};

function _rfidRenderScheduleForm() {
  // Phase 54: this quick-edit form only ever touches the DEFAULT (day 0)
  // row — explicitly filtered now that a class_id can have up to 8 rows
  // (1 default + 7 day overrides). Editing a specific day's override is a
  // Section Maker action, not a kiosk one.
  const sched = AppStore.getSlice(s => (s.attendanceSchedules || []).find(x => x.classId === _rfidSelectedClassId && (x.dayOfWeek || 0) === 0));
  const v = sched || { openTime: '07:00', startTime: '07:30', lateCutoff: '07:45', closeTime: '08:30' };
  return `
    <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;align-items:end">
      <div><label class="form-label">Opens</label><input type="time" id="rfid-sched-open" value="${_esc(v.openTime)}"></div>
      <div><label class="form-label">Start (On Time from)</label><input type="time" id="rfid-sched-start" value="${_esc(v.startTime)}"></div>
      <div><label class="form-label">Late cutoff</label><input type="time" id="rfid-sched-late" value="${_esc(v.lateCutoff)}"></div>
      <div><label class="form-label">Closes</label><input type="time" id="rfid-sched-close" value="${_esc(v.closeTime)}"></div>
    </div>
    <button class="btn btn-primary" style="width:100%;margin-top:10px" onclick="_rfidSaveSchedule()">Save Schedule</button>`;
}

window._rfidSaveSchedule = async function () {
  const times = {
    openTime: document.getElementById('rfid-sched-open').value,
    startTime: document.getElementById('rfid-sched-start').value,
    lateCutoff: document.getElementById('rfid-sched-late').value,
    closeTime: document.getElementById('rfid-sched-close').value,
  };
  const result = await AttendanceService.upsertSchedule(_rfidSelectedClassId, times, 0);
  if (!result.ok) { toast(result.error || 'Could not save schedule.', '#ffb4ab'); return; }
  toast('⏰ Schedule saved', '#4edea3');
};

window._rfidCloseSession = async function () {
  if (!confirm(`Close today's attendance for "${_rfidSelectedClassId}"? Every student with no scan will be marked Absent.`)) return;
  const result = await AttendanceService.closeAttendanceSession(_rfidSelectedClassId);
  if (!result.ok) { toast(result.error || 'Could not close session.', '#ffb4ab'); return; }
  closeModalForce();
  toast(`🔒 Session closed — ${result.absencesRecorded} marked Absent`, '#4edea3');
};

console.log('[EduQuest] attendance/att_scanner_rfid.js loaded — renderRfidScanner, unmountRfidScanner registered (Phase 4 kiosk).');

