window.achRarityClass = function (rarity) {
  return 'ach-rarity-' + (rarity || 'Common').toLowerCase();
};

// ── Stats snapshot ────────────────────────────────────────────────────────────

/**
 * achBuildStats(student) → StatSnapshot  [window.achBuildStats]
 *
 * Builds a live stats object from AppStore for a given student. Used by achCheckAndAward
 * and achEvaluateTrigger to check all trigger conditions.
 */
window.achBuildStats = function (student) {
  if (!student) return {};
  const sid = student.id;
  let bossVictories = 0, totalBossDmg = 0, totalCrits = 0, totalMinionsKilled = 0;
  Object.values(AppStore.getSlice(s => s.bossParticipants) || {}).forEach(roster => {
    const rec = roster[sid];
    if (rec) {
      totalBossDmg      += (rec.totalDamage     || 0);
      totalCrits        += (rec.critHits         || 0);
      totalMinionsKilled += (rec.minionsDefeated || 0);
    }
  });
  const bossParticipants = AppStore.getSlice(s => s.bossParticipants) || {};
  (AppStore.getSlice(s => s.bossEvents) || []).forEach((boss, bi) => {
    if (boss.status === 'ended' || boss.status === 'loot') {
      const roster = bossParticipants[bi] || {};
      if (roster[sid] && (roster[sid].totalDamage || 0) > 0) bossVictories++;
    }
  });
  const redemptions = AppStore.getSlice(s => s.redemptions) || [];
  const storePurchases  = redemptions.filter(r => r.studentId === sid).length;
  const totalCoinsSpent = redemptions.filter(r => r.studentId === sid).reduce((a, r) => a + (r.pts || 0), 0);
  // BUGFIX (Investigation Report §1): DB.attendanceSessions is a dead
  // local-only array nothing has written to since Phase 1 shipped —
  // real attendance lives in the attendanceLogs slice (Early/On Time/Late = present).
  const attendancePresent = (AppStore.getSlice(s => s.attendanceLogs) || []).filter(r => r.studentId === sid && (r.status === 'Early' || r.status === 'On Time' || r.status === 'Late')).length;
  let bestQuizScore = 0;
  const pointLog = AppStore.getSlice(s => s.pointLog) || [];
  pointLog.filter(e => e.studentId === sid && e.what && e.what.startsWith('Quest:')).forEach(e => {
    const m = e.what.match(/\((\d+)%\)/);
    if (m) { const s = parseInt(m[1]); if (s > bestQuizScore) bestQuizScore = s; }
  });
  const recitationCount = (AppStore.getSlice(s => s.recitationLog) || []).filter(r => r.studentId === sid).length;
  const sorted   = [...(AppStore.getSlice(s => s.students) || [])].sort((a, b) => b.xp - a.xp);
  const liveRank = sorted.findIndex(s => s.id === sid) + 1;
  let maxPerfectStreak = 0, currentPerfect = 0;
  [...pointLog].filter(e => e.studentId === sid && e.what && e.what.startsWith('Quest:')).reverse().forEach(e => {
    const m = e.what.match(/\((\d+)%\)/);
    if (m && parseInt(m[1]) >= 100) { currentPerfect++; if (currentPerfect > maxPerfectStreak) maxPerfectStreak = currentPerfect; }
    else currentPerfect = 0;
  });
  // Phase 4 — quest chains completed (quest_board_report.md §3.8/§13):
  // a chain counts as done when every one of its quizzes is in
  // completedQuizzes. Reuses eqGetQuestChains()/eqQuizChain() (utils.js) —
  // same grouping the student board itself renders from, so "chain done"
  // here always matches what the student actually sees clear on the board.
  const completedIds = student.completedQuizzes || [];
  const chainsCompleted = (typeof eqGetQuestChains === 'function')
    ? eqGetQuestChains().filter(c => c.quizzes.length && c.quizzes.every(q => completedIds.includes(q.id))).length
    : 0;
  // Phase 4 — current quest-board day streak (quest_board_report.md §1/§13),
  // reusing the same computeQuestStreak() the board itself displays, so an
  // achievement tied to it always agrees with what the student sees.
  const questStreak = (typeof computeQuestStreak === 'function') ? computeQuestStreak(sid).current : 0;
  return {
    level:              student.level       || 0,
    xp:                 student.xp          || 0,
    coins:              student.coins       || 0,
    attendance:         student.attendance  || 0,
    quizAvg:            student.quizAvg     || 0,
    quests_completed:   (student.completedQuizzes || []).length,
    total_quests:       (AppStore.getSlice(s => s.quizzes) || []).length,
    boss_victories:     bossVictories,
    boss_damage:        totalBossDmg,
    boss_crits:         totalCrits,
    minions_killed:     totalMinionsKilled,
    store_purchases:    storePurchases,
    coins_spent:        totalCoinsSpent,
    attendance_present: attendancePresent,
    best_quiz_score:    bestQuizScore,
    recitation_count:   recitationCount,
    live_rank:          liveRank,
    perfect_streak:     maxPerfectStreak,
    student_count:      sorted.length,
    quest_chains_completed: chainsCompleted,
    quest_streak:       questStreak,
  };
};

// ── Trigger evaluator (private) ───────────────────────────────────────────────

function achEvaluateTrigger(ach, stats) {
  if (!ach || !ach.triggerType || !ach.active) return false;
  const v = parseFloat(ach.triggerValue) || 0;
  switch (ach.triggerType) {
    case 'level':              return stats.level              >= v;
    case 'xp_earned':         return stats.xp                 >= v;
    case 'coins_earned':      return stats.coins               >= v;
    case 'coins_spent':       return stats.coins_spent         >= v;
    case 'quests_completed':  return stats.quests_completed    >= v;
    case 'all_quests':        return stats.total_quests > 0 && stats.quests_completed >= stats.total_quests;
    case 'quiz_score':        return stats.best_quiz_score     >= v;
    case 'quiz_avg':          return stats.quizAvg             >= v;
    case 'perfect_streak':    return stats.perfect_streak      >= v;
    case 'boss_victories':    return stats.boss_victories      >= v;
    case 'boss_damage':       return stats.boss_damage         >= v;
    case 'boss_crits':        return stats.boss_crits          >= v;
    case 'minions_killed':    return stats.minions_killed      >= v;
    case 'attendance_present':return stats.attendance_present  >= v;
    case 'attendance_pct':    return stats.attendance          >= v;
    case 'store_purchases':   return stats.store_purchases     >= v;
    case 'recitations':       return stats.recitation_count    >= v;
    case 'top_rank':          return stats.live_rank > 0 && stats.live_rank <= v;
    case 'quest_chains_completed': return stats.quest_chains_completed >= v;
    case 'quest_streak':      return stats.quest_streak        >= v;
    case 'manual':            return false;
    default:                  return false;
  }
}

// ── Core check-and-award ──────────────────────────────────────────────────────

/**
 * achCheckAndAward(studentId, suppressPopup) → void  [window.achCheckAndAward]
 *
 * Evaluates all active achievements for a student. For each newly met trigger:
 *   the achievementUnlocks slice for sid gets pushed({ achId, unlockedAt, xpGranted, coinsGranted,
 *                                      claimed: false, claimedAt: null })
 * NOTE: Rewards are NOT granted here — only granted when student clicks Claim.
 * On new unlocks: saveDB(), achUpdateSidebarBadge(), optionally achShowUnlockPopup().
 *
 * Called by: recitation/logger.js, attendance/scanner.js, shop/store.js,
 *            quiz engine, wbcApplyDamage, bootApp — all via typeof guard or direct.
 */
window.achCheckAndAward = function (studentId, suppressPopup) {
  _achCheckAndAwardCore(studentId, suppressPopup);
  // Event-Driven Communication (Continuation Plan §3, Category A —
  // achCheckAndAward-as-title-hook, highest blast radius on the list:
  // achCheckAndAward is called directly from ~8 places across the app —
  // campaign_engine.js, combat-settings.js, shop_store.js,
  // shop_pos_terminal.js, plus this file's own subscribers below — none of
  // which needed to change, since all of them call the single global
  // achCheckAndAward and this wrapper is now the only thing that name
  // resolves to. Wrapping the whole function (rather than emitting from
  // _achCheckAndAwardCore's own tail) preserves the old monkey-patch's
  // "always runs after the original, regardless of which internal branch
  // fired" semantics exactly — same reasoning as navTo/renderAnalytics:
  // the old patch in titles_sidebar_refresh.js called `_orig(studentId,
  // suppressPopup)` first and ran its own title-unlock scan unconditionally
  // afterward (guarded only by its own `if (!studentId) return`), even on
  // _achCheckAndAwardCore's early returns (no studentId, unknown student,
  // or zero newly-unlocked achievements this call — that last one matters:
  // an admin can link a title to an achievement AFTER a student already
  // unlocked it, so a later achCheckAndAward() call that finds nothing NEW
  // to unlock still needs to let the title-scan catch up on titles linked
  // after the fact). The existing 'achievements:unlocked' event (emitted a
  // few lines up) does NOT cover that catch-up case — it only fires when
  // newlyUnlocked.length > 0 — so a dedicated event was needed here rather
  // than reusing it.
  AppStore.emit({ type: 'achievements:check-and-award-ran', payload: { studentId, suppressPopup } });
};

function _achCheckAndAwardCore(studentId, suppressPopup) {
  if (!studentId) return;
  const student = (AppStore.getSlice(s => s.students) || []).find(s => s.id === studentId);
  if (!student) return;
  const stats   = achBuildStats(student);

  const alreadyUnlocked = new Set(((AppStore.getSlice(s => s.achievementUnlocks) || {})[studentId] || []).map(u => u.achId));

  // Phase 16: same section-scoping as renderBadges() (student-page.js) —
  // a badge assigned to specific section(s) should not auto-unlock for a
  // student outside those sections. Unassigned badges (no rows in
  // achievementSectionAssignments) stay global, matching the "opt-in
  // scoping" convention used for quiz/mail section assignment too.
  const sectionAssignments = AppStore.getSlice(s => s.achievementSectionAssignments) || {};
  const myClassId          = student.classId || 'default-class';

  const newlyUnlocked = (AppStore.getSlice(s => s.achievements) || []).filter(ach => {
    if (!ach.active || alreadyUnlocked.has(ach.id)) return false;
    const assignedSections = sectionAssignments[ach.id];
    if (assignedSections && assignedSections.length > 0 && !assignedSections.includes(myClassId)) return false;
    return achEvaluateTrigger(ach, stats);
  });

  if (!newlyUnlocked.length) return;

  AppStore.updateState(draft => {
    if (!draft.achievementUnlocks) draft.achievementUnlocks = {};
    if (!draft.achievementUnlocks[studentId]) draft.achievementUnlocks[studentId] = [];
    newlyUnlocked.forEach(ach => {
      draft.achievementUnlocks[studentId].push({
        achId:         ach.id,
        unlockedAt:    new Date().toISOString(),
        xpGranted:     parseInt(ach.xpReward)   || 0,
        coinsGranted:  parseInt(ach.coinReward) || 0,
        claimed:       false,
        claimedAt:     null,
      });
    });
  }, { type: 'achievements:unlocked', payload: { studentId, achIds: newlyUnlocked.map(a => a.id) } });

  // Phase 17: record the unlock server-side too (claimed:false, 0/0 —
  // actual xp/coins are stamped at claim time by
  // syncAchievementClaimToServer). Fire-and-forget, same posture as
  // syncStudentStatsToServer elsewhere in this file.
  newlyUnlocked.forEach(ach => syncAchievementUnlockToServer(studentId, ach.id, 0, 0, false, myClassId));

  // [Preserved from pre-migration behavior, not introduced by this
  // migration] This reassigns currentUser unconditionally, even when
  // studentId isn't the logged-in session's own id (achCheckAndAward is
  // sometimes called for other students — e.g. every boss-fight
  // participant in combat-settings.js). Whether that's correct for those
  // call sites is a pre-existing question, not something this phase's
  // storage-layer migration should silently change.
  currentUser = (AppStore.getSlice(s => s.students) || []).find(s => s.id === studentId);
  achUpdateSidebarBadge();
  if (!suppressPopup) newlyUnlocked.forEach((ach, i) => setTimeout(() => achShowUnlockPopup(ach), i * 1400));
}

// ── Claim-time reward granting ────────────────────────────────────────────────

/**
 * achGrantRewardsForClaim(studentId, achId) → { xp, coins } | false
 * [window.achGrantRewardsForClaim]
 *
 * Called from achClaimReward (student-page.js) and achAdminDoGrant (admin-page.js).
 * Grants XP + coins to student, marks unlock as claimed.
 * Returns { xp, coins } on success, false if already claimed.
 */
window.achGrantRewardsForClaim = function (studentId, achId) {
  const existingUnlock = ((AppStore.getSlice(s => s.achievementUnlocks) || {})[studentId] || []).find(u => u.achId === achId);
  if (!existingUnlock || existingUnlock.claimed) return false;

  const xpGrant   = parseInt(existingUnlock.xpGranted)   || 0;
  const coinGrant = parseInt(existingUnlock.coinsGranted) || 0;
  const achName   = (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId)?.name || 'Achievement';

  let updatedStudent = null;
  AppStore.updateState(draft => {
    const s = (draft.students || []).find(x => x.id === studentId);
    if (!s) return;
    s.xp    = (s.xp || 0) + xpGrant;
    s.coins = (s.coins || 0) + coinGrant;

    const unlockRec = ((draft.achievementUnlocks || {})[studentId] || []).find(u => u.achId === achId);
    if (unlockRec) { unlockRec.claimed = true; unlockRec.claimedAt = new Date().toISOString(); }

    if (xpGrant > 0 || coinGrant > 0) {
      if (!Array.isArray(draft.pointLog)) draft.pointLog = [];
      draft.pointLog.unshift({ id: 'pl_' + uid(), studentId, what: `🏅 Achievement Claimed: ${achName}`, pts: coinGrant || xpGrant, when: 'Just now', createdAt: new Date().toISOString() });
    }
    updatedStudent = s;
  }, { type: 'achievements:claimed', payload: { studentId, achId } });

  if (!updatedStudent) return false; // student or unlock record vanished between the pre-check and the update

  syncStudentStatsToServer(studentId, xpGrant, coinGrant);
  syncAchievementClaimToServer(studentId, achId, xpGrant, coinGrant);

  currentUser = updatedStudent;
  achUpdateSidebarBadge();
  updateTopbar();
  return { xp: xpGrant, coins: coinGrant };
};

// ── Sidebar badge ─────────────────────────────────────────────────────────────

/**
 * achUpdateSidebarBadge() → void  [window.achUpdateSidebarBadge]
 * Shows unclaimed achievement count on #nav-s-badges.
 */
window.achUpdateSidebarBadge = function () {
  if (currentRole !== 'student' || !currentUser) return;
  const unlocks       = (AppStore.getSlice(s => s.achievementUnlocks) || {})[currentUser.id] || [];
  const unclaimedCount = unlocks.filter(u => !u.claimed).length;
  const btn            = document.getElementById('nav-s-badges');
  if (!btn) return;
  let badge = btn.querySelector('.ach-nav-badge');
  if (unclaimedCount > 0) {
    if (!badge) {
      badge             = document.createElement('span');
      badge.className   = 'ach-nav-badge';
      badge.style.cssText = 'margin-left:auto;background:rgba(208,188,255,0.2);border:1px solid rgba(208,188,255,0.3);border-radius:10px;padding:1px 7px;font-size:10px;font-weight:800;color:var(--primary);font-family:var(--fh)';
      btn.appendChild(badge);
    }
    badge.textContent = unclaimedCount > 99 ? '99+' : String(unclaimedCount);
  } else {
    if (badge) badge.remove();
  }
};

// ── Unlock popup ──────────────────────────────────────────────────────────────

/**
 * achShowUnlockPopup(ach) → void  [window.achShowUnlockPopup]
 * Shows a floating popup in the bottom-right corner. Tapping it navigates to
 * s-badges. Auto-dismisses after 4.5s.
 */
window.achShowUnlockPopup = function (ach) {
  const rarity   = ACH_RARITY[ach.rarity] || ACH_RARITY.Common;
  const existing = document.getElementById('ach-unlock-popup');
  if (existing) existing.remove();

  const d    = document.createElement('div');
  d.id        = 'ach-unlock-popup';
  d.className = 'ach-unlock-popup';
  d.style.cssText = `border-color:${rarity.color}55;box-shadow:0 8px 40px ${rarity.glow};cursor:pointer`;

  const hasRewards = (ach.xpReward || 0) > 0 || (ach.coinReward || 0) > 0;
  d.innerHTML = `
    <div class="ach-popup-icon">${ach.icon || '🏅'}</div>
    <div style="flex:1">
      <div class="ach-popup-title" style="color:${rarity.color}">✨ Achievement Unlocked!</div>
      <div class="ach-popup-name">${_esc(ach.name)}</div>
      <div class="ach-popup-rewards" style="color:var(--text-muted)">${hasRewards ? 'Tap to claim rewards →' : 'View in Achievements'}</div>
    </div>
    <div style="width:8px;height:8px;border-radius:50%;background:${rarity.color};box-shadow:0 0 8px ${rarity.color};flex-shrink:0;margin-top:4px;animation:achBadgePulse 1.5s ease-in-out infinite"></div>`;

  d.addEventListener('click', () => {
    d.style.animation = 'achPopOut .4s ease forwards';
    setTimeout(() => { d.remove(); navTo('s-badges'); }, 400);
  });
  document.body.appendChild(d);
  setTimeout(() => {
    if (d.parentNode) { d.style.animation = 'achPopOut .4s ease forwards'; setTimeout(() => d.remove(), 400); }
  }, 4500);
};

// ── Trigger-hook patches ──────────────────────────────────────────────────────
// These replace the monolith's patch IIFEs. Each wraps an existing global.

// finishQuiz → achCheckAndAward: now handled by the dedicated
// 'ach-engine-quiz-finished' subscriber below (not folded into the shared
// 'ach-engine-state-sync' handler — that one hardcodes suppressPopup=true,
// but a quiz is the student's own foreground action, so the original patch
// left the popup showing. Folding this in would have silently killed it.)

// logAttendance → achCheckAndAward: this patch was dead code, not a live
// conversion target. Nothing in the codebase calls logAttendance() (grepped
// the whole repo — zero hits outside this file) or emits 'attendance:logged'
// (same — zero hits). The real, live attendance system
// (modules/attendance/attendance-service.js) uses a completely different
// event name, 'attendance:scan-recorded', which this patch never hooked —
// attendance-triggered achievement checks were silently non-functional,
// likely since attendance moved to RFID scanning and this patch was never
// updated to match. That gap is now closed: see the pub/sub subscriber
// below, which watches 'attendance:scan-recorded'/'attendance:override'.

// logRecitation → achCheckAndAward: now handled entirely by the
// AppStore.subscribe('ach-engine-state-sync', ...) pub/sub handler below,
// which watches 'recitation:logged' (see logger.js's AppStore.updateState()
// call). The monkey-patch that used to live here duplicated that handler —
// both fired achCheckAndAward(sid, true) on every recitation log. Removed
// as part of the Event-Driven Communication phase (roadmap Phase 4).

// wbcApplyDamage → achCheckAndAward, per hit: this used to be a monkey-patch
// that NEVER ACTUALLY RAN — index.html loads ach_engine.js (807) before
// combat-settings.js (853), so by the time this patch's IIFE captured
// `_orig = window.wbcApplyDamage`, nothing had defined it yet (_orig was
// undefined). combat-settings.js then OVERWRITES window.wbcApplyDamage
// outright (it doesn't chain via _orig), silently discarding this patch for
// good. Net effect: boss_damage/boss_crits achievements — the two trigger
// types that are running totals crossable on ANY hit, not just a kill —
// never got checked until some unrelated trigger happened to fire later.
// Restored here as a real subscriber on the events wbcApplyDamage actually
// emits (see combat-settings.js's own AppStore.updateState() call), on both
// a normal hit and the killing blow — a crit landed as the finishing hit
// should still count toward boss_crits. No suppressPopup, matching the
// original patch and the finishQuiz/session-booted precedent: dealing damage
// in a live raid is the student's own real-time action.
AppStore.subscribe('ach-engine-boss-damage', function (state, event) {
  if (event.type !== 'world-boss:damage-applied' && event.type !== 'world-boss:defeated') return;
  const studentId = event.payload && event.payload.studentId;
  if (studentId) setTimeout(() => achCheckAndAward(studentId), 400);
});

// session:booted → achCheckAndAward: dedicated subscriber, not folded into
// the shared 'ach-engine-state-sync' one — this patch never passed
// suppressPopup, so a login that pushes a student over an achievement
// threshold shows the unlock popup (matches the finishQuiz precedent above).
AppStore.subscribe('ach-engine-session-booted', function (state, event) {
  if (event.type !== 'session:booted') return;
  if (getCurrentRole() === 'student' && getCurrentUser()) {
    setTimeout(() => achCheckAndAward(getCurrentUser().id), 400);
  }
});

console.log('[EduQuest] achievements/engine.js loaded — ACH_RARITY, achBuildStats, achCheckAndAward, achGrantRewardsForClaim, achUpdateSidebarBadge, achShowUnlockPopup registered. Trigger hooks patched.');

// ── Pub/Sub: Cross-module reactivity ─────────────────────────────────────────
AppStore.subscribe('ach-engine-state-sync', function (state, event) {
  const watchedEvents = [
    'recitation:logged',
    'loot:claimed',
    'xp:awarded',
    'state:legacy-sync',
    // Fills the gap left by the removed dead logAttendance patch — these are
    // the real, live events attendance-service.js emits for the two
    // attendance-based achievement trigger types (attendance_present,
    // attendance_pct). attendance:session-closed is deliberately NOT
    // watched: it's a bulk absence-sweep, and marking someone absent can
    // only decrease those stats, never newly cross an unlock threshold —
    // checking there would be a guaranteed no-op every time.
    'attendance:scan-recorded',
    'attendance:override',
  ];
  if (!watchedEvents.includes(event.type)) return;

  // A duplicate re-scan (student already logged today) changed nothing —
  // skip the check rather than fire it for no reason.
  if (event.type === 'attendance:scan-recorded' && event.payload && event.payload.alreadyRecorded) return;

  const studentId = event.payload && event.payload.studentId;
  if (studentId && typeof achCheckAndAward === 'function') {
    setTimeout(function () { achCheckAndAward(studentId, true); }, 400);
  }
  if (typeof achUpdateSidebarBadge === 'function') achUpdateSidebarBadge();
});

// Separate from the subscriber above on purpose — see the comment where the
// old finishQuiz monkey-patch used to live. Same 500ms delay and
// suppressPopup left at its default (shows the unlock popup) as the
// original patch had.
AppStore.subscribe('ach-engine-quiz-finished', function (state, event) {
  if (event.type !== 'quiz:finished') return;
  const studentId = event.payload && event.payload.studentId;
  if (studentId && typeof achCheckAndAward === 'function') {
    setTimeout(function () { achCheckAndAward(studentId); }, 500);
  }
});


/* ---- ./modules/achievements/ach_student_page.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/achievements/student-page.js
//  Student Achievements (Badges) page: renderBadges, achClaimReward.
//
//  DEPENDENCY: ACH_RARITY, ACH_RARITIES, ACH_TRIGGER_TYPES, achRarityClass,
//              achGrantRewardsForClaim, achUpdateSidebarBadge (engine.js).
//              eqRewardPresent — typeof guard (reward presenter module).
//              tsUnlockTitleForStudent — typeof guard (titles module, Day 8).
// ═══════════════════════════════════════════════════════════════════════════════

// Module-level filter/search state (mirrors window.* used by onclick handlers)
// Note: these are read/written via window._achTab etc in onclick strings.

/**
 * renderBadges() → void  [window.renderBadges]
 *
 * Renders the student "Achievements" page into #s-badges.
 * Reads filter state from: window._achTab, window._achFilter,
 *                          window._achRarityFilter, window._achSearch
 *
 * Tabs: All Badges | 🎁 Unclaimed | ✅ Claimed | 🔒 Locked
 * Filters: category tabs, rarity tabs, search input
 * Each .ach-badge-card shows: rarity strip, icon, name, rarity tag, desc,
 *   unclaimed → CLAIM button; claimed → stamp + reward chips; locked → greyed rewards
 *
 * Calls achUpdateSidebarBadge() after render.
 */
window.renderBadges = function () {
  const st = currentUser;
  if (!st) return;

  const unlocks     = (AppStore.getSlice(s => s.achievementUnlocks) || {})[st.id] || [];
  const unlockedIds = new Set(unlocks.map(u => u.achId));

  // Phase 16 (closing the deferred gap noted in ach_admin_page.js): a badge
  // with no rows in achievementSectionAssignments is unassigned → visible to
  // everyone, same "opt-in scoping" semantics as everywhere else sections
  // gate content in this app. A badge assigned to one or more sections is
  // only shown to students in one of those sections. Already-unlocked badges
  // stay visible regardless (an assignment change after the fact shouldn't
  // make an earned badge disappear from a student's own collection).
  const sectionAssignments = AppStore.getSlice(s => s.achievementSectionAssignments) || {};
  const myClassId          = st.classId || 'default-class';
  const inMySection = (ach) => {
    const assigned = sectionAssignments[ach.id];
    return !assigned || assigned.length === 0 || assigned.includes(myClassId);
  };

  const allAchs     = (AppStore.getSlice(s => s.achievements) || []).filter(a => a.active && (inMySection(a) || unlockedIds.has(a.id)));
  const visibleAchs = allAchs.filter(a => !a.isHidden || unlockedIds.has(a.id));
  const earned      = allAchs.filter(a => unlockedIds.has(a.id));

  const unclaimedAchs = earned.filter(a => { const u = unlocks.find(x => x.achId === a.id); return u && !u.claimed; });
  const claimedAchs   = earned.filter(a => { const u = unlocks.find(x => x.achId === a.id); return u &&  u.claimed; });
  const completionPct = allAchs.length ? Math.round(earned.length / allAchs.length * 100) : 0;

  const rarityOrder = ['Mythic', 'Legendary', 'Epic', 'Rare', 'Uncommon', 'Common'];
  let rarestBadge = null;
  for (const r of rarityOrder) { const f = earned.find(a => a.rarity === r); if (f) { rarestBadge = f; break; } }

  const activeFilter = window._achFilter       || 'all';
  const activeRarity = window._achRarityFilter || 'all';
  const activeTab    = window._achTab           || 'all';
  const searchQ      = (window._achSearch       || '').toLowerCase();

  let displayed = visibleAchs;
  if (activeFilter !== 'all') displayed = displayed.filter(a => a.category === activeFilter);
  if (activeRarity !== 'all') displayed = displayed.filter(a => a.rarity   === activeRarity);
  if (searchQ)                displayed = displayed.filter(a => a.name.toLowerCase().includes(searchQ) || (a.description || '').toLowerCase().includes(searchQ));
  if (activeTab === 'unclaimed') displayed = displayed.filter(a => unclaimedAchs.some(u => u.id === a.id));
  else if (activeTab === 'claimed') displayed = displayed.filter(a => claimedAchs.some(u => u.id === a.id));
  else if (activeTab === 'locked')  displayed = displayed.filter(a => !unlockedIds.has(a.id));

  const categories = [...new Set(allAchs.map(a => a.category).filter(Boolean))];
  const catTabs    = [{ key: 'all', label: 'All' }, ...categories.map(c => ({ key: c, label: c }))];
  const rarityTabs = [{ key: 'all', label: 'All Rarities' }, ...ACH_RARITIES.map(r => ({ key: r, label: r }))];

  document.getElementById('s-badges').innerHTML = `
  <div class="page-hero"><div class="page-hero-bg"></div><div style="position:relative;z-index:1">
    <div class="page-hero-label">🏅 Achievements</div>
    <h1 style="font-family:var(--fh);font-size:32px;font-weight:900;color:var(--on-surface);margin-bottom:8px">Your Achievements</h1>
    <p style="font-size:14px;color:var(--text-muted)"><span style="color:var(--tertiary);font-weight:700">${earned.length}</span> / ${allAchs.length} badges unlocked</p>
  </div></div>

  ${unclaimedAchs.length > 0 ? `
  <div style="background:linear-gradient(135deg,rgba(208,188,255,0.12),rgba(139,92,246,0.08));border:1px solid rgba(208,188,255,0.3);border-radius:16px;padding:18px 20px;margin-bottom:24px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap">
    <div style="display:flex;align-items:center;gap:14px">
      <div style="width:44px;height:44px;border-radius:12px;background:rgba(208,188,255,0.15);border:1px solid rgba(208,188,255,0.3);display:flex;align-items:center;justify-content:center;font-size:22px;animation:achBadgePulse 2s ease-in-out infinite">🎁</div>
      <div>
        <div style="font-family:var(--fh);font-size:15px;font-weight:900;color:var(--primary)">${unclaimedAchs.length} Reward${unclaimedAchs.length > 1 ? 's' : ''} Ready to Claim</div>
        <div style="font-size:12px;color:var(--text-muted);margin-top:3px">Claim your achievement rewards before they expire!</div>
      </div>
    </div>
    <button class="btn btn-primary" onclick="window._achTab='unclaimed';renderBadges()" style="background:linear-gradient(135deg,#8b5cf6,#6d28d9)">🎁 View Unclaimed</button>
  </div>` : ''}

  <div class="ach-stats-bar">
    <div class="ach-stat-card"><div class="ach-stat-val" style="color:var(--primary)">${earned.length}</div><div class="ach-stat-lbl">Earned</div></div>
    <div class="ach-stat-card"><div class="ach-stat-val" style="color:${unclaimedAchs.length > 0 ? '#EC4899' : 'var(--secondary)'}"><span style="animation:${unclaimedAchs.length > 0 ? 'achBadgePulse 2s ease-in-out infinite' : 'none'};display:inline-block">${unclaimedAchs.length}</span></div><div class="ach-stat-lbl">Unclaimed</div></div>
    <div class="ach-stat-card"><div class="ach-stat-val" style="color:var(--secondary)">${completionPct}%</div><div class="ach-stat-lbl">Completion</div></div>
    <div class="ach-stat-card"><div class="ach-stat-val">${rarestBadge ? `<span style="font-size:18px">${rarestBadge.icon}</span>` : '<span style="color:var(--text-muted)">—</span>'}</div><div class="ach-stat-lbl">Rarest Badge</div></div>
  </div>

  <!-- STATUS TABS -->
  <div style="display:flex;gap:0;border-bottom:1px solid var(--border);margin-bottom:20px;overflow-x:auto">
    ${[
      { key: 'all',      label: 'All Badges',    count: allAchs.length },
      { key: 'unclaimed',label: '🎁 Unclaimed',  count: unclaimedAchs.length, accent: unclaimedAchs.length > 0 },
      { key: 'claimed',  label: '✅ Claimed',     count: claimedAchs.length },
      { key: 'locked',   label: '🔒 Locked',      count: allAchs.length - earned.length },
    ].map(t => `<button class="ach-filter-btn ${activeTab === t.key ? 'active' : ''}" style="padding:10px 16px;border-radius:0;border-bottom:2px solid ${activeTab === t.key ? (t.accent ? '#EC4899' : 'var(--primary-dark)') : 'transparent'};background:none;${activeTab === t.key && t.accent ? 'color:#EC4899' : ''}" onclick="window._achTab='${t.key}';renderBadges()">
      ${t.label}${t.count > 0 ? ` <span style="font-size:10px;padding:1px 6px;border-radius:8px;background:rgba(255,255,255,.08);margin-left:4px">${t.count}</span>` : ''}
    </button>`).join('')}
  </div>

  <div class="section-header"><span class="material-symbols-outlined">workspace_premium</span><h2>Badge Collection</h2></div>
  <div class="ach-filter-bar">
    <input class="ach-search-input" type="text" placeholder="🔍 Search badges..." value="${_esc(window._achSearch || '')}" oninput="window._achSearch=this.value;renderBadges()" style="max-width:200px">
    <div style="display:flex;gap:6px;flex-wrap:wrap">${catTabs.map(t => `<button class="ach-filter-btn${activeFilter === t.key ? ' active' : ''}" onclick="window._achFilter='${t.key}';renderBadges()">${_esc(t.label)}</button>`).join('')}</div>
    <div style="display:flex;gap:6px;flex-wrap:wrap">${rarityTabs.map(t => `<button class="ach-filter-btn${activeRarity === t.key ? ' active' : ''}" style="font-size:10px" onclick="window._achRarityFilter='${t.key}';renderBadges()">${_esc(t.label)}</button>`).join('')}</div>
  </div>

  ${displayed.length === 0 ? '<div style="text-align:center;color:var(--text-muted);padding:60px 0;font-size:14px">No badges found for these filters.</div>' : ''}
  <div class="badges-grid">
    ${displayed.map(ach => {
      const isUnlocked  = unlockedIds.has(ach.id);
      const unlockRec   = unlocks.find(u => u.achId === ach.id);
      const isClaimed   = unlockRec && unlockRec.claimed;
      const isUnclaimed = isUnlocked && !isClaimed;
      const rarity      = ACH_RARITY[ach.rarity] || ACH_RARITY.Common;
      const isHiddenLocked = ach.isHidden && !isUnlocked;
      const rewardChips = (
        ((ach.xpReward   || 0) > 0 ? `<span class="ach-reward-chip" style="color:#c4b5fd;border-color:rgba(196,181,253,${isUnlocked ? '0.3' : '0.15'})">+${ach.xpReward} XP</span>` : '') +
        ((ach.coinReward || 0) > 0 ? `<span class="ach-reward-chip" style="color:#ffb95f;border-color:rgba(255,185,95,${isUnlocked ? '0.3' : '0.15'})">+${ach.coinReward} 🪙</span>` : '')
      );
      return `<div class="ach-badge-card ${isUnclaimed ? 'ach-unclaimed ' : isUnlocked ? '' : 'ach-locked ' + (isHiddenLocked ? 'ach-hidden-locked' : '')}" style="${isUnlocked ? `box-shadow:0 0 20px ${rarity.glow}${isUnclaimed ? ',0 0 0 2px ' + rarity.color + '66' : ''};border-color:${rarity.color}${isUnclaimed ? '' : '44'}` : ''}" title="${isHiddenLocked ? '???' : _esc(ach.description)}">
        <div class="ach-rarity-strip" style="background:${rarity.strip}"></div>
        ${isUnclaimed ? `<div class="ach-unclaimed-glow" style="background:radial-gradient(circle at 50% 0%,${rarity.color}22,transparent 70%)"></div>` : ''}
        <div class="ach-badge-icon-wrap">${isHiddenLocked ? '❓' : (ach.icon || '🏅')}</div>
        <div class="ach-badge-title ${achRarityClass(ach.rarity)}">${isHiddenLocked ? 'Hidden Achievement' : _esc(ach.name)}</div>
        <span class="ach-rarity-tag ${achRarityClass(ach.rarity)}">${ach.rarity}</span>
        ${isHiddenLocked
          ? '<div class="ach-badge-desc">Complete certain actions to reveal...</div>'
          : `<div class="ach-badge-desc">${_esc(ach.description || '')}</div>`}
        ${isUnclaimed
          ? `<div class="ach-unclaimed-label">🎁 READY TO CLAIM</div>
             <div class="ach-reward-chips">${rewardChips}</div>
             <button class="ach-claim-btn" onclick="achClaimReward('${ach.id}')" style="background:linear-gradient(135deg,${rarity.strip},${rarity.color})">Claim Reward →</button>`
          : isUnlocked
          ? `<div class="ach-unlocked-stamp">✓ CLAIMED ${new Date(unlockRec.claimedAt || unlockRec.unlockedAt).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' })}</div>
             <div class="ach-reward-chips">${rewardChips}</div>`
          : `<div class="ach-reward-chips">${rewardChips}</div>`}
      </div>`;
    }).join('')}
  </div>`;

  achUpdateSidebarBadge();
};

// ── Claim reward ──────────────────────────────────────────────────────────────

/**
 * achClaimReward(achId) → void  [window.achClaimReward]
 *
 * Student-facing claim action. Guards: must be student + achievement must be unclaimed.
 * If eqRewardPresent is available, shows the Universal Reward Presentation.
 * Otherwise falls back to toast + renderBadges().
 * Calls tsUnlockTitleForStudent for any linked title (typeof guard).
 * Calls renderStudentDashboard after close (typeof guard).
 */
window.achClaimReward = function (achId) {
  if (!currentUser || currentRole !== 'student') return;
  const ach      = (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId);
  if (!ach) return;
  const unlocks  = (AppStore.getSlice(s => s.achievementUnlocks) || {})[currentUser.id] || [];
  const rec      = unlocks.find(u => u.achId === achId);
  if (!rec || rec.claimed) { toast('This achievement has already been claimed.', '#ffb4ab'); return; }

  // Fallback: no reward presenter yet
  const _present = typeof eqRewardPresent === 'function' ? eqRewardPresent
                 : typeof window.eqRewardPresent === 'function' ? window.eqRewardPresent
                 : null;
  if (!_present) {
    achGrantRewardsForClaim(currentUser.id, achId);
    toast('🏅 ' + _esc(ach.name) + ' claimed!', '#d0bcff');
    renderBadges();
    return;
  }

  // Build reward list
  const rewards = [];
  if ((rec.xpGranted   || 0) > 0) rewards.push({ type: 'xp',    amount: rec.xpGranted,   icon: '⚡',          label: 'XP',    color: 'var(--primary)'  });
  if ((rec.coinsGranted|| 0) > 0) rewards.push({ type: 'coins', amount: rec.coinsGranted, icon: '🪙',          label: 'Coins', color: 'var(--tertiary)' });

  // Check for linked title
  const linkedTitle = (AppStore.getSlice(s => s.titles) || []).find(t => t.achievementId === achId && t.active);
  if (linkedTitle) rewards.push({ type: 'title', amount: 1, icon: linkedTitle.icon || '🎖️', label: linkedTitle.name, color: '#EC4899', titleId: linkedTitle.id });

  // Grant rewards
  const granted = achGrantRewardsForClaim(currentUser.id, achId);
  if (granted === false) return;

  // Grant linked title — typeof guard (titles module, Day 8)
  if (linkedTitle && typeof tsUnlockTitleForStudent === 'function') {
    tsUnlockTitleForStudent(currentUser.id, linkedTitle.id, false);
  }

  _present({
    title:    'Achievement Claimed!',
    subtitle: ach.name,
    icon:     ach.icon || '🏅',
    rarity:   ach.rarity || 'Common',
    source:   'achievement',
    rewards,
    onClose: () => {
      renderBadges();
      if (typeof renderStudentDashboard === 'function') renderStudentDashboard();
    },
  });
};

console.log('[EduQuest] achievements/student-page.js loaded — renderBadges, achClaimReward registered.');


/* ---- ./modules/achievements/ach_admin_page.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/achievements/admin-page.js
//  Admin Achievement Management: list, create/edit, toggle, duplicate, delete,
//  preview, grant/revoke, and category management.
// ═══════════════════════════════════════════════════════════════════════════════

// Phase 16 — selected class_ids for the create/edit form's "assign to
// section(s)" picker. Kept separate from the form fields read directly off
// the DOM in achAdminSave(), since a <select multiple>'s value isn't read
// via a single .value the way every other field here is; set on open,
// updated via onchange, read back in achAdminSave().
let draftAchSections = [];

/**
 * renderAdminAchievements() → void  [window.renderAdminAchievements]
 * Renders the admin "Badge & Achievement Engine" page into #a-achievements.
 * Shows stats bar, full achievement table with unlock counts, action buttons.
 */
window.renderAdminAchievements = function () {
  const achs          = AppStore.getSlice(s => s.achievements) || [];
  const cats          = AppStore.getSlice(s => s.achievementCategories) || [];
  const totalStudents = (AppStore.getSlice(s => s.students) || []).length;
  const achievementUnlocks = AppStore.getSlice(s => s.achievementUnlocks) || {};
  const achievementSectionAssignments = AppStore.getSlice(s => s.achievementSectionAssignments) || {};
  const unlockCounts  = {};
  Object.values(achievementUnlocks).forEach(list => {
    list.forEach(u => { unlockCounts[u.achId] = (unlockCounts[u.achId] || 0) + 1; });
  });

  document.getElementById('a-achievements').innerHTML = `
  <div class="page-hero"><div class="page-hero-bg"></div>
    <div style="position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px">
      <div>
        <div class="page-hero-label">🏅 Achievement Management</div>
        <h1 style="font-family:var(--fh);font-size:28px;font-weight:900;color:var(--on-surface);margin-bottom:6px">Badge &amp; Achievement Engine</h1>
        <p style="font-size:13px;color:var(--text-muted)">${achs.length} total badges · ${achs.filter(a => a.active).length} active</p>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn btn-ghost btn-sm" onclick="achAdminManageCategories()">🗂 Categories</button>
        <button class="btn btn-ghost btn-sm" onclick="achAdminGrantAchievement()">🎁 Grant/Revoke</button>
        <button class="btn btn-primary" onclick="achAdminOpenForm(null)">+ Create Badge</button>
      </div>
    </div>
  </div>

  <div class="ach-stats-bar" style="margin-bottom:20px">
    <div class="ach-stat-card"><div class="ach-stat-val" style="color:var(--primary)">${achs.length}</div><div class="ach-stat-lbl">Total Badges</div></div>
    <div class="ach-stat-card"><div class="ach-stat-val" style="color:var(--secondary)">${achs.filter(a => a.active).length}</div><div class="ach-stat-lbl">Active</div></div>
    <div class="ach-stat-card"><div class="ach-stat-val" style="color:#ffb95f">${achs.filter(a => a.isHidden).length}</div><div class="ach-stat-lbl">Hidden</div></div>
    <div class="ach-stat-card"><div class="ach-stat-val" style="color:#f472b6">${Object.values(achievementUnlocks).reduce((a, l) => a + l.length, 0)}</div><div class="ach-stat-lbl">Total Unlocks</div></div>
  </div>

  ${achs.length === 0 ? `
  <div style="text-align:center;padding:60px 20px;color:var(--text-muted)">
    <div style="font-size:48px;margin-bottom:12px">🏅</div>
    <div style="font-size:16px;font-weight:700;color:var(--on-surface);margin-bottom:8px">No achievements yet</div>
    <div style="font-size:13px;margin-bottom:20px">Create your first badge to start the achievement engine.</div>
    <button class="btn btn-primary" onclick="achAdminOpenForm(null)">+ Create First Badge</button>
  </div>` : `
  <div style="background:rgba(255,255,255,0.03);border:1px solid var(--border);border-radius:16px;overflow:hidden">
    <table class="ach-admin-table">
      <thead><tr><th>Badge</th><th>Category</th><th>Rarity</th><th>Trigger</th><th>Rewards</th><th>Unlocks</th><th>Status</th><th style="text-align:right">Actions</th></tr></thead>
      <tbody>${achs.map(ach => {
        const rarity       = ACH_RARITY[ach.rarity] || ACH_RARITY.Common;
        const triggerDef   = ACH_TRIGGER_TYPES.find(t => t.value === ach.triggerType) || { label: ach.triggerType || '—' };
        const unlockCount  = unlockCounts[ach.id] || 0;
        const pct          = totalStudents ? Math.round(unlockCount / totalStudents * 100) : 0;
        // Phase 16: section scoping is now live (see achAdminOpenForm's NOTE
        // and student-page.js/engine.js), so surface it here the same way
        // quiz-builder.js's list rows surface quiz section assignment.
        const assignedIds   = achievementSectionAssignments[ach.id] || [];
        const sectionsLabel = assignedIds.length
          ? assignedIds.map(cid => (typeof getClassLabel === 'function' ? getClassLabel(cid) : cid)).join(', ')
          : 'All sections';
        return `<tr>
          <td><div style="display:flex;align-items:center;gap:10px"><span style="font-size:24px">${ach.icon || '🏅'}</span><div><div style="font-weight:700;color:var(--on-surface);font-size:13px">${_esc(ach.name)}${ach.isHidden ? ' <span style="font-size:9px;opacity:.6">🔒 HIDDEN</span>' : ''}</div><div style="font-size:10px;color:var(--text-muted);max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_esc(ach.description || '')}</div><span class="badge-pill ${assignedIds.length ? 'bp-primary' : 'bp-gray'}" style="font-size:9px;margin-top:4px;display:inline-block" title="${_esc(sectionsLabel)}">🏫 ${assignedIds.length ? _esc(sectionsLabel) : 'All sections'}</span></div></div></td>
          <td><span style="font-size:11px;color:var(--text-muted)">${_esc(ach.category || '—')}</span></td>
          <td><span class="ach-rarity-tag ${achRarityClass(ach.rarity)}" style="font-size:9px">${ach.rarity}</span></td>
          <td><span style="font-size:11px;color:var(--text-muted)">${_esc(triggerDef.label)}${ach.triggerType !== 'manual' && ach.triggerType !== 'all_quests' ? ' ≥ ' + (ach.triggerValue || 0) : ''}</span></td>
          <td><div style="font-size:11px">${(ach.xpReward || 0) > 0 ? `<span style="color:#c4b5fd">+${ach.xpReward} XP</span> ` : ''}${(ach.coinReward || 0) > 0 ? `<span style="color:#ffb95f">+${ach.coinReward}🪙</span>` : ''}${!ach.xpReward && !ach.coinReward ? '<span style="color:var(--text-muted)">None</span>' : ''}</div></td>
          <td><div style="font-size:12px;font-weight:700;color:${rarity.color}">${unlockCount}<span style="color:var(--text-muted);font-weight:400">/${totalStudents}</span></div><div style="font-size:9px;color:var(--text-muted)">${pct}%</div></td>
          <td><span class="${ach.active ? 'badge-pill bp-green' : 'badge-pill bp-red'}" style="font-size:9px">${ach.active ? 'Active' : 'Disabled'}</span></td>
          <td style="text-align:right"><div style="display:flex;gap:5px;justify-content:flex-end;flex-wrap:wrap">
            <button class="btn btn-ghost btn-xs" onclick="achAdminPreview('${ach.id}')" title="Preview">👁</button>
            <button class="btn btn-ghost btn-xs" onclick="achAdminOpenForm('${ach.id}')" title="Edit">✏️</button>
            <button class="btn btn-ghost btn-xs" onclick="achAdminDuplicate('${ach.id}')" title="Duplicate">⧉</button>
            <button class="ach-toggle-btn" style="border-color:${ach.active ? 'rgba(255,128,128,0.3)' : 'rgba(78,222,163,0.3)'};color:${ach.active ? '#ff8080' : '#4edea3'}" onclick="achAdminToggle('${ach.id}')">${ach.active ? 'Disable' : 'Enable'}</button>
            <button class="btn btn-ghost btn-xs" style="color:#ff8080" onclick="achAdminDelete('${ach.id}')" title="Delete">🗑</button>
          </div></td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`}`;

  // Continuation Plan §3, Category A — replaces titles_admin_page.js's
  // renderAdminAchievements monkey-patch (single confirmed site, load-order
  // traced: this file loads at index.html:809, the patch's file at :816,
  // and nothing re-assigns window.renderAdminAchievements after that).
  // DOM-injection post-hook, void return — straightforward conversion.
  // Uses emit() rather than updateState(): this is pure page rendering,
  // never mutates DB.*.
  AppStore.emit({ type: 'admin:achievements-rendered', payload: null });
};

// ── Create / Edit form ────────────────────────────────────────────────────────

window.achAdminOpenForm = function (achId) {
  const isEdit   = !!achId;
  const existing = isEdit ? (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId) : null;
  const cats     = AppStore.getSlice(s => s.achievementCategories) || [];
  const d        = existing || {
    name: '', description: '', icon: '🏅', category: cats[0] || 'Quests',
    rarity: 'Common', xpReward: 50, coinReward: 25,
    isHidden: false, active: true, triggerType: 'quests_completed', triggerValue: 1,
  };

  // Phase 16: pre-generate the id for brand-new badges (same trick
  // quiz-builder.js's draftQuiz.id uses) so the "assign to section(s)"
  // picker below has a stable achievement_id to persist against via
  // set_achievement_sections() the moment the badge is first saved,
  // instead of needing a second round-trip after creation.
  const formAchId = achId || uid();
  draftAchSections = ((AppStore.getSlice(s => s.achievementSectionAssignments) || {})[formAchId] || []).slice();

  // Phase 16: "assign to section(s)" picker — set_achievement_sections()
  // RPC and the achievement_sections junction table have existed since
  // this phase's SQL shipped, but nothing in the admin UI called it yet.
  // Mirrors quiz-builder.js's picker exactly, same sections source
  // (getActiveClassIds/getClassLabel from sections-service.js).
  //
  // NOTE on visibility: this wires the WRITE side (persisting which
  // section(s) a badge is assigned to, synced cross-device via Supabase).
  // The READ side is now wired too — renderBadges() (student-page.js) and
  // achCheckAndAward() (engine.js) both filter/gate on the
  // achievementSectionAssignments slice, so assigning sections here does
  // actually scope who can see and auto-unlock the badge. An achievement
  // with no assigned sections stays global (visible/unlockable by
  // everyone) — assigning it here is what opts it into section scoping.
  // quiz-builder.js's equivalent picker still has its matching read-side
  // gap open for renderStudentQuizzes(); that's a separate, not-yet-done
  // piece of work.
  const activeClassIds = (typeof getActiveClassIds === 'function') ? getActiveClassIds() : [];
  const sectionOpts = activeClassIds.map(cid =>
    `<option value="${cid}" ${draftAchSections.includes(cid) ? 'selected' : ''}>${_esc(typeof getClassLabel === 'function' ? getClassLabel(cid) : cid)}</option>`
  ).join('');

  showModal(`
  <div style="max-width:520px">
    <h2 style="font-family:var(--fh);font-size:20px;font-weight:900;margin-bottom:20px">${isEdit ? 'Edit' : 'Create'} Badge</h2>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">
      <div style="grid-column:1/-1"><label class="form-label">Badge Name *</label><input id="ach-f-name" class="form-control" type="text" placeholder="e.g. Quest Warrior" value="${_esc(d.name || '')}" style="width:100%"></div>
      <div style="grid-column:1/-1"><label class="form-label">Description *</label><input id="ach-f-desc" class="form-control" type="text" placeholder="Describe how to earn this badge" value="${_esc(d.description || '')}" style="width:100%"></div>
      <div><label class="form-label">Icon (Emoji)</label><input id="ach-f-icon" class="form-control" type="text" placeholder="🏅" value="${_esc(d.icon || '🏅')}" style="width:100%;font-size:18px"></div>
      <div><label class="form-label">Rarity</label><select id="ach-f-rarity" class="form-control" style="width:100%">${ACH_RARITIES.map(r => `<option value="${r}"${d.rarity === r ? ' selected' : ''}>${r}</option>`).join('')}</select></div>
      <div><label class="form-label">Category</label><select id="ach-f-cat" class="form-control" style="width:100%">${cats.map(c => `<option value="${_esc(c)}"${d.category === c ? ' selected' : ''}>${_esc(c)}</option>`).join('')}</select></div>
      <div><label class="form-label">XP Reward</label><input id="ach-f-xp" class="form-control" type="number" min="0" value="${d.xpReward || 0}" style="width:100%"></div>
      <div><label class="form-label">Coin Reward 🪙</label><input id="ach-f-coins" class="form-control" type="number" min="0" value="${d.coinReward || 0}" style="width:100%"></div>
      <div><label class="form-label">Trigger Type</label><select id="ach-f-trigger" class="form-control" style="width:100%" onchange="achAdminUpdateTriggerHint()">${ACH_TRIGGER_TYPES.map(t => `<option value="${t.value}"${d.triggerType === t.value ? ' selected' : ''}>${t.label}</option>`).join('')}</select></div>
      <div><label class="form-label">Trigger Value</label><input id="ach-f-tval" class="form-control" type="number" min="0" value="${d.triggerValue || 1}" style="width:100%"><div id="ach-trigger-hint" style="font-size:10px;color:var(--text-muted);margin-top:3px">${ACH_TRIGGER_TYPES.find(t => t.value === d.triggerType)?.hint || ''}</div></div>
      <div style="grid-column:1/-1;display:flex;gap:20px">
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px"><input type="checkbox" id="ach-f-hidden" ${d.isHidden ? 'checked' : ''} style="width:16px;height:16px"> Hidden Achievement <span style="font-size:11px;color:var(--text-muted)">(Students can't see until unlocked)</span></label>
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px"><input type="checkbox" id="ach-f-active" ${d.active !== false ? 'checked' : ''} style="width:16px;height:16px"> Active</label>
      </div>
      <div style="grid-column:1/-1">
        <label class="form-label">Assign to Section(s)</label>
        ${activeClassIds.length ? `
        <select id="ach-f-sections" multiple style="width:100%;height:96px" onchange="updateDraftAchSections(this)">${sectionOpts}</select>
        <div style="font-size:11px;color:var(--text-muted);margin-top:4px">Hold Ctrl/Cmd to select multiple. Leave empty to leave unassigned (visible to all).</div>
        ` : `
        <div style="font-size:12px;color:var(--text-muted);background:rgba(35,31,56,.5);border-radius:8px;padding:10px 12px">No sections created yet — create one in Section Maker first.</div>
        `}
      </div>
    </div>
    <div id="ach-form-err" style="color:#ff8080;font-size:12px;margin-top:8px;display:none"></div>
    <div style="display:flex;gap:10px;margin-top:20px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button>
      <button class="btn btn-primary" style="flex:1" onclick="achAdminSave('${formAchId}')">${isEdit ? 'Save Changes' : 'Create Badge'}</button>
    </div>
  </div>`, 'md');
};

window.updateDraftAchSections = function (selectEl) {
  draftAchSections = [...selectEl.selectedOptions].map(o => o.value);
};

window.achAdminUpdateTriggerHint = function () {
  const sel  = document.getElementById('ach-f-trigger');
  const hint = document.getElementById('ach-trigger-hint');
  if (sel && hint) { const t = ACH_TRIGGER_TYPES.find(tt => tt.value === sel.value); hint.textContent = t?.hint || ''; }
};

window.achAdminSave = async function (achId) {
  const name        = (document.getElementById('ach-f-name')?.value    || '').trim();
  const desc        = (document.getElementById('ach-f-desc')?.value    || '').trim();
  const icon        = (document.getElementById('ach-f-icon')?.value    || '🏅').trim();
  const cat         = document.getElementById('ach-f-cat')?.value      || 'Quests';
  const rarity      = document.getElementById('ach-f-rarity')?.value   || 'Common';
  const xpReward    = parseInt(document.getElementById('ach-f-xp')?.value)     || 0;
  const coinReward  = parseInt(document.getElementById('ach-f-coins')?.value)  || 0;
  const triggerType = document.getElementById('ach-f-trigger')?.value  || 'quests_completed';
  const triggerValue = parseFloat(document.getElementById('ach-f-tval')?.value) || 1;
  const isHidden    = document.getElementById('ach-f-hidden')?.checked  || false;
  const active      = document.getElementById('ach-f-active')?.checked !== false;
  const errEl       = document.getElementById('ach-form-err');

  if (!name) { if (errEl) { errEl.textContent = 'Badge name is required.'; errEl.style.display = 'block'; } return; }
  if (!desc) { if (errEl) { errEl.textContent = 'Description is required.'; errEl.style.display = 'block'; } return; }
  if (errEl) errEl.style.display = 'none';

  let toastMsg;
  AppStore.updateState(draft => {
    if (!Array.isArray(draft.achievements)) draft.achievements = [];
    const idx = draft.achievements.findIndex(a => a.id === achId);
    if (idx >= 0) {
      draft.achievements[idx] = { ...draft.achievements[idx], name, description: desc, icon, category: cat, rarity, xpReward, coinReward, isHidden, active, triggerType, triggerValue };
      toastMsg = `✅ Badge "${name}" updated!`;
    } else {
      // achId was pre-generated by achAdminOpenForm (Phase 16) so the section
      // picker has a stable id to save against on first creation too.
      // Phase 32: stamp the owner so the catalog isolation RLS/RPC checks
      // have something to key against — mirrors shop_admin_store.js's
      // doAddProduct() stamping ownerTeacherId at creation time.
      draft.achievements.push({ id: achId, ownerTeacherId: currentUser.id, name, description: desc, icon, category: cat, rarity, xpReward, coinReward, isHidden, active, triggerType, triggerValue, createdAt: new Date().toISOString() });
      toastMsg = `🏅 Badge "${name}" created!`;
    }
  }, { type: 'achievements:saved', payload: { id: achId } });
  toast(toastMsg);
  closeModalForce();
  const sectionIds = draftAchSections.slice();
  renderAdminAchievements();

  // Phase 16: persist the section assignment — set_achievement_sections()
  // only ever touches achievement_sections rows for THIS achievement_id,
  // and only ones the caller could have created themselves, so two
  // teachers assigning the same shared badge to their own different
  // sections can never stomp on each other (see
  // phase16_achievement_sections_rpc.sql). Fire-and-forget like the
  // quiz/shop/mail RPC calls — the badge itself already saved locally,
  // this just syncs who can see it assigned to.
  if (typeof DBService !== 'undefined' && typeof DBService.rpc === 'function') {
    const { error } = await DBService.rpc('set_achievement_sections', { p_achievement_id: achId, p_class_ids: sectionIds });
    if (error) {
      toast('⚠️ Badge saved, but section assignment may not have synced: ' + error.message, '#ffb95f');
    } else {
      // [Phase 3 migration bugfix] The pre-migration version mutated
      // DB.achievementSectionAssignments directly here with no follow-up
      // saveDB() call — memory-only, silently lost the next time anything
      // reloaded from persisted storage. Sixth instance of this exact bug
      // shape found across this phase (leaderboard, mail, campaign ×2,
      // titles, quiz-builder — see those entries in this log).
      // AppStore.updateState() always persists.
      AppStore.updateState(draft => {
        if (!draft.achievementSectionAssignments) draft.achievementSectionAssignments = {};
        draft.achievementSectionAssignments[achId] = sectionIds; // optimistic — next realtime pull confirms it
      }, { type: 'achievements:sections-set', payload: { id: achId, sectionIds } });
    }
  }
};

// ── Toggle / Delete / Duplicate ───────────────────────────────────────────────

window.achAdminToggle = function (achId) {
  const existing = (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId);
  if (!existing) return;
  let newActive = null;
  AppStore.updateState(draft => {
    const idx = (draft.achievements || []).findIndex(a => a.id === achId);
    if (idx < 0) return;
    draft.achievements[idx].active = !draft.achievements[idx].active;
    newActive = draft.achievements[idx].active;
  }, { type: 'achievements:toggled', payload: { id: achId } });
  toast(newActive ? '✅ Badge enabled.' : '⏸ Badge disabled.');
  renderAdminAchievements();
};

window.achAdminDelete = async function (achId) {
  const ach = (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId);
  if (!ach || !confirm(`Delete badge "${ach.name}"? This will also remove all unlock records.`)) return;
  AppStore.updateState(draft => {
    draft.achievements = (draft.achievements || []).filter(a => a.id !== achId);
    if (draft.achievementUnlocks) {
      Object.keys(draft.achievementUnlocks).forEach(sid => {
        draft.achievementUnlocks[sid] = (draft.achievementUnlocks[sid] || []).filter(u => u.achId !== achId);
      });
    }
  }, { type: 'achievements:deleted', payload: { id: achId } });
  toast('🗑 Badge deleted.', '#ff8080'); renderAdminAchievements();
  // Phase 23: the bulk push is upsert-only and never deletes server rows —
  // without this, the badge (and its section assignments/unlock records)
  // would silently reappear for everyone on the next pull.
  // delete_achievement() is staff-checked the same as achievements' own
  // RLS write policy.
  if (typeof DBService !== 'undefined' && typeof DBService.rpc === 'function') {
    const { error } = await DBService.rpc('delete_achievement', { p_achievement_id: achId });
    if (error) toast('⚠️ Removed locally, but may not have synced: ' + error.message, '#ffb95f');
  }
};

window.achAdminDuplicate = function (achId) {
  const ach = (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId);
  if (!ach) return;
  // Phase 32: carry the original's owner forward (falls back to the
  // current caller for any pre-migration row that somehow lacks one yet).
  AppStore.updateState(draft => {
    if (!Array.isArray(draft.achievements)) draft.achievements = [];
    draft.achievements.push({ ...ach, id: uid(), ownerTeacherId: ach.ownerTeacherId || currentUser.id, name: ach.name + ' (Copy)', createdAt: new Date().toISOString() });
  }, { type: 'achievements:duplicated', payload: { sourceId: achId } });
  toast('⧉ Badge duplicated!'); renderAdminAchievements();
};

// ── Preview ───────────────────────────────────────────────────────────────────

window.achAdminPreview = function (achId) {
  const ach        = (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId); if (!ach) return;
  const rarity     = ACH_RARITY[ach.rarity] || ACH_RARITY.Common;
  const triggerDef = ACH_TRIGGER_TYPES.find(t => t.value === ach.triggerType) || { label: ach.triggerType };
  showModal(`
  <div style="text-align:center;max-width:280px;margin:0 auto;padding:10px 0">
    <h3 style="font-family:var(--fh);font-size:16px;font-weight:900;margin-bottom:16px">Badge Preview</h3>
    <div class="ach-badge-card" style="max-width:200px;margin:0 auto 20px;box-shadow:0 0 30px ${rarity.glow};border-color:${rarity.color}55">
      <div class="ach-rarity-strip" style="background:${rarity.strip}"></div>
      <div class="ach-badge-icon-wrap">${ach.icon || '🏅'}</div>
      <div class="ach-badge-title ${achRarityClass(ach.rarity)}">${_esc(ach.name)}</div>
      <span class="ach-rarity-tag ${achRarityClass(ach.rarity)}">${ach.rarity}</span>
      <div class="ach-badge-desc">${_esc(ach.description || '')}</div>
      <div class="ach-unlocked-stamp">✓ UNLOCKED</div>
      <div class="ach-reward-chips">
        ${(ach.xpReward   || 0) > 0 ? `<span class="ach-reward-chip" style="color:#c4b5fd;border-color:rgba(196,181,253,0.3)">+${ach.xpReward} XP</span>` : ''}
        ${(ach.coinReward || 0) > 0 ? `<span class="ach-reward-chip" style="color:#ffb95f;border-color:rgba(255,185,95,0.3)">+${ach.coinReward} 🪙</span>` : ''}
      </div>
    </div>
    <div style="text-align:left;background:rgba(255,255,255,0.04);border-radius:10px;padding:12px;font-size:12px">
      <div style="margin-bottom:6px"><span style="color:var(--text-muted)">Category:</span> <strong>${_esc(ach.category)}</strong></div>
      <div style="margin-bottom:6px"><span style="color:var(--text-muted)">Trigger:</span> <strong>${_esc(triggerDef.label)}${ach.triggerType !== 'manual' && ach.triggerType !== 'all_quests' ? ' ≥ ' + ach.triggerValue : ''}</strong></div>
      <div style="margin-bottom:6px"><span style="color:var(--text-muted)">Hidden:</span> <strong>${ach.isHidden ? 'Yes — hidden until unlocked' : 'No'}</strong></div>
      <div><span style="color:var(--text-muted)">Status:</span> <strong style="color:${ach.active ? '#4edea3' : '#ff8080'}">${ach.active ? 'Active' : 'Disabled'}</strong></div>
    </div>
    <button class="btn btn-ghost btn-block" style="margin-top:14px" onclick="closeModalForce()">Close</button>
  </div>`, 'sm');
};

// ── Grant / Revoke ────────────────────────────────────────────────────────────

window.achAdminGrantAchievement = function () {
  const achs = AppStore.getSlice(s => s.achievements) || [];
  if (!achs.length) { toast('❌ Create achievements first', '#ffb4ab'); return; }
  const achOpts     = achs.map(a => `<option value="${a.id}">${a.icon} ${_esc(a.name)}</option>`).join('');
  const studentOpts = (AppStore.getSlice(s => s.students) || []).map(s => `<option value="${s.id}">${_esc(s.name)}</option>`).join('');
  showModal(`
  <div style="max-width:480px">
    <h2 style="font-family:var(--fh);font-size:20px;font-weight:900;margin-bottom:20px">🎁 Grant/Revoke Achievements</h2>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px">
      <div><label class="form-label">Student *</label><select id="ach-grant-student" class="form-control" style="width:100%"><option value="">Select student...</option>${studentOpts}</select></div>
      <div><label class="form-label">Achievement *</label><select id="ach-grant-ach" class="form-control" style="width:100%" onchange="achAdminUpdateGrantPreview()"><option value="">Select achievement...</option>${achOpts}</select></div>
    </div>
    <div id="ach-grant-preview" style="background:rgba(255,255,255,0.04);border-radius:10px;padding:14px;margin-bottom:14px;display:none">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:12px">
        <div><span style="color:var(--text-muted)">Achievement:</span><br><strong id="ach-grant-preview-name">—</strong></div>
        <div><span style="color:var(--text-muted)">Rarity:</span><br><strong id="ach-grant-preview-rarity">—</strong></div>
        <div><span style="color:var(--text-muted)">XP Reward:</span><br><strong style="color:#c4b5fd">+<span id="ach-grant-preview-xp">0</span> XP</strong></div>
        <div><span style="color:var(--text-muted)">Coin Reward:</span><br><strong style="color:#ffb95f">+<span id="ach-grant-preview-coin">0</span> 🪙</strong></div>
      </div>
    </div>
    <div style="background:rgba(255,255,255,0.04);border-radius:10px;padding:14px;margin-bottom:14px">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
        <input type="radio" name="ach-grant-action" value="grant" id="ach-action-grant" checked style="width:16px;height:16px;cursor:pointer">
        <label for="ach-action-grant" style="cursor:pointer;flex:1"><span style="font-weight:700;color:#4edea3">Grant Achievement</span><div style="font-size:11px;color:var(--text-muted);margin-top:2px">Award this badge &amp; reward XP/coins</div></label>
      </div>
      <div style="display:flex;align-items:center;gap:10px">
        <input type="radio" name="ach-grant-action" value="revoke" id="ach-action-revoke" style="width:16px;height:16px;cursor:pointer">
        <label for="ach-action-revoke" style="cursor:pointer;flex:1"><span style="font-weight:700;color:#ff8080">Revoke Achievement</span><div style="font-size:11px;color:var(--text-muted);margin-top:2px">Remove badge &amp; rewards</div></label>
      </div>
    </div>
    <div id="ach-grant-err" style="color:#ff8080;font-size:12px;margin-bottom:10px;display:none"></div>
    <div style="display:flex;gap:10px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button>
      <button class="btn btn-primary" style="flex:1" onclick="achAdminDoGrant()">Execute</button>
    </div>
  </div>`, 'md');
};

window.achAdminUpdateGrantPreview = function () {
  const achId   = document.getElementById('ach-grant-ach').value;
  const ach     = achId ? (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId) : null;
  const preview = document.getElementById('ach-grant-preview');
  if (ach && preview) {
    document.getElementById('ach-grant-preview-name').textContent  = ach.name;
    document.getElementById('ach-grant-preview-rarity').textContent = ach.rarity;
    document.getElementById('ach-grant-preview-xp').textContent    = ach.xpReward    || 0;
    document.getElementById('ach-grant-preview-coin').textContent  = ach.coinReward  || 0;
    preview.style.display = 'block';
  } else if (preview) {
    preview.style.display = 'none';
  }
};

window.achAdminDoGrant = function () {
  const sid     = document.getElementById('ach-grant-student').value;
  const achId   = document.getElementById('ach-grant-ach').value;
  const action  = document.querySelector('input[name="ach-grant-action"]:checked').value;
  const errEl   = document.getElementById('ach-grant-err');
  if (!sid)   { if (errEl) { errEl.textContent = 'Please select a student.';     errEl.style.display = 'block'; } return; }
  if (!achId) { if (errEl) { errEl.textContent = 'Please select an achievement.'; errEl.style.display = 'block'; } return; }
  if (errEl) errEl.style.display = 'none';

  const ach     = (AppStore.getSlice(s => s.achievements) || []).find(a => a.id === achId);
  const student = (AppStore.getSlice(s => s.students) || []).find(s => s.id === sid);
  if (!ach || !student) return;

  const alreadyUnlocked = ((AppStore.getSlice(s => s.achievementUnlocks) || {})[sid] || []).some(u => u.achId === achId);

  if (action === 'grant') {
    if (alreadyUnlocked) { if (errEl) { errEl.textContent = '❌ Student already has this achievement.'; errEl.style.display = 'block'; } return; }
    const xpGrant   = parseInt(ach.xpReward)   || 0;
    const coinGrant = parseInt(ach.coinReward) || 0;
    AppStore.updateState(draft => {
      const s = (draft.students || []).find(x => x.id === sid);
      if (s) { s.xp = (s.xp || 0) + xpGrant; s.coins = (s.coins || 0) + coinGrant; }
      if (!draft.achievementUnlocks) draft.achievementUnlocks = {};
      if (!draft.achievementUnlocks[sid]) draft.achievementUnlocks[sid] = [];
      draft.achievementUnlocks[sid].push({ achId, unlockedAt: new Date().toISOString(), xpGranted: xpGrant, coinsGranted: coinGrant, claimed: true, claimedAt: new Date().toISOString() });
    }, { type: 'achievements:granted', payload: { sid, achId } });
    syncStudentStatsToServer(sid, xpGrant, coinGrant);
    // Phase 17: admin grants unlock+claim in one step, unlike auto-unlock.
    syncAchievementUnlockToServer(sid, achId, xpGrant, coinGrant, true, student.classId || 'default-class');
    closeModalForce();
    toast(`✅ Granted "${_esc(ach.name)}" to ${_esc(student.name)}! +${xpGrant} XP, +${coinGrant} 🪙`);
  } else {
    if (!alreadyUnlocked) { if (errEl) { errEl.textContent = '❌ Student does not have this achievement.'; errEl.style.display = 'block'; } return; }
    let revokedXp = 0, revokedCoins = 0;
    AppStore.updateState(draft => {
      const unlock = ((draft.achievementUnlocks || {})[sid] || []).find(u => u.achId === achId);
      if (unlock) {
        revokedXp = unlock.xpGranted || 0;
        revokedCoins = unlock.coinsGranted || 0;
        const s = (draft.students || []).find(x => x.id === sid);
        if (s) {
          s.xp    = Math.max(0, (s.xp || 0)    - revokedXp);
          s.coins = Math.max(0, (s.coins || 0) - revokedCoins);
        }
      }
      draft.achievementUnlocks[sid] = (draft.achievementUnlocks[sid] || []).filter(u => u.achId !== achId);
    }, { type: 'achievements:revoked', payload: { sid, achId } });
    syncStudentStatsToServer(sid, -revokedXp, -revokedCoins);
    syncAchievementRevokeToServer(sid, achId);
    closeModalForce();
    toast(`🗑 Revoked "${_esc(ach.name)}" from ${_esc(student.name)}.`, '#ff8080');
  }
  renderAdminAchievements();
};

// ── Category management ───────────────────────────────────────────────────────

window.achAdminManageCategories = function () {
  const cats = AppStore.getSlice(s => s.achievementCategories) || [];
  showModal(`
  <div style="max-width:400px">
    <h2 style="font-family:var(--fh);font-size:18px;font-weight:900;margin-bottom:16px">Manage Categories</h2>
    <div id="ach-cats-list" style="margin-bottom:14px">
      ${cats.map((c, i) => `<div style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid var(--border)"><span style="flex:1;font-size:13px">${_esc(c)}</span><button class="btn btn-ghost btn-xs" style="color:#ff8080" onclick="achAdminDeleteCat(${i})">✕</button></div>`).join('')}
    </div>
    <div style="display:flex;gap:8px">
      <input id="ach-new-cat-input" class="form-control" type="text" placeholder="New category name..." style="flex:1">
      <button class="btn btn-primary" onclick="achAdminAddCat()">Add</button>
    </div>
    <button class="btn btn-ghost btn-block" style="margin-top:14px" onclick="closeModalForce();renderAdminAchievements()">Done</button>
  </div>`, 'sm');
};

window.achAdminAddCat = function () {
  const input = document.getElementById('ach-new-cat-input');
  const val   = (input?.value || '').trim();
  if (!val) return;
  const existing = AppStore.getSlice(s => s.achievementCategories) || [];
  if (existing.includes(val)) return;
  AppStore.updateState(draft => {
    if (!draft.achievementCategories) draft.achievementCategories = [];
    if (!draft.achievementCategories.includes(val)) draft.achievementCategories.push(val);
  }, { type: 'achievements:category-added', payload: { name: val } });
  toast(`✅ Category "${val}" added!`);
  achAdminManageCategories();
};

window.achAdminDeleteCat = function (idx) {
  const cat = (AppStore.getSlice(s => s.achievementCategories) || [])[idx];
  if (!cat) return;
  if (confirm(`Remove category "${cat}"?`)) {
    AppStore.updateState(draft => {
      if (Array.isArray(draft.achievementCategories)) draft.achievementCategories.splice(idx, 1);
    }, { type: 'achievements:category-deleted', payload: { name: cat } });
    toast('🗑 Category removed.', '#ff8080');
    achAdminManageCategories();
  }
};

console.log('[EduQuest] achievements/admin-page.js loaded — renderAdminAchievements, achAdmin* registered.');


