// ── Constants ─────────────────────────────────────────────────────────────────

window.BS_PALETTES = [
  { label: 'Void',    theme: '#8b5cf6', aura: '#EC4899', accent: '#d0bcff' },
  { label: 'Inferno', theme: '#ef4444', aura: '#f97316', accent: '#ffb95f' },
  { label: 'Abyssal', theme: '#1d4ed8', aura: '#06b6d4', accent: '#93c5fd' },
  { label: 'Poison',  theme: '#16a34a', aura: '#4ade80', accent: '#86efac' },
  { label: 'Shadow',  theme: '#374151', aura: '#6b7280', accent: '#d1d5db' },
  { label: 'Cursed',  theme: '#7c3aed', aura: '#db2777', accent: '#f472b6' },
  { label: 'Gilded',  theme: '#d97706', aura: '#fbbf24', accent: '#fef08a' },
  { label: 'Blood',   theme: '#9f1239', aura: '#be123c', accent: '#fda4af' },
];

window.bsvpBlank = function () {
  return {
    id: 'bvp_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    name: '', description: '', lore: '', tags: [],
    artwork:      { type: 'emoji', value: '💀' },
    rageArtwork:  { type: null, value: null },
    visual:       { themeColor: BS_DEFAULT_THEME, auraColor: BS_DEFAULT_AURA, cardAccent: BS_DEFAULT_ACCENT },
    animations:   { idle: null, cast: null, hit: null, rage: null },
    effects:      { aura: null, particle: null },
    schemaVersion: BS_SCHEMA_VERSION,
    createdAt: Date.now(), updatedAt: Date.now(),
  };
};

// ── Module state ──────────────────────────────────────────────────────────────
let _bsSearch  = '';
let _bsFilter  = 'all';
let _bsSort    = 'newest';
let _bsView    = 'grid';
let _bsPage    = 1;
const BS_PAGE_SIZE = 20;
let _bsPreview = null;
let _bsDirty   = false;
let _bsSearchDebounceTimer = null;
let _bsTab     = 'bosses'; // 'bosses' | 'animations'
// Guards _bsInitRemoteLibrary() (Pending Fixes Report §2a) to a single pull
// per page load — renderBossStudio() re-runs on every tab switch
// (_bsSetTab), and re-fetching on each of those would be wasteful.
let _bsLibraryRemoteFetchStarted = false;

Object.defineProperty(window, '_bsDraft', {
  get () { return window.__bsDraftValue; },
  set (v) { window.__bsDraftValue = v; },
  configurable: true,
});
window.__bsDraftValue = null;

// ── Private card helpers ──────────────────────────────────────────────────────

function _bsBossCardArtwork(boss) {
  const art   = boss.artwork;
  const theme = _cssColor(boss.visual?.themeColor, '#8b5cf6');
  const aura  = _cssColor(boss.visual?.auraColor, '#EC4899');
  const auraStyle = `background:radial-gradient(ellipse at center,${aura}55 0%,${theme}22 60%,transparent 100%)`;
  if (!art || !art.value) return `<div class="bs-card-artwork"><div class="bs-card-artwork-placeholder"><span class="material-symbols-outlined">image_not_supported</span><span>No Artwork</span></div></div>`;
  if (art.type === 'emoji') return `<div class="bs-card-artwork"><div class="bs-card-aura" style="${auraStyle}"></div><div class="bs-card-artwork-emoji">${_esc(art.value)}</div></div>`;
  return `<div class="bs-card-artwork"><div class="bs-card-aura" style="${auraStyle}"></div><img class="bs-card-artwork-img" src="${_esc(art.value)}" alt="${_esc(boss.name)}" onerror="this.style.display='none'"></div>`;
}

function _bsCardSlotPips(boss) {
  const anim  = boss.animations || {};
  const slots = [
    { key: 'idle', label: 'Idle', val: anim.idle, rage: false },
    { key: 'cast', label: 'Cast', val: anim.cast, rage: false },
    { key: 'hit',  label: 'Hit',  val: anim.hit,  rage: false },
    { key: 'rage', label: 'Rage', val: anim.rage, rage: true  },
  ];
  const pips = slots.map(s => {
    const animName = s.val && typeof window._alGet === 'function' ? (window._alGet(s.val) || {}).name : null;
    const title    = animName ? `${s.label}: ${animName}` : `${s.label}: unassigned`;
    return `<div class="bs-card-slot-pip ${s.val ? 'filled' : ''} ${s.rage ? 'rage-pip' : ''}" title="${_esc(title)}"></div>`;
  }).join('');
  return `<div class="bs-card-slot-pips" title="Animation slots: Idle / Cast / Hit / Rage">${pips}</div>`;
}

window._bsDateLabel = function (ts) {
  if (!ts) return '';
  const d = new Date(ts), now = new Date(), diff = now - d;
  if (diff < 60000)   return 'Just now';
  if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
  if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
};

// ── Library body renderer (refreshable) ───────────────────────────────────────

function _bsRenderLibraryBody() {
  const library = AppStore.getSlice(s => s.bossLibrary) || [];
  const total   = library.length;

  let filtered = library.filter(b => {
    if (_bsFilter === 'artwork')    return b.artwork?.value;
    if (_bsFilter === 'no-artwork') return !b.artwork?.value;
    if (_bsFilter === 'rage')       return b.rageArtwork?.value;
    if (_bsFilter === 'themed')     return b.visual && (b.visual.themeColor !== '#8b5cf6' || b.visual.auraColor !== '#EC4899');
    return true;
  });
  if (_bsSearch.trim()) {
    const q = _bsSearch.trim().toLowerCase();
    filtered = filtered.filter(b =>
      (b.name || '').toLowerCase().includes(q) ||
      (b.description || '').toLowerCase().includes(q) ||
      (b.lore || '').toLowerCase().includes(q) ||
      (b.tags || []).some(t => t.toLowerCase().includes(q))
    );
  }
  filtered = [...filtered].sort((a, b) => {
    if (_bsSort === 'newest') return (b.updatedAt || 0) - (a.updatedAt || 0);
    if (_bsSort === 'oldest') return (a.updatedAt || 0) - (b.updatedAt || 0);
    if (_bsSort === 'az')     return (a.name || '').localeCompare(b.name || '');
    if (_bsSort === 'za')     return (b.name || '').localeCompare(a.name || '');
    return 0;
  });

  const sectionHeader = `<div class="section-header" style="margin-bottom:0"><span class="material-symbols-outlined">library_books</span><h2>Boss Library</h2><span class="badge-pill">${total} Boss${total !== 1 ? 'es' : ''}</span></div>`;
  const toolbar = `<div class="bs-library-toolbar" style="margin-top:16px">
    <div class="bs-search-wrap"><span class="material-symbols-outlined">search</span>
      <input type="text" placeholder="Search by name, lore, or tag…" value="${_esc(_bsSearch)}" oninput="window._bsSearchUpdate(this.value)" id="bs-search-input"></div>
    <div class="bs-filter-row">
      <button class="bs-filter-btn ${_bsFilter==='all'?'active':''}" onclick="window._bsSetFilter('all')">All</button>
      <button class="bs-filter-btn ${_bsFilter==='artwork'?'active':''}" onclick="window._bsSetFilter('artwork')">Has Artwork</button>
      <button class="bs-filter-btn ${_bsFilter==='no-artwork'?'active':''}" onclick="window._bsSetFilter('no-artwork')">No Artwork</button>
      <button class="bs-filter-btn ${_bsFilter==='rage'?'active':''}" onclick="window._bsSetFilter('rage')">Has Rage Art</button>
      <button class="bs-filter-btn ${_bsFilter==='themed'?'active':''}" onclick="window._bsSetFilter('themed')">Themed</button>
    </div>
    <div style="display:flex;align-items:center;gap:8px;flex-shrink:0">
      <select class="bs-sort-select" onchange="window._bsSetSort(this.value)">
        <option value="newest" ${_bsSort==='newest'?'selected':''}>Newest</option>
        <option value="oldest" ${_bsSort==='oldest'?'selected':''}>Oldest</option>
        <option value="az"     ${_bsSort==='az'?'selected':''}>A → Z</option>
        <option value="za"     ${_bsSort==='za'?'selected':''}>Z → A</option>
      </select>
      <button class="bs-view-btn ${_bsView==='grid'?'active':''}" onclick="window._bsSetView('grid')" title="Grid view"><span class="material-symbols-outlined" style="font-size:16px">grid_view</span></button>
      <button class="bs-view-btn ${_bsView==='list'?'active':''}" onclick="window._bsSetView('list')" title="List view"><span class="material-symbols-outlined" style="font-size:16px">view_list</span></button>
    </div>
  </div>`;

  if (total === 0) return sectionHeader + toolbar + `<div class="bs-empty" style="margin-top:20px"><div class="bs-empty-icon">🏰</div><div class="bs-empty-title">No Boss Profiles Yet</div><div class="bs-empty-sub">Create your first boss profile to begin building your visual library.</div><button class="btn btn-primary" onclick="bsOpenCreate()" style="font-family:var(--fh);font-weight:800"><span class="material-symbols-outlined" style="font-size:16px;vertical-align:middle">add</span> Create First Boss</button></div>`;
  if (filtered.length === 0) return sectionHeader + toolbar + `<div class="bs-empty" style="margin-top:20px"><div class="bs-empty-icon">🔍</div><div class="bs-empty-title">No Results</div><div class="bs-empty-sub">No boss profiles match your search or filter.</div><button class="btn btn-ghost" onclick="window._bsSearchUpdate('');window._bsSetFilter('all')" style="font-family:var(--fh)">Clear Filters</button></div>`;

  const totalPages = Math.max(1, Math.ceil(filtered.length / BS_PAGE_SIZE));
  if (_bsPage > totalPages) _bsPage = totalPages;
  const pageStart = (_bsPage - 1) * BS_PAGE_SIZE;
  const pageItems = filtered.slice(pageStart, pageStart + BS_PAGE_SIZE);

  const cards = pageItems.map(boss => {
    const cardAccent = _cssColor(boss.visual?.cardAccent, '#d0bcff');
    const cardTheme  = _cssColor(boss.visual?.themeColor, '#8b5cf6');
    const hasRage    = boss.rageArtwork?.value;
    return `<div class="bs-boss-card ${_bsView==='list'?'list-card':''}" onclick="bsOpenPreview('${_esc(boss.id)}')" style="border-color:${cardTheme}55;--bs-card-accent:${cardAccent};--bs-card-glow:${_cssColor(boss.visual?.auraColor, '#EC4899')}55">
      ${_bsBossCardArtwork(boss)}
      ${hasRage ? `<div class="bs-card-rage-badge" title="Rage artwork configured">🔥</div>` : ''}
      <button class="bs-card-preview-btn" onclick="event.stopPropagation();bsOpenPreview('${_esc(boss.id)}')" title="Full encounter preview"><span class="material-symbols-outlined">visibility</span>Preview</button>
      <div class="bs-card-body">
        ${boss.tags?.length ? `<div class="bs-card-tags">${boss.tags.slice(0,3).map(t=>`<span class="bs-card-tag" style="color:${cardAccent};border-color:${cardTheme}44">${_esc(t)}</span>`).join('')}</div>` : ''}
        <div class="bs-card-name" style="color:${cardAccent}">${_esc(boss.name || 'Unnamed Boss')}</div>
        <div class="bs-card-desc">${_esc(boss.description || 'No description provided.')}</div>
        ${_bsCardSlotPips(boss)}
        <div class="bs-card-footer">
          <div class="bs-card-meta">${window._bsDateLabel(boss.updatedAt)}</div>
          <div class="bs-card-actions" onclick="event.stopPropagation()">
            <button class="bs-card-act-btn clone" onclick="bsDuplicate('${_esc(boss.id)}')" title="Duplicate"><span class="material-symbols-outlined">content_copy</span></button>
            <button class="bs-card-act-btn" onclick="bsOpenEdit('${_esc(boss.id)}')" title="Edit"><span class="material-symbols-outlined">edit</span></button>
            <button class="bs-card-act-btn danger" onclick="bsConfirmDelete('${_esc(boss.id)}')" title="Delete"><span class="material-symbols-outlined">delete</span></button>
          </div>
        </div>
      </div>
    </div>`;
  }).join('');

  return sectionHeader + toolbar + `<div class="bs-library-grid ${_bsView === 'list' ? 'list-view' : ''}" style="margin-top:20px">${cards}</div>`
    + _bsPagination(_bsPage, totalPages, filtered.length, pageStart + 1, pageStart + pageItems.length);
}

function _bsRefreshLibrary() {
  bsLoad();
  const root = document.getElementById('bs-library-root');
  if (root) root.innerHTML = _bsRenderLibraryBody();
}

// ── Boss Studio tab renderer ───────────────────────────────────────────────────

function _bsRenderBossTab() {
  const all = AppStore.getSlice(s => s.bossLibrary) || [];
  const themed = all.filter(b => b.visual?.themeColor && b.visual.themeColor !== BS_DEFAULT_THEME).length;
  const hasArt = all.filter(b => b.artwork?.value).length;
  const hasRage = all.filter(b => b.rageArtwork?.value).length;
  const fullySlotted = all.filter(b => { const a = b.animations || {}; return a.idle && a.cast && a.hit && a.rage; }).length;
  return `
  <div class="bs-hero"><div class="bs-hero-inner">
    <div class="bs-hero-icon">🎭</div>
    <div class="bs-hero-info">
      <div class="bs-hero-label">Asset Management</div>
      <div class="bs-hero-title">Boss Studio</div>
      <div class="bs-hero-sub">Create and manage reusable Boss Visual Profiles. Each profile defines a boss's identity, artwork, lore, and animation slot assignments.</div>
      <div class="bs-hero-stats-bar">
        <div class="bs-stat-pill"><span class="material-symbols-outlined">smart_toy</span><strong>${all.length}</strong> Profile${all.length !== 1 ? 's' : ''}</div>
        ${hasArt ? `<div class="bs-stat-pill"><span class="material-symbols-outlined">palette</span><strong>${hasArt}</strong> With Artwork</div>` : ''}
        ${themed ? `<div class="bs-stat-pill"><span class="material-symbols-outlined">auto_awesome</span><strong>${themed}</strong> Themed</div>` : ''}
        ${hasRage ? `<div class="bs-stat-pill"><span class="material-symbols-outlined">local_fire_department</span><strong>${hasRage}</strong> Rage Art</div>` : ''}
        ${fullySlotted ? `<div class="bs-stat-pill"><span class="material-symbols-outlined">animation</span><strong>${fullySlotted}</strong> Fully Slotted</div>` : ''}
      </div>
      <div class="bs-io-row">
        <span class="bs-io-label">Library:</span>
        <button class="bs-io-btn" onclick="window._bsExportAll()"><span class="material-symbols-outlined">download</span>Export All</button>
        <button class="bs-io-btn" onclick="window._bsImportJSON()"><span class="material-symbols-outlined">upload</span>Import JSON</button>
      </div>
    </div>
    <div class="bs-hero-actions">
      <button class="btn btn-primary" onclick="bsOpenCreate()" style="display:flex;align-items:center;gap:7px;padding:11px 20px;font-family:var(--fh);font-weight:800">
        <span class="material-symbols-outlined" style="font-size:18px">add</span>New Boss Profile
      </button>
    </div>
  </div></div>
  <div id="bs-library-root">${_bsRenderLibraryBody()}</div>`;
}

// ── Main render ────────────────────────────────────────────────────────────────

window.renderBossStudio = function () {
  bsLoad();
  const page = document.getElementById('a-boss-studio');
  if (!page) return;
  window._bsMigrateLegacyInlineImages();
  // Cross-device library sync (Pending Fixes Report §2a) — deliberately NOT
  // kicked off at app boot (see bs_storage.js's _bsInitRemoteLibrary comment
  // for why: no Supabase Auth session exists yet at that point, and
  // get_boss_library() is staff-only). This page only ever mounts post-login
  // for an admin/teacher, so it's the right place. Runs once per page load;
  // re-renders the library view when the pull resolves so remote-only
  // designs appear without the admin needing to do anything.
  if (!_bsLibraryRemoteFetchStarted && typeof window._bsInitRemoteLibrary === 'function') {
    _bsLibraryRemoteFetchStarted = true;
    window._bsInitRemoteLibrary().then(function () {
      if (document.getElementById('a-boss-studio')) renderBossStudio();
    });
  }
  const alTab = typeof window._alRenderTabBody === 'function' ? window._alRenderTabBody() : '<div style="color:var(--text-muted);padding:40px">Animation library loading...</div>';
  page.innerHTML = `<div class="page" style="padding:32px;max-width:1200px;margin:0 auto;display:block">
    <div class="bs-tabs">
      <button class="bs-tab ${_bsTab==='bosses'?'active':''}" onclick="window._bsSetTab('bosses')"><span class="material-symbols-outlined">library_books</span>Boss Library<span class="badge-pill">${(AppStore.getSlice(s => s.bossLibrary)||[]).length}</span></button>
      <button class="bs-tab ${_bsTab==='animations'?'active':''}" onclick="window._bsSetTab('animations')"><span class="material-symbols-outlined">animation</span>Animation Library<span class="badge-pill">${(AppStore.getSlice(s => s.animationLibrary)||[]).length}</span></button>
    </div>
    <div id="bs-tab-root">${_bsTab === 'animations' ? alTab : _bsRenderBossTab()}</div>
  </div>`;
};

window._bsSetTab = function (tab) { _bsTab = tab; renderBossStudio(); };

// ── Preview overlay ────────────────────────────────────────────────────────────

window.bsOpenPreview = function (id) {
  bsLoad();
  const boss = bsGet(id);
  if (!boss) return;
  _bsPreview = boss;
  const theme = _cssColor(boss.visual?.themeColor, BS_DEFAULT_THEME);
  const aura  = _cssColor(boss.visual?.auraColor, BS_DEFAULT_AURA);
  const accent = _cssColor(boss.visual?.cardAccent, BS_DEFAULT_ACCENT);
  const animSlots = boss.animations || {};
  const slotRows = ['idle', 'cast', 'hit', 'rage'].map(s => {
    const preset = animSlots[s] && typeof window._alGet === 'function' ? window._alGet(animSlots[s]) : null;
    return `<div style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.04)"><span style="font-size:11px;color:var(--text-muted);width:32px;text-transform:uppercase;font-weight:700">${s}</span><span style="font-size:12px;font-weight:700;color:${preset ? accent : 'var(--text-muted)'}">${preset ? _esc(preset.name) : 'Unassigned'}</span></div>`;
  }).join('');

  showModal(`<div>
    <div style="display:flex;align-items:flex-start;gap:18px;margin-bottom:16px">
      <div class="bs-anim-stage" style="width:110px;height:110px;flex-shrink:0;background:radial-gradient(circle,${aura}44,${theme}22);border:1.5px solid ${theme}55;border-radius:16px;display:flex;align-items:center;justify-content:center">
        ${boss.artwork?.type === 'emoji' ? `<span class="bs-anim-stage-art ${animSlots.idle ? window._alGet?.(animSlots.idle)?.cssClass||'' : ''}" style="font-size:52px">${_esc(boss.artwork.value)}</span>` : boss.artwork?.value ? `<img src="${_esc(boss.artwork.value)}" style="width:88px;height:88px;object-fit:contain">` : `<span style="font-size:48px">💀</span>`}
      </div>
      <div style="flex:1;min-width:0">
        <div style="font-family:var(--fh);font-size:20px;font-weight:900;color:${accent};margin-bottom:4px">${_esc(boss.name || 'Unnamed Boss')}</div>
        <div style="font-size:12px;color:var(--text-muted);margin-bottom:10px;line-height:1.5">${_esc(boss.description || '')}</div>
        ${boss.tags?.length ? `<div style="display:flex;gap:5px;flex-wrap:wrap">${boss.tags.map(t=>`<span style="background:${theme}22;border:1px solid ${theme}44;color:${accent};border-radius:5px;padding:2px 8px;font-size:10px;font-weight:700">${_esc(t)}</span>`).join('')}</div>` : ''}
      </div>
    </div>
    ${boss.lore ? `<div style="background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.07);border-radius:10px;padding:12px;margin-bottom:14px;font-size:12px;color:var(--text-muted);line-height:1.6;font-style:italic">"${_esc(boss.lore)}"</div>` : ''}
    <div style="font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);margin-bottom:8px">Animation Slots</div>
    ${slotRows}
    <div style="display:flex;gap:10px;margin-top:16px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Close</button>
      <button class="btn btn-primary" style="flex:1" onclick="closeModalForce();bsOpenEdit('${_esc(id)}')">Edit Profile</button>
    </div>
  </div>`, 'md');
};

// ── Encounter preview ──────────────────────────────────────────────────────────

window._bsCloseEncounter = function () {
  const ov = document.getElementById('bs-encounter-overlay');
  if (ov) ov.remove();
};

window._bsEncPlayState = function (bossId, stateKey) {
  bsLoad();
  const boss = bsGet(bossId); if (!boss) return;
  const animSlots = boss.animations || {};
  const slotId    = animSlots[stateKey];
  const preset    = slotId && typeof window._alGet === 'function' ? window._alGet(slotId) : null;
  const artEl = document.getElementById('bs-enc-art');
  if (!artEl) return;
  artEl.className = 'bs-anim-stage-art' + (preset ? ' ' + preset.cssClass : '');
};

// ── Search / filter / sort / view controls ─────────────────────────────────────

window._bsSearchUpdate = function (val) {
  clearTimeout(_bsSearchDebounceTimer);
  _bsSearchDebounceTimer = setTimeout(() => {
    _bsSearch = val;
    _bsPage = 1;
    _bsRefreshLibrary();
    setTimeout(() => {
      const inp = document.getElementById('bs-search-input');
      if (inp) { inp.focus(); const l = inp.value.length; inp.setSelectionRange(l, l); }
    }, 0);
  }, 120);
};
window._bsSetFilter = function (f)    { _bsFilter = f; _bsPage = 1; _bsRefreshLibrary(); };
window._bsSetSort   = function (s)    { _bsSort   = s; _bsPage = 1; _bsRefreshLibrary(); };
window._bsSetView   = function (v)    { _bsView   = v; _bsRefreshLibrary(); };

window._bsGoToPage = function (page) {
  _bsPage = Math.max(1, page | 0);
  _bsRefreshLibrary();
  const root = document.getElementById('bs-library-root');
  if (root) root.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
};
window._bsPrevPage = function () { window._bsGoToPage(_bsPage - 1); };
window._bsNextPage = function () { window._bsGoToPage(_bsPage + 1); };

function _bsPagination(page, totalPages, totalCount, rangeStart, rangeEnd) {
  if (totalPages <= 1) {
    return `<div style="text-align:center;margin-top:14px;font-size:11px;color:var(--text-muted)">Showing all ${totalCount}</div>`;
  }
  const nums = new Set([1, totalPages, page, page - 1, page + 1, page - 2, page + 2]);
  const pages = Array.from(nums).filter(n => n >= 1 && n <= totalPages).sort((a, b) => a - b);
  let btns = '';
  let prevN = 0;
  pages.forEach(n => {
    if (n - prevN > 1) btns += `<span style="padding:0 6px;color:var(--text-muted);font-size:11px">…</span>`;
    btns += `<button class="bs-view-btn ${n === page ? 'active' : ''}" style="width:auto;padding:0 10px" onclick="window._bsGoToPage(${n})">${n}</button>`;
    prevN = n;
  });
  return `
  <div style="display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap;margin-top:20px">
    <button class="bs-view-btn" style="width:auto;padding:0 10px" ${page <= 1 ? 'disabled' : ''} onclick="window._bsPrevPage()">← Prev</button>
    ${btns}
    <button class="bs-view-btn" style="width:auto;padding:0 10px" ${page >= totalPages ? 'disabled' : ''} onclick="window._bsNextPage()">Next →</button>
  </div>
  <div style="text-align:center;margin-top:8px;font-size:11px;color:var(--text-muted)">Showing ${rangeStart}–${rangeEnd} of ${totalCount}</div>`;
}

// ── Duplicate / delete ─────────────────────────────────────────────────────────

window.bsDuplicate = function (id) {
  bsLoad();
  const orig = bsGet(id); if (!orig) return;
  const clone = JSON.parse(JSON.stringify(orig));
  clone.id        = 'bvp_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
  clone.name      = (orig.name || 'Boss') + ' (Copy)';
  clone.createdAt = Date.now();
  clone.updatedAt = Date.now();
  // Clear IDB references — clone doesn't own them; artwork remains as-is in memory for this session
  bsUpsert(clone); bsLoad();
  toast(`⧉ "${_esc(clone.name)}" duplicated!`);
  _bsRefreshLibrary();
};

window.bsConfirmDelete = function (id) {
  bsLoad();
  const boss = bsGet(id); if (!boss) return;
  showModal(`<div style="text-align:center;padding:8px 0">
    <div style="font-size:48px;margin-bottom:12px">⚠️</div>
    <div class="modal-h2" style="margin-bottom:8px">Delete Boss Profile?</div>
    <div style="font-size:13px;color:var(--text-muted);margin-bottom:24px">
      <strong style="color:var(--on-surface)">${_esc(boss.name || 'This boss')}</strong> will be permanently removed. Any boss events using this profile will revert to defaults.
    </div>
    <div style="display:flex;gap:10px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button>
      <button class="btn btn-danger" style="flex:1;font-family:var(--fh);font-weight:800" onclick="window._bsDeleteConfirmed('${_esc(id)}')">Delete</button>
    </div>
  </div>`, 'sm');
};

window._bsDeleteConfirmed = function (id) {
  bsLoad();
  const boss = bsGet(id);
  const name = boss ? boss.name : 'Boss';
  bsDelete(id);
  closeModalForce();
  toast(`🗑 "${name}" deleted`, '#ffb4ab');
  _bsRefreshLibrary();
};

// ── Export / Import ────────────────────────────────────────────────────────────

window._bsExportSingle = function (id) {
  bsLoad();
  const boss = bsGet(id); if (!boss) return;
  const json = JSON.stringify({ bossStudioExport: true, version: BS_SCHEMA_VERSION, profiles: [boss] }, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const a    = document.createElement('a');
  a.href     = URL.createObjectURL(blob);
  a.download = (boss.name || 'boss').replace(/[^a-z0-9]/gi, '_') + '.bvp.json';
  a.click(); URL.revokeObjectURL(a.href);
};

window._bsExportAll = function () {
  bsLoad();
  const json = JSON.stringify({ bossStudioExport: true, version: BS_SCHEMA_VERSION, profiles: AppStore.getSlice(s => s.bossLibrary) || [] }, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const a    = document.createElement('a');
  a.href     = URL.createObjectURL(blob);
  a.download = 'eduquest_boss_library_' + new Date().toISOString().slice(0, 10) + '.json';
  a.click(); URL.revokeObjectURL(a.href);
};

window._bsImportJSON = function () {
  const input = document.createElement('input');
  input.type  = 'file'; input.accept = 'application/json';
  input.onchange = function (e) {
    const file = e.target.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = function (ev) {
      try {
        const parsed = JSON.parse(ev.target.result);
        const profiles = parsed.profiles || (Array.isArray(parsed) ? parsed : [parsed]);
        bsLoad();
        let imported = 0;
        profiles.forEach(p => {
          if (!p || !p.id) return;
          // Avoid overwriting existing; give clone a new id
          if (bsGet(p.id)) p.id = 'bvp_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
          _bsResolveProfileArtwork(p);
          bsUpsert(p);
          imported++;
        });
        bsLoad();
        toast(`✅ Imported ${imported} profile${imported !== 1 ? 's' : ''}!`, '#4edea3');
        _bsRefreshLibrary();
      } catch (err) {
        toast('❌ Invalid JSON file', '#ffb4ab');
      }
    };
    reader.readAsText(file);
  };
  input.click();
};

// Expose _bsRefreshLibrary and other needed symbols for editor.js
window._bsRefreshLibrary   = _bsRefreshLibrary;
window._bsBossCardArtwork  = _bsBossCardArtwork;
window._bsRenderLibraryBody = _bsRenderLibraryBody;
window._BS_PALETTES        = BS_PALETTES;
window._bsRenderFormModal  = null; // set by editor.js after it loads

console.log('[EduQuest] boss-studio/library.js loaded — renderBossStudio, boss library, preview, search/filter/export/import registered.');


/* ---- ./modules/boss-studio/bs_animation_library.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/boss-studio/animation-library.js
//  Animation Library: 13 built-in presets + full custom CRUD.
//  Provides _alGet and _alOptionsForTarget consumed by editor.js slot pickers.
//  LOAD AFTER: storage.js, library.js
// ═══════════════════════════════════════════════════════════════════════════════

// ── Built-in presets ──────────────────────────────────────────────────────────

const AL_BUILTINS = [
  { id:'al_idle_float',   name:'Idle Float',     description:'Gentle up-and-down floating loop.',      cssClass:'bs-anim-play-idle-float',   targets:['idle'],  tags:['idle','float','loop'],      builtin:true },
  { id:'al_idle_bob',     name:'Idle Bob',        description:'Short rhythmic bobbing motion.',         cssClass:'bs-anim-play-idle-bob',     targets:['idle'],  tags:['idle','bob','loop'],        builtin:true },
  { id:'al_idle_sway',    name:'Idle Sway',       description:'Slow pendulum sway left and right.',    cssClass:'bs-anim-play-idle-sway',    targets:['idle'],  tags:['idle','sway','loop'],       builtin:true },
  { id:'al_idle_glow',    name:'Idle Pulse Glow', description:'Subtle scale pulse with aura glow.',    cssClass:'bs-anim-play-idle-glow',    targets:['idle'],  tags:['idle','glow','pulse'],      builtin:true },
  { id:'al_cast_charge',  name:'Cast Charge-Up',  description:'Boss swells and brightens before attack.',cssClass:'bs-anim-play-cast-charge', targets:['cast'],  tags:['cast','charge','skill'],    builtin:true },
  { id:'al_cast_spin',    name:'Cast Spin',        description:'Full rotation during skill execution.', cssClass:'bs-anim-play-cast-spin',    targets:['cast'],  tags:['cast','spin','skill'],      builtin:true },
  { id:'al_cast_flash',   name:'Cast Flash',       description:'Rapid brightness burst on skill use.',  cssClass:'bs-anim-play-cast-flash',   targets:['cast'],  tags:['cast','flash','skill'],     builtin:true },
  { id:'al_hit_flinch',   name:'Hit Flinch',       description:'Recoil with slight rotation on impact.',cssClass:'bs-anim-play-hit-flinch',   targets:['hit'],   tags:['hit','flinch','damage'],    builtin:true },
  { id:'al_hit_shake',    name:'Hit Shake',         description:'Full-body jitter on taking damage.',   cssClass:'bs-anim-play-hit-shake',    targets:['hit'],   tags:['hit','shake','damage'],     builtin:true },
  { id:'al_hit_flashred', name:'Hit Flash Red',    description:'Red tint flash when struck.',           cssClass:'bs-anim-play-hit-flashred', targets:['hit'],   tags:['hit','flash','damage'],     builtin:true },
  { id:'al_rage_burst',   name:'Rage Burst',       description:'Explosive entry into rage state.',      cssClass:'bs-anim-play-rage-burst',   targets:['rage'],  tags:['rage','burst','intense'],   builtin:true },
  { id:'al_rage_pulse',   name:'Rage Pulse',       description:'Intense pulsing glow in rage mode.',    cssClass:'bs-anim-play-rage-pulse',   targets:['rage'],  tags:['rage','pulse','glow'],      builtin:true },
  { id:'al_rage_vibrate', name:'Rage Vibrate',     description:'High-frequency vibration during rage.', cssClass:'bs-anim-play-rage-vibrate', targets:['rage'],  tags:['rage','vibrate','intense'], builtin:true },
];

// ── Module state ──────────────────────────────────────────────────────────────
let _alSearch = '';
let _alFilter = 'all';
let _alDraft  = null;

const AL_TARGET_OPTIONS = [
  { key:'idle', icon:'play_circle',           label:'Idle' },
  { key:'cast', icon:'bolt',                  label:'Cast' },
  { key:'hit',  icon:'gpp_bad',               label:'Hit'  },
  { key:'rage', icon:'local_fire_department', label:'Rage' },
];

// ── Storage helpers ───────────────────────────────────────────────────────────

function _alLoad() { return AppStore.getSlice(s => s.animationLibrary) || []; }

function _alUpsert(preset) {
  AppStore.updateState(draft => {
    if (!Array.isArray(draft.animationLibrary)) draft.animationLibrary = [];
    const idx = draft.animationLibrary.findIndex(a => a.id === preset.id);
    if (idx >= 0) draft.animationLibrary[idx] = preset;
    else          draft.animationLibrary.push(preset);
  }, { type: 'boss-studio:animation-preset-saved', payload: { id: preset.id } });
}

function _alDeleteRecord(id) {
  AppStore.updateState(draft => {
    draft.animationLibrary = (draft.animationLibrary || []).filter(a => a.id !== id);
  }, { type: 'boss-studio:animation-preset-deleted', payload: { id } });
}

// ── Core public API ───────────────────────────────────────────────────────────

function _alAll() {
  const animationLibrary = _alLoad();
  const customIds = new Set(animationLibrary.map(a => a.id));
  return [...AL_BUILTINS.filter(b => !customIds.has(b.id)), ...animationLibrary];
}

function alGet(id) {
  if (!id) return null;
  const custom = _alLoad().find(a => a.id === id);
  return custom || AL_BUILTINS.find(b => b.id === id) || null;
}

function alOptionsForTarget(target) {
  return _alAll().filter(a => !a.targets || a.targets.length === 0 || a.targets.includes(target));
}

// ── Refresh helper ────────────────────────────────────────────────────────────

function _alRefreshGrid() {
  const root = document.getElementById('al-library-root');
  if (root) root.innerHTML = _alRenderGrid();
}

// ── Tab body renderer ─────────────────────────────────────────────────────────

function _alRenderTabBody() {
  const all         = _alAll();
  const customCount = _alLoad().length;
  return `
  <div class="al-hero"><div class="al-hero-inner">
    <div class="al-hero-icon">🎬</div>
    <div class="al-hero-info">
      <div class="al-hero-label">Asset Management</div>
      <div class="al-hero-title">Animation Library</div>
      <div class="al-hero-sub">Manage reusable CSS animation presets. Assign them to Boss Visual Profile slots to define how bosses move during gameplay.</div>
    </div>
    <div class="al-hero-actions">
      <button class="btn btn-primary" onclick="window._alOpenCreate()" style="display:flex;align-items:center;gap:7px;padding:11px 20px;font-family:var(--fh);font-weight:800">
        <span class="material-symbols-outlined" style="font-size:18px">add</span>New Preset
      </button>
    </div>
  </div></div>
  <div class="section-header" style="margin-bottom:0">
    <span class="material-symbols-outlined">animation</span>
    <h2>Animation Presets</h2>
    <span class="badge-pill">${all.length} Preset${all.length !== 1 ? 's' : ''}</span>
    ${customCount > 0 ? `<span class="badge-pill" style="background:rgba(78,222,163,0.1);color:var(--secondary);border:1px solid rgba(78,222,163,0.2)">${customCount} Custom</span>` : ''}
  </div>
  <div class="bs-library-toolbar" style="margin-top:16px">
    <div class="bs-search-wrap">
      <span class="material-symbols-outlined">search</span>
      <input type="text" placeholder="Search by name, tag, or CSS class…" value="${_esc(_alSearch)}" oninput="window._alSearchUpdate(this.value)" id="al-search-input">
    </div>
    <div class="bs-filter-row">
      ${['all','idle','cast','hit','rage','custom'].map(f =>
        `<button class="bs-filter-btn ${_alFilter===f?'active':''}" onclick="window._alSetFilter('${f}')">${f.charAt(0).toUpperCase()+f.slice(1)}</button>`
      ).join('')}
    </div>
  </div>
  <div id="al-library-root" style="margin-top:20px">${_alRenderGrid()}</div>`;
}

// ── Grid renderer ─────────────────────────────────────────────────────────────

function _alRenderGrid() {
  let list = _alAll();
  if (_alFilter === 'custom')    list = list.filter(a => !a.builtin);
  else if (_alFilter !== 'all')  list = list.filter(a => a.targets && a.targets.includes(_alFilter));
  if (_alSearch.trim()) {
    const q = _alSearch.trim().toLowerCase();
    list = list.filter(a => (a.name||'').toLowerCase().includes(q) || (a.description||'').toLowerCase().includes(q) || (a.cssClass||'').toLowerCase().includes(q) || (a.tags||[]).some(t => t.toLowerCase().includes(q)));
  }
  if (!list.length) return `<div class="al-empty"><div class="al-empty-icon">🎭</div><div class="al-empty-title">No Presets Found</div><div class="al-empty-sub">Try clearing the search or filter, or create a new custom preset.</div><button class="btn btn-ghost" onclick="window._alSearchUpdate('');window._alSetFilter('all')" style="font-family:var(--fh)">Clear Filters</button></div>`;
  const TARGET_ICONS = { idle:'play_circle', cast:'bolt', hit:'gpp_bad', rage:'local_fire_department' };
  return `<div class="al-library-grid">${list.map(a => {
    const targetsHtml = (a.targets||[]).map(t => `<span style="display:inline-flex;align-items:center;gap:3px;font-size:9px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--secondary)"><span class="material-symbols-outlined" style="font-size:11px">${TARGET_ICONS[t]||'animation'}</span>${t}</span>`).join('<span style="color:var(--border);margin:0 2px">·</span>');
    return `<div class="al-card">
      <div class="al-card-stage bs-anim-stage" id="al-stage-${_esc(a.id)}" onclick="window._alTogglePreview('${_esc(a.id)}')" style="cursor:pointer" title="Click to preview">
        <div class="bs-anim-stage-art" id="al-art-${_esc(a.id)}">💀</div>
        <div class="bs-anim-label">${_esc(a.name)}</div>
      </div>
      <div class="al-card-body">
        <div class="al-card-name">${_esc(a.name)}</div>
        <div class="al-card-type">${targetsHtml||'<span style="color:var(--text-muted)">Universal</span>'}</div>
        <div class="al-card-desc">${_esc(a.description||'—')}</div>
        <div class="al-card-tags">${a.builtin ? '<span class="al-card-tag builtin">Built-in</span>' : ''}${(a.tags||[]).filter(t => !['idle','cast','hit','rage'].includes(t)).slice(0,4).map(t=>`<span class="al-card-tag">${_esc(t)}</span>`).join('')}</div>
        <div class="al-card-footer">
          <div style="font-size:10px;color:var(--text-muted);font-family:monospace">${_esc(a.cssClass||'—')}</div>
          <div class="al-card-actions">
            <button class="al-card-act-btn" onclick="window._alOpenPreviewModal('${_esc(a.id)}')" title="Preview"><span class="material-symbols-outlined">play_circle</span></button>
            <button class="al-card-act-btn" onclick="window._alOpenEdit('${_esc(a.id)}')" title="${a.builtin?'Duplicate & Edit':'Edit'}"><span class="material-symbols-outlined">${a.builtin?'content_copy':'edit'}</span></button>
            ${!a.builtin ? `<button class="al-card-act-btn danger" onclick="window._alConfirmDelete('${_esc(a.id)}')" title="Delete"><span class="material-symbols-outlined">delete</span></button>` : ''}
          </div>
        </div>
      </div>
    </div>`;
  }).join('')}</div>`;
}

// ── Card stage preview toggle ─────────────────────────────────────────────────

window._alTogglePreview = function (id) {
  const art = document.getElementById(`al-art-${id}`); if (!art) return;
  const preset = alGet(id); if (!preset) return;
  const playing = art.dataset.playing === '1';
  art.className    = 'bs-anim-stage-art' + (playing ? '' : ' ' + (preset.cssClass || ''));
  art.dataset.playing = playing ? '' : '1';
};

// ── Preview modal ─────────────────────────────────────────────────────────────

window._alOpenPreviewModal = function (id) {
  const preset = alGet(id); if (!preset) { toast('❌ Preset not found', '#ffb4ab'); return; }
  const TARGET_ICONS = { idle:'play_circle', cast:'bolt', hit:'gpp_bad', rage:'local_fire_department' };
  showModal(`<div>
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:20px">
      <div style="width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,rgba(78,222,163,0.25),rgba(139,92,246,0.15));border:1px solid rgba(78,222,163,0.35);display:flex;align-items:center;justify-content:center;font-size:20px">🎬</div>
      <div><div class="modal-h2" style="margin-bottom:2px">${_esc(preset.name)}</div><div style="font-size:12px;color:var(--text-muted)">Animation Preview</div></div>
    </div>
    <div style="display:flex;gap:20px;flex-wrap:wrap;align-items:flex-start">
      <div style="flex:0 0 180px;display:flex;flex-direction:column;gap:10px;align-items:center">
        <div class="al-preview-stage bs-anim-stage" style="display:flex;align-items:center;justify-content:center">
          <div class="bs-anim-stage-art ${_esc(preset.cssClass||'')}" id="alpm-art" style="font-size:64px">💀</div>
        </div>
        <button class="al-preview-replay" onclick="window._alPreviewModalReplay()"><span class="material-symbols-outlined">replay</span> Replay</button>
      </div>
      <div style="flex:1;min-width:200px">
        <div style="margin-bottom:12px"><div style="font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--text-muted);margin-bottom:5px">CSS Class</div>
          <code style="font-family:monospace;font-size:12px;color:var(--secondary);background:rgba(78,222,163,0.08);padding:5px 9px;border-radius:7px;border:1px solid rgba(78,222,163,0.18);display:block">${_esc(preset.cssClass||'(none)')}</code></div>
        <div style="margin-bottom:12px"><div style="font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--text-muted);margin-bottom:5px">Target Slots</div>
          <div style="display:flex;gap:6px;flex-wrap:wrap">
            ${(preset.targets&&preset.targets.length ? preset.targets : ['universal']).map(t=>`<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 9px;border-radius:7px;background:rgba(78,222,163,0.1);border:1px solid rgba(78,222,163,0.2);font-size:11px;font-weight:700;color:var(--secondary)"><span class="material-symbols-outlined" style="font-size:12px">${TARGET_ICONS[t]||'animation'}</span>${t}</span>`).join('')}
          </div></div>
        ${preset.description ? `<div style="font-size:12px;color:var(--text-muted);line-height:1.6">${_esc(preset.description)}</div>` : ''}
        ${preset.tags&&preset.tags.length ? `<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:10px">${preset.tags.map(t=>`<span class="al-card-tag">${_esc(t)}</span>`).join('')}</div>` : ''}
      </div>
    </div>
    <div style="display:flex;gap:10px;margin-top:20px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Close</button>
      <button class="btn btn-primary" style="flex:1;font-family:var(--fh);font-weight:800" onclick="closeModalForce();window._alOpenEdit('${_esc(id)}')">${preset.builtin?'Duplicate & Customize':'Edit Preset'}</button>
    </div>
  </div>`, 'sm');
};

window._alPreviewModalReplay = function () {
  const art = document.getElementById('alpm-art'); if (!art) return;
  const cls = art.className; art.className = 'bs-anim-stage-art'; void art.offsetWidth; art.className = cls;
};

// ── Create / Edit form ────────────────────────────────────────────────────────

function _alRenderFormModal(isEdit) {
  const d = _alDraft;
  showModal(`<div>
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:20px">
      <div style="width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,rgba(78,222,163,0.25),rgba(139,92,246,0.15));border:1px solid rgba(78,222,163,0.35);display:flex;align-items:center;justify-content:center;font-size:20px">${isEdit?'✏️':'➕'}</div>
      <div><div class="modal-h2" style="margin-bottom:2px">${isEdit?'Edit Animation Preset':'New Animation Preset'}</div><div style="font-size:12px;color:var(--text-muted)">Define a reusable CSS animation preset for boss states.</div></div>
    </div>
    <div class="al-form-layout">
      <div class="al-form-col">
        <div class="form-group" style="margin-bottom:12px"><label class="form-label">Preset Name *</label>
          <input type="text" id="al-f-name" value="${_esc(d.name||'')}" placeholder="e.g. Inferno Pulse" style="width:100%" oninput="window._alDraft.name=this.value;document.getElementById('al-f-name-err').style.display='none'">
          <div class="field-err" id="al-f-name-err" style="display:none">Name is required.</div></div>
        <div class="form-group" style="margin-bottom:12px"><label class="form-label">Description</label>
          <input type="text" id="al-f-desc" value="${_esc(d.description||'')}" placeholder="Short description" style="width:100%" oninput="window._alDraft.description=this.value"></div>
        <div class="form-group" style="margin-bottom:12px"><label class="form-label">CSS Class *</label>
          <input type="text" id="al-f-css" value="${_esc(d.cssClass||'')}" placeholder="e.g. bs-anim-play-idle-float" style="width:100%;font-family:monospace;font-size:12px" oninput="window._alDraft.cssClass=this.value.trim();document.getElementById('al-f-css-err').style.display='none';window._alFormPreviewRefresh()">
          <div class="field-err" id="al-f-css-err" style="display:none">CSS class is required.</div>
          <div style="font-size:10px;color:var(--text-muted);margin-top:4px">Applied to the artwork element. Built-in classes: <code>bs-anim-play-*</code></div></div>
        <div class="form-group" style="margin-bottom:12px"><label class="form-label">Tags (comma-separated)</label>
          <input type="text" id="al-f-tags" value="${_esc((d.tags||[]).join(', '))}" placeholder="e.g. fire, loop" style="width:100%" oninput="window._alDraft.tags=this.value.split(',').map(t=>t.trim()).filter(Boolean)"></div>
        <div class="form-group" style="margin-bottom:0"><label class="form-label">Target Slots</label>
          <div class="al-target-grid" id="al-f-targets">
            ${AL_TARGET_OPTIONS.map(t=>`<button type="button" class="al-target-btn ${(d.targets||[]).includes(t.key)?'sel':''}" onclick="window._alToggleTarget('${t.key}')"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:middle">${t.icon}</span> ${t.label}</button>`).join('')}
          </div>
          <div style="font-size:10px;color:var(--text-muted);margin-top:4px">Leave all unselected to allow any slot.</div></div>
      </div>
      <div class="al-preview-col">
        <div class="al-preview-stage bs-anim-stage" style="display:flex;align-items:center;justify-content:center">
          <div class="bs-anim-stage-art ${_esc(d.cssClass||'')}" id="al-f-preview-art" style="font-size:64px">💀</div>
        </div>
        <button type="button" class="al-preview-replay" onclick="window._alFormPreviewRefresh()"><span class="material-symbols-outlined">replay</span> Replay</button>
      </div>
    </div>
    <div style="display:flex;gap:10px;margin-top:20px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button>
      <button class="btn btn-primary" style="flex:2;font-family:var(--fh);font-weight:800" onclick="window._alSaveForm()">${isEdit?'Save Changes':'Create Preset'}</button>
    </div>
  </div>`, 'md');
}

window._alOpenCreate = function () {
  _alDraft = { id:'al_'+Date.now()+'_'+Math.random().toString(36).slice(2,6), name:'', description:'', cssClass:'', targets:[], tags:[], builtin:false, createdAt:Date.now(), updatedAt:Date.now() };
  _alRenderFormModal(false);
};

window._alOpenEdit = function (id) {
  const preset = alGet(id); if (!preset) { toast('❌ Preset not found', '#ffb4ab'); return; }
  _alDraft = preset.builtin
    ? Object.assign({}, preset, { id:'al_'+Date.now()+'_'+Math.random().toString(36).slice(2,6), name:preset.name+' (Custom)', builtin:false, createdAt:Date.now(), updatedAt:Date.now() })
    : JSON.parse(JSON.stringify(preset));
  _alRenderFormModal(!preset.builtin);
};

window._alToggleTarget = function (key) {
  if (!_alDraft) return;
  _alDraft.targets = _alDraft.targets || [];
  const idx = _alDraft.targets.indexOf(key);
  if (idx >= 0) _alDraft.targets.splice(idx, 1); else _alDraft.targets.push(key);
  const grid = document.getElementById('al-f-targets');
  if (grid) grid.innerHTML = AL_TARGET_OPTIONS.map(t=>`<button type="button" class="al-target-btn ${(_alDraft.targets||[]).includes(t.key)?'sel':''}" onclick="window._alToggleTarget('${t.key}')"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:middle">${t.icon}</span> ${t.label}</button>`).join('');
};

window._alFormPreviewRefresh = function () {
  const art = document.getElementById('al-f-preview-art'); if (!art) return;
  const cls = (_alDraft && _alDraft.cssClass) || '';
  art.className = 'bs-anim-stage-art'; void art.offsetWidth; art.className = 'bs-anim-stage-art ' + cls;
};

window._alSaveForm = function () {
  if (!_alDraft) { toast('❌ No draft', '#ffb4ab'); return; }
  const name = (document.getElementById('al-f-name')?.value || '').trim();
  const css  = (document.getElementById('al-f-css')?.value  || '').trim();
  if (!name) { const e = document.getElementById('al-f-name-err'); if (e) e.style.display = 'block'; return; }
  if (!css)  { const e = document.getElementById('al-f-css-err');  if (e) e.style.display = 'block'; return; }
  _alDraft.name        = name;
  _alDraft.description = (document.getElementById('al-f-desc')?.value || '').trim();
  _alDraft.cssClass    = css;
  _alDraft.tags        = (document.getElementById('al-f-tags')?.value || '').split(',').map(t => t.trim()).filter(Boolean);
  _alDraft.updatedAt   = Date.now();
  _alUpsert(_alDraft);
  closeModalForce();
  toast(`✅ Preset "${_esc(_alDraft.name)}" saved`, '#4edea3');
  _alDraft = null;
  _alRefreshGrid();
};

// ── Delete ────────────────────────────────────────────────────────────────────

window._alConfirmDelete = function (id) {
  const preset = alGet(id); if (!preset) { toast('❌ Not found', '#ffb4ab'); return; }
  showModal(`<div style="text-align:center;padding:8px 0">
    <div style="font-size:48px;margin-bottom:12px">⚠️</div>
    <div class="modal-h2" style="margin-bottom:8px">Delete Preset?</div>
    <div style="font-size:13px;color:var(--text-muted);margin-bottom:24px"><strong style="color:var(--on-surface)">${_esc(preset.name)}</strong> will be permanently removed. Any boss profiles referencing this preset will show the slot as unassigned.</div>
    <div style="display:flex;gap:10px"><button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button><button class="btn btn-danger" style="flex:1;font-family:var(--fh);font-weight:800" onclick="window._alDeleteConfirmed('${_esc(id)}')">Delete</button></div>
  </div>`, 'sm');
};

window._alDeleteConfirmed = function (id) {
  const preset = alGet(id);
  _alDeleteRecord(id);
  closeModalForce();
  toast(`🗑 "${preset?.name||'Preset'}" deleted`, '#ffb4ab');
  _alRefreshGrid();
};

// ── Search / filter ───────────────────────────────────────────────────────────

window._alSearchUpdate = function (val) {
  _alSearch = val;
  _alRefreshGrid();
  setTimeout(() => { const inp = document.getElementById('al-search-input'); if (inp) { inp.focus(); const l = inp.value.length; inp.setSelectionRange(l, l); } }, 0);
};

window._alSetFilter = function (filter) { _alFilter = filter; _alRefreshGrid(); };

// ── Public exports ────────────────────────────────────────────────────────────

window._alGet              = alGet;
window._alOptionsForTarget = alOptionsForTarget;
window._alRenderTabBody    = _alRenderTabBody;

Object.defineProperty(window, '_alDraft', {
  get () { return _alDraft; },
  set (v) { _alDraft = v; },
  configurable: true,
});

console.log('[EduQuest] boss-studio/animation-library.js loaded — 13 built-in presets, alGet, alOptionsForTarget, full CRUD registered.');

// ── Phase 7 (2026-08-10, session 7): explicit window exports ──
// These were previously implicit globals (bare top-level declarations,
// reachable to other files only via classic-script auto-attach-to-window
// behavior). Made explicit ahead of any real bundle/module scoping change
// — found by build/audit-window-exports.js, which checks every symbol with
// a real cross-file consumer, not just ones reachable from onclick markup.
// See PHASE7_WINDOW_EXPORT_AUDIT.md.
window.alGet = alGet;


/* ---- ./modules/boss-studio/bs_editor.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/boss-studio/editor.js
//  Full-screen Boss Profile Editor overlay — open/close, form rendering,
//  live preview sync, tool tabs, artwork upload/drag-drop, palette, save.
//  LOAD AFTER: storage.js, library.js
// ═══════════════════════════════════════════════════════════════════════════════

// ── Module state ──────────────────────────────────────────────────────────────
let _bsDirtyFlag = false;
let _bsToolTab   = 'identity'; // 'identity' | 'artwork' | 'animations' | 'theme'

// expose via closure bridge (library.js sets _bsDirty via window._bsDraft proxy)
Object.defineProperty(window, '_bsDirty', {
  get () { return _bsDirtyFlag; },
  set (v) { _bsDirtyFlag = v; },
  configurable: true,
});

// ── Colour utility ────────────────────────────────────────────────────────────

function _hexToRgba(hex, alpha) {
  const h = (hex || '#8b5cf6').replace('#', '');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}
window._hexToRgba = _hexToRgba;

// ── Open / close overlay ──────────────────────────────────────────────────────

window.bsOpenCreate = function () {
  window._bsDraft = bsvpBlank();
  _bsDirtyFlag    = false;
  _bsOpenEditorOverlay(false);
};

window.bsOpenEdit = function (id) {
  const boss = bsGet(id);
  if (!boss) { toast('❌ Boss not found', '#ffb4ab'); return; }
  window._bsDraft = JSON.parse(JSON.stringify(boss));
  _bsDirtyFlag    = false;
  _bsOpenEditorOverlay(true);
};

function _bsOpenEditorOverlay(isEdit) {
  const overlay = document.getElementById('bs-editor-overlay');
  if (!overlay) return;
  _bsUpdateEditorTitle(isEdit);
  _bsRenderFormModal(isEdit);
  window._bsSyncEditorPreview();
  overlay.classList.add('open');
  document.body.style.overflow = 'hidden';
}

function _bsUpdateEditorTitle(isEdit) {
  const titleEl  = document.getElementById('bs-eo-title');
  const dirtyDot = document.getElementById('bs-dirty-dot');
  const d        = window._bsDraft;
  if (!titleEl || !d) return;
  if (isEdit === undefined) isEdit = !!bsGet(d.id);
  const base = isEdit ? `Editing: ${d.name || 'Boss Profile'}` : 'New Boss Profile';
  titleEl.textContent = _bsDirtyFlag ? `${base} •` : base;
  titleEl.title       = _bsDirtyFlag ? 'Unsaved changes' : '';
  if (dirtyDot) dirtyDot.classList.toggle('visible', !!_bsDirtyFlag);
}

window._bsMarkDirty = function () {
  if (_bsDirtyFlag) return;
  _bsDirtyFlag = true;
  _bsUpdateEditorTitle();
};

window._bsCloseEditor = function () {
  if (_bsDirtyFlag) {
    showModal(`<div style="text-align:center;padding:8px 0">
      <div style="font-size:48px;margin-bottom:12px">⚠️</div>
      <div class="modal-h2" style="margin-bottom:8px">Discard Unsaved Changes?</div>
      <div style="font-size:13px;color:var(--text-muted);margin-bottom:24px">You have unsaved changes. Closing now will discard them.</div>
      <div style="display:flex;gap:10px">
        <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Keep Editing</button>
        <button class="btn btn-danger" style="flex:1;font-family:var(--fh);font-weight:800" onclick="closeModalForce();window._bsForceCloseEditor()">Discard Changes</button>
      </div>
    </div>`, 'sm');
    return;
  }
  window._bsForceCloseEditor();
};

window._bsForceCloseEditor = function () {
  const overlay = document.getElementById('bs-editor-overlay');
  if (overlay) overlay.classList.remove('open');
  document.body.style.overflow = '';
  window._bsDraft = null;
  _bsDirtyFlag    = false;
};

// ── Live preview sync ─────────────────────────────────────────────────────────

window._bsSyncEditorPreview = function () {
  const d = window._bsDraft; if (!d) return;
  const stageArt = document.getElementById('bsed-stage-art');
  if (stageArt) {
    if (d.artwork?.value) {
      stageArt.innerHTML = d.artwork.type === 'emoji'
        ? `<span style="font-size:88px">${_esc(d.artwork.value)}</span>`
        : `<img src="${_esc(d.artwork.value)}" style="max-width:80%;max-height:80%;object-fit:contain" onerror="this.outerHTML='<span style=\\'font-size:40px\\'>💀</span>'">`;
    } else {
      stageArt.innerHTML = `<span style="font-size:88px">💀</span>`;
    }
  }
  const theme  = d.visual?.themeColor || BS_DEFAULT_THEME;
  const aura   = d.visual?.auraColor  || BS_DEFAULT_AURA;
  const accent = d.visual?.cardAccent || BS_DEFAULT_ACCENT;
  const stage  = document.getElementById('bsed-main-stage');
  if (stage)  stage.style.setProperty('--bs-stage-glow', _hexToRgba(theme, 0.3));
  const hpFill = document.getElementById('bsed-hp-fill');
  if (hpFill) { hpFill.style.setProperty('--bs-hp-color', aura); hpFill.style.setProperty('--bs-hp-color2', theme); }
  const np = document.getElementById('bsed-nameplate');
  if (np) np.textContent = d.name || 'New Boss';
  ['idle', 'cast', 'hit', 'rage'].forEach(k => {
    const pip = document.getElementById(`bsed-pip-${k}`);
    if (pip) pip.classList.toggle('filled', !!(d.animations?.[k]));
    const btn = document.getElementById(`bsed-btn-${k}`);
    if (btn) { const assigned = d.animations?.[k] && typeof window._alGet === 'function' && window._alGet(d.animations[k]); btn.disabled = !assigned; btn.style.opacity = assigned ? '1' : '0.5'; if (!assigned) btn.classList.remove('active'); }
  });
  const tagDiv = document.getElementById('bsed-tag-preview');
  if (tagDiv) tagDiv.innerHTML = (d.tags || []).slice(0, 5).map(t => `<span class="bs-card-tag" style="border-color:${_cssColor(theme)}55;color:${_cssColor(theme)}">${_esc(t)}</span>`).join('');
  const setTS = (id, valId, val) => { const s = document.getElementById(id); if (s) s.style.background = val; const v = document.getElementById(valId); if (v) v.textContent = val; };
  setTS('bsed-ts-theme', 'bsed-ts-theme-val', theme);
  setTS('bsed-ts-aura',  'bsed-ts-aura-val',  aura);
  setTS('bsed-ts-accent','bsed-ts-accent-val', accent);
  _bsUpdateEditorTitle();
  _bsUpdateReadiness();
};

window._bsEditorPlayState = function (stateKey) {
  const d = window._bsDraft; if (!d) return;
  const animId = d.animations?.[stateKey];
  const preset = animId && typeof window._alGet === 'function' ? window._alGet(animId) : null;
  if (!preset) { const btn = document.getElementById(`bsed-btn-${stateKey}`); if (btn) { btn.style.transform = 'scale(0.9)'; setTimeout(() => btn.style.transform = '', 150); } return; }
  const art = document.getElementById('bsed-stage-art'); if (!art) return;
  const useArt = (stateKey === 'rage' && d.rageArtwork?.value) ? d.rageArtwork : d.artwork;
  if (useArt?.value) art.innerHTML = useArt.type === 'emoji' ? `<span style="font-size:88px">${_esc(useArt.value)}</span>` : `<img src="${_esc(useArt.value)}" style="max-width:80%;max-height:80%;object-fit:contain">`;
  const stageWrap = document.getElementById('bsed-main-stage');
  if (stageWrap) stageWrap.style.setProperty('--bs-stage-glow', stateKey === 'rage' ? 'rgba(236,72,153,0.4)' : _hexToRgba(d.visual?.themeColor || BS_DEFAULT_THEME, 0.3));
  art.className = 'bsed-stage-art ' + (preset.cssClass || '');
  setTimeout(() => { if (art) art.className = 'bsed-stage-art'; }, 2000);
  ['idle', 'cast', 'hit', 'rage'].forEach(k => { const btn = document.getElementById(`bsed-btn-${k}`); if (btn) btn.classList.toggle('active', k === stateKey); });
};

// ── Tool tab switching ────────────────────────────────────────────────────────

window._bsSetToolTab = function (tab) {
  _bsToolTab = tab;
  document.querySelectorAll('.bs-tool-tab').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === tab));
  document.querySelectorAll('.bsf-tool-panel').forEach(panel => { panel.style.display = panel.dataset.panel === tab ? '' : 'none'; });
};

// ── Slot stage renderers ──────────────────────────────────────────────────────
// RESTORED: _bsSlotStageArt was missing entirely (its only job is rendering the
// small static glyph inside each animation slot's mini preview stage).

/** Render the small static glyph used inside a slot preview stage, using the
 *  boss's currently-configured primary artwork (or rage artwork for the rage slot). */
function _bsSlotStageArt(key){
  const d = window._bsDraft || {};
  const art = (key==='rage' && d.rageArtwork && d.rageArtwork.value) ? d.rageArtwork : d.artwork;
  if(!art || !art.value){
    return `<span class="material-symbols-outlined" style="font-size:20px;color:rgba(255,255,255,0.2)">image_not_supported</span>`;
  }
  if(art.type==='emoji'){
    return _esc(art.value);
  }
  return `<img src="${_esc(art.value)}" onerror="this.style.display='none'">`;
}
window._bsSlotStageArt = _bsSlotStageArt;

/** Refresh all four animation-slot mini stages (used when boss artwork changes). */
window._bsRefreshAllSlotStages = function(){
  ['idle','cast','hit','rage'].forEach(key=>window._bsRefreshSlotStage(key));
};

/** Refresh a single animation slot's mini preview stage. If `forceStatic` is
 *  true (used on initial form render), the animation is not played — the
 *  stage simply shows the artwork at rest. */
window._bsRefreshSlotStage = function(key, forceStatic){
  const d = window._bsDraft; if(!d) return;
  const stage = document.getElementById(`bsf-anim-stage-${key}`);
  const btn   = document.getElementById(`bsf-anim-preview-${key}`);
  if(!stage) return;
  const animId = d.animations ? d.animations[key] : null;
  const anim    = animId && typeof window._alGet === 'function' ? window._alGet(animId) : null;
  const cls     = (!forceStatic && anim) ? (anim.cssClass||'') : '';
  stage.innerHTML = `<div class="bs-anim-stage-art ${cls}">${_bsSlotStageArt(key)}</div>`;
  if(btn){
    btn.disabled = !animId;
    if(forceStatic || !btn.dataset.playing) btn.dataset.playing = '';
    btn.innerHTML = `<span class="material-symbols-outlined">play_arrow</span>Preview`;
  }
};

/** Toggle play/pause of a slot's assigned animation preview. */
window._bsToggleSlotPreview = function(key){
  const d = window._bsDraft; if(!d) return;
  const stage = document.getElementById(`bsf-anim-stage-${key}`);
  const btn   = document.getElementById(`bsf-anim-preview-${key}`);
  if(!stage || !btn) return;
  const animId = d.animations ? d.animations[key] : null;
  if(!animId) return;
  const anim = typeof window._alGet === 'function' ? window._alGet(animId) : null;
  const art  = stage.querySelector('.bs-anim-stage-art');
  if(!art) return;
  const playing = btn.dataset.playing === '1';
  if(playing){
    art.className = 'bs-anim-stage-art';
    btn.dataset.playing = '';
    btn.innerHTML = `<span class="material-symbols-outlined">play_arrow</span>Preview`;
  } else {
    art.className = 'bs-anim-stage-art ' + ((anim&&anim.cssClass)||'');
    btn.dataset.playing = '1';
    btn.innerHTML = `<span class="material-symbols-outlined">pause</span>Pause`;
  }
};

// ── Artwork tab ───────────────────────────────────────────────────────────────
// RESTORED: the original toggles persistent show/hide wrapper divs
// (#bsf-${which}-emoji-wrap / -url-wrap / -upload-wrap) that are rendered once
// by _bsRenderFormModal, rather than rebuilding innerHTML from scratch on every
// tab switch. This preserves user-entered values across tab switches without
// re-render flicker, and is required for the CSS in boss-studio.css (.bsf-*
// classes already present in the stylesheet) to apply correctly.

const BS_EMOJI_PRESETS = ['💀','👾','🐉','👹','🧙','🦹','🤖','👺','🧿','🌑','🔱','👁️','🌋','⚡','🦴','🧨','🔥','💜','🫀','🧠'];
window.BS_EMOJI_PRESETS = BS_EMOJI_PRESETS;

window._bsArtTab = function(which, type){
  const d = window._bsDraft; if(!d) return;
  const emojiWrap  = document.getElementById(`bsf-${which}-emoji-wrap`);
  const urlWrap    = document.getElementById(`bsf-${which}-url-wrap`);
  const uploadWrap = document.getElementById(`bsf-${which}-upload-wrap`);
  const btnEmoji   = document.getElementById(`bsf-${which}-tab-emoji`);
  const btnUrl     = document.getElementById(`bsf-${which}-tab-url`);
  const btnUpload  = document.getElementById(`bsf-${which}-tab-upload`);
  if(!emojiWrap||!urlWrap) return;

  if(emojiWrap)  emojiWrap.style.display  = type==='emoji'  ?'block':'none';
  if(urlWrap)    urlWrap.style.display    = type==='url'    ?'block':'none';
  if(uploadWrap) uploadWrap.style.display = type==='upload' ?'block':'none';

  btnEmoji &&(btnEmoji.className ='bs-filter-btn'+(type==='emoji' ?' active':''));
  btnUrl   &&(btnUrl.className   ='bs-filter-btn'+(type==='url'   ?' active':''));
  btnUpload&&(btnUpload.className='bs-filter-btn'+(type==='upload'?' active':''));

  // Update preview bg for transparent support
  const prevId = which==='primary'?'bsf-art-preview':'bsf-rage-preview';
  const prev = document.getElementById(prevId);
  if(prev){
    if(type==='upload') prev.classList.add('transparent-bg');
    else prev.classList.remove('transparent-bg');
  }

  // sync draft — keep existing value when switching tabs so user doesn't lose data
  if(which==='primary'){
    const curVal = type==='emoji'
      ? (document.getElementById('bsf-art-emoji')?.value||'💀')
      : type==='url'
        ? (document.getElementById('bsf-art-url')?.value||'')
        : (d.artwork&&d.artwork.type==='upload'?d.artwork.value:'');
    d.artwork = { type, value: curVal };
    if(type==='emoji'){
      const emoji = document.getElementById('bsf-art-emoji')?.value||'💀';
      if(prev) prev.innerHTML=`<span id="bsf-art-preview-emoji">${emoji}</span>`;
    } else if(type==='url'){
      const url = document.getElementById('bsf-art-url')?.value||'';
      window._bsUpdatePreviewImg('primary', url);
    } else {
      window._bsRefreshAllSlotStages();
      window._bsSyncEditorPreview();
    }
  } else {
    const curVal = type==='emoji'
      ? (document.getElementById('bsf-rage-emoji')?.value||null)
      : type==='url'
        ? (document.getElementById('bsf-rage-url')?.value||null)
        : (d.rageArtwork&&d.rageArtwork.type==='upload'?d.rageArtwork.value:null);
    d.rageArtwork = { type, value: curVal };
    if(type==='emoji'){
      const emoji = document.getElementById('bsf-rage-emoji')?.value||'';
      if(prev) prev.innerHTML = emoji
        ? `<span>${emoji}</span>`
        : `<span class="material-symbols-outlined" style="font-size:24px;color:rgba(255,255,255,0.15)">add_photo_alternate</span>`;
    } else if(type==='url'){
      const url = document.getElementById('bsf-rage-url')?.value||'';
      window._bsUpdatePreviewImg('rage', url);
    } else {
      window._bsRefreshAllSlotStages();
      window._bsSyncEditorPreview();
    }
  }
  window._bsMarkDirty();
  window._bsSyncEditorPreview();
};

window._bsPickEmoji = function(which, emoji){
  const d = window._bsDraft; if(!d) return;
  if(which==='primary'){
    d.artwork = { type:'emoji', value:emoji };
    const inp = document.getElementById('bsf-art-emoji');
    if(inp) inp.value = emoji;
    const prev = document.getElementById('bsf-art-preview');
    if(prev) prev.innerHTML = `<span id="bsf-art-preview-emoji">${emoji}</span>`;
    // update selected state on emoji buttons
    document.querySelectorAll('#bsf-primary-emoji-wrap .bsf-emoji-btn').forEach(b=>{
      b.classList.toggle('sel', b.textContent===emoji);
    });
  } else {
    d.rageArtwork = { type:'emoji', value:emoji };
    const inp = document.getElementById('bsf-rage-emoji');
    if(inp) inp.value = emoji;
    const prev = document.getElementById('bsf-rage-preview');
    if(prev) prev.innerHTML = `<span>${emoji}</span>`;
    document.querySelectorAll('#bsf-rage-emoji-wrap .bsf-emoji-btn').forEach(b=>{
      b.classList.toggle('sel', b.textContent===emoji);
    });
  }
  window._bsRefreshAllSlotStages();
  window._bsMarkDirty();
  window._bsSyncEditorPreview();
};

window._bsUpdatePreviewImg = function(which, url){
  const d = window._bsDraft; if(!d) return;
  const prevId = which==='primary'?'bsf-art-preview':'bsf-rage-preview';
  const prev = document.getElementById(prevId);
  if(!prev) return;
  if(!url){
    if(which==='primary'){
      d.artwork = { type:'url', value:'' };
    } else {
      d.rageArtwork = { type:'url', value:'' };
    }
    prev.innerHTML = '<span class="material-symbols-outlined" style="font-size:24px;color:rgba(255,255,255,0.15)">add_photo_alternate</span>';
    window._bsRefreshAllSlotStages();
    window._bsMarkDirty();
    window._bsSyncEditorPreview();
    return;
  }
  if(which==='primary'){
    d.artwork = { type:'url', value:url };
  } else {
    d.rageArtwork = { type:'url', value:url };
  }
  prev.innerHTML=`<img src="${_esc(url)}" style="width:100%;height:100%;object-fit:contain" onerror="this.outerHTML='<span class=\\'material-symbols-outlined\\'style=\\'font-size:24px;color:rgba(255,255,255,0.15)\\'>broken_image</span>'">`;
  window._bsRefreshAllSlotStages();
  window._bsMarkDirty();
  window._bsSyncEditorPreview();
};

// ── File upload handlers ───────────────────────────────────────────────────────

window._bsHandleFileUpload = function(which, inputEl){
  const file = inputEl && inputEl.files && inputEl.files[0];
  if(!file) return;
  const MAX = 3 * 1024 * 1024; // 3 MB
  if(file.size > MAX){
    toast('❌ File is too large (max 3 MB)', '#ffb4ab');
    if(inputEl && inputEl.value !== undefined) inputEl.value = '';
    return;
  }
  const reader = new FileReader();
  reader.onload = function(e){
    const dataUrl = e.target.result;
    const d = window._bsDraft; if(!d) return;
    if(which === 'primary'){
      d.artwork = { type:'upload', value: dataUrl };
      const prev = document.getElementById('bsf-art-preview');
      if(prev){
        prev.classList.add('transparent-bg');
        prev.innerHTML = `<img src="${dataUrl}" style="width:100%;height:100%;object-fit:contain">`;
      }
      const chosen     = document.getElementById('bsf-art-chosen');
      const chosenName = document.getElementById('bsf-art-chosen-name');
      if(chosen)     chosen.style.display = 'flex';
      if(chosenName) chosenName.textContent = file.name;
    } else {
      d.rageArtwork = { type:'upload', value: dataUrl };
      const prev = document.getElementById('bsf-rage-preview');
      if(prev){
        prev.classList.add('transparent-bg');
        prev.innerHTML = `<img src="${dataUrl}" style="width:100%;height:100%;object-fit:contain">`;
      }
      const chosen     = document.getElementById('bsf-rage-chosen');
      const chosenName = document.getElementById('bsf-rage-chosen-name');
      if(chosen)     chosen.style.display = 'flex';
      if(chosenName) chosenName.textContent = file.name;
    }
    window._bsRefreshAllSlotStages();
    window._bsMarkDirty();
    window._bsSyncEditorPreview();
  };
  reader.onerror = function(){
    toast('❌ Could not read file', '#ffb4ab');
  };
  reader.readAsDataURL(file);
};

window._bsDragOver = function(event, zoneId){
  event.preventDefault();
  event.stopPropagation();
  const zone = document.getElementById(zoneId);
  if(zone) zone.classList.add('drag-over');
};

window._bsDragLeave = function(zoneId){
  const zone = document.getElementById(zoneId);
  if(zone) zone.classList.remove('drag-over');
};

window._bsDropFile = function(event, which, zoneId){
  event.preventDefault();
  event.stopPropagation();
  const zone = document.getElementById(zoneId);
  if(zone) zone.classList.remove('drag-over');
  const file = event.dataTransfer && event.dataTransfer.files && event.dataTransfer.files[0];
  if(!file) return;
  window._bsHandleFileUpload(which, { files: [file] });
};

window._bsClearUpload = function(which){
  const d = window._bsDraft; if(!d) return;
  if(which === 'primary'){
    d.artwork = { type:'emoji', value:'💀' };
    const fileEl = document.getElementById('bsf-art-file');
    if(fileEl) fileEl.value = '';
    const chosen = document.getElementById('bsf-art-chosen');
    if(chosen) chosen.style.display = 'none';
    const prev = document.getElementById('bsf-art-preview');
    if(prev){
      prev.classList.remove('transparent-bg');
      prev.innerHTML = `<span id="bsf-art-preview-emoji">💀</span>`;
    }
    const emojiInp = document.getElementById('bsf-art-emoji');
    if(emojiInp) emojiInp.value = '💀';
    window._bsArtTab('primary', 'emoji');
  } else {
    d.rageArtwork = { type:null, value:null };
    const fileEl = document.getElementById('bsf-rage-file');
    if(fileEl) fileEl.value = '';
    const chosen = document.getElementById('bsf-rage-chosen');
    if(chosen) chosen.style.display = 'none';
    const prev = document.getElementById('bsf-rage-preview');
    if(prev){
      prev.classList.remove('transparent-bg');
      prev.innerHTML = `<span class="material-symbols-outlined" style="font-size:24px;color:rgba(255,255,255,0.15)">add_photo_alternate</span>`;
    }
    window._bsArtTab('rage', 'emoji');
  }
  window._bsRefreshAllSlotStages();
  window._bsMarkDirty();
  window._bsSyncEditorPreview();
};

// ── Palette ───────────────────────────────────────────────────────────────────

window._bsApplyPaletteIdx = function (idx) {
  const palette = (BS_PALETTES || window.BS_PALETTES || [])[idx]; if (!palette) return;
  window._bsApplyPalette(palette);
};

window._bsApplyPalette = function (palette) {
  const d = window._bsDraft; if (!d || !palette) return;
  if (!d.visual) d.visual = {};
  d.visual.themeColor = palette.theme;
  d.visual.auraColor  = palette.aura;
  d.visual.cardAccent = palette.accent;
  window._bsMarkDirty();
  window._bsSyncEditorPreview();
  window._bsDeactivatePaletteSwatches();
  // Sync colour pickers, swatch dots, and hex labels
  [['theme', palette.theme], ['aura', palette.aura], ['accent', palette.accent]].forEach(([key, val]) => {
    const input = document.getElementById(`bsf-color-${key}`);
    const dot   = document.getElementById(`bsf-swatch-${key}`);
    const hex   = document.getElementById(`bsf-color-${key}-hex`);
    if (input) input.value = val;
    if (dot)   dot.style.background = val;
    if (hex)   hex.textContent = val;
  });
};

window._bsDeactivatePaletteSwatches = function () {
  document.querySelectorAll('.bsf-palette-swatch').forEach(s => s.classList.remove('active'));
};

// ── Readiness score ────────────────────────────────────────────────────────────
// FIXED: this previously targeted #bsed-readiness-bar / #bsed-readiness-text,
// neither of which exist in the overlay HTML (the real elements are
// #bs-readiness-pill / #bs-readiness-label) — so the readiness indicator was
// silently doing nothing. Restored the original's 7-factor scoring formula
// and pill/icon/label update logic.

/** Compute and display a readiness score for the current boss draft. */
function _bsUpdateReadiness(){
  const d = window._bsDraft; if(!d) return;
  const pill = document.getElementById('bs-readiness-pill');
  const label = document.getElementById('bs-readiness-label');
  if(!pill||!label) return;

  let score = 0;
  if(d.name && d.name.trim()) score += 25;                          // has name
  if(d.artwork && d.artwork.value) score += 25;                     // has artwork
  if(d.lore && d.lore.trim()) score += 10;                         // has lore
  if(d.visual && d.visual.themeColor && d.visual.themeColor !== BS_DEFAULT_THEME) score += 10; // custom theme
  const animCount = ['idle','cast','hit','rage'].filter(k => d.animations && d.animations[k]).length;
  score += animCount * 7;                                            // up to 28 for all 4 slots
  if(d.tags && d.tags.length > 0) score += 5;                      // has tags

  score = Math.min(100, score);
  let cls, icon, text;
  if(score >= 70){ cls='high'; icon='check_circle'; text=`Ready · ${score}%`; }
  else if(score >= 35){ cls='mid'; icon='pending'; text=`In Progress · ${score}%`; }
  else { cls='low'; icon='radio_button_unchecked'; text=`Not Ready · ${score}%`; }

  pill.className = `bs-bar-readiness ${cls}`;
  const iconEl = pill.querySelector('.material-symbols-outlined');
  if(iconEl) iconEl.textContent = icon;
  label.textContent = text;
}

// ── Save form ─────────────────────────────────────────────────────────────────

window.bsSaveForm = async function () {
  const d = window._bsDraft; if (!d) return;
  // Read all form fields into draft
  const getName    = id => (document.getElementById(id)?.value || '').trim();
  d.name           = getName('bsf-name')  || d.name;
  d.description    = getName('bsf-desc')  || d.description || '';
  d.lore           = getName('bsf-lore')  || d.lore        || '';
  d.tags           = (getName('bsf-tags') || (d.tags || []).join(', ')).split(',').map(t => t.trim()).filter(Boolean);
  if (!d.name) {
    toast('❌ Boss name is required', '#ffb4ab');
    const errEl = document.getElementById('bsf-name-err'); if (errEl) errEl.style.display = '';
    window._bsSetToolTab('identity');
    return;
  }
  if (!d.visual) d.visual = {};
  const tc = document.getElementById('bsf-color-theme');  if (tc) d.visual.themeColor = tc.value;
  const ac = document.getElementById('bsf-color-aura');   if (ac) d.visual.auraColor  = ac.value;
  const cc = document.getElementById('bsf-color-accent'); if (cc) d.visual.cardAccent = cc.value;

  const savingToast = toast('💾 Saving...', '#d0bcff', 30000);
  try {
    await bsUpsertAsync(d);
    if (savingToast && typeof savingToast.dismiss === 'function') savingToast.dismiss();
    toast(`✅ "${_esc(d.name)}" saved!`, '#4edea3');
    _bsDirtyFlag = false;
    window._bsForceCloseEditor();
    bsLoad();
    window._bsRefreshLibrary();
  } catch (err) {
    console.error('[BossStudio] Save failed:', err);
    toast('❌ Save failed — check console', '#ffb4ab');
  }
};

