        if (!WBC || !WBC.refreshInterval) { clearInterval(_wbpPoll); return; }
        const found = (typeof wbcGetActiveBoss === 'function') && wbcGetActiveBoss();
        if (!found) { clearInterval(_wbpPoll); return; }
