/* ---- ./modules/world-boss/battle-overlay.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/world-boss/battle-overlay.js
//  Full-screen boss battle overlay (WBE), orientation prompt, random spawn-loop
//  replacement, and minion-inject monkey-patches.
//
//  LOAD AFTER: student-page.js, minions.js, leaderboard.js
//  (Monkey-patches _wbcStartLiveRefresh, renderStudentWorldBoss,
//   wbmStopSpawnLoop, wbmStartSpawnLoop — all must exist before this runs.)
// ═══════════════════════════════════════════════════════════════════════════════

// ── Patch 1: _wbcStartLiveRefresh — also starts minion loop ──────────────────
;(function () {
  var _orig = _wbcStartLiveRefresh;
  _wbcStartLiveRefresh = function () {
    _orig();
    var found = wbcGetActiveBoss();
    if (found && currentRole === 'student') {
      wbmStartSpawnLoop(found.idx);
      var rec = wbmMyHp(found.idx);
      if (rec.isKO) wbmStartKoTimer(found.idx);
      var minion = wbmGetCurrentMinion(found.idx);
      if (minion) wbmStartMinionCountdown(found.idx);
    }
  };
})();

// ── Patch 2: renderStudentWorldBoss — injects HP hearts + minion sections ─────
;(function () {
  var _orig = renderStudentWorldBoss;
  renderStudentWorldBoss = function () {
    wbmStopSpawnLoop();
    _orig();
    var found = wbcGetActiveBoss();
    if (!found || currentRole !== 'student') return;
    var boss = found.boss, idx = found.idx;
    var s = wbmSettings(boss);
    if (!s.enabled) return;
    var combatArea = document.getElementById('wbc-combat-area');
    if (!combatArea) return;
    var myRec = wbcMyRecord(idx);
    if (!myRec) return;

    // HP bar above combat area
    var hpDiv = document.createElement('div');
    hpDiv.id = 'wbm-hp-bar-section';
    hpDiv.innerHTML = wbmRenderHpBar(idx);
    combatArea.parentNode.insertBefore(hpDiv, combatArea);

    // Minion / KO section above combat area
    var minionDiv = document.createElement('div');
    minionDiv.id = 'wbm-minion-section';
    var rec = wbmMyHp(idx);
    if (rec.isKO) {
      minionDiv.innerHTML = wbmRenderKOSection(idx);
    } else {
      var minion = wbmGetCurrentMinion(idx);
      if (minion) minionDiv.innerHTML = wbmRenderMinionSection(idx);
    }
    combatArea.parentNode.insertBefore(minionDiv, combatArea);
  };
})();

// [Phase 1 cleanup] Patch 3 (a wbcJoinBoss wrapper adding hp/maxHp/isKO on
// first join) used to live here. Removed 2026-07-21 — raid-flow.js's own
// window.wbcJoinBoss (loaded after this file) unconditionally overwrote
// this patch's result anyway, and that version already sets hp/maxHp/isKO
// inline at participant creation, making this patch's job redundant even
// on top of being unreachable. See the refactor log's Tier-1 debt-review
// entry for the verification behind this deletion.

// ── Patch 4: replace wbmStopSpawnLoop + wbmStartSpawnLoop with random-delay ──
;(function () {
  wbmStopSpawnLoop = function () {
    if (WBM.spawnInterval)  { clearTimeout(WBM.spawnInterval);  WBM.spawnInterval  = null; }
    if (WBM.countdownTimer) { clearInterval(WBM.countdownTimer); WBM.countdownTimer = null; }
    if (WBM.koReviveTimer)  { clearInterval(WBM.koReviveTimer);  WBM.koReviveTimer  = null; }
  };

  wbmStartSpawnLoop = function (bossIdx) {
    wbmStopSpawnLoop();
    var scheduleNext = function () {
      var boss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[bossIdx];
      if (!boss || boss.status !== 'active') return;
      var s = wbmSettings(boss);
      if (!s.enabled) return;
      var delay = wbeRandomDelay(s);
      WBM.spawnInterval = setTimeout(function () {
        var liveBoss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[bossIdx];
        if (!liveBoss || liveBoss.status !== 'active') return;
        var liveSettings = wbmSettings(liveBoss);
        if (!liveSettings.enabled) return;
        wbmPruneExpiredMinions(bossIdx);
        wbmSpawnMinion(bossIdx);
        if (currentRole === 'student') {
          _wbmRefreshBattleArea(bossIdx);
          var minion = wbmGetCurrentMinion(bossIdx);
          if (minion) wbmStartMinionCountdown(bossIdx);
        }
        scheduleNext();
      }, delay);
    };
    scheduleNext();
  };
})();

// ── WBE state ─────────────────────────────────────────────────────────────────

var WBE = { activeBossIdx: null };

// ── Random delay helper ───────────────────────────────────────────────────────

function wbeRandomDelay(settings) {
  var base = Math.max(10, parseInt(settings.spawnIntervalSec) || 35) * 1000;
  var min  = Math.max(4500, base * 0.45);
  var max  = Math.max(min + 1000, base * 1.35);
  return Math.round(min + Math.random() * (max - min));
}

// ── Spark field particle background ──────────────────────────────────────────

function wbeSparkField() {
  return '<div class="wbe-sparks">' + Array.from({ length: 34 }, function (_, i) {
    var left  = Math.round(Math.random() * 100);
    var dur   = (5 + Math.random() * 8).toFixed(2);
    var delay = (Math.random() * -8).toFixed(2);
    var drift = Math.round((Math.random() - 0.5) * 120);
    return '<span class="wbe-spark" style="left:' + left + '%;animation-duration:' + dur + 's;animation-delay:' + delay + 's;--x:' + drift + 'px"></span>';
  }).join('') + '</div>';
}

// ── Intro "skip" handler ──────────────────────────────────────────────────────

function wbeFinishIntro(bossIdx) {
  AppStore.updateState(function (draft) {
    var p = ((draft.bossParticipants || {})[bossIdx] || {})[currentUser.id];
    if (p) p.bossIntroSeen = true;
  }, { type: 'world-boss:intro-seen', payload: { bossIdx, studentId: currentUser.id } });
  renderStudentWorldBoss();
}

// ── Question panel (used inside wbeRenderFullBattle) ─────────────────────────

function wbeQuestionPanel(bossIdx, boss, myRec) {
  var questions = wbcGetBossQuestions(boss);
  var myQIdx    = myRec ? (myRec.lastQIdx || 0) : 0;
  var allDone   = questions.length > 0 && myQIdx >= questions.length;

  if (myRec && myRec.isKO) {
    return '<div class="wbc-panel wbe-question" id="wbc-combat-area" style="text-align:center">' +
      '<div style="font-size:42px;margin-bottom:10px">KO</div>' +
      '<div style="font-family:var(--fh);font-size:22px;font-weight:900;color:#ef4444;margin-bottom:8px">You are knocked out</div>' +
      '<div style="font-size:13px;color:var(--text-muted)">Revive before you can damage the boss again.</div>' +
      '</div>';
  }
  if (!questions.length) {
    return '<div class="wbc-panel wbe-question" id="wbc-combat-area" style="text-align:center">' +
      '<div style="font-family:var(--fh);font-size:22px;font-weight:900;color:var(--tertiary);margin-bottom:8px">Waiting for questions</div>' +
      '<div style="font-size:13px;color:var(--text-muted)">The boss is active, but no combat questions have been added yet.</div>' +
      '</div>';
  }
  if (allDone) {
    return '<div class="wbc-panel wbe-question" id="wbc-combat-area" style="text-align:center">' +
      '<div style="font-family:var(--fh);font-size:24px;font-weight:900;color:#4edea3;margin-bottom:8px">Question deck complete</div>' +
      '<div style="font-size:13px;color:var(--text-muted);line-height:1.6">Your damage is locked in. Stay alert for random minion spawns while the raid continues.</div>' +
      '</div>';
  }

  var q          = questions[myQIdx];
  var myHistory  = myRec ? (myRec.answerHistory || []) : [];
  var dots = questions.map(function (_, i) {
    if (i < myQIdx) {
      var hist = myHistory[i];
      return '<div class="wbc-q-dot ' + (hist && hist.correct ? 'answered-correct' : 'answered-wrong') + '" title="Q' + (i + 1) + '"></div>';
    }
    return '<div class="wbc-q-dot ' + (i === myQIdx ? 'current' : '') + '" title="Q' + (i + 1) + '"></div>';
  }).join('');

  return '<div class="wbc-panel wbe-question" id="wbc-combat-area">' +
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:8px;flex-wrap:wrap">' +
    '<div style="font-family:var(--fm);font-size:9px;color:#EC4899;letter-spacing:.14em">QUESTION ' + (myQIdx + 1) + ' OF ' + questions.length + '</div>' +
    '<div class="wb-joined-badge">LIVE BATTLE</div></div>' +
    '<div class="wbc-q-nav">' + dots + '</div>' +
    '<div class="wbc-q-text">' + q.q + '</div>' +
    '<div class="wbc-opts" id="wbc-opts-list">' +
    q.opts.map(function (opt, oi) {
      return '<div class="wbc-opt" id="wbc-opt-' + oi + '" onclick="wbcAnswer(' + bossIdx + ',' + myQIdx + ',' + oi + ')">' +
        '<div class="wbc-opt-letter">' + String.fromCharCode(65 + oi) + '</div>' + opt + '</div>';
    }).join('') +
    '</div>' +
    '<div class="wbc-cooldown-bar"><div class="wbc-cooldown-fill" id="wbc-cd-fill" style="width:0%"></div></div>' +
    '</div>';
}

// ── Minion panel (used inside wbeRenderFullBattle) ────────────────────────────

function wbeMinionPanel(bossIdx, boss, myRec) {
  var s = wbmSettings(boss);
  if (!s.enabled) {
    return '<div class="wbe-threat-idle"><span class="material-symbols-outlined">radar</span>Minion spawner is off.</div>';
  }
  if (myRec && myRec.isKO) return wbmRenderKOSection(bossIdx);
  var minion = wbmGetCurrentMinion(bossIdx);
  if (minion) return wbmRenderMinionSection(bossIdx);
  return '<div class="wbe-threat-idle"><span class="material-symbols-outlined">radar</span>Threat scanner active. Random minions can appear at any moment.</div>';
}

// ── Full-screen battle render ─────────────────────────────────────────────────

function wbeRenderFullBattle(bossIdx) {
  var boss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[bossIdx];
  var page = document.getElementById('s-world-boss');
  if (!page || !boss) return false;
  var myRec = wbcMyRecord(bossIdx);
  if (!myRec) return false;

  var bossArtCompact = (typeof bveRenderCompactArt === 'function') ? bveRenderCompactArt(boss, 26) : (boss.image || 'B');
  var bossArtFull    = (typeof bveRenderBossArt === 'function')    ? bveRenderBossArt(boss, { id: 'wb-boss-sprite-art', stateClass: 'state-idle' }) : (boss.image || 'B');

  if (!myRec.bossIntroSeen) {
    page.innerHTML = '<div class="wbe-shell">' +
      wbeSparkField() +
      '<div id="boss-orientation-prompt"><div class="bop-icon">📱</div><div class="bop-title">Rotate to Landscape</div><div class="bop-sub">The Boss Battle requires landscape orientation. Please rotate your device to continue.</div></div>' +
      '<div class="wbe-top"><div class="wbe-brand"><div class="wbe-boss-chip">' + bossArtCompact + '</div><div style="min-width:0"><div class="wbe-title">' + _esc(boss.name) + '</div><div class="wbe-subtitle">Boss Encounter Intro</div></div></div>' +
      '<button class="wbe-close" onclick="navTo(\'s-dashboard\')">Dashboard</button></div>' +
      '<div class="wbe-intro"><div class="wbe-intro-card">' +
      '<div class="wbe-intro-boss">' + bossArtFull + '</div>' +
      '<div class="wbe-intro-kicker">A class raid begins</div>' +
      '<div class="wbe-intro-name">' + _esc(boss.name) + '</div>' +
      '<div class="wbe-intro-copy">' + _esc(boss.description || 'The boss has entered the arena. Answer fast, land critical hits, and watch for minions trying to break your focus.') + '</div>' +
      '<div class="wbe-intro-actions"><button class="wbe-begin" onclick="wbeFinishIntro(' + bossIdx + ')">Begin Battle</button></div>' +
      '</div></div></div>';
    wbmStopSpawnLoop();
    return true;
  }

  var stats       = wbcBattleStats(bossIdx);
  var parts       = Object.values(wbcGetParticipants(bossIdx)).sort(function (a, b) { return (b.totalDamage || 0) - (a.totalDamage || 0); }).slice(0, 5);
  var pct         = Math.max(0, Math.min(100, Math.round((boss.currentHp || boss.maxHp) / boss.maxHp * 100)));
  var hpText      = (boss.currentHp || boss.maxHp).toLocaleString() + ' / ' + boss.maxHp.toLocaleString();
  var s           = wbmSettings(boss);
  var minionCount = (boss.activeMinions || []).length;

  page.innerHTML = '<div class="wbe-shell">' +
    wbeSparkField() +
    '<div id="boss-orientation-prompt"><div class="bop-icon">📱</div><div class="bop-title">Rotate to Landscape</div><div class="bop-sub">The Boss Battle requires landscape orientation. Please rotate your device to continue.</div></div>' +
    '<div class="wbe-top"><div class="wbe-brand"><div class="wbe-boss-chip">' + bossArtCompact + '</div>' +
    '<div style="min-width:0"><div class="wbe-title">' + _esc(boss.name) + '</div><div class="wbe-subtitle">Full-screen raid arena</div></div></div>' +
    '<button class="wbe-close" onclick="navTo(\'s-dashboard\')">Exit Screen</button></div>' +
    '<div class="wbe-arena">' +
    // Left column
    '<div class="wbe-side-stack">' +
    '<div class="wbe-panel"><div class="wbe-panel-title"><span>Your Status</span><span>' + myRec.totalDamage.toLocaleString() + ' DMG</span></div>' +
    '<div id="wbm-hp-bar-section">' + wbmRenderHpBar(bossIdx) + '</div>' +
    '<div class="wbe-stat-grid" style="margin-top:12px"><div class="wbe-stat"><div class="v" style="color:#4edea3">' + (myRec.correctAnswers || 0) + '</div><div class="l">Correct</div></div>' +
    '<div class="wbe-stat"><div class="v" style="color:#f97316">' + (myRec.minionsDefeated || 0) + '</div><div class="l">Minions</div></div></div></div>' +
    '<div class="wbe-panel"><div class="wbe-panel-title"><span>Raid Stats</span><span>' + stats.participants + ' raiders</span></div>' +
    '<div class="wbe-stat-grid">' +
    '<div class="wbe-stat"><div class="v" id="bss-total-dmg" style="color:#EC4899">' + stats.totalDmg.toLocaleString() + '</div><div class="l">Damage</div></div>' +
    '<div class="wbe-stat"><div class="v" id="bss-dps" style="color:#a78bfa">' + stats.dps.toLocaleString() + '/s</div><div class="l">DPS</div></div>' +
    '<div class="wbe-stat"><div class="v" id="bss-participants" style="color:#4edea3">' + stats.participants + '</div><div class="l">Raiders</div></div>' +
    '<div class="wbe-stat"><div class="v" id="bss-time" style="color:#ffb95f">' + (stats.timeRemaining || '-') + '</div><div class="l">Time</div></div>' +
    '</div></div></div>' +
    // Center column
    '<div class="wbe-center">' +
    '<div class="wbe-panel"><div class="wbe-panel-title"><span>Boss HP</span><span id="wb-hp-pct">' + pct + '% HP remaining</span></div>' +
    '<div class="wbe-hp-strip"><div class="wbe-hp-row"><span>' + (boss.difficulty || 'Normal') + '</span><span id="wb-hp-num">' + hpText + '</span></div>' +
    '<div class="wbe-hp-track"><div class="wbe-hp-fill" id="wb-hp-fill" style="width:' + pct + '%"></div></div></div></div>' +
    '<div class="wbe-boss-stage ' + (myRec.isKO ? 'wbe-ko-cover' : '') + '">' +
    '<div class="wb-boss-sprite" id="wb-boss-sprite">' + bossArtFull + '</div></div>' +
    wbeQuestionPanel(bossIdx, boss, myRec) +
    '</div>' +
    // Right column
    '<div class="wbe-side-stack">' +
    '<div class="wbe-panel"><div class="wbe-panel-title"><span>Minion Threat</span><span>' + (s.enabled ? 'ON' : 'OFF') + (minionCount ? ' - ' + minionCount + ' active' : '') + '</span></div>' +
    '<div id="wbm-minion-section">' + wbeMinionPanel(bossIdx, boss, myRec) + '</div></div>' +
    '<div class="wbe-panel"><div class="wbe-panel-title"><span>Top Raiders</span><span id="bss-remaining">' + Math.max(0, boss.currentHp || 0).toLocaleString() + ' HP left</span></div>' +
    '<div style="display:flex;flex-direction:column;gap:8px" id="wb-dmg-list">' +
    (parts.length ? parts.map(function (p, i) {
      return '<div class="wbl-row ' + (p.studentId === currentUser.id ? 'me' : '') + '" style="margin-bottom:0;padding:10px">' +
        '<div class="wbl-rank-badge ' + (i < 3 ? 'r' + (i + 1) : '') + '">' + (i + 1) + '</div>' +
        '<div class="wbl-info"><div class="wbl-info-name">' + p.studentName + '</div>' +
        '<div class="wbl-info-sub">' + (p.correctAnswers || 0) + ' correct - ' + (p.minionsDefeated || 0) + ' minions</div></div>' +
        '<div class="wbl-stat-cell"><div class="wbl-stat-main" style="color:#EC4899">' + (p.totalDamage || 0).toLocaleString() + '</div><div class="wbl-stat-label">DMG</div></div>' +
        '</div>';
    }).join('') : '<div class="wbe-threat-idle">No raid damage yet.</div>') +
    '</div></div></div>' +
    '</div>' +
    '<div id="wbc-float-container"></div><div class="wbc-combo" id="wbc-combo"></div>' +
    '</div>';

  WBE.activeBossIdx = bossIdx;
  _wbcStartLiveRefresh();
  wbcUpdateTopbarWidget();
  wbmStartSpawnLoop(bossIdx);
  if (myRec.isKO) wbmStartKoTimer(bossIdx);
  var minion = wbmGetCurrentMinion(bossIdx);
  if (minion) wbmStartMinionCountdown(bossIdx);
  _wbeInitOrientationPrompt();
  return true;
}

// ── Orientation prompt ────────────────────────────────────────────────────────

function _wbeInitOrientationPrompt() {
  if (window.screen && window.screen.width > 900 && window.screen.height > 900) return;
  function _updatePrompt() {
    var prompt      = document.getElementById('boss-orientation-prompt');
    if (!prompt) return;
    var isPortrait   = window.innerWidth < window.innerHeight;
    var isMobileSize = Math.min(window.innerWidth, window.innerHeight) <= 600;
    prompt.style.display = (isPortrait && isMobileSize) ? 'flex' : 'none';
  }
  _updatePrompt();
  // Phase 7 (2026-08-10, session 4 dependency-map pass): hoisted out of an
  // inline named function expression. A named function expression's own
  // name is only visible INSIDE that function's own body (for recursion) —
  // it is NOT bound in the enclosing scope. `_wbeOrientResizeListener` used
  // to be declared this way inline in the `addEventListener('resize', ...)`
  // call below, which meant the reference to it a few lines earlier (inside
  // the orientationchange handler's cleanup) pointed at a name that was
  // never actually accessible there — a real ReferenceError the moment a
  // user rotated their device while a boss battle's shell had already
  // closed, silently leaking the resize listener forever (its removal
  // never completed). Declaring it as a real function here, before both
  // addEventListener calls, gives both a shared, correctly-scoped
  // reference. See EduQuest_Engineering_Refactor_Log.md Phase 7 session 4.
  function _wbeOrientResizeListener() { _updatePrompt(); }
  window.addEventListener('orientationchange', function _wbeOrientListener() {
    setTimeout(_updatePrompt, 120);
    if (!document.querySelector('.wbe-shell')) {
      window.removeEventListener('orientationchange', _wbeOrientListener);
      window.removeEventListener('resize', _wbeOrientResizeListener);
    }
  });
  window.addEventListener('resize', _wbeOrientResizeListener);
}

// ── Patch 5: renderStudentWorldBoss — promote to full battle if joined ────────
;(function () {
  var _baseRenderStudentWorldBoss = renderStudentWorldBoss;
  renderStudentWorldBoss = function () {
    if (currentRole === 'student') {
      var loot = (typeof wblrGetCurrentLootBoss === 'function') ? wblrGetCurrentLootBoss() : null;
      if (!loot) {
        var found = wbcGetActiveBoss();
        if (found) {
          var rec = wbcMyRecord(found.idx);
          if (rec) {
            if (wbeRenderFullBattle(found.idx)) return;
          }
        }
      }
    }
    WBE.activeBossIdx = null;
    return _baseRenderStudentWorldBoss();
  };
})();

// ── Phase 7 (2026-08-10, session 2): explicit window export ──
// These were previously implicit globals (bare top-level function
// declarations, exposed to window only via classic-script behavior).
// Made explicit ahead of any real module/bundle scoping change —
// see PHASE7_IMPLICIT_GLOBALS.md.
window.wbeFinishIntro = wbeFinishIntro;


/* ---- ./modules/world-boss/raid-flow.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/world-boss/raid-flow.js
//  Campaign-overlay raid flow (WBR): lobby page, battle opening, intro scene,
//  question encounter, answer handler, live-feed, side overlays, victory hook,
//  and final renderStudentWorldBoss = wbrRenderLobby assignment.
//
//  LOAD AFTER: battle-overlay.js, leaderboard.js, loot-rain.js
// ═══════════════════════════════════════════════════════════════════════════════

// ── WBR state ─────────────────────────────────────────────────────────────────

var WBR = {
  bossIdx:      null,
  phase:        'intro',
  typingTimer:  null,
  fullText:     '',
  charIdx:      0,
  refreshTimer: null,
  keyHandler:   null,
};

// ── Boss stage descriptor ─────────────────────────────────────────────────────

function wbrBossStage(boss) {
  var qs      = wbcGetBossQuestions(boss) || [];
  var bossArt = (typeof bveRenderBossArt === 'function')
    ? bveRenderBossArt(boss, { id: 'wb-boss-sprite-art', stateClass: 'state-idle' })
    : (boss.image || 'B');
  var bossIcon = (typeof bveRenderCompactArt === 'function')
    ? bveRenderCompactArt(boss, 32)
    : (boss.image || 'B');
  return {
    title:   boss.name || 'World Boss',
    icon:    bossIcon,
    scenes:  [{
      speaker: 'RAID ALERT',
      bg:      '#190718',
      text:    (boss.name || 'The boss') + ' has entered the arena. This is a class-wide raid: every correct answer damages the same shared HP bar. Watch the live feed and strike when ready.',
    }],
    enemies: [{
      sprite:    bossArt,
      name:      boss.name || 'World Boss',
      title:     'BOSS ENCOUNTER',
      questions: qs,
    }],
  };
}

// ── Stop all WBR timers ───────────────────────────────────────────────────────

function wbrStop() {
  clearInterval(WBR.typingTimer);
  clearInterval(WBR.refreshTimer);
  WBR.typingTimer  = null;
  WBR.refreshTimer = null;
  if (WBR.keyHandler) { document.removeEventListener('keydown', WBR.keyHandler); WBR.keyHandler = null; }
  wbmStopSpawnLoop();
}

// ── Close overlay ─────────────────────────────────────────────────────────────

function wbrCloseBattle() {
  wbrStop();
  document.getElementById('campaign-overlay')?.classList.remove('open');
  WBR.bossIdx = null;
  renderStudentWorldBoss();
}

// ── Background tint ───────────────────────────────────────────────────────────

function wbrSetBg(color) {
  var bg = document.getElementById('camp-bg');
  if (bg) bg.style.background = 'radial-gradient(ellipse at 30% 40%,' + (color || '#190718') + ' 0%,#0a0914 100%)';
}

// ── HP percentage helper ──────────────────────────────────────────────────────

function wbrPct(boss) {
  if (!boss || !boss.maxHp) return 0;
  return Math.max(0, Math.min(100, Math.round((boss.currentHp || 0) / boss.maxHp * 100)));
}

// ── HUD update ────────────────────────────────────────────────────────────────

function wbrUpdateHUD() {
  var boss  = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[WBR.bossIdx];
  if (!boss) return;
  var rec   = wbcMyRecord(WBR.bossIdx);
  var pct   = wbrPct(boss);
  var s     = (boss.minionSettings && boss.minionSettings.enabled) ? 'MINIONS ON' : 'MINIONS OFF';
  var stageLabel = document.getElementById('camp-stage-label');
  var titleHud   = document.getElementById('camp-title-hud');
  var lives      = document.getElementById('camp-lives');
  var enemyBar   = document.getElementById('camp-enemy-bar');
  var enemyName  = document.getElementById('camp-enemy-name');
  var enemyHp    = document.getElementById('camp-enemy-hp');
  if (stageLabel) stageLabel.textContent = 'WORLD BOSS RAID';
  if (titleHud)   titleHud.textContent   = boss.name;
  if (lives)      lives.innerHTML        = rec ? wbmRenderHearts(rec.hp != null ? rec.hp : 3, rec.maxHp || 3, true) : '';
  if (enemyBar)   enemyBar.style.display = 'block';
  if (enemyName)  enemyName.textContent  = boss.name + ' · ' + s;
  if (enemyHp)    enemyHp.style.width    = pct + '%';
}

// ── Typewriter ────────────────────────────────────────────────────────────────

function wbrType(text) {
  WBR.fullText = text || ''; WBR.charIdx = 0;
  var el   = document.getElementById('camp-narr-text');
  var hint = document.getElementById('camp-continue-hint');
  if (el)   el.textContent  = '';
  if (hint) hint.style.display = 'none';
  clearInterval(WBR.typingTimer);
  WBR.typingTimer = setInterval(function () {
    if (!el) return;
    if (WBR.charIdx < WBR.fullText.length) {
      el.textContent += WBR.fullText[WBR.charIdx++];
    } else {
      clearInterval(WBR.typingTimer);
      if (hint) hint.style.display = 'block';
    }
  }, 22);
}

// ── Scene click / keypress handler ───────────────────────────────────────────

function wbrSceneClick() {
  var story = document.getElementById('camp-story-panel');
  if (!story || story.style.display === 'none') return;
  var el   = document.getElementById('camp-narr-text');
  var hint = document.getElementById('camp-continue-hint');
  if (WBR.charIdx < WBR.fullText.length) {
    clearInterval(WBR.typingTimer);
    if (el) el.textContent = WBR.fullText;
    WBR.charIdx = WBR.fullText.length;
    if (hint) hint.style.display = 'block';
    return;
  }
  AppStore.updateState(function (draft) {
    var p = ((draft.bossParticipants || {})[WBR.bossIdx] || {})[currentUser.id];
    if (p) p.bossIntroSeen = true;
  }, { type: 'world-boss:intro-seen', payload: { bossIdx: WBR.bossIdx, studentId: currentUser.id } });
  wbrShowEncounter();
}

// ── Intro screen ──────────────────────────────────────────────────────────────

function wbrShowIntro() {
  var boss  = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[WBR.bossIdx];
  if (!boss) return;
  var stage = wbrBossStage(boss);
  WBR.phase = 'intro';
  document.getElementById('camp-scene')?.querySelectorAll('#wbr-live-feed,#wbr-minion-dock,#wbr-minion-dock-right,#wbr-raid-meta')
    .forEach(function (el) { el.remove(); });
  document.getElementById('camp-story-panel').style.display = 'block';
  document.getElementById('camp-encounter').style.display   = 'none';
  document.getElementById('camp-result').style.display      = 'none';
  document.getElementById('camp-continue-hint').style.display = 'none';
  wbrSetBg(stage.scenes[0].bg);
  wbrUpdateHUD();
  document.getElementById('camp-speaker').textContent = stage.scenes[0].speaker;
  wbrType(stage.scenes[0].text);
}

// ── Damage feed ───────────────────────────────────────────────────────────────

function wbrRecordFeed(bossIdx, entry) {
  AppStore.updateState(function (draft) {
    var boss = (draft.bossEvents || [])[bossIdx];
    if (!boss) return;
    if (!boss.damageFeed) boss.damageFeed = [];
    boss.damageFeed.unshift(Object.assign({ id: uid(), ts: Date.now() }, entry));
    boss.damageFeed = boss.damageFeed.slice(0, 40);
  }, { type: 'world-boss:feed-recorded', payload: { bossIdx: bossIdx } });
}

function wbrFeedHTML(bossIdx) {
  var boss  = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[bossIdx];
  var feed  = (boss && boss.damageFeed) || [];
  if (!feed.length) return '<div class="wbr-feed-item"><div class="wbr-feed-copy">No raid hits yet.</div></div>';
  return feed.slice(0, 10).map(function (e) {
    var color = _cssColor(e.color);
    var label = e.type === 'kill'
      ? '<b>' + wblrEsc(e.name) + '</b> defeated the boss!'
      : '<b>' + wblrEsc(e.name) + '</b> dealt <b style="color:#EC4899">' + (e.damage || 0).toLocaleString() + '</b> damage' + (e.crit ? ' with a critical hit' : '') + '.';
    return '<div class="wbr-feed-item ' + (e.type === 'kill' ? 'kill' : '') + '">' +
      '<div class="wbr-feed-avatar" style="border-color:' + color + '66;background:' + color + '22;color:' + color + '">' + wblrEsc(e.init || '?') + '</div>' +
      '<div class="wbr-feed-copy">' + label + '</div></div>';
  }).join('');
}

// ── Side overlays (feed + minion docks) ───────────────────────────────────────

function wbrRenderSideOverlays() {
  var scene = document.getElementById('camp-scene');
  if (!scene) return;
  scene.querySelectorAll('#wbr-live-feed,#wbr-minion-dock,#wbr-minion-dock-right,#wbr-raid-meta,#wbr-close-btn')
       .forEach(function (el) { el.remove(); });
  var boss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[WBR.bossIdx];
  if (!boss) return;
  var stats = wbcBattleStats(WBR.bossIdx);
  var rec   = wbcMyRecord(WBR.bossIdx);

  // Meta pill strip
  var meta = document.createElement('div');
  meta.id = 'wbr-raid-meta'; meta.className = 'wbr-raid-meta';
  meta.innerHTML =
    '<button class="btn btn-ghost btn-sm" onclick="wbrCloseBattle()" style="justify-content:center">Exit Battle</button>' +
    '<div class="wbr-meta-pill"><div class="v" style="color:#EC4899">' + stats.totalDmg.toLocaleString() + '</div><div class="l">Class Damage</div></div>' +
    '<div class="wbr-meta-pill"><div class="v" style="color:#4edea3">' + stats.participants + '</div><div class="l">Raiders</div></div>' +
    '<div class="wbr-meta-pill"><div class="v" style="color:#f97316">' + (rec ? rec.minionsDefeated || 0 : 0) + '</div><div class="l">Your Minions</div></div>';
  scene.appendChild(meta);

  // Live feed
  var feed = document.createElement('div');
  feed.id = 'wbr-live-feed'; feed.className = 'wbr-live-feed';
  feed.innerHTML = '<div class="wbr-feed-title"><span>Live Raid Feed</span><span>' + Math.max(0, boss.currentHp || 0).toLocaleString() + ' HP</span></div>' +
    '<div class="wbr-feed-list">' + wbrFeedHTML(WBR.bossIdx) + '</div>';
  scene.appendChild(feed);

  var s = wbmSettings(boss);

  // Left minion dock
  var dock = document.createElement('div');
  dock.id = 'wbr-minion-dock'; dock.className = 'wbr-minion-dock';
  if (rec && rec.isKO) {
    dock.innerHTML = wbmRenderKOSection(WBR.bossIdx);
  } else if (s.enabled) {
    var spawnSide   = s.spawnSide || 'random';
    var minionLeft  = wbmGetCurrentMinionBySide(WBR.bossIdx, 'left');
    if (minionLeft) {
      dock.innerHTML = wbmRenderMinionSection(WBR.bossIdx, 'left');
    } else if (spawnSide !== 'right' && spawnSide !== 'both') {
      var oldest = wbmGetCurrentMinion(WBR.bossIdx);
      if (oldest) dock.innerHTML = wbmRenderMinionSection(WBR.bossIdx);
    }
  }
  scene.appendChild(dock);

  // Right minion dock
  var dockRight = document.createElement('div');
  dockRight.id = 'wbr-minion-dock-right'; dockRight.className = 'wbr-minion-dock-right';
  if (rec && !rec.isKO && s.enabled) {
    var minionRight = wbmGetCurrentMinionBySide(WBR.bossIdx, 'right');
    if (minionRight) dockRight.innerHTML = wbmRenderMinionSection(WBR.bossIdx, 'right');
  }
  scene.appendChild(dockRight);

  var anyMinion = wbmGetCurrentMinion(WBR.bossIdx);
  if (anyMinion) wbmStartMinionCountdown(WBR.bossIdx);
}

// ── Encounter screen ──────────────────────────────────────────────────────────

function wbrShowEncounter() {
  var boss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[WBR.bossIdx];
  if (!boss) return;
  if (boss.status === 'loot' || boss.status === 'ended') { wbrCloseBattle(); return; }

  WBR.phase = 'battle';
  var stage  = wbrBossStage(boss);
  var enemy  = stage.enemies[0];
  var rec    = wbcMyRecord(WBR.bossIdx);
  var qIdx   = rec ? (rec.lastQIdx || 0) : 0;
  var q      = enemy.questions[qIdx];

  document.getElementById('camp-story-panel').style.display = 'none';
  document.getElementById('camp-encounter').style.display   = 'flex';
  document.getElementById('camp-result').style.display      = 'none';
  wbrSetBg('#150a2e');
  wbrUpdateHUD();

  // Boss sprite (may be HTML art from BVE)
  var spriteEl = document.getElementById('camp-enemy-sprite');
  if (spriteEl) {
    if (enemy.sprite && enemy.sprite.indexOf('<') !== -1) { spriteEl.innerHTML = enemy.sprite; }
    else { spriteEl.textContent = enemy.sprite || '💀'; }
  }
  document.getElementById('camp-enemy-title').textContent = enemy.title;

  if (!q) {
    document.getElementById('camp-q-text').innerHTML = '<div class="wbr-empty-question">No more boss questions available. Stay in the raid and watch the live feed.</div>';
    document.getElementById('camp-options').innerHTML = '';
    document.getElementById('camp-q-progress').textContent = (rec ? (rec.totalDamage || 0).toLocaleString() : '0') + ' DMG · waiting with the raid';
  } else {
    document.getElementById('camp-q-text').textContent    = q.q;
    document.getElementById('camp-q-progress').textContent = 'QUESTION ' + (qIdx + 1) + ' OF ' + enemy.questions.length + ' · ' + Math.max(0, boss.currentHp || 0).toLocaleString() + ' HP LEFT';
    document.getElementById('camp-options').innerHTML = (q.opts || []).map(function (opt, i) {
      return '<button class="camp-opt" id="wbr-opt-' + i + '" onclick="wbrAnswer(' + WBR.bossIdx + ',' + qIdx + ',' + i + ')">' +
        '<span class="camp-opt-letter">' + String.fromCharCode(65 + i) + '</span>' + opt + '</button>';
    }).join('');
  }
  wbrRenderSideOverlays();
}

// ── Answer handler ────────────────────────────────────────────────────────────

async function wbrAnswer(bossIdx, qIdx, choice) {
  var boss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[bossIdx];
  if (!boss || boss.status !== 'active') return;
  var rec = wbcMyRecord(bossIdx);
  if (!rec || rec.isKO) return;
  var questions = wbcGetBossQuestions(boss);
  var q = questions[qIdx];
  if (!q) return;

  document.querySelectorAll('.camp-opt').forEach(function (el) { el.disabled = true; el.onclick = null; });
  var isCorrect = choice === q.answer;
  var chosen    = document.getElementById('wbr-opt-' + choice);
  var correct   = document.getElementById('wbr-opt-' + q.answer);

  if (isCorrect) {
    chosen?.classList.add('correct');
    var result  = wbcCalcDamage(boss);
    var outcome = await wbcApplyDamage(bossIdx, result.damage, currentUser.id, result.isCrit);
    AppStore.updateState(function (draft) {
      var p = ((draft.bossParticipants || {})[bossIdx] || {})[currentUser.id];
      if (!p) return;
      if (result.isCrit) p.critHits = (p.critHits || 0) + 1;
      if (!p.answerHistory) p.answerHistory = [];
      p.answerHistory[qIdx] = { correct: true, damage: result.damage };
      p.lastQIdx = qIdx + 1;
    }, { type: 'world-boss:answer-recorded', payload: { bossIdx: bossIdx, studentId: currentUser.id } });
    wbrRecordFeed(bossIdx, {
      type:      outcome === 'defeated' ? 'kill' : 'hit',
      studentId: currentUser.id, name: currentUser.name,
      init:      currentUser.init, color: currentUser.color,
      damage:    result.damage, crit: result.isCrit,
    });
    toast(_esc(currentUser.name) + ' dealt ' + result.damage.toLocaleString() + ' damage!', result.isCrit ? '#ffb95f' : '#EC4899');
    document.getElementById('camp-scene')?.classList.add('shake');
    setTimeout(function () { document.getElementById('camp-scene')?.classList.remove('shake'); }, 350);

    if (outcome === 'defeated') {
      toast(_esc(currentUser.name) + ' defeated ' + _esc(boss.name) + '! Loot Rush is open.', '#ffb95f');
      setTimeout(function () {
        wbrStop();
        document.getElementById('campaign-overlay')?.classList.remove('open');
        WBR.bossIdx = null;
        wblShowVictoryScreen(bossIdx, function () { renderStudentWorldBoss(); });
      }, 900);
      return;
    }
    setTimeout(function () { wbrShowEncounter(); }, 900);
  } else {
    chosen?.classList.add('wrong');
    correct?.classList.add('correct');
    AppStore.updateState(function (draft) {
      var p = ((draft.bossParticipants || {})[bossIdx] || {})[currentUser.id];
      if (!p) return;
      p.wrongAnswers = (p.wrongAnswers || 0) + 1;
      if (!p.answerHistory) p.answerHistory = [];
      p.answerHistory[qIdx] = { correct: false, damage: 0 };
      p.lastQIdx = qIdx + 1;
    }, { type: 'world-boss:answer-recorded', payload: { bossIdx: bossIdx, studentId: currentUser.id } });
    toast('Wrong answer. The boss resists.', '#ffb4ab');
    setTimeout(function () { wbrShowEncounter(); }, 1100);
  }
}

// ── Open battle (with BVE art preload) ───────────────────────────────────────

function wbrOpenBattle(bossIdx) {
  var boss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[bossIdx];
  if (!boss || boss.status !== 'active') return;
  if (typeof bvePreloadBossArt === 'function') {
    bvePreloadBossArt(boss)
      .then(function () { _wbrOpenBattleRender(bossIdx); })
      .catch(function () { _wbrOpenBattleRender(bossIdx); });
    return;
  }
  _wbrOpenBattleRender(bossIdx);
}

function _wbrOpenBattleRender(bossIdx) {
  var boss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[bossIdx];
  if (!boss || boss.status !== 'active') return;
  WBR.bossIdx = bossIdx;
  document.getElementById('campaign-overlay').classList.add('open');
  document.getElementById('camp-scene').onclick = wbrSceneClick;
  if (WBR.keyHandler) document.removeEventListener('keydown', WBR.keyHandler);
  WBR.keyHandler = function (e) { if (e.key === ' ' || e.key === 'Enter') wbrSceneClick(); };
  document.addEventListener('keydown', WBR.keyHandler);
  clearInterval(WBR.refreshTimer);
  WBR.refreshTimer = setInterval(function () {
    if (WBR.bossIdx == null) return;
    var b = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[WBR.bossIdx];
    if (!b || b.status !== 'active') { wbrCloseBattle(); return; }
    wbrUpdateHUD();
    if (WBR.phase === 'battle') {
      wbrRenderSideOverlays();
      var _rec = wbcMyRecord(WBR.bossIdx);
      if (_rec) {
        var _qs   = wbcGetBossQuestions(b);
        var _qIdx = _rec.lastQIdx || 0;
        var _noQ  = document.querySelector('.wbr-empty-question');
        if (_noQ && _qs.length > _qIdx) wbrShowEncounter();
      }
    }
  }, 1200);
  wbmStartSpawnLoop(bossIdx);
  var rec = wbcMyRecord(bossIdx);
  if (rec && rec.bossIntroSeen) wbrShowEncounter();
  else wbrShowIntro();
}

// ── Lobby page render ─────────────────────────────────────────────────────────

function wbrRenderLobby() {
  var page = document.getElementById('s-world-boss');
  if (!page) return;
  var loot = (typeof wblrGetCurrentLootBoss === 'function') ? wblrGetCurrentLootBoss() : null;
  if (loot) { wblrRenderStudentLootPage(loot.idx); return; }
  var found = wbcGetActiveBoss();
  if (found && typeof bvePreloadBossArt === 'function') {
    bvePreloadBossArt(found.boss)
      .then(function () { _wbrRenderLobbyCore(); })
      .catch(function () { _wbrRenderLobbyCore(); });
    _wbrRenderLobbyCore(); // immediate render with cached/fallback art
    return;
  }
  _wbrRenderLobbyCore();
}

function _wbrRenderLobbyCore() {
  var page = document.getElementById('s-world-boss');
  if (!page) return;
  var loot = (typeof wblrGetCurrentLootBoss === 'function') ? wblrGetCurrentLootBoss() : null;
  if (loot) { wblrRenderStudentLootPage(loot.idx); return; }
  var found = wbcGetActiveBoss();

  if (!found) {
    var summary = (typeof wblrGetLatestSummaryBoss === 'function') ? wblrGetLatestSummaryBoss() : null;
    if (summary) { wblrRenderFinalSummaryPage(summary.idx); return; }
    page.innerHTML = '<div style="padding:32px;max-width:1000px;margin:0 auto">' +
      '<div class="wb-hero" style="min-height:260px;display:flex;align-items:center;justify-content:center;text-align:center">' +
      '<div class="wb-hero-bg"></div>' +
      '<div style="position:relative;z-index:2">' +
      '<div style="font-size:64px;margin-bottom:16px;opacity:.5">💀</div>' +
      '<div style="font-family:var(--fh);font-size:24px;font-weight:900;color:var(--on-surface);margin-bottom:8px">No Active Boss Event</div>' +
      '<div style="font-size:14px;color:var(--text-muted)">Your teacher will activate a boss event soon.</div>' +
      '</div></div></div>';
    return;
  }

  var boss      = found.boss, idx = found.idx;
  var rec       = wbcMyRecord(idx);
  var stats     = wbcBattleStats(idx);
  var questions = wbcGetBossQuestions(boss);
  var pct       = wbrPct(boss);
  var bossArt   = (typeof bveRenderBossArt === 'function')
    ? bveRenderBossArt(boss, { id: 'wb-boss-sprite-lobby-art', stateClass: 'state-idle' })
    : (boss.image || '💀');

  page.innerHTML = '<div style="padding:32px;max-width:1100px;margin:0 auto">' +
    '<div class="wb-hero" style="margin-bottom:24px">' +
    '<div class="wb-hero-bg"></div><div class="wb-hero-grid"></div><div class="wb-hero-particles" id="wb-particles"></div>' +
    '<div class="wb-hero-content">' +
    '<div class="wb-hero-left">' +
    '<div class="wb-boss-tag">LIVE RAID LOBBY</div>' +
    '<div class="wb-boss-name">' + _esc(boss.name) + '</div>' +
    '<div class="wb-boss-desc">' + _esc(boss.description || 'A powerful boss has appeared. Join the raid to open the full-screen battle.') + '</div>' +
    '<div class="wb-hero-stats">' +
    '<div class="wb-stat-chip"><div class="v" style="color:#EC4899">' + pct + '%</div><div class="l">HP Remaining</div></div>' +
    '<div class="wb-stat-chip"><div class="v" style="color:var(--secondary)">' + stats.participants + '</div><div class="l">Raiders</div></div>' +
    '<div class="wb-stat-chip"><div class="v" style="color:#ffb95f">' + questions.length + '</div><div class="l">Questions</div></div>' +
    '</div></div>' +
    '<div class="wb-hero-right"><div class="wb-boss-sprite-wrap"><div class="wb-boss-sprite-ring"></div><div class="wb-boss-sprite-ring2"></div>' +
    '<div class="wb-boss-sprite" id="wb-boss-sprite-lobby">' + bossArt + '</div></div></div>' +
    '</div></div>' +
    '<div class="wb-hp-section">' +
    '<div class="wb-hp-header"><div class="wb-hp-label">SHARED BOSS HP</div><div class="wb-hp-numbers">' + Math.max(0, boss.currentHp || 0).toLocaleString() + ' <span>/ ' + boss.maxHp.toLocaleString() + '</span></div></div>' +
    '<div class="wb-hp-bar-track"><div class="wb-hp-bar-fill" style="width:' + pct + '%"></div></div>' +
    '<div class="wb-hp-pct">' + pct + '% HP remaining</div>' +
    '</div>' +
    '<div class="wbc-panel" style="text-align:center">' +
    '<div style="font-size:48px;margin-bottom:14px">' + (rec ? '⚔️' : '🛡️') + '</div>' +
    '<div style="font-family:var(--fh);font-size:22px;font-weight:900;color:var(--on-surface);margin-bottom:8px">' + (rec ? 'You are in the raid' : 'Join the Raid') + '</div>' +
    '<div style="font-size:14px;color:var(--text-muted);line-height:1.6;margin:0 auto 22px;max-width:620px">' +
    (rec ? 'Open the full-screen boss battle to attack. This lobby stays here while the fight happens in the battle overlay.'
         : 'Join to open the campaign-style boss battle: narration first, then shared collaborative combat.') +
    '</div>' +
    (questions.length === 0 ? '<div style="margin-bottom:18px;color:#ffb95f;font-size:13px">No boss questions are configured yet.</div>' : '') +
    '<button class="btn btn-primary" style="background:linear-gradient(135deg,#EC4899,#9333ea);padding:13px 32px;font-size:15px" ' +
    (questions.length === 0 ? 'disabled' : '') +
    ' onclick="' + (rec ? 'wbrOpenBattle(' + idx + ')' : 'wbcJoinBoss(' + idx + ')') + '">' +
    (rec ? 'Enter Battle' : 'Join Raid') + '</button></div>' +
    '<div class="wbc-panel">' +
    '<div style="font-family:var(--fm);font-size:9px;color:#ffb95f;letter-spacing:.16em;margin-bottom:12px">LIVE RAID FEED</div>' +
    '<div class="wbr-feed-list">' + wbrFeedHTML(idx) + '</div>' +
    '</div></div>';

  _wbcSpawnParticles();
  wbcUpdateTopbarWidget();

  // Event-Driven Communication phase (roadmap Phase 4) — restores the
  // trigger point 3 patches (skills.js, this file's OWN former patch, rage.js)
  // used to hook via monkey-patching window.renderStudentWorldBoss, before
  // being silently discarded: this function replaces renderStudentWorldBoss
  // wholesale (see below) rather than chaining, so anything that patched an
  // EARLIER definition of it never ran again after this line executed. Full
  // trace: skills.js/phases.js/rage.js patch → clobbered by student-page.js's
  // later non-chaining definition → battle-overlay.js patches THAT →
  // clobbered again by this file's own replacement below. Only bve-patches.js
  // (which chains on top of THIS function, loading after it) survived.
  const _activeForEmit = (typeof wbcGetActiveBoss === 'function') ? wbcGetActiveBoss() : null;
  AppStore.emit({ type: 'world-boss:student-view-rendered', payload: { bossIdx: _activeForEmit ? _activeForEmit.idx : null } });
}

// ── Replace renderStudentWorldBoss with lobby ─────────────────────────────────
// NOTE: battle-overlay.js further wraps this below (its patch runs after).
window.renderStudentWorldBoss = wbrRenderLobby;

// ── Replace wbcJoinBoss to open battle immediately after joining ──────────────
// [Phase 1 cleanup] This is now the only window.wbcJoinBoss definition in
// the module — combat-settings.js's original and battle-overlay.js's Patch
// 3 wrapper (which used to add hp/maxHp/isKO to a joined-but-missing-them
// record) were both confirmed-dead (unconditionally overwritten by this
// file, per this file's own header: "LOAD AFTER: battle-overlay.js") and
// removed 2026-07-21. This version already includes hp/maxHp/isKO/
// bossIntroSeen inline at creation, which is what made the battle-overlay.js
// patch redundant even before it was unreachable. See the refactor log's
// Tier-1 debt-review entry.
window.wbcJoinBoss = function (bossIdx) {
  var boss = (AppStore.getSlice(function (s) { return s.bossEvents; }) || [])[bossIdx];
  if (!boss || boss.status !== 'active') return;
  var existing = wbcGetParticipants(bossIdx)[currentUser.id];
  if (!existing) {
    AppStore.updateState(function (draft) {
      if (!draft.bossParticipants) draft.bossParticipants = {};
      if (!draft.bossParticipants[bossIdx]) draft.bossParticipants[bossIdx] = {};
      if (!draft.bossParticipants[bossIdx][currentUser.id]) {
        draft.bossParticipants[bossIdx][currentUser.id] = {
          studentId: currentUser.id, studentName: currentUser.name,
          studentInit: currentUser.init, studentColor: currentUser.color,
          totalDamage: 0, correctAnswers: 0, wrongAnswers: 0,
          critHits: 0, minionsDefeated: 0,
          joinTime: Date.now(), lastQIdx: 0,
          hp: 3, maxHp: 3, isKO: false, bossIntroSeen: false,
        };
      }
    }, { type: 'world-boss:joined', payload: { bossIdx: bossIdx, studentId: currentUser.id } });
  }
  var myRec = wbcGetParticipants(bossIdx)[currentUser.id];
  WBC.joined = true; WBC.bossIdx = bossIdx;
  WBC.qIdx = myRec.lastQIdx || 0;
  WBC.battleStartTime = myRec.joinTime;
  renderStudentWorldBoss();
  toast('You joined the raid. Opening battle...', '#EC4899');
  setTimeout(function () { wbrOpenBattle(bossIdx); }, 150);
};

console.log('[EduQuest] world-boss/raid-flow.js loaded — WBR, wbrRenderLobby, wbrOpenBattle, wbrAnswer, wbrFeedHTML, side overlays, wbcJoinBoss replacement registered.');

// ── Phase 7 (2026-08-10, session 2): explicit window export ──
// These were previously implicit globals (bare top-level function
// declarations, exposed to window only via classic-script behavior).
// Made explicit ahead of any real module/bundle scoping change —
// see PHASE7_IMPLICIT_GLOBALS.md.
window.wbrAnswer = wbrAnswer;
window.wbrCloseBattle = wbrCloseBattle;

// ── Phase 7 (2026-08-10, session 7): explicit window exports ──
// These were previously implicit globals (bare top-level declarations,
// reachable to other files only via classic-script auto-attach-to-window
// behavior). Made explicit ahead of any real bundle/module scoping change
// — found by build/audit-window-exports.js, which checks every symbol with
// a real cross-file consumer, not just ones reachable from onclick markup.
// See PHASE7_WINDOW_EXPORT_AUDIT.md.
window.wbrSetBg = wbrSetBg;
window.WBR = WBR;
window.wbrStop = wbrStop;
window.wbrType = wbrType;


/* ---- ./modules/world-boss/bve-patches.js ---- */
// ─────────────────────────────────────────────────────────────────────────────
// §6  BVE CSS INJECTION
