/* ---- ./modules/admin/teacher-directory-service.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/admin/teacher-directory-service.js
//  Service layer for admin-only account/role management.
//  (ISOLATION_ROLES_PLAN.md §11 "Account & access management", §12 step 5,
//   chunk A1 — see supabase/phase34_admin_role_management.sql.)
//
//  REPOSITORY PATTERN CONTRACT — same rule as RegistrationService/
//  SectionService: teacher-directory.js (the render layer, chunk A2) NEVER
//  calls DBService.rpc() directly for a role change. It calls
//  TeacherDirectoryService.<method>(...).
//
//  WHAT'S HERE NOW (A1 + A2 + A3 + A4 + A5)
//    getDirectory() — read-only list backing the Teacher Directory screen.
//    promoteToAdmin() / demoteToTeacher() — the two role-change RPCs.
//    deactivateAccount() / reactivateAccount() — account lockout RPCs.
//    sendPasswordReset() — chunk A4. NOT an RPC (no server-side admin gate
//    exists or is needed for it — see its own comment) — routed through
//    DBService.sendPasswordResetEmail() instead of DBService.rpc().
//    createInvite() / getInvites() / revokeInvite() — chunk A5, teacher
//    account creation via invite link. See supabase/phase37_teacher_invites.sql
//    and modules/admin/teacher-invite.js (the invited person's completion
//    screen — a separate, mostly-anonymous flow, not part of this service).
//    The role/status/invite actions above are all admin-gated server-side
//    (see phase34/35/36/37's is_admin() checks); the JS side does no
//    authorization of its own, same posture as every other *Service module
//    in this app.
// ═══════════════════════════════════════════════════════════════════════════════

window.TeacherDirectoryService = (function () {
  'use strict';

  /**
   * getDirectory() → Promise<{ok, teachers?, error?}>
   * Read-only list of every admin/teacher account (chunk A2). Shape per
   * row mirrors get_teacher_directory()'s jsonb_build_object keys exactly —
   * no renaming here, so the SQL comment stays the single source of truth
   * for the shape.
   */
  async function getDirectory() {
    const { data, error } = await DBService.rpc('get_teacher_directory', {});
    if (error) return { ok: false, error: error.message || 'Could not load the teacher directory.' };
    return { ok: true, teachers: data || [] };
  }

  /**
   * promoteToAdmin(teacherId) → Promise<{ok, error?}>
   * Promotes an existing role='teacher' profile to role='admin'.
   */
  async function promoteToAdmin(teacherId) {
    if (!teacherId) return { ok: false, error: 'Missing teacher id.' };
    const { error } = await DBService.rpc('promote_to_admin', { p_teacher_id: teacherId });
    if (error) return { ok: false, error: error.message || 'Could not promote this account.' };
    return { ok: true };
  }

  /**
   * demoteToTeacher(adminId) → Promise<{ok, error?}>
   * Demotes an existing role='admin' profile back to role='teacher'.
   * The RPC itself refuses to demote the last remaining admin — surface
   * that message as-is rather than re-deriving the same rule here.
   */
  async function demoteToTeacher(adminId) {
    if (!adminId) return { ok: false, error: 'Missing admin id.' };
    const { error } = await DBService.rpc('demote_to_teacher', { p_admin_id: adminId });
    if (error) return { ok: false, error: error.message || 'Could not demote this account.' };
    return { ok: true };
  }

  /**
   * deactivateAccount(targetId) → Promise<{ok, error?}>
   * Refuses (server-side) to deactivate the caller's own account or the
   * last remaining active admin — see deactivate_teacher_account()'s guards.
   */
  async function deactivateAccount(targetId) {
    if (!targetId) return { ok: false, error: 'Missing account id.' };
    const { error } = await DBService.rpc('deactivate_teacher_account', { p_target_id: targetId });
    if (error) return { ok: false, error: error.message || 'Could not deactivate this account.' };
    return { ok: true };
  }

  /**
   * reactivateAccount(targetId) → Promise<{ok, error?}>
   */
  async function reactivateAccount(targetId) {
    if (!targetId) return { ok: false, error: 'Missing account id.' };
    const { error } = await DBService.rpc('reactivate_teacher_account', { p_target_id: targetId });
    if (error) return { ok: false, error: error.message || 'Could not reactivate this account.' };
    return { ok: true };
  }

  /**
   * sendPasswordReset(email) → Promise<{ok, error?}>
   * (Chunk A4 — Teacher Directory "Send Reset Email" action.)
   *
   * Triggers Supabase's standard recovery email for the given account via
   * DBService.sendPasswordResetEmail() — NOT a Postgres RPC, so unlike
   * every other method in this file it has no server-side is_admin() gate
   * to lean on. That's fine here specifically: resetPasswordForEmail() is
   * intentionally a public, unauthenticated GoTrue endpoint (it's the same
   * call an unauthenticated "Forgot password?" link would use) that never
   * reveals whether the email exists and never touches another account's
   * data — it only ever results in an email being sent to whatever address
   * is given. The Teacher Directory just gives an admin a one-click way to
   * fire it at a specific teacher's known address instead of that teacher
   * needing a "forgot password" link of their own (which this app doesn't
   * have yet — see recovery.js's header for why that's a fine gap for now).
   *
   * redirectTo points back at this app's own origin+path (see recovery.js)
   * so the link lands on the in-app "Set new password" screen rather than
   * Supabase's bare default page.
   */
  async function sendPasswordReset(email) {
    if (!email) return { ok: false, error: 'This account has no email on file.' };
    const redirectTo = window.location.origin + window.location.pathname;
    return DBService.sendPasswordResetEmail(email, redirectTo);
  }

  /**
   * createInvite() → Promise<{ok, error?, invite?}>
   * (Chunk A5.) Generates a new pending, 7-day invite. The token comes back
   * so the caller can build the shareable link — see teacher-directory.js's
   * _teacherInviteLink() for the exact URL shape.
   */
  async function createInvite() {
    const { data, error } = await DBService.rpc('create_teacher_invite', {});
    if (error) return { ok: false, error: error.message || 'Could not create an invite link.' };
    return {
      ok: true,
      invite: {
        token: data.token, createdAt: data.created_at,
        expiresAt: data.expires_at, status: data.status,
      },
    };
  }

  /**
   * getInvites() → Promise<{ok, error?, invites?}>
   * Every invite ever created (pending/used/revoked), for the directory's
   * "Outstanding invites" panel.
   */
  async function getInvites() {
    const { data, error } = await DBService.rpc('get_teacher_invites', {});
    if (error) return { ok: false, error: error.message || 'Could not load invite links.' };
    return { ok: true, invites: data || [] };
  }

  /**
   * revokeInvite(token) → Promise<{ok, error?}>
   */
  async function revokeInvite(token) {
    if (!token) return { ok: false, error: 'Missing invite token.' };
    const { error } = await DBService.rpc('revoke_teacher_invite', { p_token: token });
    if (error) return { ok: false, error: error.message || 'Could not revoke this invite.' };
    return { ok: true };
  }

  return {
    getDirectory: getDirectory,
    promoteToAdmin: promoteToAdmin,
    demoteToTeacher: demoteToTeacher,
    deactivateAccount: deactivateAccount,
    reactivateAccount: reactivateAccount,
    sendPasswordReset: sendPasswordReset,
    createInvite: createInvite,
    getInvites: getInvites,
    revokeInvite: revokeInvite,
  };
})();


/* ---- ./modules/admin/teacher-directory.js ---- */
// ══════════════════════════════════════════════════════
//  modules/admin/teacher-directory.js
//  Teacher Directory — admin-only screen.
//  (ISOLATION_ROLES_PLAN.md §11 "Teacher directory", §12 step 5, chunk A)
//
//  A1: nav split + admin-only gating + promote/demote RPCs.
//  A2: get_teacher_directory() read list + promote/demote wired up.
//  A3: status column + Deactivate/Reactivate actions, backed by
//     supabase/phase36_deactivate_reactivate.sql.
//  A4: "Send Reset Email" action per row, backed by
//     TeacherDirectoryService.sendPasswordReset() (Supabase Auth's
//     resetPasswordForEmail(), not an RPC — no schema change). The
//     in-app landing screen the reset link opens lives in recovery.js.
//  A5 (this phase): "Invite a New Teacher" panel — generate a generic,
//     7-day invite link (supabase/phase37_teacher_invites.sql), copy it to
//     share manually, see outstanding invites, revoke a pending one. The
//     invited person's own completion screen lives in
//     modules/admin/teacher-invite.js / teacher-invite-service.js — this
//     file only ever handles the admin side (create/list/revoke).
//  Chunk D: "Transfer Ownership" per-row action — full offboarding, moves
//     every section and every piece of content a teacher owns to one
//     destination teacher (supabase/phase42_ownership_lifecycle.sql, via
//     OwnershipService — modules/admin/ownership-service.js). Separate
//     from Deactivate — see that action's button for account lockout.
//
//  REPOSITORY PATTERN: this file never calls DBService.rpc() (or the raw
//  Supabase client) directly — only TeacherDirectoryService / OwnershipService.
//
//  Exports: renderTeacherDirectory, doPromoteTeacher, doDemoteAdmin,
//           doDeactivateAccount, doReactivateAccount, doSendPasswordReset,
//           doGenerateTeacherInvite, doCopyTeacherInviteLink, doRevokeTeacherInvite,
//           _tdOpenTransferModal, _tdSubmitTransfer
// ══════════════════════════════════════════════════════

let _teacherDirLoading = false;
let _teacherDirRows = null;   // last successfully loaded list, or null
let _teacherDirError = null;
let _teacherDirBusyId = null; // id currently mid promote/demote/deactivate, for button spinners

let _teacherInvitesLoading = false;
let _teacherInvites = null;      // last successfully loaded invite list, or null
let _teacherInvitesError = null;
let _teacherInviteBusyToken = null; // token currently mid revoke, for button spinners
let _teacherInviteGenerating = false;

// Directory table — search + pagination (same house pattern as
// registrations.js / quiz-builder.js). Note: adminCount / activeAdminCount /
// activeStaffCount (used for disabling "last remaining admin" actions) are
// always computed against the FULL unfiltered _teacherDirRows, never the
// filtered/paged slice below — a search or page change must never change
// which buttons are disabled.
let _teacherDirSearch = '';
let _teacherDirPage = 1;
const TEACHER_DIR_PAGE_SIZE = 20;

window.tdSetSearch = function (value) {
  _teacherDirSearch = String(value || '');
  _teacherDirPage = 1;
  _teacherDirRenderTable();
};

window.tdGoToPage = function (page) {
  _teacherDirPage = Math.max(1, page | 0);
  _teacherDirRenderTable();
  const list = document.getElementById('td-table');
  if (list) list.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
};
window.tdPrevPage = function () { window.tdGoToPage(_teacherDirPage - 1); };
window.tdNextPage = function () { window.tdGoToPage(_teacherDirPage + 1); };

function _teacherDirPagination(page, totalPages, totalCount, rangeStart, rangeEnd) {
  if (totalPages <= 1) {
    return `<div style="text-align:center;margin-top:10px;font-size:11px;color:var(--text-muted)">Showing all ${totalCount}</div>`;
  }
  const nums = new Set([1, totalPages, page, page - 1, page + 1, page - 2, page + 2]);
  const pages = Array.from(nums).filter(n => n >= 1 && n <= totalPages).sort((a, b) => a - b);
  let btns = '';
  let prevN = 0;
  pages.forEach(n => {
    if (n - prevN > 1) btns += `<span style="padding:0 6px;color:var(--text-muted);font-size:11px">…</span>`;
    btns += `<button class="btn btn-ghost btn-sm" style="${n === page ? 'background:var(--primary);color:#fff;font-weight:800' : ''}" onclick="tdGoToPage(${n})">${n}</button>`;
    prevN = n;
  });
  return `
  <div style="display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap;margin-top:14px">
    <button class="btn btn-ghost btn-sm" ${page <= 1 ? 'disabled' : ''} onclick="tdPrevPage()">← Prev</button>
    ${btns}
    <button class="btn btn-ghost btn-sm" ${page >= totalPages ? 'disabled' : ''} onclick="tdNextPage()">Next →</button>
  </div>
  <div style="text-align:center;margin-top:8px;font-size:11px;color:var(--text-muted)">Showing ${rangeStart}–${rangeEnd} of ${totalCount}</div>`;
}

window.renderTeacherDirectory = async function () {
  const el = document.getElementById('a-teachers');
  if (!el) return;

  // Defense in depth: nav.js already hides this tab and bounces direct
  // navTo() calls for a non-admin — this should be unreachable, but never
  // show an oversight screen to a teacher account regardless.
  if (currentRole !== 'admin') {
    el.innerHTML = `
    <div class="glass-card" style="padding:32px;text-align:center">
      <span class="material-symbols-outlined" style="font-size:40px;color:var(--text-muted)">lock</span>
      <h2 style="font-family:var(--fh);font-size:18px;margin:12px 0 4px">Admin only</h2>
      <p style="font-size:13px;color:var(--text-muted)">This screen is only available to oversight admin accounts.</p>
    </div>`;
    return;
  }

  _teacherDirLoading = true;
  _teacherDirError = null;
  _teacherInvitesLoading = true;
  _teacherInvitesError = null;
  _teacherDirRenderShell(el);

  const [dirResult, invitesResult] = await Promise.all([
    TeacherDirectoryService.getDirectory(),
    TeacherDirectoryService.getInvites(),
  ]);

  _teacherDirLoading = false;
  if (!dirResult.ok) {
    _teacherDirError = dirResult.error;
    _teacherDirRows = null;
  } else {
    _teacherDirRows = dirResult.teachers;
  }

  _teacherInvitesLoading = false;
  if (!invitesResult.ok) {
    _teacherInvitesError = invitesResult.error;
    _teacherInvites = null;
  } else {
    _teacherInvites = invitesResult.invites;
  }

  // Only re-render if we're still on this page (admin may have navigated
  // away while the RPCs were in flight).
  if (document.getElementById('a-teachers')) _teacherDirRenderShell(document.getElementById('a-teachers'));
};

function _teacherDirRenderShell(el) {
  el.innerHTML = `
  <div class="page-hero">
    <div class="page-hero-bg"></div>
    <div style="position:relative;z-index:1">
      <div class="page-hero-label">🛠️ Oversight</div>
      <h1 style="font-family:var(--fh);font-size:32px;font-weight:900;color:var(--on-surface);margin-bottom:8px">Teacher Directory</h1>
      <p style="font-size:14px;color:var(--text-muted)">Every admin and teacher account, their sections, content, and access status.</p>
    </div>
  </div>
  ${_teacherInvitePanel()}
  ${_teacherDirBody()}
  `;
  _teacherDirRenderTable();
}

const _TD_COLS = '1.3fr 90px 90px 1.1fr 80px 80px 1.3fr 100px 170px';

function _teacherDirBody() {
  if (_teacherDirLoading) {
    return `<div class="glass-card" style="padding:32px;text-align:center;color:var(--text-muted);font-size:13px">Loading teacher directory…</div>`;
  }
  if (_teacherDirError) {
    return `
    <div class="glass-card" style="padding:32px;text-align:center">
      <span class="material-symbols-outlined" style="font-size:36px;color:#ffb4ab">error</span>
      <p style="font-size:13px;color:var(--text-muted);margin:10px 0 16px">${_esc(_teacherDirError)}</p>
      <button class="btn btn-primary btn-sm" onclick="renderTeacherDirectory()">Retry</button>
    </div>`;
  }
  const rows = _teacherDirRows || [];
  if (rows.length === 0) {
    return `<div class="glass-card" style="padding:32px;text-align:center;color:var(--text-muted);font-size:13px">No teacher or admin accounts found.</div>`;
  }

  return `
  <div style="margin-bottom:14px;max-width:280px">
    <input type="text" placeholder="Search name or email…" value="${_esc(_teacherDirSearch)}" oninput="tdSetSearch(this.value)">
  </div>
  <div id="td-table-wrap"></div>`;
}

/** Re-renders just the directory table (search/page changes skip the invites panel + search box repaint). */
function _teacherDirRenderTable() {
  const wrap = document.getElementById('td-table-wrap');
  if (!wrap) return;
  const rows = _teacherDirRows || [];

  // Counts for disabled-state logic always reflect the FULL roster.
  const adminCount = rows.filter(r => r.role === 'admin').length;
  const activeAdminCount = rows.filter(r => r.role === 'admin' && r.isActive !== false).length;
  const activeStaffCount = rows.filter(r => r.isActive !== false).length;

  const q = _teacherDirSearch.trim().toLowerCase();
  const filtered = q
    ? rows.filter(r => (r.displayName || '').toLowerCase().includes(q) || (r.email || '').toLowerCase().includes(q))
    : rows;

  const totalPages = Math.max(1, Math.ceil(filtered.length / TEACHER_DIR_PAGE_SIZE));
  if (_teacherDirPage > totalPages) _teacherDirPage = totalPages;
  const start = (_teacherDirPage - 1) * TEACHER_DIR_PAGE_SIZE;
  const shown = filtered.slice(start, start + TEACHER_DIR_PAGE_SIZE);

  wrap.innerHTML = `
  <div id="td-table" class="glass-card" style="padding:0;overflow:hidden">
    <div style="display:grid;grid-template-columns:${_TD_COLS};gap:10px;align-items:center;padding:10px 16px;font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);border-bottom:1px solid var(--border2)">
      <span>Name</span><span>Role</span><span>Status</span><span>Email</span><span>Students</span><span>Content</span><span>Sections</span><span>Last Active</span><span></span>
    </div>
    ${filtered.length ? shown.map(r => _teacherDirRow(r, adminCount, activeAdminCount, activeStaffCount)).join('')
      : `<div style="padding:24px;text-align:center;color:var(--text-muted);font-size:13px">No teachers match your search.</div>`}
  </div>
  ${filtered.length ? _teacherDirPagination(_teacherDirPage, totalPages, filtered.length, start + 1, start + shown.length) : ''}`;
}

function _teacherDirRow(r, adminCount, activeAdminCount, activeStaffCount) {
  const isAdmin = r.role === 'admin';
  const isActive = r.isActive !== false;
  const isSelf = currentUser && currentUser.id === r.id;
  const busy = _teacherDirBusyId === r.id;
  const label = _esc(r.displayName || r.email || '');

  const contentTotal = (r.achievementCount || 0) + (r.titleCount || 0) + (r.quizCount || 0)
    + (r.campaignWorldCount || 0) + (r.shopProductCount || 0);
  const sectionsLabel = (r.sections || []).length
    ? r.sections.map(s => _esc(s.label) + (s.archived ? ' (archived)' : '')).join(', ')
    : '—';
  const lastActive = r.lastActiveAt ? _teacherDirFormatDate(r.lastActiveAt) : 'Never';
  const created = r.createdAt ? _teacherDirFormatDate(r.createdAt) : '—';

  // Demoting/deactivating the last active admin is refused server-side
  // anyway, but disable the buttons client-side too so it's not a
  // dead-end click followed by a toast.
  const demoteDisabled = isAdmin && adminCount <= 1;
  const deactivateDisabled = isSelf || (isAdmin && isActive && activeAdminCount <= 1);
  const deactivateTitle = isSelf
    ? 'You cannot deactivate your own account'
    : (isAdmin && isActive && activeAdminCount <= 1 ? 'Cannot deactivate the last remaining active admin' : '');

  const roleBtn = isAdmin
    ? `<button class="btn btn-xs ${demoteDisabled ? 'btn-ghost' : 'btn-danger'}" ${demoteDisabled ? 'disabled title="Cannot demote the last remaining admin"' : ''} onclick="doDemoteAdmin('${r.id}','${label}')" style="width:100%">Demote to Teacher</button>`
    : `<button class="btn btn-xs btn-primary" onclick="doPromoteTeacher('${r.id}','${label}')" style="width:100%">Promote to Admin</button>`;

  const statusBtn = isActive
    ? `<button class="btn btn-xs ${deactivateDisabled ? 'btn-ghost' : 'btn-danger'}" ${deactivateDisabled ? `disabled title="${deactivateTitle}"` : ''} onclick="doDeactivateAccount('${r.id}','${label}')" style="width:100%">Deactivate</button>`
    : `<button class="btn btn-xs btn-success" onclick="doReactivateAccount('${r.id}','${label}')" style="width:100%">Reactivate</button>`;

  // A4: reset email needs somewhere to send TO. A deactivated account can
  // still receive and act on a reset link (recovery.js's screen only calls
  // updateUser() against whatever session the link resolves to — it never
  // checks is_active), so this is available regardless of status, same as
  // it would be if the teacher had used a "Forgot password?" link herself.
  const resetEmail = r.email || '';
  const resetDisabled = !resetEmail;
  const resetBtn = `<button class="btn btn-xs btn-ghost" ${resetDisabled ? 'disabled title="No email on file"' : ''} onclick="doSendPasswordReset('${r.id}','${_esc(resetEmail)}','${label}')" style="width:100%">Send Reset Email</button>`;

  // Chunk C: jump straight into that teacher's Content Oversight drill-in
  // (read-only by default — "Edit as" is a separate opt-in inside that screen).
  const contentBtn = `<button class="btn btn-xs btn-ghost" onclick="openContentOversightFor('${r.id}','${label}')" style="width:100%">View Content</button>`;

  // Chunk D: full offboarding — moves every section AND every piece of
  // content this account owns to a destination teacher in one call. Kept
  // separate from Deactivate (an admin may want to transfer without
  // locking the account, or vice versa — see ownership-service.js header).
  // Disabled when there's no OTHER active account to receive it.
  const otherActiveCount = activeStaffCount - (isActive ? 1 : 0);
  const transferDisabled = otherActiveCount < 1;
  const transferBtn = `<button class="btn btn-xs btn-ghost" ${transferDisabled ? 'disabled title="No other active account to transfer to"' : ''} onclick="_tdOpenTransferModal('${r.id}')" style="width:100%">Transfer Ownership</button>`;

  return `
  <div style="display:grid;grid-template-columns:${_TD_COLS};gap:10px;align-items:center;padding:12px 16px;border-bottom:1px solid var(--border2);${busy ? 'opacity:.5' : ''}${isActive ? '' : ';background:rgba(255,180,171,.05)'}">
    <div style="min-width:0">
      <div style="font-size:13px;font-weight:700;color:var(--on-surface);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${_esc(r.displayName || '(no name)')}${isSelf ? ' <span style="font-size:10px;color:var(--text-muted);font-weight:600">(you)</span>' : ''}</div>
      <div style="font-size:10px;color:var(--text-muted);margin-top:2px">Joined ${created}</div>
    </div>
    <span class="btn btn-xs ${isAdmin ? 'btn-primary' : 'btn-ghost'}" style="width:fit-content;pointer-events:none">${isAdmin ? 'Admin' : 'Teacher'}</span>
    <span class="btn btn-xs ${isActive ? 'btn-success' : 'btn-danger'}" style="width:fit-content;pointer-events:none">${isActive ? 'Active' : 'Deactivated'}</span>
    <div style="font-size:12px;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${_esc(r.email || '—')}</div>
    <div style="font-size:13px;font-weight:700;text-align:center">${r.studentCount ?? 0}</div>
    <div style="font-size:13px;font-weight:700;text-align:center"><a href="javascript:void(0)" onclick="openContentOversightFor('${r.id}','${label}')" style="color:inherit;text-decoration:underline;text-decoration-style:dotted" title="${r.achievementCount||0} achievements · ${r.titleCount||0} titles · ${r.quizCount||0} quizzes · ${r.campaignWorldCount||0} worlds · ${r.shopProductCount||0} shop items">${contentTotal}</a></div>
    <div style="font-size:11px;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${_esc(sectionsLabel)}">${_esc(sectionsLabel)}</div>
    <div style="font-size:11px;color:var(--text-muted)">${lastActive}</div>
    <div style="display:flex;flex-direction:column;gap:4px">${roleBtn}${statusBtn}${resetBtn}${contentBtn}${transferBtn}</div>
  </div>`;
}

function _teacherDirFormatDate(iso) {
  try {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '—';
    return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  } catch (e) { return '—'; }
}

// ── INVITE A NEW TEACHER (chunk A5) ─────────────────────
//
// Generic links only (no per-invite pre-filled name/email — the invited
// person fills in everything themselves, see teacher-invite.js). The link
// is built client-side; the token itself is the only thing that ever needs
// to round-trip through Supabase.

function _teacherInviteLink(token) {
  return window.location.origin + window.location.pathname + '?teacher_invite=' + encodeURIComponent(token);
}

function _teacherInvitePanel() {
  const generating = _teacherInviteGenerating;
  const genBtn = `<button class="btn btn-sm btn-primary" ${generating ? 'disabled' : ''} onclick="doGenerateTeacherInvite()">
    ${generating ? 'Generating…' : '+ Generate Invite Link'}
  </button>`;

  return `
  <div class="glass-card" style="padding:20px 16px;margin-bottom:16px">
    <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px;flex-wrap:wrap">
      <div>
        <h3 style="font-family:var(--fh);font-size:16px;font-weight:800;margin:0">Invite a New Teacher</h3>
        <p style="font-size:12px;color:var(--text-muted);margin:2px 0 0">
          Generate a link, then share it yourself (Slack, email, etc.) — the teacher fills in their own name, email, and password. Links expire after 7 days.
        </p>
      </div>
      ${genBtn}
    </div>
    ${_teacherInviteBody()}
  </div>`;
}

function _teacherInviteBody() {
  if (_teacherInvitesLoading) {
    return `<div style="padding:16px;text-align:center;color:var(--text-muted);font-size:13px">Loading invites…</div>`;
  }
  if (_teacherInvitesError) {
    return `<div style="padding:16px;text-align:center;color:#ffb4ab;font-size:13px">${_esc(_teacherInvitesError)}</div>`;
  }
  const invites = _teacherInvites || [];
  if (invites.length === 0) {
    return `<div style="padding:12px 2px;color:var(--text-muted);font-size:12px">No invites yet — generate one above.</div>`;
  }
  const cols = '1.6fr 90px 110px 110px 1fr 140px';
  return `
  <div style="border:1px solid var(--border2);border-radius:12px;overflow:hidden">
    <div style="display:grid;grid-template-columns:${cols};gap:10px;align-items:center;padding:8px 14px;font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);border-bottom:1px solid var(--border2)">
      <span>Link</span><span>Status</span><span>Created</span><span>Expires</span><span>Used By</span><span></span>
    </div>
    ${invites.map(_teacherInviteRow).join('')}
  </div>`;
}

function _teacherInviteRow(inv) {
  const busy = _teacherInviteBusyToken === inv.token;
  const isPending = inv.status === 'pending';
  const isExpired = isPending && inv.expiresAt && new Date(inv.expiresAt).getTime() <= Date.now();
  const effectiveStatus = isExpired ? 'expired' : inv.status;
  const statusColors = { pending: 'btn-success', used: 'btn-primary', revoked: 'btn-danger', expired: 'btn-ghost' };
  const statusLabels = { pending: 'Pending', used: 'Used', revoked: 'Revoked', expired: 'Expired' };
  const canCopy = isPending && !isExpired;
  const canRevoke = isPending && !isExpired;

  const cols = '1.6fr 90px 110px 110px 1fr 140px';
  return `
  <div style="display:grid;grid-template-columns:${cols};gap:10px;align-items:center;padding:10px 14px;border-bottom:1px solid var(--border2);${busy ? 'opacity:.5' : ''}">
    <div style="font-size:11px;font-family:monospace;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${_esc(_teacherInviteLink(inv.token))}">${_esc(inv.token.slice(0, 12))}…</div>
    <span class="btn btn-xs ${statusColors[effectiveStatus] || 'btn-ghost'}" style="width:fit-content;pointer-events:none">${statusLabels[effectiveStatus] || effectiveStatus}</span>
    <div style="font-size:11px;color:var(--text-muted)">${_teacherDirFormatDate(inv.createdAt)}</div>
    <div style="font-size:11px;color:var(--text-muted)">${_teacherDirFormatDate(inv.expiresAt)}</div>
    <div style="font-size:12px;color:var(--text-muted)">${inv.usedByName ? _esc(inv.usedByName) : '—'}</div>
    <div style="display:flex;gap:6px;justify-content:flex-end">
      ${canCopy ? `<button class="btn btn-xs btn-ghost" onclick="doCopyTeacherInviteLink('${inv.token}')">Copy Link</button>` : ''}
      ${canRevoke ? `<button class="btn btn-xs btn-danger" onclick="doRevokeTeacherInvite('${inv.token}')">Revoke</button>` : ''}
    </div>
  </div>`;
}

window.doGenerateTeacherInvite = async function () {
  if (_teacherInviteGenerating) return;
  _teacherInviteGenerating = true;
  const el = document.getElementById('a-teachers');
  if (el) _teacherDirRenderShell(el);

  const result = await TeacherDirectoryService.createInvite();
  _teacherInviteGenerating = false;

  if (!result.ok) {
    toast('❌ ' + (result.error || 'Could not create an invite link.'), '#ffb4ab');
    if (document.getElementById('a-teachers')) window.renderTeacherDirectory();
    return;
  }

  // Copy immediately — generating a link is almost always followed by
  // pasting it somewhere, so save the extra click.
  await _teacherInviteCopyToClipboard(_teacherInviteLink(result.invite.token));
  toast('✅ Invite link created and copied to clipboard.');
  if (document.getElementById('a-teachers')) window.renderTeacherDirectory();
};

window.doCopyTeacherInviteLink = async function (token) {
  await _teacherInviteCopyToClipboard(_teacherInviteLink(token));
};

async function _teacherInviteCopyToClipboard(text) {
  try {
    await navigator.clipboard.writeText(text);
    toast('✅ Link copied to clipboard.');
  } catch (e) {
    // Clipboard API can fail (no permission, insecure context, etc.) — fall
    // back to just showing the link so the admin can select/copy it by hand.
    toast('⚠️ Could not auto-copy. Link: ' + text, '#ffb95f');
  }
}

window.doRevokeTeacherInvite = async function (token) {
  if (_teacherInviteBusyToken) return;
  if (!confirm('Revoke this invite link? Anyone who still has it will no longer be able to use it.')) return;

  _teacherInviteBusyToken = token;
  const el = document.getElementById('a-teachers');
  if (el) _teacherDirRenderShell(el);

  const result = await TeacherDirectoryService.revokeInvite(token);
  _teacherInviteBusyToken = null;

  if (!result.ok) toast('❌ ' + (result.error || 'Could not revoke this invite.'), '#ffb4ab');
  else toast('✅ Invite revoked.');

  if (document.getElementById('a-teachers')) window.renderTeacherDirectory();
};

// ── ROLE ACTIONS ────────────────────────────────────────

window.doPromoteTeacher = async function (teacherId, label) {
  if (_teacherDirBusyId) return;
  if (!confirm(`Promote "${label}" to admin? They'll gain school-wide oversight access.`)) return;
  await _teacherDirRunAction(teacherId, () => TeacherDirectoryService.promoteToAdmin(teacherId),
    `✅ ${label} promoted to admin.`, 'Could not promote this account.');
};

window.doDemoteAdmin = async function (adminId, label) {
  if (_teacherDirBusyId) return;
  if (!confirm(`Demote "${label}" to teacher? They'll lose school-wide oversight access and keep only their own content.`)) return;
  await _teacherDirRunAction(adminId, () => TeacherDirectoryService.demoteToTeacher(adminId),
    `✅ ${label} demoted to teacher.`, 'Could not demote this account.');
};

// ── ACCOUNT STATUS ACTIONS ──────────────────────────────

window.doDeactivateAccount = async function (targetId, label) {
  if (_teacherDirBusyId) return;
  if (!confirm(`Deactivate "${label}"? They'll immediately lose access to log in or use any teacher/admin features until reactivated.`)) return;
  await _teacherDirRunAction(targetId, () => TeacherDirectoryService.deactivateAccount(targetId),
    `✅ ${label} deactivated.`, 'Could not deactivate this account.');
};

window.doReactivateAccount = async function (targetId, label) {
  if (_teacherDirBusyId) return;
  if (!confirm(`Reactivate "${label}"? They'll regain access immediately.`)) return;
  await _teacherDirRunAction(targetId, () => TeacherDirectoryService.reactivateAccount(targetId),
    `✅ ${label} reactivated.`, 'Could not reactivate this account.');
};

// ── PASSWORD RESET ──────────────────────────────────────

window.doSendPasswordReset = async function (targetId, email, label) {
  if (_teacherDirBusyId) return;
  if (!email) { toast('❌ No email on file for this account.', '#ffb4ab'); return; }
  if (!confirm(`Send a password reset email to "${label}" (${email})? Their current password keeps working until they open the link and set a new one.`)) return;
  await _teacherDirRunAction(targetId, () => TeacherDirectoryService.sendPasswordReset(email),
    `✅ Reset email sent to ${email}.`, 'Could not send the reset email.');
};

// Shared helper: mark busy, run the service call, toast the result, refetch.
async function _teacherDirRunAction(id, runFn, successMsg, defaultErrorMsg) {
  _teacherDirBusyId = id;
  const el = document.getElementById('a-teachers');
  if (el) _teacherDirRenderShell(el);

  const result = await runFn();
  _teacherDirBusyId = null;

  if (!result.ok) toast('❌ ' + (result.error || defaultErrorMsg), '#ffb4ab');
  else toast(successMsg);

  if (document.getElementById('a-teachers')) window.renderTeacherDirectory();
}

// ── TRANSFER OWNERSHIP (Chunk D — full offboarding) ─────
//
// Moves EVERY section this teacher advises and EVERY piece of content they
// own to one destination teacher, in a single transaction
// (transfer_teacher_ownership(), Phase 42). Each active section gets a
// per-row choice: reassign to the destination (default), or archive
// instead. Content always bulk-moves — no per-item picker (see phase42's
// header for why). This is intentionally a DIFFERENT action from Section
// Maker's "🔁 Reassign" quick action (sections.js) — that one moves a
// single section and never touches content.

window._tdOpenTransferModal = function (fromTeacherId) {
  const rows = _teacherDirRows || [];
  const from = rows.find(r => r.id === fromTeacherId);
  if (!from) { toast('❌ Account not found.', '#ffb4ab'); return; }

  const fromLabel = _esc(from.displayName || from.email || from.id);
  const destinations = rows.filter(r => r.id !== fromTeacherId && r.isActive !== false);
  if (!destinations.length) { toast('❌ No other active account to transfer to.', '#ffb4ab'); return; }

  const destOptions = destinations
    .map(r => `<option value="${_esc(r.id)}">${_esc(r.displayName || r.email || r.id)}${r.role === 'admin' ? ' (Admin)' : ''}</option>`)
    .join('');

  const activeSections = (from.sections || []).filter(s => !s.archived);
  const sectionRows = activeSections.length
    ? activeSections.map(s => `
      <label style="display:flex;align-items:center;gap:8px;padding:6px 0;font-size:13px;cursor:pointer">
        <input type="checkbox" class="td-transfer-archive-cb" value="${_esc(s.id)}">
        <span style="flex:1">${_esc(s.label)}</span>
        <span style="font-size:11px;color:var(--text-muted)">check to archive instead of reassign</span>
      </label>`).join('')
    : `<div style="font-size:12px;color:var(--text-muted)">No active sections to reassign.</div>`;

  const contentTotal = (from.achievementCount || 0) + (from.titleCount || 0) + (from.quizCount || 0)
    + (from.campaignWorldCount || 0) + (from.shopProductCount || 0);

  showModal(`
    <div style="font-family:var(--fh);font-size:18px;font-weight:900;margin-bottom:6px">📤 Transfer Ownership</div>
    <div style="font-size:13px;color:var(--text-muted);margin-bottom:16px">
      Moves everything <strong>${fromLabel}</strong> owns — ${contentTotal} content item${contentTotal === 1 ? '' : 's'}
      and ${activeSections.length} active section${activeSections.length === 1 ? '' : 's'} — to one destination account.
      This does not deactivate ${fromLabel}'s account; do that separately if they're actually leaving.
    </div>

    <div class="form-group">
      <label class="form-label">Transfer everything to</label>
      <select id="td-transfer-dest" style="width:100%">
        <option value="">— Select a teacher —</option>
        ${destOptions}
      </select>
    </div>

    ${activeSections.length ? `
    <div class="form-group">
      <label class="form-label">Sections</label>
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:6px">
        Every section below is reassigned to the destination teacher by default. Check any you'd
        rather archive instead (e.g. a section being dissolved, not handed off).
      </div>
      <div style="max-height:160px;overflow-y:auto;border:1px solid var(--border2);border-radius:8px;padding:4px 10px">
        ${sectionRows}
      </div>
    </div>` : ''}

    <div id="td-transfer-err" style="color:#ffb4ab;font-size:13px;margin:10px 0;display:none"></div>

    <div style="display:flex;gap:8px;margin-top:6px">
      <button class="btn btn-ghost" style="flex:1" onclick="closeModalForce()">Cancel</button>
      <button class="btn btn-primary" style="flex:1" onclick="_tdSubmitTransfer('${_esc(fromTeacherId)}','${fromLabel}')">Transfer Ownership</button>
    </div>`, 'md');
};

window._tdSubmitTransfer = async function (fromTeacherId, fromLabel) {
  const destEl = document.getElementById('td-transfer-dest');
  const toTeacherId = destEl ? destEl.value : '';
  const errEl = document.getElementById('td-transfer-err');

  if (!toTeacherId) {
    if (errEl) { errEl.textContent = '❌ Choose a destination teacher.'; errEl.style.display = 'block'; }
    return;
  }

  const archiveSectionIds = Array.from(document.querySelectorAll('.td-transfer-archive-cb:checked')).map(cb => cb.value);
  const destLabel = destEl.options[destEl.selectedIndex]?.text || 'the destination teacher';

  if (!confirm(`Transfer all of ${fromLabel}'s sections and content to ${destLabel}? This cannot be undone automatically.`)) return;

  closeModalForce();
  toast('⏳ Transferring ownership…');

  const result = await OwnershipService.transferOwnership({ fromTeacherId, toTeacherId, archiveSectionIds });
  if (!result.ok) {
    toast('❌ ' + (result.error || 'Could not transfer ownership.'), '#ffb4ab');
    return;
  }

  const s = result.summary;
  const contentMoved = s.achievements + s.titles + s.quizzes + s.campaignWorlds + s.shopProducts + s.bossLibrary;
  toast(`✅ Transferred to ${destLabel}: ${s.sectionsReassigned} section${s.sectionsReassigned === 1 ? '' : 's'} reassigned, ${s.sectionsArchived} archived, ${contentMoved} content item${contentMoved === 1 ? '' : 's'} moved.`);

  if (document.getElementById('a-teachers')) window.renderTeacherDirectory();
};


/* ---- ./modules/admin/content-oversight-service.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/admin/content-oversight-service.js
//  Service layer for Chunk C: Content Oversight (read-only drill-in + "Edit as").
//  (ISOLATION_ROLES_PLAN.md Chunk C — see supabase/phase41_content_oversight.sql,
//   audit-log-service.js, teacher-directory-service.js.)
//
//  REPOSITORY PATTERN CONTRACT — same rule as every other *Service module:
//  content-oversight.js (the render layer) NEVER calls DBService.rpc() or
//  AuditLogService directly — it calls ContentOversightService.<method>(...).
//  This file is the ONLY place that pairs an oversight write with its
//  log_edit_as_action() call, so "every Edit-as write gets logged" is
//  enforced in one spot rather than repeated per render-layer call site.
//
//  Deliberately does NOT touch AppStore/DB.achievements etc. — same reason
//  starter-pack-service.js stays separate (see its header): another
//  teacher's content must never end up mixed into the admin's own local
//  catalog cache. This screen fetches and mutates its own separate,
//  short-lived local state instead.
//
//  WHAT'S HERE
//    fetchTeacherContent(teacherId) — read-only bundle (get_teacher_content()).
//    saveAchievement()/saveTitle()/saveQuiz()/saveCampaignWorld()/saveShopItem()
//      — each takes { teacherId, row, isNew }, calls the matching
//      oversight_upsert_*() RPC, then logs via AuditLogService on success.
//    deleteAchievement()/deleteTitle()/deleteQuiz()/deleteCampaignWorld()/
//    deleteShopItem() — reuse the EXISTING delete_*() RPCs unchanged (they
//    already accept any admin regardless of owner), then log the delete.
//
//  A write RPC succeeding but the follow-up log call failing is a real gap
//  (the two aren't atomic) — same tradeoff already accepted in Chunk E's
//  design note. If that ever matters in practice, wrapping both in a single
//  RPC is the fix; not done here to keep this chunk's SQL surface small.
// ═══════════════════════════════════════════════════════════════════════════════

window.ContentOversightService = (function () {
  'use strict';

  async function fetchTeacherContent(teacherId) {
    const { data, error } = await DBService.rpc('get_teacher_content', { p_owner_teacher_id: teacherId });
    if (error) return { ok: false, error: error.message || 'Could not load this teacher\u2019s content.' };
    return { ok: true, content: data || { achievements: [], titles: [], quizzes: [], campaignWorlds: [], shopProducts: [] } };
  }

  async function _logWrite(teacherId, tableName, recordId, action) {
    // Best-effort — a logging failure shouldn't undo an otherwise-successful
    // save/delete or block the admin from continuing; surfaced via console
    // only. See header note on the non-atomicity tradeoff.
    const res = await AuditLogService.logEditAsAction({ targetTeacherId: teacherId, tableName, recordId, action });
    if (!res.ok) console.error('[EduQuest] Edit-as action succeeded but logging failed:', tableName, recordId, action, res.error);
  }

  async function saveAchievement(teacherId, a, isNew) {
    const { data, error } = await DBService.rpc('oversight_upsert_achievement', {
      p_owner_teacher_id: teacherId,
      p_id: a.id, p_name: a.name, p_description: a.description || '', p_icon: a.icon || '🏅',
      p_category: a.category || 'General', p_rarity: a.rarity || 'Common',
      p_xp_reward: a.xpReward || 0, p_coin_reward: a.coinReward || 0,
      p_trigger_type: a.triggerType || 'manual', p_trigger_value: a.triggerValue || 0,
      p_active: a.active !== false,
    });
    if (error) return { ok: false, error: error.message || 'Could not save this achievement.' };
    await _logWrite(teacherId, 'achievements', data.id, isNew ? 'create' : 'update');
    return { ok: true, row: data };
  }

  async function saveTitle(teacherId, t, isNew) {
    const { data, error } = await DBService.rpc('oversight_upsert_title', {
      p_owner_teacher_id: teacherId,
      p_id: t.id, p_name: t.name, p_description: t.description || '', p_icon: t.icon || '🎖️',
      p_rarity: t.rarity || 'Common', p_active: t.active !== false,
      p_text_color: t.textColor || null, p_border_color: t.borderColor || null,
      p_glow_color: t.glowColor || null, p_bg_color: t.bgColor || null,
    });
    if (error) return { ok: false, error: error.message || 'Could not save this title.' };
    await _logWrite(teacherId, 'titles', data.id, isNew ? 'create' : 'update');
    return { ok: true, row: data };
  }

  async function saveQuiz(teacherId, q, isNew) {
    const { data, error } = await DBService.rpc('oversight_upsert_quiz', {
      p_owner_teacher_id: teacherId,
      p_id: q.id, p_title: q.title, p_description: q.description || '',
      p_xp_reward: q.xpReward || 0, p_coin_reward: q.coinReward || 0,
      p_time_limit: q.timeLimit || null, p_questions: q.questions || [],
      p_active: q.active !== false,
      p_rarity: q.rarity || 'Common', p_cadence: q.cadence || 'standing',
      // Phase 60 pass-through — see matching note in starter-pack-service.js.
      p_chain_id: q.chainId ?? null, p_chain_order: q.chainOrder ?? 1, p_chain_label: q.chainLabel ?? null,
      p_start_date: q.startDate ?? null, p_end_date: q.endDate ?? null,
    });
    if (error) return { ok: false, error: error.message || 'Could not save this quiz.' };
    await _logWrite(teacherId, 'quizzes', data.id, isNew ? 'create' : 'update');
    return { ok: true, row: data };
  }

  async function saveCampaignWorld(teacherId, w, isNew) {
    const { data, error } = await DBService.rpc('oversight_upsert_campaign_world', {
      p_owner_teacher_id: teacherId,
      p_id: w.id, p_label: w.label, p_icon: w.icon || '🗺️', p_color: w.color || '#8b5cf6',
      p_description: w.description || '', p_stages: w.stages || [], p_active: w.active !== false,
    });
    if (error) return { ok: false, error: error.message || 'Could not save this campaign world.' };
    await _logWrite(teacherId, 'campaign_worlds', data.id, isNew ? 'create' : 'update');
    return { ok: true, row: data };
  }

  async function saveShopItem(teacherId, p, isNew) {
    const { data, error } = await DBService.rpc('oversight_upsert_shop_item', {
      p_owner_teacher_id: teacherId,
      p_id: p.id, p_name: p.name, p_emoji: p.emoji || '🎁', p_description: p.description || '',
      p_category: p.category || 'General', p_cost: p.cost || 0, p_active: p.active !== false,
    });
    if (error) return { ok: false, error: error.message || 'Could not save this shop item.' };
    await _logWrite(teacherId, 'shop_products', data.id, isNew ? 'create' : 'update');
    return { ok: true, row: data };
  }

  async function deleteAchievement(teacherId, id) {
    const { error } = await DBService.rpc('delete_achievement', { p_achievement_id: id });
    if (error) return { ok: false, error: error.message || 'Could not delete this achievement.' };
    await _logWrite(teacherId, 'achievements', id, 'delete');
    return { ok: true };
  }

  async function deleteTitle(teacherId, id) {
    const { error } = await DBService.rpc('delete_title', { p_title_id: id });
    if (error) return { ok: false, error: error.message || 'Could not delete this title.' };
    await _logWrite(teacherId, 'titles', id, 'delete');
    return { ok: true };
  }

  async function deleteQuiz(teacherId, id) {
    const { error } = await DBService.rpc('delete_quiz', { p_quiz_id: id });
    if (error) return { ok: false, error: error.message || 'Could not delete this quiz.' };
    await _logWrite(teacherId, 'quizzes', id, 'delete');
    return { ok: true };
  }

  async function deleteCampaignWorld(teacherId, id) {
    const { error } = await DBService.rpc('delete_campaign_world', { p_world_id: id });
    if (error) return { ok: false, error: error.message || 'Could not delete this campaign world.' };
    await _logWrite(teacherId, 'campaign_worlds', id, 'delete');
    return { ok: true };
  }

  async function deleteShopItem(teacherId, id) {
    const { error } = await DBService.rpc('delete_shop_product', { p_product_id: id });
    if (error) return { ok: false, error: error.message || 'Could not delete this shop item.' };
    await _logWrite(teacherId, 'shop_products', id, 'delete');
    return { ok: true };
  }

  return {
    fetchTeacherContent,
    saveAchievement, saveTitle, saveQuiz, saveCampaignWorld, saveShopItem,
    deleteAchievement, deleteTitle, deleteQuiz, deleteCampaignWorld, deleteShopItem,
  };
})();


/* ---- ./modules/admin/content-oversight.js ---- */
// ══════════════════════════════════════════════════════
//  modules/admin/content-oversight.js
//  Content Oversight — admin-only screen (Chunk C).
//  (ISOLATION_ROLES_PLAN.md Chunk C — see content-oversight-service.js and
//   supabase/phase41_content_oversight.sql.)
//
//  Two modes on the same screen:
//    - READ-ONLY (default): pick a teacher, browse their achievements/
//      titles/quizzes/campaign world/shop content. No Add/Edit/Delete
//      controls render at all in this mode — this isn't just buttons
//      hidden by CSS, _coRenderXxx() below never emits them.
//    - EDIT AS (opt-in, confirmed, logged): same 5 tabs, now with Add/
//      Edit/Delete, backed by the oversight_upsert_*()/delete_*() RPCs.
//      Every write is logged via ContentOversightService (which pairs each
//      RPC call with log_edit_as_action() — see its header).
//
//  Field depth mirrors the Starter Pack Editor (Phase 38) exactly, per the
//  scope decided before building this — see starter-pack-editor.js for the
//  same "small screen" reasoning (quiz questions as a repeatable list, not
//  the full Quest Builder; campaign stages as raw JSON).
//
//  REPOSITORY PATTERN: this file never calls DBService.rpc() or
//  AuditLogService directly — only ContentOversightService and
//  TeacherDirectoryService (for the picker/header label).
//
//  Exports: renderContentOversight, openContentOversightFor
// ══════════════════════════════════════════════════════

let _coTeacherId = null;
let _coTeacherLabel = '';
let _coEditMode = false;
let _coLoading = false;
let _coError = null;
let _coContent = { achievements: [], titles: [], quizzes: [], campaignWorlds: [], shopProducts: [] };
let _coTab = 'achievements';

let _coPickerLoading = false;
let _coPickerError = null;
let _coPickerRows = null;
let _coPickerSearch = '';

window._coSetPickerSearch = function (value) {
  _coPickerSearch = String(value || '');
  _coRedrawPickerList();
};

// Per-tab search — this screen drills into ONE teacher's content at a time
// (bounded in practice, unlike a school-wide list), so a quick filter is
// what actually helps here; full pagination isn't worth the added
// complexity against the idx-based Edit/Delete handlers below. Search
// state persists per tab so switching tabs and back doesn't lose it.
let _coSearch = { achievements: '', titles: '', quizzes: '', campaignWorlds: '', shopProducts: '' };

window._coSetSearch = function (tab, value) {
  _coSearch[tab] = String(value || '');
  const redraw = {
    achievements: _coRedrawAchievements, titles: _coRedrawTitles, quizzes: _coRedrawQuizzes,
    campaignWorlds: _coRedrawCampaignWorlds, shopProducts: _coRedrawShopProducts,
  }[tab];
  if (redraw) redraw();
};

const _CO_TABS = [
  { id: 'achievements',   label: 'Achievements',    icon: '🏅' },
  { id: 'titles',         label: 'Titles',          icon: '🎖️' },
  { id: 'quizzes',        label: 'Quiz',            icon: '📝' },
  { id: 'campaignWorlds', label: 'Campaign World',  icon: '🗺️' },
  { id: 'shopProducts',   label: 'Shop Items',      icon: '🏪' },
];

// ── Entry points ─────────────────────────────────────────────────────────

// Called from Teacher Directory's "View Content" action — jumps straight
// to a specific teacher's drill-in, skipping the picker.
window.openContentOversightFor = function (teacherId, label) {
  _coTeacherId = teacherId;
  _coTeacherLabel = label || '';
  _coEditMode = false;
  navTo('a-content-oversight');
};

window.renderContentOversight = async function () {
  const el = document.getElementById('a-content-oversight');
  if (!el) return;

  // Defense in depth: nav.js already hides this tab and bounces direct
  // navTo() calls for a non-admin — same guard as every other
  // ADMIN_ONLY_NAV_IDS screen (see teacher-directory.js).
  if (currentRole !== 'admin') {
    el.innerHTML = `
    <div class="glass-card" style="padding:32px;text-align:center">
      <span class="material-symbols-outlined" style="font-size:40px;color:var(--text-muted)">lock</span>
      <h2 style="font-family:var(--fh);font-size:18px;margin:12px 0 4px">Admin only</h2>
      <p style="font-size:13px;color:var(--text-muted)">This screen is only available to oversight admin accounts.</p>
    </div>`;
    return;
  }

  if (!_coTeacherId) return _coRenderPicker(el);

  _coLoading = true;
  _coError = null;
  _coRenderShell(el);

  const res = await ContentOversightService.fetchTeacherContent(_coTeacherId);
  _coLoading = false;
  if (!res.ok) {
    _coError = res.error;
  } else {
    _coContent = res.content;
  }

  if (document.getElementById('a-content-oversight')) _coRenderShell(document.getElementById('a-content-oversight'));
};

window.unmountContentOversight = function () {
  // Leaving the screen entirely (not just switching tabs) always drops back
  // to read-only — an admin should never return to this tab later and find
  // themselves silently still in Edit-as mode from a previous visit.
  _coEditMode = false;
};

// ── Teacher picker ──────────────────────────────────────────────────────

async function _coRenderPicker(el) {
  el.innerHTML = `
  <div style="margin-bottom:20px">
    <div style="font-family:var(--fh);font-size:26px;font-weight:900">🔎 Content Oversight</div>
    <div style="font-size:13px;color:var(--text-muted);margin-top:4px">Pick a teacher to browse their content read-only, or make a rare direct fix via "Edit as".</div>
  </div>
  <div id="co-picker-body">${_coPickerLoading ? `<div style="padding:40px;text-align:center;color:var(--text-muted)">Loading teachers…</div>` : ''}</div>`;

  if (_coPickerRows === null || _coPickerLoading) {
    _coPickerLoading = true;
    const res = await TeacherDirectoryService.getDirectory();
    _coPickerLoading = false;
    if (!res.ok) { _coPickerError = res.error; _coPickerRows = null; }
    else { _coPickerRows = res.teachers; _coPickerError = null; }
  }
  const body = document.getElementById('co-picker-body');
  if (!body) return;

  if (_coPickerError) {
    body.innerHTML = `<div class="glass-card" style="padding:16px;color:#ff6b6b">⚠️ ${_coEsc(_coPickerError)}</div>`;
    return;
  }
  body.innerHTML = `
  <div style="margin-bottom:14px;max-width:280px">
    <input type="text" placeholder="Search name or email…" value="${_coEscAttr(_coPickerSearch)}" oninput="_coSetPickerSearch(this.value)">
  </div>
  <div id="co-picker-list"></div>`;
  _coRedrawPickerList();
}

function _coRedrawPickerList() {
  const el = document.getElementById('co-picker-list');
  if (!el) return;
  const all = _coPickerRows || [];
  const q = _coPickerSearch.trim().toLowerCase();
  const rows = q ? all.filter(r => (r.displayName || '').toLowerCase().includes(q) || (r.email || '').toLowerCase().includes(q)) : all;
  el.innerHTML = `
  <div class="glass-card" style="padding:0;overflow:hidden">
    <table class="admin-table">
      <thead><tr><th>Teacher</th><th>Role</th><th style="text-align:center">Content Items</th><th style="width:140px"></th></tr></thead>
      <tbody>
        ${rows.map(r => `
          <tr>
            <td>
              <strong>${_coEsc(r.displayName || '(no name)')}</strong>
              <div style="font-size:11px;color:var(--text-muted)">${_coEsc(r.email || '')}</div>
            </td>
            <td><span class="btn btn-xs ${r.role === 'admin' ? 'btn-primary' : 'btn-ghost'}" style="pointer-events:none">${r.role === 'admin' ? 'Admin' : 'Teacher'}</span></td>
            <td style="text-align:center">${(r.achievementCount||0)+(r.titleCount||0)+(r.quizCount||0)+(r.campaignWorldCount||0)+(r.shopProductCount||0)}</td>
            <td><button class="btn btn-primary btn-sm" onclick="openContentOversightFor('${r.id}','${_coEsc(r.displayName || r.email || '')}')" style="width:100%">View Content</button></td>
          </tr>`).join('') || `<tr><td colspan="4" style="text-align:center;color:var(--text-muted);padding:20px">${q ? 'No teachers match your search.' : 'No teacher accounts yet.'}</td></tr>`}
      </tbody>
    </table>
  </div>`;
}

// ── Drill-in shell ──────────────────────────────────────────────────────

function _coRenderShell(el) {
  el.innerHTML = `
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:10px">
    <div>
      <button class="btn btn-ghost btn-sm" onclick="_coBackToPicker()" style="margin-bottom:6px">← All Teachers</button>
      <div style="font-family:var(--fh);font-size:24px;font-weight:900">${_coEsc(_coTeacherLabel || 'Teacher')}'s Content</div>
    </div>
    <div>
      ${_coEditMode
        ? `<button class="btn btn-danger btn-sm" onclick="_coToggleEditMode()">✓ Done Editing</button>`
        : `<button class="btn btn-primary btn-sm" onclick="_coToggleEditMode()">✏️ Edit as ${_coEsc(_coTeacherLabel || 'this teacher')}</button>`}
    </div>
  </div>

  ${_coEditMode ? `
  <div class="glass-card" style="padding:12px 16px;margin-bottom:16px;background:rgba(255,185,95,.1);border-color:rgba(255,185,95,.35)">
    <strong style="color:#ffb95f">✏️ Editing as ${_coEsc(_coTeacherLabel || 'this teacher')}</strong>
    <span style="font-size:12px;color:var(--text-muted);margin-left:6px">Every change here is logged and attributed to your admin account.</span>
  </div>` : `
  <div class="glass-card" style="padding:12px 16px;margin-bottom:16px">
    <span style="font-size:12px;color:var(--text-muted)">👁️ Read-only. Use "Edit as" above for the rare direct-fix case.</span>
  </div>`}

  ${_coLoading ? `<div style="padding:40px;text-align:center;color:var(--text-muted)">Loading…</div>` : ''}
  ${_coError ? `<div class="glass-card" style="padding:16px;color:#ff6b6b;margin-bottom:16px">⚠️ ${_coEsc(_coError)}</div>` : ''}

  ${!_coLoading && !_coError ? `
  <div style="display:flex;gap:6px;margin-bottom:16px;flex-wrap:wrap">
    ${_CO_TABS.map(t => `
      <button class="btn ${_coTab === t.id ? 'btn-primary' : 'btn-ghost'}" onclick="_coSwitchTab('${t.id}')">
        ${t.icon} ${t.label} <span style="opacity:.6;font-size:11px">(${(_coContent[t.id] || []).length})</span>
      </button>
    `).join('')}
  </div>
  <div id="co-tab-body"></div>` : ''}
  `;
  if (!_coLoading && !_coError) _coRenderTabBody();
}

window._coBackToPicker = function () {
  _coTeacherId = null;
  _coTeacherLabel = '';
  _coEditMode = false;
  _coContent = { achievements: [], titles: [], quizzes: [], campaignWorlds: [], shopProducts: [] };
  renderContentOversight();
};

window._coToggleEditMode = function () {
  if (!_coEditMode) {
    if (!confirm(`You're about to make direct edits to ${_coTeacherLabel || 'this teacher'}'s account content. Every change is logged. Continue?`)) return;
    _coEditMode = true;
  } else {
    _coEditMode = false;
  }
  _coRenderShell(document.getElementById('a-content-oversight'));
};

window._coSwitchTab = function (id) {
  _coTab = id;
  _coRenderTabBody();
};

function _coRenderTabBody() {
  const body = document.getElementById('co-tab-body');
  if (!body) return;
  if (_coTab === 'achievements') return _coRenderAchievements(body);
  if (_coTab === 'titles') return _coRenderTitles(body);
  if (_coTab === 'quizzes') return _coRenderQuizzes(body);
  if (_coTab === 'campaignWorlds') return _coRenderCampaignWorlds(body);
  if (_coTab === 'shopProducts') return _coRenderShopProducts(body);
}

async function _coRefreshAndRender() {
  const res = await ContentOversightService.fetchTeacherContent(_coTeacherId);
  if (res.ok) _coContent = res.content;
  _coRenderShell(document.getElementById('a-content-oversight'));
}

// ── Achievements ─────────────────────────────────────────────────────────

function _coRenderAchievements(body) {
  body.innerHTML = `
  <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px;flex-wrap:wrap">
    <input type="text" placeholder="Search achievements…" value="${_coEscAttr(_coSearch.achievements)}" oninput="_coSetSearch('achievements',this.value)" style="max-width:280px;flex:1">
    ${_coEditMode ? `<button class="btn btn-primary" onclick="_coOpenAchievementForm(-1)">＋ Add Achievement</button>` : ''}
  </div>
  <div id="co-list-achievements"></div>`;
  _coRedrawAchievements();
}

function _coRedrawAchievements() {
  const el = document.getElementById('co-list-achievements');
  if (!el) return;
  const all = _coContent.achievements || [];
  const q = _coSearch.achievements.trim().toLowerCase();
  const rows = q ? all.filter(a => (a.name || '').toLowerCase().includes(q) || (a.category || '').toLowerCase().includes(q)) : all;
  el.innerHTML = `
  <div class="glass-card" style="padding:0;overflow:hidden">
    <table class="admin-table">
      <thead><tr><th></th><th>Name</th><th>Category</th><th>Rarity</th><th>Trigger</th><th style="text-align:right">Reward</th>${_coEditMode ? '<th style="width:120px"></th>' : ''}</tr></thead>
      <tbody>
        ${rows.map(a => { const i = all.indexOf(a); return `
          <tr>
            <td style="font-size:20px">${a.icon || '🏅'}</td>
            <td><strong>${_coEsc(a.name)}</strong><div style="font-size:11px;color:var(--text-muted)">${_coEsc(a.description || '')}</div></td>
            <td>${_coEsc(a.category || '—')}</td>
            <td>${_coEsc(a.rarity)}</td>
            <td style="font-size:12px;color:var(--text-muted)">${_coEsc(a.triggerType)} ≥ ${a.triggerValue}</td>
            <td style="text-align:right;font-size:12px">${a.xpReward} XP / ${a.coinReward} 🪙</td>
            ${_coEditMode ? `<td>
              <button class="btn btn-ghost btn-sm" onclick="_coOpenAchievementForm(${i})">Edit</button>
              <button class="btn btn-ghost btn-sm" onclick="_coDeleteAchievement(${i})">🗑️</button>
            </td>` : ''}
          </tr>`; }).join('') || `<tr><td colspan="${_coEditMode ? 7 : 6}" style="text-align:center;color:var(--text-muted);padding:20px">${q ? 'No achievements match your search.' : 'No achievements yet.'}</td></tr>`}
      </tbody>
    </table>
  </div>`;
}

window._coOpenAchievementForm = function (idx) {
  if (!_coEditMode) return;
  const d = idx >= 0 ? _coContent.achievements[idx] : { id: 'oversight-ach-' + uid(), name: '', description: '', icon: '🏅', category: 'General', rarity: 'Common', xpReward: 30, coinReward: 15, triggerType: 'manual', triggerValue: 1, active: true };
  window._coEditIdx = idx;
  window._coEditBaseId = d.id;
  showModal(`
    <div style="font-family:var(--fh);font-size:18px;font-weight:800;margin-bottom:16px">${idx >= 0 ? 'Edit' : 'Add'} Achievement</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
      <div><label class="form-label">Name</label><input id="co-a-name" class="form-control" value="${_coEscAttr(d.name)}"></div>
      <div><label class="form-label">Icon (emoji)</label><input id="co-a-icon" class="form-control" value="${_coEscAttr(d.icon)}"></div>
      <div style="grid-column:1/-1"><label class="form-label">Description</label><input id="co-a-desc" class="form-control" value="${_coEscAttr(d.description)}"></div>
      <div><label class="form-label">Category</label><input id="co-a-cat" class="form-control" value="${_coEscAttr(d.category)}"></div>
      <div><label class="form-label">Rarity</label>
        <select id="co-a-rarity" class="form-control">${(window.ACH_RARITIES || ['Common','Uncommon','Rare','Epic','Legendary','Mythic']).map(r => `<option value="${r}"${d.rarity === r ? ' selected' : ''}>${r}</option>`).join('')}</select>
      </div>
      <div><label class="form-label">Trigger Type</label>
        <select id="co-a-trigger">${(window.ACH_TRIGGER_TYPES || [{value:'manual',label:'Manual'}]).map(t => `<option value="${t.value}"${d.triggerType === t.value ? ' selected' : ''}>${t.label}</option>`).join('')}</select>
      </div>
      <div><label class="form-label">Trigger Value</label><input id="co-a-tval" class="form-control" type="number" min="0" value="${d.triggerValue || 1}"></div>
      <div><label class="form-label">XP Reward</label><input id="co-a-xp" class="form-control" type="number" min="0" value="${d.xpReward || 0}"></div>
      <div><label class="form-label">Coin Reward</label><input id="co-a-coin" class="form-control" type="number" min="0" value="${d.coinReward || 0}"></div>
    </div>
    <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:20px">
      <button class="btn btn-ghost" onclick="closeModalForce()">Cancel</button>
      <button class="btn btn-primary" onclick="_coSaveAchievement()">Save</button>
    </div>
  `, 'md');
};

window._coSaveAchievement = async function () {
  const isNew = window._coEditIdx < 0;
  const row = {
    id: window._coEditBaseId,
    name: document.getElementById('co-a-name').value.trim(),
    description: document.getElementById('co-a-desc').value.trim(),
    icon: document.getElementById('co-a-icon').value.trim() || '🏅',
    category: document.getElementById('co-a-cat').value.trim() || 'General',
    rarity: document.getElementById('co-a-rarity').value,
    triggerType: document.getElementById('co-a-trigger').value,
    triggerValue: parseInt(document.getElementById('co-a-tval').value) || 0,
    xpReward: parseInt(document.getElementById('co-a-xp').value) || 0,
    coinReward: parseInt(document.getElementById('co-a-coin').value) || 0,
    active: true,
  };
  if (!row.name) { toast('⚠️ Name is required', '#ff6b6b'); return; }
  const res = await ContentOversightService.saveAchievement(_coTeacherId, row, isNew);
  if (!res.ok) { toast('⚠️ ' + res.error, '#ff6b6b'); return; }
  closeModalForce();
  toast('✅ Saved');
  _coRefreshAndRender();
};

window._coDeleteAchievement = async function (idx) {
  const row = _coContent.achievements[idx];
  if (!row) return;
  if (!confirm(`Delete "${row.name}" from ${_coTeacherLabel}'s achievements? This is logged.`)) return;
  const res = await ContentOversightService.deleteAchievement(_coTeacherId, row.id);
  if (!res.ok) { toast('⚠️ ' + res.error, '#ff6b6b'); return; }
  toast('🗑️ Deleted');
  _coRefreshAndRender();
};

