// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/admin/audit-log-service.js
//  Service layer for the admin audit log.
//  (ISOLATION_ROLES_PLAN.md Chunk E "Governance" — built ahead of Chunk C per
//   the agreed build order A → B → E → C → D → F, so "Edit as" has somewhere
//   to log to on day one. See supabase/phase40_governance_audit_and_settings.sql.)
//
//  SCOPE NOTE (confirmed before building): this is deliberately NARROW —
//  wired for the "Edit as" override only, not a generic action-logger for
//  every admin write. Chunk D's ownership transfer and Chunk F's
//  registration reassignment get their own logging later if wanted; don't
//  extend this file's surface to cover them without that being decided.
//
//  REPOSITORY PATTERN CONTRACT — same rule as every other *Service module:
//  no render layer calls DBService.rpc() directly for audit data. It calls
//  AuditLogService.<method>(...).
//
//  WHAT'S HERE
//    logEditAsAction() — called once per write Chunk C performs while an
//    admin is in "Edit as" mode for a teacher. No render layer calls this
//    yet — Chunk C is what will. It's here now so C doesn't also need a
//    SQL change when it ships.
//    getLog() — admin-only read, optionally filtered to one teacher. No
//    screen consumes this yet either (there's nothing to show until C
//    produces entries) — provided now so a future "Audit Log" viewer screen
//    is a render-layer-only addition.
// ═══════════════════════════════════════════════════════════════════════════════

window.AuditLogService = (function () {
  'use strict';

  /**
   * logEditAsAction({ targetTeacherId, tableName, recordId, action, details?, sessionId? })
   *   → Promise<{ok, row?, error?}>
   * action must be 'create' | 'update' | 'delete'. actor is resolved
   * server-side from the caller's own session — never pass one in.
   */
  async function logEditAsAction({ targetTeacherId, tableName, recordId, action, details = null, sessionId = null }) {
    const { data, error } = await DBService.rpc('log_edit_as_action', {
      p_target_teacher_id: targetTeacherId,
      p_table_name: tableName,
      p_record_id: recordId,
      p_action: action,
      p_details: details,
      p_session_id: sessionId,
    });
    if (error) return { ok: false, error: error.message || 'Could not log this action.' };
    return { ok: true, row: data };
  }

  /**
   * getLog({ targetTeacherId?, limit? }) → Promise<{ok, rows?, error?}>
   * Admin-only server-side; a non-admin caller gets back an RPC error.
   */
  async function getLog({ targetTeacherId = null, limit = 200 } = {}) {
    const { data, error } = await DBService.rpc('get_audit_log', {
      p_target_teacher_id: targetTeacherId,
      p_limit: limit,
    });
    if (error) return { ok: false, error: error.message || 'Could not load the audit log.' };
    return { ok: true, rows: data || [] };
  }

  return { logEditAsAction, getLog };
})();


/* ---- ./modules/admin/audit-log.js ---- */
// ══════════════════════════════════════════════════════
//  modules/admin/audit-log.js
//  Audit Log — admin-only screen (Chunk E, viewer half).
//  (ISOLATION_ROLES_PLAN.md Chunk E "Governance" — see
//   supabase/phase40_governance_audit_and_settings.sql and
//   audit-log-service.js, both already shipped ahead of this file.)
//
//  audit-log-service.js and its RPCs (log_edit_as_action / get_audit_log)
//  already existed and were already wired into Chunk C's "Edit as" writes
//  (content-oversight-service.js calls AuditLogService.logEditAsAction()
//  on every write) — this file is the missing other half: an admin-facing
//  screen to actually read that log back. Nothing here changes the SQL or
//  the write path.
//
//  Filtering: get_audit_log() only takes an optional target_teacher_id
//  server-side (see its SQL). Action/table filters below are applied
//  client-side against the fetched batch rather than adding new RPC
//  params — this is a small, classroom-scale table (one row per "Edit as"
//  write), so a client-side filter over the current fetch is simpler than
//  a SQL change for what's still a light-traffic log.
//
//  REPOSITORY PATTERN: this file never calls DBService.rpc() directly —
//  only AuditLogService (for log rows) and TeacherDirectoryService (to
//  resolve actor_id/target_teacher_id into names for display, and to
//  populate the "Filter by teacher" dropdown).
//
//  Exports: renderAuditLog, auditLogSetTeacherFilter, auditLogSetActionFilter,
//           auditLogSetTableFilter, auditLogLoadMore
// ══════════════════════════════════════════════════════

const AUDIT_LOG_DEFAULT_LIMIT = 200;
const AUDIT_LOG_LOAD_MORE_STEP = 200;

let _auditLogLoading = false;
let _auditLogError = null;
let _auditLogRows = null;        // raw rows from the last fetch (server-side teacher filter already applied)
let _auditLogLimit = AUDIT_LOG_DEFAULT_LIMIT;
let _auditLogTeacherFilter = null; // target_teacher_id, or null = all teachers
let _auditLogActionFilter = null;  // 'create' | 'update' | 'delete', client-side only
let _auditLogTableFilter = null;   // table_name, client-side only
let _auditLogTeachers = null;     // TeacherDirectoryService rows, for names + the filter dropdown
let _auditLogNameById = {};       // id -> displayName lookup built from _auditLogTeachers

window.renderAuditLog = async function () {
  const el = document.getElementById('a-audit-log');
  if (!el) return;

  // Defense in depth: nav.js already hides this tab and bounces direct
  // navTo() calls for a non-admin — this should be unreachable, but never
  // show an oversight screen to a teacher account regardless.
  if (currentRole !== 'admin') {
    el.innerHTML = `
    <div class="glass-card" style="padding:32px;text-align:center">
      <span class="material-symbols-outlined" style="font-size:40px;color:var(--text-muted)">lock</span>
      <h2 style="font-family:var(--fh);font-size:18px;margin:12px 0 4px">Admin only</h2>
      <p style="font-size:13px;color:var(--text-muted)">This screen is only available to oversight admin accounts.</p>
    </div>`;
    return;
  }

  _auditLogLoading = true;
  _auditLogError = null;
  _auditLogRows = null;
  _auditLogRenderShell(el);

  const [logResult, dirResult] = await Promise.all([
    AuditLogService.getLog({ targetTeacherId: _auditLogTeacherFilter, limit: _auditLogLimit }),
    _auditLogTeachers ? Promise.resolve({ ok: true, teachers: _auditLogTeachers }) : TeacherDirectoryService.getDirectory(),
  ]);

  _auditLogLoading = false;
  if (!logResult.ok) {
    _auditLogError = logResult.error;
    _auditLogRows = null;
  } else {
    _auditLogRows = logResult.rows;
  }

  if (dirResult.ok) {
    _auditLogTeachers = dirResult.teachers;
    _auditLogNameById = {};
    _auditLogTeachers.forEach(t => { _auditLogNameById[t.id] = t.displayName || t.email || t.id; });
  }

  if (document.getElementById('a-audit-log')) _auditLogRenderShell(document.getElementById('a-audit-log'));
};

window.auditLogSetTeacherFilter = function (teacherId) {
  _auditLogTeacherFilter = teacherId || null;
  _auditLogLimit = AUDIT_LOG_DEFAULT_LIMIT; // fresh page size on a new server-side filter
  window.renderAuditLog();
};

window.auditLogSetActionFilter = function (action) {
  _auditLogActionFilter = action || null;
  _auditLogRenderShell(document.getElementById('a-audit-log'));
};

window.auditLogSetTableFilter = function (tableName) {
  _auditLogTableFilter = tableName || null;
  _auditLogRenderShell(document.getElementById('a-audit-log'));
};

window.auditLogLoadMore = async function () {
  if (_auditLogLoading || !_auditLogRows) return;
  _auditLogLimit += AUDIT_LOG_LOAD_MORE_STEP;
  _auditLogLoading = true;
  _auditLogRenderShell(document.getElementById('a-audit-log'));

  const result = await AuditLogService.getLog({ targetTeacherId: _auditLogTeacherFilter, limit: _auditLogLimit });
  _auditLogLoading = false;

  if (!result.ok) {
    toast('❌ ' + (result.error || 'Could not load more entries.'), '#ffb4ab');
  } else {
    _auditLogRows = result.rows;
  }
  if (document.getElementById('a-audit-log')) _auditLogRenderShell(document.getElementById('a-audit-log'));
};

function _auditLogRenderShell(el) {
  if (!el) return;
  el.innerHTML = `
  <div class="page-hero">
    <div class="page-hero-bg"></div>
    <div style="position:relative;z-index:1">
      <div class="page-hero-label">🛠️ Oversight</div>
      <h1 style="font-family:var(--fh);font-size:32px;font-weight:900;color:var(--on-surface);margin-bottom:8px">Audit Log</h1>
      <p style="font-size:14px;color:var(--text-muted)">Every write made while an admin was in "Edit as" mode for a teacher's content.</p>
    </div>
  </div>
  ${_auditLogFilterBar()}
  ${_auditLogBody()}
  `;
}

function _auditLogFilterBar() {
  const teachers = (_auditLogTeachers || []).slice().sort((a, b) => (a.displayName || '').localeCompare(b.displayName || ''));
  const teacherOptions = teachers.map(t =>
    `<option value="${_esc(t.id)}" ${_auditLogTeacherFilter === t.id ? 'selected' : ''}>${_esc(t.displayName || t.email || t.id)}</option>`
  ).join('');

  const tableNames = Array.from(new Set((_auditLogRows || []).map(r => r.table_name).filter(Boolean))).sort();
  const tableOptions = tableNames.map(tn =>
    `<option value="${_esc(tn)}" ${_auditLogTableFilter === tn ? 'selected' : ''}>${_esc(tn)}</option>`
  ).join('');

  return `
  <div class="glass-card" style="padding:14px 16px;margin-bottom:14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap">
    <div>
      <label style="display:block;font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted);margin-bottom:4px">Teacher</label>
      <select id="audit-log-teacher-filter" style="width:auto;min-width:200px" onchange="auditLogSetTeacherFilter(this.value)">
        <option value="">All teachers</option>
        ${teacherOptions}
      </select>
    </div>
    <div>
      <label style="display:block;font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted);margin-bottom:4px">Action</label>
      <select id="audit-log-action-filter" style="width:auto;min-width:130px" onchange="auditLogSetActionFilter(this.value)">
        <option value="">All actions</option>
        <option value="create" ${_auditLogActionFilter === 'create' ? 'selected' : ''}>Create</option>
        <option value="update" ${_auditLogActionFilter === 'update' ? 'selected' : ''}>Update</option>
        <option value="delete" ${_auditLogActionFilter === 'delete' ? 'selected' : ''}>Delete</option>
      </select>
    </div>
    <div>
      <label style="display:block;font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted);margin-bottom:4px">Table</label>
      <select id="audit-log-table-filter" style="width:auto;min-width:150px" onchange="auditLogSetTableFilter(this.value)">
        <option value="">All tables</option>
        ${tableOptions}
      </select>
    </div>
    ${(_auditLogTeacherFilter || _auditLogActionFilter || _auditLogTableFilter) ? `
    <button class="btn btn-ghost btn-sm" style="align-self:flex-end" onclick="auditLogSetTeacherFilter('');auditLogSetActionFilter('');auditLogSetTableFilter('')">Clear filters</button>
    ` : ''}
  </div>`;
}

function _auditLogFilteredRows() {
  let rows = _auditLogRows || [];
  if (_auditLogActionFilter) rows = rows.filter(r => r.action === _auditLogActionFilter);
  if (_auditLogTableFilter) rows = rows.filter(r => r.table_name === _auditLogTableFilter);
  return rows;
}

function _auditLogBody() {
  if (_auditLogLoading && !_auditLogRows) {
    return `<div class="glass-card" style="padding:32px;text-align:center;color:var(--text-muted);font-size:13px">Loading audit log…</div>`;
  }
  if (_auditLogError) {
    return `
    <div class="glass-card" style="padding:32px;text-align:center">
      <span class="material-symbols-outlined" style="font-size:36px;color:#ffb4ab">error</span>
      <p style="font-size:13px;color:var(--text-muted);margin:10px 0 16px">${_esc(_auditLogError)}</p>
      <button class="btn btn-primary btn-sm" onclick="renderAuditLog()">Retry</button>
    </div>`;
  }

  const allRows = _auditLogRows || [];
  const rows = _auditLogFilteredRows();

  if (allRows.length === 0) {
    return `
    <div class="glass-card" style="padding:32px;text-align:center;color:var(--text-muted);font-size:13px">
      No "Edit as" actions logged yet.
    </div>`;
  }
  if (rows.length === 0) {
    return `
    <div class="glass-card" style="padding:32px;text-align:center;color:var(--text-muted);font-size:13px">
      No entries match the current filters.
    </div>`;
  }

  const cols = '150px 1fr 1fr 1.2fr 90px 1fr';
  // get_audit_log() has no offset — "load more" widens the same server-side
  // limit and refetches, so this is only a meaningful action while the
  // fetched batch is still exactly at the current limit (i.e. there could
  // be more rows beyond it).
  const canLoadMore = allRows.length >= _auditLogLimit && _auditLogLimit < 1000;

  return `
  <div class="glass-card" style="padding:0;overflow:hidden">
    <div style="display:grid;grid-template-columns:${cols};gap:10px;align-items:center;padding:10px 16px;font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);border-bottom:1px solid var(--border2)">
      <span>When</span><span>Admin</span><span>Teacher</span><span>Table · Record</span><span>Action</span><span>Details</span>
    </div>
    ${rows.map(_auditLogRow).join('')}
  </div>
  ${canLoadMore ? `
  <div style="text-align:center;margin-top:14px">
    <button class="btn btn-ghost btn-sm" ${_auditLogLoading ? 'disabled' : ''} onclick="auditLogLoadMore()">
      ${_auditLogLoading ? 'Loading…' : `Load more (showing latest ${allRows.length})`}
    </button>
  </div>` : `
  <div style="text-align:center;margin-top:10px;font-size:11px;color:var(--text-muted)">Showing ${rows.length}${rows.length !== allRows.length ? ` of ${allRows.length} loaded` : ''} entries</div>
  `}`;
}

function _auditLogRow(r) {
  const actorName = _auditLogNameById[r.actor_id] || r.actor_id;
  const targetName = _auditLogNameById[r.target_teacher_id] || r.target_teacher_id;
  const detailsStr = (r.details && Object.keys(r.details).length) ? _esc(JSON.stringify(r.details)) : '';
  const actionColor = r.action === 'delete' ? 'btn-danger' : (r.action === 'create' ? 'btn-success' : 'btn-primary');

  return `
  <div style="display:grid;grid-template-columns:150px 1fr 1fr 1.2fr 90px 1fr;gap:10px;align-items:start;padding:12px 16px;border-bottom:1px solid var(--border2)">
    <div style="font-size:11px;color:var(--text-muted)">${_auditLogFormatDate(r.created_at)}</div>
    <div style="font-size:13px;font-weight:700;color:var(--on-surface)">${_esc(actorName)}</div>
    <div style="font-size:12px;color:var(--on-surface)">${_esc(targetName)}</div>
    <div style="font-size:12px;color:var(--text-muted)">${_esc(r.table_name)}<div style="font-size:10px;opacity:.7;word-break:break-all">${_esc(r.record_id)}</div></div>
    <span class="btn btn-xs ${actionColor}" style="width:fit-content;pointer-events:none;text-transform:capitalize">${_esc(r.action)}</span>
    <div style="font-size:10px;color:var(--text-muted);word-break:break-word">${detailsStr}${r.session_id ? `<div style="opacity:.6;margin-top:2px">session: ${_esc(r.session_id)}</div>` : ''}</div>
  </div>`;
}

function _auditLogFormatDate(iso) {
  try {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '—';
    return d.toLocaleString(undefined, { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  } catch (e) { return '—'; }
}


/* ---- ./modules/admin/system-health-service.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/admin/system-health-service.js
//  Service layer for the admin System Health panel (Phase 2 of
//  ADMIN_SYSTEM_HEALTH.md). Repository-pattern wrapper around the three
//  RPC groups added in supabase/phase69_system_health_analytics.sql, same
//  shape as AuditLogService.
//
//  REPOSITORY PATTERN CONTRACT — same rule as every other *Service module:
//  no render layer calls DBService.rpc() directly for system-health data.
//  It calls SystemHealthService.<method>(...).
//
//  WHAT'S HERE
//    touchPresence()      — the heartbeat write (own row only, server-side).
//    getUserCounts()       — admin-only read: total/online users by role.
//    getErrorLogs()        — admin-only read: filterable client error log.
//    resolveErrorLog()     — admin-only write: toggles the resolved flag.
//    logClientError()      — anon/authenticated write, fire-and-forget, same
//                             posture as wbcApplyDamage. error-capture.js
//                             (loaded much earlier in index.html, before
//                             DBService exists) calls the RPC directly
//                             instead of this — see that file's own note —
//                             but any render-layer code that wants to log a
//                             handled error should call this, not the RPC.
//    startPresenceHeartbeat() / stopPresenceHeartbeat() — the heartbeat's
//    interval lifecycle. Called from auth.js's bootApp()/doLogout(), the
//    same pairing WBC.refreshInterval already uses elsewhere in that file.
//    Colocated here (rather than left inline in auth.js) since the pause-
//    on-hidden-tab logic is presence-specific bookkeeping, not auth
//    bookkeeping — auth.js just starts/stops it at the right lifecycle
//    points, same as it does for WBC's own interval.
// ═══════════════════════════════════════════════════════════════════════════════

window.SystemHealthService = (function () {
  'use strict';

  const HEARTBEAT_INTERVAL_MS = 60000; // matches the "proposed: every 60s" in the phase doc

  let _heartbeatTimer = null;
  let _visibilityHandler = null;

  /**
   * touchPresence() → Promise<{ok, timestamp?, error?}>
   * Writes the caller's own last_seen_at. No params — auth.uid() is
   * resolved server-side, never passed in.
   */
  async function touchPresence() {
    const { data, error } = await DBService.rpc('touch_presence', {});
    if (error) return { ok: false, error: error.message || 'Could not update presence.' };
    return { ok: true, timestamp: data };
  }

  /**
   * getUserCounts() → Promise<{ok, counts?, error?}>
   * counts = { total_users, total_admins, total_teachers, total_students, online_now }
   * Admin-only server-side; a non-admin caller gets back an RPC error.
   */
  async function getUserCounts() {
    const { data, error } = await DBService.rpc('get_admin_user_counts', {});
    if (error) return { ok: false, error: error.message || 'Could not load user counts.' };
    const row = Array.isArray(data) ? data[0] : data;
    return { ok: true, counts: row || null };
  }

  /**
   * getErrorLogs({resolved?, role?, limit?}) → Promise<{ok, rows?, error?}>
   * Admin-only server-side. limit is clamped 1-1000 by the RPC itself.
   */
  async function getErrorLogs({ resolved = null, role = null, limit = 200 } = {}) {
    const { data, error } = await DBService.rpc('get_client_error_logs', {
      p_resolved: resolved,
      p_role: role,
      p_limit: limit,
    });
    if (error) return { ok: false, error: error.message || 'Could not load client error logs.' };
    return { ok: true, rows: data || [] };
  }

  /**
   * resolveErrorLog({id, resolved?}) → Promise<{ok, row?, error?}>
   * Admin-only server-side. resolved defaults to true (the common "mark
   * resolved" case); pass false to un-resolve.
   */
  async function resolveErrorLog({ id, resolved = true }) {
    const { data, error } = await DBService.rpc('resolve_client_error_log', {
      p_id: id,
      p_resolved: resolved,
    });
    if (error) return { ok: false, error: error.message || 'Could not update this error log.' };
    return { ok: true, row: data };
  }

  /**
   * logClientError({message, stack?, source?, userAgent?, url?}) → Promise<{ok, error?}>
   * Fire-and-forget, same posture as wbcApplyDamage: never throws. Safe to
   * call with no session (log_client_error() is granted to anon too).
   * error-capture.js's window.onerror/unhandledrejection hooks call the RPC
   * directly rather than this function, since they load and can fire before
   * this file exists — see error-capture.js's header note. This wrapper is
   * for any other render-layer code that wants to log a handled error.
   */
  async function logClientError({ message, stack = null, source = null, userAgent = null, url = null }) {
    try {
      const { error } = await DBService.rpc('log_client_error', {
        p_message: message,
        p_stack: stack,
        p_source: source,
        p_user_agent: userAgent,
        p_url: url,
      });
      if (error) {
        console.warn('[SystemHealthService] log_client_error RPC failed:', error);
        return { ok: false, error };
      }
      return { ok: true };
    } catch (e) {
      console.warn('[SystemHealthService] log_client_error threw:', e);
      return { ok: false, error: e };
    }
  }

  // ── Presence heartbeat lifecycle ────────────────────────────────────────

  function _tick() {
    touchPresence().catch(function (e) {
      console.warn('[SystemHealthService] presence heartbeat failed:', e);
    });
  }

  /**
   * startPresenceHeartbeat() — call once per login (bootApp()). No-ops if
   * already running (bootApp() can run more than once per page load —
   * fresh login vs. restoreSession() — so this must be idempotent).
   * Pings immediately, then every 60s. Skips (not clears) the tick while
   * `document.hidden` is true — the open item flagged in
   * ADMIN_SYSTEM_HEALTH.md: without this, a forgotten background tab counts
   * as "online" all day. The visibilitychange listener is attached once,
   * lazily, on first start, and pings immediately on becoming visible again
   * so "online now" doesn't wait up to 60s to catch up.
   */
  function startPresenceHeartbeat() {
    if (_heartbeatTimer) return;
    _tick();
    _heartbeatTimer = setInterval(function () {
      if (document.hidden) return;
      _tick();
    }, HEARTBEAT_INTERVAL_MS);

    if (!_visibilityHandler) {
      _visibilityHandler = function () {
        if (!document.hidden && _heartbeatTimer) _tick();
      };
      document.addEventListener('visibilitychange', _visibilityHandler);
    }
  }

  /**
   * stopPresenceHeartbeat() — call once per logout (doLogout()), same
   * pairing as WBC.refreshInterval's own clearInterval in that function.
   * The visibilitychange listener is left attached (harmless no-op while
   * _heartbeatTimer is null) rather than added/removed every cycle.
   */
  function stopPresenceHeartbeat() {
    if (_heartbeatTimer) {
      clearInterval(_heartbeatTimer);
      _heartbeatTimer = null;
    }
  }

  return {
    touchPresence,
    getUserCounts,
    getErrorLogs,
    resolveErrorLog,
    logClientError,
    startPresenceHeartbeat,
    stopPresenceHeartbeat,
  };
})();


/* ---- ./modules/admin/system-health.js ---- */
// ══════════════════════════════════════════════════════
//  modules/admin/system-health.js
//  Admin System Health page (a-system-health) — ADMIN_SYSTEM_HEALTH.md
//  Phase 3 (render layer). Phase 1 (data) and Phase 2 (service layer +
//  heartbeat + error capture) already shipped — see
//  modules/admin/system-health-service.js and error-capture.js.
//
//  WHAT'S HERE
//    Stat cards: online now / total users / total teachers / total
//    students, from SystemHealthService.getUserCounts().
//    Error log table: filterable (resolved status, role) and paginated
//    (same "load more" pattern as audit-log.js — get_client_error_logs()
//    has no offset, so "load more" widens the same server-side limit and
//    refetches), with a resolve/un-resolve toggle per row.
//
//  REPOSITORY PATTERN: this file never calls DBService.rpc() directly —
//  only SystemHealthService.
//
//  PHASE 4 (polish) — auto-refresh interval for the live counts only, added
//  here. Same self-clearing "stop if the page isn't active anymore" pattern
//  as _adminStoreInterval in shop_admin_store.js, plus the matching explicit
//  clear in nav.js's navTo() when leaving a-system-health. Deliberately
//  scoped to the stat cards ONLY (re-fetches getUserCounts() and patches
//  just the #sh-stat-cards node) — the error log table is left alone so an
//  admin mid-filter, mid-"load more", or with a stack trace expanded never
//  gets their state clobbered by a background tick.
//
//  STILL NOT DECIDED/BUILT (see ADMIN_SYSTEM_HEALTH.md "Open items"):
//    - Tuning the "online now" 2-minute window — needs real heartbeat
//      traffic to observe, not something to guess at in code.
//    - Bulk/retention cleanup for client_error_logs — doc explicitly flags
//      this as "not decided which" approach; not folded in here.
//  Empty/loading states for the error log table are left matching the same
//  plain-text convention audit-log.js already uses elsewhere in the admin
//  section — that IS the app's baseline, not a placeholder to upgrade.
//
//  Exports: renderSystemHealth, shSetResolvedFilter, shSetRoleFilter,
//           shLoadMoreLogs, shToggleResolved, shToggleStack
// ══════════════════════════════════════════════════════

const SH_LOG_DEFAULT_LIMIT = 200;
const SH_LOG_LOAD_MORE_STEP = 200;
const SH_COUNTS_REFRESH_MS = 30000; // stat cards only — half the heartbeat interval, no reason to go faster

let _shCountsInterval = null;

let _shCountsLoading = false;
let _shCounts = null;             // { total_users, total_admins, total_teachers, total_students, online_now }
let _shCountsError = null;

let _shLogsLoading = false;
let _shLogsError = null;
let _shLogRows = null;            // raw rows from the last fetch (server-side resolved/role filters already applied)
let _shLogLimit = SH_LOG_DEFAULT_LIMIT;
let _shResolvedFilter = null;     // true | false | null (= all)
let _shRoleFilter = null;         // 'admin' | 'teacher' | 'student' | null (= all)
let _shExpandedStackIds = {};     // id -> true, which rows have their stack trace expanded
let _shBusyId = null;             // error log id currently mid resolve/un-resolve toggle

window.renderSystemHealth = async function () {
  const el = document.getElementById('a-system-health');
  if (!el) return;

  // Defense in depth: nav.js already hides this tab and bounces direct
  // navTo() calls for a non-admin — this should be unreachable, but never
  // show the counts/error log to a teacher account regardless (both
  // get_admin_user_counts() and get_client_error_logs() are admin-gated
  // server-side too, so a teacher would just see an RPC error otherwise).
  if (currentRole !== 'admin') {
    el.innerHTML = `
    <div class="glass-card" style="padding:32px;text-align:center">
      <span class="material-symbols-outlined" style="font-size:40px;color:var(--text-muted)">lock</span>
      <h2 style="font-family:var(--fh);font-size:18px;margin:12px 0 4px">Admin only</h2>
      <p style="font-size:13px;color:var(--text-muted)">This screen is only available to oversight admin accounts.</p>
    </div>`;
    return;
  }

  _shCountsLoading = true;
  _shCountsError = null;
  _shLogsLoading = true;
  _shLogsError = null;
  _shLogRows = null;
  _shRenderShell(el);

  const [countsResult, logsResult] = await Promise.all([
    SystemHealthService.getUserCounts(),
    SystemHealthService.getErrorLogs({ resolved: _shResolvedFilter, role: _shRoleFilter, limit: _shLogLimit }),
  ]);

  _shCountsLoading = false;
  if (!countsResult.ok) { _shCountsError = countsResult.error; _shCounts = null; }
  else { _shCounts = countsResult.counts; }

  _shLogsLoading = false;
  if (!logsResult.ok) { _shLogsError = logsResult.error; _shLogRows = null; }
  else { _shLogRows = logsResult.rows; }

  if (document.getElementById('a-system-health')) _shRenderShell(document.getElementById('a-system-health'));
  _shStartCountsRefresh();
};

/**
 * shStopCountsRefresh() — [window.shStopCountsRefresh] called from nav.js's
 * navTo() when leaving a-system-health, same explicit-clear pairing as
 * _adminStoreInterval for a-store. Also self-clears from inside the tick
 * itself if the page ever goes inactive without navTo() catching it first
 * (belt-and-suspenders, matching the shop_admin_store.js precedent).
 */
window.shStopCountsRefresh = function () {
  if (_shCountsInterval) { clearInterval(_shCountsInterval); _shCountsInterval = null; }
};

function _shStartCountsRefresh() {
  shStopCountsRefresh();
  _shCountsInterval = setInterval(async function () {
    const page = document.getElementById('a-system-health');
    if (!page || !page.classList.contains('active')) { shStopCountsRefresh(); return; }
    const result = await SystemHealthService.getUserCounts();
    // Re-check after the await — the admin may have navigated away while
    // this was in-flight.
    const stillHere = document.getElementById('a-system-health');
    if (!stillHere || !stillHere.classList.contains('active') || !_shCountsInterval) return;
    // A transient failure on a background tick isn't worth surfacing over
    // whatever counts are already on screen — just skip this tick and let
    // the next one try again. Only a fetch triggered by the admin (page
    // load / Retry button) shows the error state.
    if (!result.ok) return;
    _shCounts = result.counts;
    _shCountsError = null;
    const cardsEl = document.getElementById('sh-stat-cards');
    if (cardsEl) cardsEl.outerHTML = _shCountsHTML();
  }, SH_COUNTS_REFRESH_MS);
}

window.shSetResolvedFilter = function (value) {
  // value: '' (all) | 'unresolved' | 'resolved'
  _shResolvedFilter = value === 'unresolved' ? false : value === 'resolved' ? true : null;
  _shLogLimit = SH_LOG_DEFAULT_LIMIT; // fresh page size on a new server-side filter
  _shRefetchLogs();
};

window.shSetRoleFilter = function (value) {
  _shRoleFilter = value || null;
  _shLogLimit = SH_LOG_DEFAULT_LIMIT;
  _shRefetchLogs();
};

async function _shRefetchLogs() {
  _shLogsLoading = true;
  _shLogsError = null;
  _shRenderShell(document.getElementById('a-system-health'));

  const result = await SystemHealthService.getErrorLogs({ resolved: _shResolvedFilter, role: _shRoleFilter, limit: _shLogLimit });
  _shLogsLoading = false;

  if (!result.ok) { _shLogsError = result.error; _shLogRows = null; }
  else { _shLogRows = result.rows; }

  if (document.getElementById('a-system-health')) _shRenderShell(document.getElementById('a-system-health'));
}

window.shLoadMoreLogs = async function () {
  if (_shLogsLoading || !_shLogRows) return;
  _shLogLimit += SH_LOG_LOAD_MORE_STEP;
  await _shRefetchLogs();
};

window.shToggleStack = function (id) {
  _shExpandedStackIds[id] = !_shExpandedStackIds[id];
  _shRenderShell(document.getElementById('a-system-health'));
};

window.shToggleResolved = async function (id, currentlyResolved) {
  if (_shBusyId) return;
  _shBusyId = id;
  _shRenderShell(document.getElementById('a-system-health'));

  const result = await SystemHealthService.resolveErrorLog({ id, resolved: !currentlyResolved });
  _shBusyId = null;

  if (!result.ok) {
    toast('❌ ' + (result.error || 'Could not update this error log.'), '#ffb4ab');
  } else {
    toast(currentlyResolved ? '✅ Marked unresolved.' : '✅ Marked resolved.');
    // Patch the row in place rather than a full refetch — same list, one
    // field changed, and a refetch would also reset scroll position.
    if (_shLogRows) {
      const row = _shLogRows.find(r => r.id === id);
      if (row) row.resolved = !currentlyResolved;
    }
  }
  if (document.getElementById('a-system-health')) _shRenderShell(document.getElementById('a-system-health'));
};

function _shRenderShell(el) {
  if (!el) return;
  el.innerHTML = `
  <div class="page-hero">
    <div class="page-hero-bg"></div>
    <div style="position:relative;z-index:1">
      <div class="page-hero-label">🩺 Oversight</div>
      <h1 style="font-family:var(--fh);font-size:32px;font-weight:900;color:var(--on-surface);margin-bottom:8px">System Health</h1>
      <p style="font-size:14px;color:var(--text-muted)">Who's online, how many accounts exist, and what's gone wrong on the client.</p>
    </div>
  </div>
  ${_shCountsHTML()}
  ${_shFilterBarHTML()}
  ${_shLogsHTML()}
  `;
}

// ── STAT CARDS ──────────────────────────────────────────────────────────
function _shCountsHTML() {
  // Wrapped in #sh-stat-cards so _shStartCountsRefresh() can patch just this
  // node on each 30s tick without touching the filter bar / log table below
  // (which have their own loading/scroll/expanded-row state to preserve).
  if (_shCountsLoading && !_shCounts) {
    return `<div id="sh-stat-cards"><div class="stat-grid" style="margin-bottom:24px">
      ${[0, 1, 2, 3].map(() => `<div class="stat-card"><div class="val" style="color:var(--text-muted)">—</div><div class="lbl">Loading…</div></div>`).join('')}
    </div></div>`;
  }
  if (_shCountsError) {
    return `
    <div id="sh-stat-cards">
    <div class="glass-card" style="padding:20px;margin-bottom:24px;text-align:center">
      <p style="font-size:13px;color:var(--text-muted);margin-bottom:10px">${_esc(_shCountsError)}</p>
      <button class="btn btn-primary btn-sm" onclick="renderSystemHealth()">Retry</button>
    </div>
    </div>`;
  }
  const c = _shCounts || {};
  return `
  <div id="sh-stat-cards">
  <div class="stat-grid" style="margin-bottom:24px">
    <div class="stat-card">
      <div class="val" style="color:#4edea3">${c.online_now ?? 0}</div>
      <div class="lbl">Online Now</div>
    </div>
    <div class="stat-card"><div class="val" style="color:#d0bcff">${c.total_users ?? 0}</div><div class="lbl">Total Users</div></div>
    <div class="stat-card"><div class="val" style="color:#ffb95f">${c.total_teachers ?? 0}</div><div class="lbl">Teachers</div></div>
    <div class="stat-card"><div class="val" style="color:#fb923c">${c.total_students ?? 0}</div><div class="lbl">Students</div></div>
  </div>
  <p style="font-size:11px;color:var(--text-muted);margin:-14px 0 24px">
    "Online now" = active in the last 2 minutes (heartbeat-based, not a live socket count — see ADMIN_SYSTEM_HEALTH.md).
    ${(c.total_admins || 0) > 0 ? ` ${c.total_admins} admin account${c.total_admins === 1 ? '' : 's'} not shown above.` : ''}
  </p>
  </div>`;
}

// ── FILTER BAR ───────────────────────────────────────────────────────────
function _shFilterBarHTML() {
  const resolvedValue = _shResolvedFilter === false ? 'unresolved' : _shResolvedFilter === true ? 'resolved' : '';
  return `
  <div class="glass-card sh-filter-bar">
    <div>
      <label>Status</label>
      <select id="sh-resolved-filter" style="width:auto;min-width:150px" onchange="shSetResolvedFilter(this.value)">
        <option value="" ${resolvedValue === '' ? 'selected' : ''}>All</option>
        <option value="unresolved" ${resolvedValue === 'unresolved' ? 'selected' : ''}>Unresolved</option>
        <option value="resolved" ${resolvedValue === 'resolved' ? 'selected' : ''}>Resolved</option>
      </select>
    </div>
    <div>
      <label>Role</label>
      <select id="sh-role-filter" style="width:auto;min-width:140px" onchange="shSetRoleFilter(this.value)">
        <option value="" ${!_shRoleFilter ? 'selected' : ''}>All roles</option>
        <option value="admin" ${_shRoleFilter === 'admin' ? 'selected' : ''}>Admin</option>
        <option value="teacher" ${_shRoleFilter === 'teacher' ? 'selected' : ''}>Teacher</option>
        <option value="student" ${_shRoleFilter === 'student' ? 'selected' : ''}>Student</option>
      </select>
    </div>
    ${(_shResolvedFilter !== null || _shRoleFilter) ? `
    <button class="btn btn-ghost btn-sm" style="align-self:flex-end" onclick="shSetResolvedFilter('');shSetRoleFilter('')">Clear filters</button>
    ` : ''}
  </div>`;
}

// ── ERROR LOG TABLE ────────────────────────────────────────────────────
function _shLogsHTML() {
  if (_shLogsLoading && !_shLogRows) {
    return `<div class="glass-card" style="padding:32px;text-align:center;color:var(--text-muted);font-size:13px">Loading client error logs…</div>`;
  }
  if (_shLogsError) {
    return `
    <div class="glass-card" style="padding:32px;text-align:center">
      <span class="material-symbols-outlined" style="font-size:36px;color:#ffb4ab">error</span>
      <p style="font-size:13px;color:var(--text-muted);margin:10px 0 16px">${_esc(_shLogsError)}</p>
      <button class="btn btn-primary btn-sm" onclick="renderSystemHealth()">Retry</button>
    </div>`;
  }

  const rows = _shLogRows || [];
  const hasAnyFilter = _shResolvedFilter !== null || !!_shRoleFilter;

  if (rows.length === 0) {
    return `
    <div class="glass-card" style="padding:32px;text-align:center;color:var(--text-muted);font-size:13px">
      ${hasAnyFilter ? 'No entries match the current filters.' : 'No client errors logged yet. 🎉'}
    </div>`;
  }

  // No offset on get_client_error_logs() — "load more" widens the same
  // server-side limit and refetches, same as audit-log.js. Only meaningful
  // while the fetched batch is still exactly at the current limit (there
  // could be more beyond it) and under the RPC's own 1000-row cap.
  const canLoadMore = rows.length >= _shLogLimit && _shLogLimit < 1000;

  return `
  <div class="sh-log-table">
    <div class="sh-log-head">
      <span>When</span><span>Role</span><span>Message</span><span>Source</span><span>Status</span>
    </div>
    ${rows.map(_shLogRow).join('')}
  </div>
  ${canLoadMore ? `
  <div style="text-align:center;margin-top:14px">
    <button class="btn btn-ghost btn-sm" ${_shLogsLoading ? 'disabled' : ''} onclick="shLoadMoreLogs()">
      ${_shLogsLoading ? 'Loading…' : `Load more (showing latest ${rows.length})`}
    </button>
  </div>` : `
  <div style="text-align:center;margin-top:10px;font-size:11px;color:var(--text-muted)">Showing ${rows.length} ${rows.length === 1 ? 'entry' : 'entries'}</div>
  `}`;
}

function _shLogRow(r) {
  const roleClass = r.role === 'admin' ? 'admin' : r.role === 'teacher' ? 'teacher' : r.role === 'student' ? 'student' : 'none';
  const roleLabel = r.role || 'anon';
  const stackExpanded = !!_shExpandedStackIds[r.id];
  const busy = _shBusyId === r.id;

  return `
  <div class="sh-log-row ${r.resolved ? 'resolved' : ''}">
    <div data-label="When" style="font-size:11px;color:var(--text-muted)">${_shFormatDate(r.created_at)}</div>
    <div data-label="Role"><span class="sh-role-chip ${roleClass}">${_esc(roleLabel)}</span></div>
    <div data-label="Message">
      <div class="sh-log-msg">${_esc(r.message)}</div>
      ${r.url ? `<div class="sh-log-msg-source">${_esc(r.url)}</div>` : ''}
      ${r.stack ? `
      <span class="sh-log-stack-toggle" onclick="shToggleStack('${_esc(r.id)}')">${stackExpanded ? 'Hide stack trace' : 'Show stack trace'}</span>
      ${stackExpanded ? `<div class="sh-log-stack">${_esc(r.stack)}</div>` : ''}
      ` : ''}
    </div>
    <div data-label="Source" style="font-size:11px;color:var(--text-muted)">${_esc(r.source || '—')}</div>
    <div data-label="Status">
      <button class="btn btn-xs sh-log-resolve-btn ${r.resolved ? 'btn-ghost' : 'btn-success'}" ${busy ? 'disabled' : ''}
        onclick="shToggleResolved('${_esc(r.id)}', ${!!r.resolved})">
        ${busy ? '…' : (r.resolved ? 'Un-resolve' : 'Resolve')}
      </button>
    </div>
  </div>`;
}

function _shFormatDate(iso) {
  try {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '—';
    return d.toLocaleString(undefined, { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  } catch (e) { return '—'; }
}


/* ---- ./modules/admin/ownership-service.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/admin/ownership-service.js
//  Service layer for Chunk D: Ownership & Lifecycle.
//  (ISOLATION_ROLES_PLAN.md Chunk D — see supabase/phase42_ownership_lifecycle.sql.)
//
//  TWO SEPARATE ACTIONS, TWO SEPARATE ENTRY POINTS
//    - Standalone, single-section reassignment ("who covers this section
//      now") lives in SectionService.reassignAdviser() — it's a sections
//      concern, triggered from Section Maker, and doesn't touch content.
//    - Full offboarding — transferOwnership() below — is the bulk,
//      cross-cutting action: every section AND every piece of content a
//      departing teacher owns, moved to one destination teacher in a
//      single call. Triggered from the Teacher Directory (teacher-directory.js),
//      NOT from Section Maker.
//  Don't merge these — see phase42's header for why they're kept apart.
//
//  REPOSITORY PATTERN CONTRACT — same rule as every other *Service module:
//  the render layer (teacher-directory.js) never calls DBService.rpc()
//  directly for this. It calls OwnershipService.transferOwnership(...).
//
//  Deliberately does NOT touch AppStore's classSections slice directly —
//  it calls window.refreshSectionData() (sections_index.js) after a
//  successful transfer instead, the same "just re-fetch" approach every
//  other cross-cutting admin action in this app uses, rather than trying
//  to hand-patch a potentially-large, server-computed set of section
//  changes into the draft here.
// ═══════════════════════════════════════════════════════════════════════════════

window.OwnershipService = (function () {
  'use strict';

  /**
   * transferOwnership({ fromTeacherId, toTeacherId, archiveSectionIds? })
   *   → Promise<{ok, summary?, error?}>
   * summary (on success) mirrors transfer_teacher_ownership()'s returned
   * jsonb exactly: { fromTeacherId, toTeacherId, sectionsReassigned,
   * sectionsArchived, achievements, titles, quizzes, campaignWorlds,
   * shopProducts, bossLibrary }.
   */
  async function transferOwnership({ fromTeacherId, toTeacherId, archiveSectionIds = [] }) {
    if (!fromTeacherId) return { ok: false, error: 'Missing departing teacher id.' };
    if (!toTeacherId) return { ok: false, error: 'Choose a destination teacher.' };
    if (fromTeacherId === toTeacherId) return { ok: false, error: 'Destination must be a different teacher.' };

    const { data, error } = await DBService.rpc('transfer_teacher_ownership', {
      p_from_teacher_id: fromTeacherId,
      p_to_teacher_id: toTeacherId,
      p_archive_section_ids: archiveSectionIds || [],
    });
    if (error) return { ok: false, error: error.message || 'Could not transfer ownership.' };

    const summary = {
      fromTeacherId: data.fromTeacherId,
      toTeacherId: data.toTeacherId,
      sectionsReassigned: data.sectionsReassigned || 0,
      sectionsArchived: data.sectionsArchived || 0,
      achievements: data.achievements || 0,
      titles: data.titles || 0,
      quizzes: data.quizzes || 0,
      campaignWorlds: data.campaignWorlds || 0,
      shopProducts: data.shopProducts || 0,
      bossLibrary: data.bossLibrary || 0,
    };

    // Sections changed server-side (adviser reassigned or archived) — pull
    // the fresh set so Section Maker and every getActiveClassIds()/
    // getClassLabel() consumer reflect it without waiting on realtime.
    if (typeof window.refreshSectionData === 'function') {
      window.refreshSectionData().catch(function (e) {
        console.warn('[OwnershipService] post-transfer section refresh failed:', e);
      });
    }

    return { ok: true, summary };
  }

  return { transferOwnership };
})();


/* ---- ./modules/admin/school-settings-service.js ---- */
// ═══════════════════════════════════════════════════════════════════════════════
//  EduQuest — modules/admin/school-settings-service.js
//  Service layer for global school settings (Chunk E "Governance").
//  (ISOLATION_ROLES_PLAN.md Chunk E, "global settings beyond nav config" —
//   see supabase/phase40_governance_audit_and_settings.sql.)
//
//  SCOPE NOTE (confirmed before building): v1 is just school_name (text) and
//  school_year_label (single free-text label, e.g. "SY 2026-2027") — no
//  logo/branding, no start/end dates, no multi-term calendar. Extend the SQL
//  singleton row + these two functions together if that scope grows later;
//  don't bolt extra fields onto get()/save() without a matching column.
//
//  REPOSITORY PATTERN CONTRACT — same rule as every other *Service module:
//  no render layer calls DBService.rpc() directly for this. It calls
//  SchoolSettingsService.<method>(...).
//
//  get() is intentionally callable by anyone signed in (or anon) — a school
//  name/year label isn't sensitive and may end up shown in headers or the
//  kiosk display later. save() is admin-only server-side (is_admin() check
//  inside save_school_settings()); a teacher calling it gets an RPC error.
// ═══════════════════════════════════════════════════════════════════════════════

window.SchoolSettingsService = (function () {
  'use strict';

  /**
   * get() → Promise<{ok, settings?, error?}>
   * settings shape: { schoolName, schoolYearLabel, updatedAt, updatedBy }
   */
  async function get() {
    const { data, error } = await DBService.rpc('get_school_settings', {});
    if (error) return { ok: false, error: error.message || 'Could not load school settings.' };
    const row = data || {};
    return {
      ok: true,
      settings: {
        schoolName: row.school_name || '',
        schoolYearLabel: row.school_year_label || '',
        updatedAt: row.updated_at || null,
        updatedBy: row.updated_by || null,
      },
    };
  }

  /**
   * save({ schoolName, schoolYearLabel }) → Promise<{ok, settings?, error?}>
   */
  async function save({ schoolName, schoolYearLabel }) {
    const { data, error } = await DBService.rpc('save_school_settings', {
      p_school_name: schoolName || null,
      p_school_year_label: schoolYearLabel || null,
    });
    if (error) return { ok: false, error: error.message || 'Could not save school settings.' };
    const row = data || {};
    return {
      ok: true,
      settings: {
        schoolName: row.school_name || '',
        schoolYearLabel: row.school_year_label || '',
        updatedAt: row.updated_at || null,
        updatedBy: row.updated_by || null,
      },
    };
  }

  return { get, save };
})();


/* ---- ./modules/admin/school-settings.js ---- */
// ══════════════════════════════════════════════════════
//  modules/admin/school-settings.js
//  School Settings — admin-only screen (Chunk E "Governance").
//  (ISOLATION_ROLES_PLAN.md Chunk E — see school-settings-service.js and
//   supabase/phase40_governance_audit_and_settings.sql.)
//
//  v1 scope (confirmed before building): school name + a single free-text
//  school-year label. No logo/branding, no dates. See the service file's
//  header before adding fields here.
//
//  REPOSITORY PATTERN: this file never calls DBService.rpc() directly —
//  only SchoolSettingsService.
//
//  Exports: renderSchoolSettings, saveSchoolSettings
// ══════════════════════════════════════════════════════

let _schoolSettings = { schoolName: '', schoolYearLabel: '', updatedAt: null, updatedBy: null };
let _schoolSettingsLoading = false;
let _schoolSettingsError = null;
let _schoolSettingsSaving = false;

window.renderSchoolSettings = async function () {
  const el = document.getElementById('a-settings');
  if (!el) return;

  // Defense in depth: nav.js already hides this tab and bounces direct
  // navTo() calls for a non-admin — same guard as every other
  // ADMIN_ONLY_NAV_IDS screen (see teacher-directory.js).
  if (currentRole !== 'admin') {
    el.innerHTML = `
    <div class="glass-card" style="padding:32px;text-align:center">
      <span class="material-symbols-outlined" style="font-size:40px;color:var(--text-muted)">lock</span>
      <h2 style="font-family:var(--fh);font-size:18px;margin:12px 0 4px">Admin only</h2>
      <p style="font-size:13px;color:var(--text-muted)">This screen is only available to oversight admin accounts.</p>
    </div>`;
    return;
  }

  _schoolSettingsLoading = true;
  _schoolSettingsError = null;
  _ssRenderShell(el);

  const res = await SchoolSettingsService.get();
  _schoolSettingsLoading = false;
  if (!res.ok) {
    _schoolSettingsError = res.error;
  } else {
    _schoolSettings = res.settings;
  }

  if (document.getElementById('a-settings')) _ssRenderShell(document.getElementById('a-settings'));
};

function _ssRenderShell(el) {
  const s = _schoolSettings;
  const updatedLine = s.updatedAt
    ? `<div style="font-size:11px;color:var(--text-muted);margin-top:6px">Last saved ${_ssEsc(new Date(s.updatedAt).toLocaleString())}</div>`
    : '';

  el.innerHTML = `
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px">
    <div>
      <div style="font-family:var(--fh);font-size:26px;font-weight:900">⚙️ School Settings</div>
      <div style="font-size:13px;color:var(--text-muted);margin-top:2px">Global settings shared across the whole app.</div>
    </div>
  </div>

  ${_schoolSettingsLoading ? `<div style="padding:40px;text-align:center;color:var(--text-muted)">Loading…</div>` : ''}
  ${_schoolSettingsError ? `<div class="glass-card" style="padding:16px;color:#ff6b6b;margin-bottom:16px">⚠️ ${_ssEsc(_schoolSettingsError)}</div>` : ''}

  ${!_schoolSettingsLoading ? `
  <div class="glass-card" style="padding:24px;max-width:520px">
    <div style="display:flex;flex-direction:column;gap:16px">
      <div>
        <label class="form-label">School Name</label>
        <input id="ss-school-name" class="form-control" value="${_ssEscAttr(s.schoolName)}" placeholder="e.g. Rizal Integrated School">
      </div>
      <div>
        <label class="form-label">School Year Label</label>
        <input id="ss-school-year" class="form-control" value="${_ssEscAttr(s.schoolYearLabel)}" placeholder="e.g. SY 2026-2027">
      </div>
      ${updatedLine}
      <div>
        <button class="btn-primary" onclick="saveSchoolSettings()" ${_schoolSettingsSaving ? 'disabled' : ''} style="padding:10px 20px;border-radius:10px;font-weight:700">
          ${_schoolSettingsSaving ? 'Saving…' : 'Save'}
        </button>
      </div>
    </div>
  </div>` : ''}
  `;
}

window.saveSchoolSettings = async function () {
  const nameEl = document.getElementById('ss-school-name');
  const yearEl = document.getElementById('ss-school-year');
  const schoolName = nameEl ? nameEl.value.trim() : '';
  const schoolYearLabel = yearEl ? yearEl.value.trim() : '';

  _schoolSettingsSaving = true;
  _ssRenderShell(document.getElementById('a-settings'));

  const res = await SchoolSettingsService.save({ schoolName, schoolYearLabel });

  _schoolSettingsSaving = false;
  if (!res.ok) {
    toast('⚠️ ' + res.error, '#ff6b6b');
    _ssRenderShell(document.getElementById('a-settings'));
    return;
  }
  _schoolSettings = res.settings;
  toast('✅ Saved');
  _ssRenderShell(document.getElementById('a-settings'));
};

function _ssEsc(s) {
  const d = document.createElement('div');
  d.textContent = (s === null || s === undefined) ? '' : String(s);
  return d.innerHTML;
}
function _ssEscAttr(s) { return _ssEsc(s); }


